private fun AppState.hasAndroidBackTarget(): Boolean =
    isCreatingWorkOrder ||
        selectedWorkOrder != null ||
        selectedRecord != null ||
        navigationDepth > 0 ||
        section != AppSection.Operations ||
        (section == AppSection.More && moreFocus != MoreSectionFocus.Overview)

class SafeNexusViewModel(application: Application) : AndroidViewModel(application) {
    private val api = SafeNexusApi()
    private val authStore = SafeNexusAuthStore(application)
    private val workOrderMutationVersions = mutableMapOf<String, Int>()
    private val documentationContextCache = mutableMapOf<String, WorkOrderDocumentationContext>()
    private val documentationContextRequests = mutableSetOf<String>()
    private val navigationBackStack = mutableListOf<AppNavigationDestination>()
    private var shouldRememberSession = false

    var state by mutableStateOf(AppState())
        private set

    init {
        loadRememberedSession()
    }

    private fun loadRememberedSession() {
        val storedSession = authStore.load()
        state = state.copy(rememberedUser = storedSession?.user)
    }

    fun unlockRememberedSession() {
        val storedSession = authStore.load()
        if (storedSession == null) {
            shouldRememberSession = false
            state = state.copy(rememberedUser = null, error = "Nema spremljene prijave. Prijavi se emailom i lozinkom.")
            return
        }
        shouldRememberSession = true
        api.restoreSession(storedSession.accessToken, storedSession.cookieHeader)
        val destination = normalizeClientPortalDestination(
            destination = AppNavigationDestination(state.section, state.moreFocus),
            user = storedSession.user,
        )
        state = state.copy(
            user = storedSession.user,
            rememberedUser = storedSession.user,
            section = destination.section,
            moreFocus = destination.moreFocus,
            navigationDepth = 0,
            isLoading = true,
            error = "",
        )
        navigationBackStack.clear()
        registerPushToken()
        refresh()
    }

    fun login(email: String, password: String, rememberSession: Boolean) {
        if (email.isBlank() || password.isBlank()) {
            state = state.copy(error = "Upisi email i lozinku.")
            return
        }
        state = state.copy(isLoading = true, error = "")
        viewModelScope.launch {
            api.login(email, password)
                .onSuccess { user ->
                    shouldRememberSession = rememberSession
                    if (rememberSession) {
                        authStore.save(user, api.currentAccessToken(), api.currentAuthCookieHeader())
                    } else {
                        authStore.clear()
                    }
                    val destination = normalizeClientPortalDestination(
                        destination = AppNavigationDestination(state.section, state.moreFocus),
                        user = user,
                    )
                    if (user.hasClientPortalAccess()) {
                        navigationBackStack.clear()
                    }
                    state = state.copy(
                        user = user,
                        rememberedUser = if (rememberSession) user else null,
                        section = destination.section,
                        moreFocus = destination.moreFocus,
                        navigationDepth = navigationBackStack.size,
                        isLoading = false,
                        error = "",
                    )
                    registerPushToken()
                    refresh()
                }
                .onFailure { error ->
                    state = state.copy(isLoading = false, error = error.message ?: "Prijava nije uspjela.")
                }
        }
    }

    fun registerPushToken() {
        if (state.user == null) return
        FirebaseMessaging.getInstance().token
            .addOnSuccessListener { token ->
                if (token.isBlank()) return@addOnSuccessListener
                viewModelScope.launch {
                    api.registerPushToken(
                        token = token,
                        platform = "android",
                        deviceId = androidDeviceId(),
                    )
                }
            }
    }

    fun refresh() {
        state = state.copy(isLoading = true, error = "", notice = "")
        viewModelScope.launch {
            api.bootstrap()
                .onSuccess { data ->
                    if (shouldRememberSession) {
                        state.user?.let { user ->
                            authStore.save(user, api.currentAccessToken(), api.currentAuthCookieHeader())
                        }
                    }
                    val selectedId = state.selectedWorkOrder?.id
                    val portalUser = state.user ?: state.rememberedUser
                    val isClientPortal = portalUser.hasClientPortalAccess()
                    val destination = normalizeClientPortalDestination(
                        destination = AppNavigationDestination(state.section, state.moreFocus),
                        user = portalUser,
                    )
                    if (isClientPortal) {
                        navigationBackStack.clear()
                    }
                    state = state.copy(
                        data = data,
                        workOrders = data.workOrders,
                        selectedWorkOrder = selectedId?.let { id -> data.workOrders.firstOrNull { it.id == id } } ?: state.selectedWorkOrder,
                        selectedRecord = if (isClientPortal) null else state.selectedRecord,
                        isCreatingWorkOrder = if (isClientPortal) false else state.isCreatingWorkOrder,
                        section = destination.section,
                        moreFocus = destination.moreFocus,
                        navigationDepth = navigationBackStack.size,
                        isLoading = false,
                        error = "",
                    )
                    loadCompanyDirectory(reset = true)
                }
                .onFailure { error ->
                    val message = error.message ?: "Ne mogu učitati mobilne podatke."
                    if (message.contains("(401)")) {
                        val remembered = authStore.load()?.user ?: state.rememberedUser
                        api.clearSession()
                        shouldRememberSession = remembered != null
                        state = AppState(
                            rememberedUser = remembered,
                            error = if (remembered != null) {
                                "Sesija treba novu potvrdu. Otključaj otiskom prsta."
                            } else {
                                "Sesija je istekla. Prijavi se ponovno."
                            },
                        )
                    } else {
                        state = state.copy(isLoading = false, error = message)
                    }
                }
        }
    }

    private suspend fun reloadAfterTodoMutation(
        selectedTodoId: String? = state.selectedRecord?.takeIf { it.kind == "todo_task" }?.id,
        notice: String = "",
    ) {
        api.bootstrap()
            .onSuccess { data ->
                if (shouldRememberSession) {
                    state.user?.let { user ->
                        authStore.save(user, api.currentAccessToken(), api.currentAuthCookieHeader())
                    }
                }
                val selectedWorkOrderId = state.selectedWorkOrder?.id
                val nextSelectedRecord = if (!selectedTodoId.isNullOrBlank()) {
                    data.todoTasks.firstOrNull { it.id == selectedTodoId } ?: state.selectedRecord
                } else {
                    state.selectedRecord
                }
                state = state.copy(
                    data = data,
                    workOrders = data.workOrders,
                    selectedWorkOrder = selectedWorkOrderId?.let { id -> data.workOrders.firstOrNull { it.id == id } } ?: state.selectedWorkOrder,
                    selectedRecord = nextSelectedRecord,
                    isLoading = false,
                    error = "",
                    notice = notice,
                )
            }
            .onFailure { error ->
                state = state.copy(isLoading = false, error = error.message ?: "ToDo je spremljen, ali osvježavanje nije uspjelo.")
            }
    }

