    fun updateWorkOrderExecutors(workOrder: WorkOrder, executors: List<String>) {
        if (workOrder.id.isBlank()) {
            state = state.copy(error = "RN nema ispravan ID za spremanje izvršitelja.")
            return
        }
        val normalized = executors.map { it.trim() }.filter { it.isNotBlank() }.distinct()
        val mutationVersion = beginWorkOrderMutation(workOrder.id)
        val previousWorkOrder = state.workOrders.firstOrNull { it.id == workOrder.id } ?: workOrder
        replaceWorkOrderInState(workOrder.copy(executors = normalized))
        viewModelScope.launch {
            api.updateWorkOrderExecutors(workOrder.id, normalized)
                .onSuccess { updatedWorkOrder ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(updatedWorkOrder, "Izvršitelji RN-a su spremljeni.")
                    }
                }
                .onFailure { error ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(previousWorkOrder)
                        state = state.copy(error = error.message ?: "Ne mogu spremiti izvršitelje RN-a.", notice = "")
                    }
                }
        }
    }

    fun updateWorkOrderWatchers(workOrder: WorkOrder, watcherIds: List<String>) {
        if (workOrder.id.isBlank()) {
            state = state.copy(error = "RN nema ispravan ID za spremanje watcher-a.")
            return
        }
        val normalized = watcherIds.map { it.trim() }.filter { it.isNotBlank() }.distinct()
        val mutationVersion = beginWorkOrderMutation(workOrder.id)
        val previousWorkOrder = state.workOrders.firstOrNull { it.id == workOrder.id } ?: workOrder
        replaceWorkOrderInState(workOrder.copy(watcherIds = normalized))
        viewModelScope.launch {
            api.updateWorkOrderWatchers(workOrder.id, normalized)
                .onSuccess { updatedWorkOrder ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(updatedWorkOrder, "Watcher-i RN-a su spremljeni.")
                    }
                }
                .onFailure { error ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(previousWorkOrder)
                        state = state.copy(error = error.message ?: "Ne mogu spremiti watcher-e RN-a.", notice = "")
                    }
                }
        }
    }

    fun updateWorkOrderMeta(workOrder: WorkOrder, priority: String, tags: List<String>) {
        if (workOrder.id.isBlank()) {
            state = state.copy(error = "RN nema ispravan ID za spremanje prioriteta i tagova.")
            return
        }
        val normalizedPriority = priority.trim().ifBlank { "Normal" }
        val normalizedTags = tags
            .flatMap { tag -> tag.split(',', ';', '\n', '•') }
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
        if (
            normalizedPriority == workOrder.priority &&
            normalizedTags.map { it.lowercase(Locale.getDefault()) } == workOrder.tags.map { it.lowercase(Locale.getDefault()) }
        ) {
            return
        }

        val mutationVersion = beginWorkOrderMutation(workOrder.id)
        val previousWorkOrder = state.workOrders.firstOrNull { it.id == workOrder.id } ?: workOrder
        replaceWorkOrderInState(
            workOrder.copy(
                priority = normalizedPriority,
                tags = normalizedTags,
            ),
        )
        viewModelScope.launch {
            api.updateWorkOrderMeta(workOrder.id, normalizedPriority, normalizedTags.joinToString(", "))
                .onSuccess { updatedWorkOrder ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(updatedWorkOrder, "Prioritet i tagovi su spremljeni.")
                    }
                }
                .onFailure { error ->
                    if (isCurrentWorkOrderMutation(workOrder.id, mutationVersion)) {
                        replaceWorkOrderInState(previousWorkOrder)
                        state = state.copy(error = error.message ?: "Ne mogu spremiti prioritet i tagove RN-a.", notice = "")
                    }
                }
        }
    }

