    }

    fun downloadOfferPdf(context: Context, offer: MobileRecord) {
        if (offer.id.isBlank()) {
            state = state.copy(error = "Ponuda nema ispravan ID za PDF.")
            return
        }

        val number = offer.meta["offerNumber"].orEmpty().ifBlank { offer.title }
        val slug = number
            .replace(Regex("[^A-Za-z0-9_-]+"), "-")
            .trim('-')
            .ifBlank { "ponuda" }
        val fallbackFileName = "$slug.pdf"
        state = state.copy(isLoading = true, error = "", notice = "")
        viewModelScope.launch {
            api.downloadOfferPdf(offer.id, fallbackFileName)
                .onSuccess { downloaded ->
                    runCatching { saveDownloadedDocument(context, downloaded) }
                        .onSuccess { uri ->
                            val opened = openCachedDocument(context, uri, downloaded.fileType)
                            state = state.copy(
                                isLoading = false,
                                notice = if (opened) {
                                    "PDF ponude je spremljen u Preuzimanja / SafeNexus i otvoren."
                                } else {
                                    "PDF ponude je spremljen u Preuzimanja / SafeNexus."
                                },
                                error = if (opened) "" else "Na uređaju nema aplikacije za otvaranje PDF-a.",
                            )
                        }
                        .onFailure { error ->
                            state = state.copy(
                                isLoading = false,
                                error = error.message ?: "Ne mogu spremiti PDF ponude.",
                            )
                        }
                }
                .onFailure { error ->
                    state = state.copy(
                        isLoading = false,
                        error = error.message ?: "Ne mogu preuzeti PDF ponude.",
                    )
                }
        }
    }

    fun signWorkOrderPdf(
        context: Context,
        workOrder: WorkOrder,
        signaturePngBytes: ByteArray,
        signerName: String,
        signatureLocation: String,
        includeSignerName: Boolean,
        includeSignedAt: Boolean,
        includeSignatureLocation: Boolean,
    ) {
        if (workOrder.id.isBlank()) {
            state = state.copy(error = "Radni nalog nema ispravan ID za potpis.")
            return
        }
        if (signaturePngBytes.isEmpty()) {
            state = state.copy(error = "Potpis je prazan.")
            return
        }

        val fallbackFileName = "${workOrder.displayNumber.ifBlank { "radni-nalog" }}-potpisano.pdf"
        val resolvedSignerName = signerName.trim()
        val signedAt = java.time.ZonedDateTime.now().format(DateTimeFormatter.ISO_OFFSET_DATE_TIME)
        state = state.copy(isLoading = true, error = "", notice = "")
        viewModelScope.launch {
            api.signWorkOrderPdf(
                workOrderId = workOrder.id,
                signaturePngBytes = signaturePngBytes,
                signerName = resolvedSignerName,
                signatureLocation = signatureLocation.trim(),
                signedAt = signedAt,
                includeSignerName = includeSignerName,
                includeSignedAt = includeSignedAt,
                includeSignatureLocation = includeSignatureLocation,
                fallbackFileName = fallbackFileName,
            )
                .onSuccess { downloaded ->
                    runCatching { saveDownloadedDocument(context, downloaded) }
                        .onSuccess { uri ->
                            val opened = openCachedDocument(context, uri, downloaded.fileType)
                            val successNotice = "Potpisani RN je spremljen, dodan u dokumentaciju i status je Ovjeren RN."
                            state = state.copy(
                                isLoading = false,
                                notice = successNotice,
                                error = if (opened) "" else "Na uređaju nema aplikacije za otvaranje PDF-a.",
                            )
                            loadWorkOrderDocuments(workOrder.id)
                            markWorkOrderVerifiedAfterApproval(workOrder, successNotice)
                        }
                        .onFailure { error ->
                            state = state.copy(
                                isLoading = false,
                                error = error.message ?: "Ne mogu spremiti potpisani RN na mobitel.",
                            )
                            loadWorkOrderDocuments(workOrder.id)
                        }
                }
                .onFailure { error ->
                    state = state.copy(
                        isLoading = false,
                        error = error.message ?: "Ne mogu potpisati radni nalog.",
                    )
                }
        }
    }

    private fun androidDeviceId(): String =
        Settings.Secure.getString(getApplication<Application>().contentResolver, Settings.Secure.ANDROID_ID).orEmpty()
}

@SuppressLint("SetJavaScriptEnabled")
@Composable
private fun SafeNexusLearningTestApp(token: String) {
    val context = LocalContext.current
    val activity = context.findFragmentActivity()
    val testUrl = remember(token) {
        Uri.parse(BuildConfig.SAFE_NEXUS_BASE_URL.trimEnd('/'))
            .buildUpon()
            .appendEncodedPath("learning-test.html")
            .appendQueryParameter("token", token)
            .appendQueryParameter("mobile", "app")
            .build()
            .toString()
    }

    BackHandler(enabled = true) {
        activity?.finish()
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text("SafeNexus ispit", fontWeight = FontWeight.Black)
                        Text(
                            "Samo dio za polaganje",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { activity?.finish() }) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Zatvori")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background,
                ),
            )
        },
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .background(MaterialTheme.colorScheme.background),
        ) {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                shape = RoundedCornerShape(20.dp),
                color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.42f),
            ) {
                Row(
                    modifier = Modifier.padding(14.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    Icon(Icons.Rounded.Fingerprint, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                    Column {
                        Text("Ispit je otvoren iz email linka", fontWeight = FontWeight.Black)
                        Text(
                            "Ne otvara se cijeli SafeNexus workspace.",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                        )
                    }
                }
            }
            AndroidView(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                factory = { viewContext ->
                    WebView(viewContext).apply {
                        webViewClient = WebViewClient()
                        settings.javaScriptEnabled = true
                        settings.domStorageEnabled = true
                        settings.allowContentAccess = true
                        settings.loadWithOverviewMode = true
                        settings.useWideViewPort = true
                        setBackgroundColor(AndroidColor.WHITE)
                    }
                },
                update = { webView ->
                    if (webView.tag != testUrl) {
                        webView.tag = testUrl
                        webView.loadUrl(testUrl)
                    }
                },
            )
        }
    }
}

@Composable
fun SafeNexusApp(learningTestToken: String = "") {
    if (learningTestToken.isNotBlank()) {
        SafeNexusLearningTestApp(token = learningTestToken)
        return
    }
    SafeNexusWorkspaceApp()
}

@Composable
private fun SafeNexusWorkspaceApp(viewModel: SafeNexusViewModel = viewModel()) {
    val state = viewModel.state
    val context = LocalContext.current
    LaunchedEffect(state.pendingExternalUrl) {
        val url = state.pendingExternalUrl.trim()
        if (url.isNotBlank()) {
            openExternalUrl(context, url)
            viewModel.clearPendingExternalUrl()
        }
    }
    val notificationPermissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) {
        viewModel.registerPushToken()
    }
    var documentationActionTarget by remember { mutableStateOf<WorkOrder?>(null) }
    var documentationWizardTargetId by rememberSaveable { mutableStateOf("") }
    var documentationWizardObjectId by rememberSaveable { mutableStateOf("") }
    val documentationWizardTarget = remember(documentationWizardTargetId, state.selectedWorkOrder, state.workOrders, state.data.workOrders) {
        if (documentationWizardTargetId.isBlank()) {
            null
        } else {
            (listOfNotNull(state.selectedWorkOrder) + state.workOrders + state.data.workOrders)
                .firstOrNull { it.id == documentationWizardTargetId }
        }
    }
    var signatureActionTarget by remember { mutableStateOf<WorkOrder?>(null) }
    var serviceManagementTarget by remember { mutableStateOf<WorkOrder?>(null) }
    var pendingTrainingImportTarget by remember { mutableStateOf<WorkOrder?>(null) }
    var pendingTrainingImportObjectId by remember { mutableStateOf("") }
    var pendingPicker by remember { mutableStateOf<Pair<WorkOrder, WorkOrderDocumentInputMode>?>(null) }
    var pendingCameraCapture by remember { mutableStateOf<Pair<WorkOrder, Uri>?>(null) }
    var pendingSelection by remember { mutableStateOf<PendingDocumentSelection?>(null) }
    var workOrderDocumentPreview by remember { mutableStateOf<WorkOrderDocumentPreviewState?>(null) }
    BackHandler(enabled = state.user != null && state.hasAndroidBackTarget()) {
        viewModel.navigateBack()
    }
    val confirmDocumentSelection: (WorkOrderDocumentCategory, String) -> Unit = { category, projectDocumentName ->
        val selection = pendingSelection
        pendingSelection = null
        if (selection != null) {
            viewModel.uploadWorkOrderDocuments(
                context = context.applicationContext,
                workOrder = selection.workOrder,
                uris = selection.uris,
                category = category,
                mode = selection.mode,
                projectDocumentName = projectDocumentName,
            )
        }
    }
    val photoLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        val target = pendingPicker
        pendingPicker = null
        if (target != null && uris.isNotEmpty()) {
            pendingSelection = PendingDocumentSelection(target.first, uris, target.second)
        }
    }
    val pdfLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris ->
        val target = pendingPicker
        pendingPicker = null
        if (target != null && uris.isNotEmpty()) {
            pendingSelection = PendingDocumentSelection(target.first, uris, target.second)
        }
    }
    val fileLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris ->
        val target = pendingPicker
        pendingPicker = null
        if (target != null && uris.isNotEmpty()) {
            pendingSelection = PendingDocumentSelection(target.first, uris, target.second)
        }
    }
    val cameraLauncher = rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()) { success ->
        val target = pendingCameraCapture
        pendingCameraCapture = null
        if (success && target != null) {
            pendingSelection = PendingDocumentSelection(target.first, listOf(target.second), WorkOrderDocumentInputMode.Photos)
        }
    }
    val trainingImportLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        val target = pendingTrainingImportTarget
        val objectId = pendingTrainingImportObjectId
        pendingTrainingImportTarget = null
        pendingTrainingImportObjectId = ""
        if (target != null && uri != null) {
            viewModel.importTrainingPeopleFromExcel(
                context = context.applicationContext,
                workOrder = target,
                uri = uri,
                objectId = objectId,
            )
        }
    }
    val documentScannerLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { result ->
        val target = pendingPicker
        pendingPicker = null
        if (result.resultCode == Activity.RESULT_OK && target != null) {
            val scanResult = GmsDocumentScanningResult.fromActivityResultIntent(result.data)
            val pdfUri = scanResult?.pdf?.uri
            if (pdfUri != null) {
                pendingSelection = PendingDocumentSelection(target.first, listOf(pdfUri), target.second)
            } else {
                viewModel.showError("Sken nije vratio PDF dokument.")
            }
        }
    }
    val startDocumentationFlow: (WorkOrder, WorkOrderDocumentInputMode) -> Unit = { workOrder, mode ->
        documentationActionTarget = null
        pendingPicker = workOrder to mode
        when (mode) {
            WorkOrderDocumentInputMode.Scan -> {
                val activity = context.findFragmentActivity()
                if (activity == null) {
                    pendingPicker = null
                    viewModel.showError("Skeniranje dokumenta nije dostupno u ovom prikazu.")
                } else {
                    val options = GmsDocumentScannerOptions.Builder()
                        .setGalleryImportAllowed(true)
                        .setPageLimit(30)
                        .setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_PDF)
                        .setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL)
                        .build()
                    GmsDocumentScanning.getClient(options)
                        .getStartScanIntent(activity)
                        .addOnSuccessListener { intentSender ->
                            documentScannerLauncher.launch(IntentSenderRequest.Builder(intentSender).build())
                        }
                        .addOnFailureListener { error ->
                            pendingPicker = null
                            viewModel.showError(error.message ?: "Ne mogu pokrenuti skeniranje dokumenta.")
                        }
                }
            }
            WorkOrderDocumentInputMode.Photos -> photoLauncher.launch("image/*")
            WorkOrderDocumentInputMode.Pdf -> pdfLauncher.launch(arrayOf("application/pdf"))
            WorkOrderDocumentInputMode.File -> fileLauncher.launch(workOrderDocumentAllowedMimeTypes)
        }
    }
    val startCameraDocumentationFlow: (WorkOrder) -> Unit = { workOrder ->
        documentationActionTarget = null
        val outputUri = createWorkOrderCameraCaptureUri(context.applicationContext)
        if (outputUri == null) {
            viewModel.showError("Ne mogu pripremiti fotografiju za spremanje.")
        } else {
            pendingCameraCapture = workOrder to outputUri
            cameraLauncher.launch(outputUri)
        }
    }
    val openDocumentationActions: (WorkOrder) -> Unit = { workOrder ->
        documentationActionTarget = workOrder
    }
    val resolveDocumentPreview: (WorkOrderDocument) -> Unit = { document ->
        viewModel.previewWorkOrderDocument(
            context = context.applicationContext,
            document = document,
        ) { uri, fileType ->
            workOrderDocumentPreview = workOrderDocumentPreview?.let { preview ->
                if (preview.documents.none { it.id == document.id }) {
                    preview
                } else {
                    preview.copy(
                        resolvedUris = preview.resolvedUris + (document.id to uri),
                        resolvedFileTypes = preview.resolvedFileTypes + (document.id to fileType.ifBlank { document.fileType }),
                    )
                }
            }
        }
    }
    val openDocumentPreview: (WorkOrderDocument) -> Unit = { document ->
        val galleryDocuments = state.workOrderDocuments
            .filter { it.isImage }
            .ifEmpty { listOf(document) }
        val selectedIndex = galleryDocuments.indexOfFirst { it.id == document.id }
            .takeIf { it >= 0 }
            ?: 0
        workOrderDocumentPreview = WorkOrderDocumentPreviewState(
            documents = galleryDocuments,
            initialIndex = selectedIndex,
        )
    }
    val openMobileRecord: (MobileRecord) -> Unit = { record ->
        val linkedWorkOrder = state.workOrders.firstOrNull { workOrder ->
            record.kind in setOf("work_order", "work_order_execution", "work_order_due") && (
                workOrder.id == record.relatedId ||
                    workOrder.id == record.id.removePrefix("work-order:")
                    || workOrder.id == record.id.removePrefix("work-order-due:")
                    || workOrder.id == record.id.removePrefix("work-order-execution:")
                )
        }
        if (linkedWorkOrder != null) {
            viewModel.selectWorkOrder(linkedWorkOrder)
        } else {
            viewModel.selectRecord(record)
        }
    }

    LaunchedEffect(state.user?.email) {
        if (state.user == null) return@LaunchedEffect
        viewModel.registerPushToken()
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            val hasPermission = ContextCompat.checkSelfPermission(
                context,
                Manifest.permission.POST_NOTIFICATIONS,
            ) == PackageManager.PERMISSION_GRANTED
            if (!hasPermission) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }

    AnimatedContent(targetState = state.user != null, label = "auth") { isSignedIn ->
        if (isSignedIn) {
            if (state.isCreatingWorkOrder) {
                WorkOrderCreateScreen(
                    data = state.data,
                    directoryCompanies = state.companyDirectoryRecords,
                    directoryCompanyTotal = state.companyDirectoryTotal,
                    directoryCompanyLoading = state.companyDirectoryLoading,
                    directoryCompanyHasMore = state.companyDirectoryHasMore,
                    directoryLocationsByCompany = state.companyDirectoryLocations,
                    directoryLocationLoading = state.companyDirectoryLocationLoading,
                    directoryLocationHasMoreByCompany = state.companyDirectoryLocationHasMore,
                    initialDraft = state.workOrderCreatePrefill,
                    isLoading = state.isLoading,
                    error = state.error,
                    onBack = { viewModel.navigateBack() },
                    onSave = viewModel::createWorkOrder,
                    onCreateLocation = viewModel::createWorkOrderLocation,
                    onLoadMoreCompanies = { viewModel.loadCompanyDirectory(reset = false) },
                    onLoadCompanyLocations = { company -> viewModel.loadCompanyLocations(company) },
                    onLoadMoreCompanyLocations = { company -> viewModel.loadCompanyLocations(company, reset = false) },
                )
            } else {
            val selected = state.selectedWorkOrder
            if (selected == null) {
                val selectedRecord = state.selectedRecord
                if (selectedRecord == null) {
                    WorkOrdersScreen(
                        state = state,
                        onQueryChange = viewModel::updateQuery,
                        onFilterChange = viewModel::updateFilter,
                        onViewModeChange = viewModel::updateViewMode,
                        onSectionChange = { section, focus -> viewModel.updateSection(section, focus) },
                        onRefresh = viewModel::refresh,
                        onLogout = viewModel::logout,
                        onOpenWorkOrder = viewModel::selectWorkOrder,
                        onOpenRecord = openMobileRecord,
                        onNewWorkOrder = viewModel::openWorkOrderCreate,
                        onStatusChange = viewModel::updateWorkOrderStatus,
                        onAddDocumentation = openDocumentationActions,
                        onSaveFieldInquiry = viewModel::saveFieldInquiry,
                        onPolishFieldInquiryNote = viewModel::polishFieldInquiryNote,
                        onConvertFieldInquiry = viewModel::convertFieldInquiryToWorkOrder,
                        onCreateJob = viewModel::createJob,
                        onCreateRiskAssessment = viewModel::createRiskAssessment,
                        onLoadIsznrMeasurementEquipment = viewModel::loadIsznrMeasurementEquipment,
                        onLoadIsznrPeople = viewModel::loadIsznrPeople,
                        onLoadMoreCompanies = { viewModel.loadCompanyDirectory(reset = false) },
                        onLoadCompanyLocations = { company -> viewModel.loadCompanyLocations(company) },
                        onLoadMoreCompanyLocations = { company -> viewModel.loadCompanyLocations(company, reset = false) },
                        onDownloadDocument = { record ->
                            viewModel.downloadMobileDocument(context.applicationContext, record)
                        },
                        onDownloadTrainingDocument = { record, document ->
                            viewModel.downloadPeopleTrainingDocument(context.applicationContext, record, document)
                        },
                        onCreateReminder = viewModel::createReminder,
                        onUpdateReminderStatus = viewModel::updateReminderStatus,
                        onCreateTodoTask = viewModel::createTodoTask,
                        onUpdateTodoTask = viewModel::updateTodoTask,
                        onAddTodoTaskComment = viewModel::addTodoTaskComment,
                        onSaveClientPortalRecord = viewModel::saveClientPortalRecord,
                    )
                } else if (selectedRecord.kind == "todo_task") {
                    TodoTaskDetailScreen(
                        record = selectedRecord,
                        statusOptions = state.data.todoTaskStatuses.ifEmpty { fallbackTodoTaskStatusOptions },
                        priorityOptions = state.data.priorities,
                        users = state.data.workOrderUsers,
                        workOrders = state.workOrders,
                        isLoading = state.isLoading,
                        onBack = { viewModel.navigateBack() },
                        onOpenWorkOrder = viewModel::selectWorkOrder,
                        onUpdateTodoTask = viewModel::updateTodoTask,
                        onAddTodoTaskComment = viewModel::addTodoTaskComment,
                    )
                } else {
                    MobileRecordDetailScreen(
                        record = selectedRecord,
                        users = state.data.workOrderUsers,
                        workOrders = state.data.workOrders,
                        currentUserLabel = state.user?.displayName.orEmpty(),
                        isLoading = state.isLoading,
                        onBack = { viewModel.navigateBack() },
                        onReserveVehicle = viewModel::createVehicleReservation,
                        onRecordVehicleUsage = viewModel::recordVehicleUsage,
                        onDownloadVehicleEvidencePdf = { vehicle -> viewModel.downloadVehicleEvidencePdf(context.applicationContext, vehicle) },
                        onDownloadOfferPdf = { offer -> viewModel.downloadOfferPdf(context.applicationContext, offer) },
                        onDownloadDocument = { record -> viewModel.downloadMobileDocument(context.applicationContext, record) },
                        onConvertFieldInquiry = viewModel::convertFieldInquiryToWorkOrder,
                        onDownloadFieldInquiryDocument = { record, document ->
                            viewModel.downloadFieldInquiryDocument(context.applicationContext, record, document)
                        },
                        onDownloadTrainingDocument = { record, document ->
                            viewModel.downloadPeopleTrainingDocument(context.applicationContext, record, document)
                        },
                    )
                }
            } else {
                WorkOrderDetailScreen(
                    workOrder = selected,
                    services = state.data.workOrderServices,
                    users = state.data.workOrderUsers,
                    currentUser = state.user,
                    priorityOptions = state.data.priorities,
                    tagSuggestions = state.workOrders
                        .flatMap { it.tags }
                        .distinctBy { it.lowercase(Locale.getDefault()) },
                    isLoading = state.isLoading,
                    error = state.error,
                    notice = state.notice,
                    documents = state.workOrderDocuments,
                    documentsLoading = state.workOrderDocumentsLoading,
                    statusOptions = state.data.workOrderStatuses.map { it.value }.ifEmpty { workOrderStatusOptions },
                    readOnly = state.user.hasClientPortalAccess(),
                    onBack = { viewModel.navigateBack() },
                    onNumberChange = viewModel::updateWorkOrderNumber,
                    onStatusChange = viewModel::updateWorkOrderStatus,
                    onMetaChange = viewModel::updateWorkOrderMeta,
                    onDatesChange = viewModel::updateWorkOrderDates,
                    onExecutorsChange = viewModel::updateWorkOrderExecutors,
                    onWatchersChange = viewModel::updateWorkOrderWatchers,
                    onManageServices = { workOrder -> serviceManagementTarget = workOrder },
                    onGenerateDocumentation = { workOrder ->
                        documentationWizardTargetId = workOrder.id
                        documentationWizardObjectId = workOrder.objectId
                        viewModel.loadWorkOrderDocumentationContext(workOrder, documentationWizardObjectId, forceRefresh = true)
                    },
                    onAddDocumentation = openDocumentationActions,
                    onDownloadPdf = { workOrder -> viewModel.downloadWorkOrderPdf(context.applicationContext, workOrder) },
                    onSignWorkOrder = { workOrder -> signatureActionTarget = workOrder },
                    onOpenDocument = openDocumentPreview,
                    onDownloadDocument = { document ->
                        viewModel.downloadWorkOrderDocument(
                            context.applicationContext,
                            document,
                            openAfterDownload = !document.isImage,
                        )
                    },
                    onDeleteDocument = viewModel::deleteWorkOrderDocument,
                    onRefreshDocuments = viewModel::refreshWorkOrderDocuments,
                )
            }
            }
        } else {
            if (state.isLoading) {
                SafeNexusLoadingScreen(rememberedUser = state.rememberedUser)
            } else {
                LoginScreen(
                    isLoading = state.isLoading,
                    error = state.error,
                    rememberedUser = state.rememberedUser,
                    onLogin = viewModel::login,
                    onUnlockRememberedSession = viewModel::unlockRememberedSession,
                )
            }
        }
    }

    documentationActionTarget?.let { workOrder ->
        WorkOrderDocumentationActionDialog(
            workOrder = workOrder,
            onDismiss = { documentationActionTarget = null },
            onCapturePhoto = { startCameraDocumentationFlow(workOrder) },
            onSelect = { mode -> startDocumentationFlow(workOrder, mode) },
        )
    }
    serviceManagementTarget?.let { workOrder ->
        WorkOrderServiceManagementDialog(
            workOrder = workOrder,
            services = state.data.workOrderServices,
            isLoading = state.isLoading,
            onDismiss = { serviceManagementTarget = null },
            onSelectionChange = { selectedServiceIds ->
                viewModel.updateWorkOrderServices(workOrder, selectedServiceIds)
            },
        )
    }
    documentationWizardTarget?.let { workOrder ->
        WorkOrderDocumentationWizardDialog(
            workOrder = workOrder,
            users = state.data.workOrderUsers,
            currentUser = state.user,
            services = state.data.workOrderServices,
            locationObjects = state.data.workOrderLocationObjects,
            selectedObjectId = documentationWizardObjectId,
            context = if (
                state.documentationContextWorkOrderId == workOrder.id &&
                state.documentationContextObjectId == documentationWizardObjectId
            ) {
                state.documentationContext
            } else {
                WorkOrderDocumentationContext(workOrderId = workOrder.id, workOrderNumber = workOrder.displayNumber)
            },
            contextLoading = state.documentationContextLoading &&
                state.documentationContextWorkOrderId == workOrder.id &&
                state.documentationContextObjectId == documentationWizardObjectId,
            isLoading = state.isLoading,
            workEquipmentSubmitResult = state.workEquipmentSubmitResults[workOrder.id] ?: IsznrWorkEquipmentSubmitResult(),
            physicalFactorsSubmitResult = state.physicalFactorsSubmitResults[workOrder.id] ?: IsznrWorkEquipmentSubmitResult(),
            onDismiss = { documentationWizardTargetId = "" },
            onObjectSelectionChange = { objectId ->
                documentationWizardObjectId = objectId
                viewModel.loadWorkOrderDocumentationContext(workOrder, objectId, forceRefresh = true)
            },
            onCreateObject = { name ->
                viewModel.createWorkOrderLocationObject(workOrder, name) { createdObject ->
                    documentationWizardObjectId = createdObject.id
                    viewModel.loadWorkOrderDocumentationContext(workOrder, createdObject.id, forceRefresh = true)
                }
            },
            onExecutorsChange = { executors ->
                viewModel.updateWorkOrderExecutors(workOrder, executors)
            },
            onRunAi = { template, files, modelTier, onSuccess, onFailure ->
                viewModel.prepareWorkOrderDocumentationAi(
                    workOrder = workOrder,
                    template = template,
                    files = files,
                    modelTier = modelTier,
                    onSuccess = onSuccess,
                    onFailure = onFailure,
                )
            },
            onRunSprVoiceAi = { template, transcript, onSuccess, onFailure ->
                viewModel.prepareSprVoiceMeasurementRows(
                    workOrder = workOrder,
                    template = template,
                    transcript = transcript,
                    onSuccess = onSuccess,
                    onFailure = onFailure,
                )
            },
            onRecognizeWorkEquipmentImages = { equipment, files, onSuccess, onFailure ->
                viewModel.recognizeWorkEquipmentFromImages(
                    workOrder = workOrder,
                    equipment = equipment,
                    files = files,
                    onSuccess = onSuccess,
                    onFailure = onFailure,
                )
            },
            onRecognizeWorkEquipmentBatchImages = { currentEquipments, files, onSuccess, onFailure ->
                viewModel.recognizeWorkEquipmentBatchFromImages(
                    workOrder = workOrder,
                    currentEquipments = currentEquipments,
                    files = files,
                    onSuccess = onSuccess,
                    onFailure = onFailure,
                )
            },
            onSubmitIsznrWorkEquipment = { selectedItemIds, manualEquipments ->
                viewModel.submitWorkOrderIsznrWorkEquipment(workOrder, selectedItemIds, manualEquipments, documentationWizardObjectId)
            },
            onSubmitIsznrPhysicalFactors = { selectedItemIds, manualPhysicalFactors ->
                viewModel.submitWorkOrderIsznrPhysicalFactors(workOrder, selectedItemIds, manualPhysicalFactors, documentationWizardObjectId)
            },
            onConfirmTraining = { mode, personIds, serviceKeys, sendEmails, onlyRecommended ->
                viewModel.confirmWorkOrderTraining(
                    workOrder,
                    mode,
                    personIds,
                    serviceKeys,
                    sendEmails,
                    onlyRecommended,
                    documentationWizardObjectId,
                )
            },
            onGenerateTrainingRecord = {
                viewModel.generateWorkOrderTrainingRecord(workOrder, documentationWizardObjectId)
            },
            onDownloadTrainingImportTemplate = {
                viewModel.downloadTrainingImportTemplate(context.applicationContext, workOrder)
            },
            onUploadTrainingImport = {
                pendingTrainingImportTarget = workOrder
                pendingTrainingImportObjectId = documentationWizardObjectId
                trainingImportLauncher.launch(peopleTrainingImportMimeTypes)
            },
            onAddTrainingPerson = { draft ->
                viewModel.addTrainingPersonManually(workOrder, draft, documentationWizardObjectId)
            },
            onConfirm = { draft ->
                documentationWizardTargetId = ""
                viewModel.generateWorkOrderDocumentation(workOrder, draft)
            },
        )
    }
    signatureActionTarget?.let { workOrder ->
        WorkOrderFingerSignatureDialog(
            workOrder = workOrder,
            defaultSignerName = "",
            isLoading = state.isLoading,
            onDismiss = { signatureActionTarget = null },
            onConfirm = { signatureBytes, signerName, signatureLocation, includeSignerName, includeSignedAt, includeSignatureLocation ->
                signatureActionTarget = null
                viewModel.signWorkOrderPdf(
                    context = context.applicationContext,
                    workOrder = workOrder,
                    signaturePngBytes = signatureBytes,
                    signerName = signerName,
                    signatureLocation = signatureLocation,
                    includeSignerName = includeSignerName,
                    includeSignedAt = includeSignedAt,
                    includeSignatureLocation = includeSignatureLocation,
                )
            },
        )
    }
    pendingSelection?.let { selection ->
        WorkOrderDocumentCategoryDialog(
            selection = selection,
            isLoading = state.isLoading,
            onDismiss = { pendingSelection = null },
            onConfirm = confirmDocumentSelection,
        )
    }
    workOrderDocumentPreview?.let { preview ->
        WorkOrderDocumentPreviewDialog(
            preview = preview,
            onResolveDocument = resolveDocumentPreview,
            onOpenExternal = { document -> viewModel.openWorkOrderDocument(context.applicationContext, document) },
            onDismiss = { workOrderDocumentPreview = null },
        )
    }
}

@Composable
private fun WorkOrderFingerSignatureDialog(
    workOrder: WorkOrder,
    defaultSignerName: String,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onConfirm: (ByteArray, String, String, Boolean, Boolean, Boolean) -> Unit,
) {
    val strokes = remember(workOrder.id) { mutableStateListOf<List<Offset>>() }
    var currentStroke by remember(workOrder.id) { mutableStateOf<List<Offset>>(emptyList()) }
    var canvasSize by remember(workOrder.id) { mutableStateOf(IntSize.Zero) }
    var signerName by remember(workOrder.id, defaultSignerName) { mutableStateOf(defaultSignerName) }
    var includeSignerName by remember(workOrder.id) { mutableStateOf(true) }
    var includeSignedAt by remember(workOrder.id) { mutableStateOf(true) }
    var includeSignatureLocation by remember(workOrder.id) { mutableStateOf(true) }
    var signatureLocation by remember(workOrder.id) {
        mutableStateOf(
            listOf(workOrder.locationName, workOrder.coordinates)
                .map { it.trim() }
                .filter { it.isNotBlank() }
                .joinToString(" · "),
        )
    }
    var gpsMessage by remember(workOrder.id) { mutableStateOf("") }
    var gpsLoading by remember(workOrder.id) { mutableStateOf(false) }
    var gpsRequestNonce by remember(workOrder.id) { mutableStateOf(0) }
    val context = LocalContext.current
    val captureGpsLocation = {
        gpsLoading = true
        gpsMessage = "Dohvaćam GPS lokaciju..."
        requestSignatureGpsLocation(
            context = context.applicationContext,
            onResult = { locationText ->
                signatureLocation = locationText
                gpsMessage = "GPS lokacija je dodana u potpis."
                gpsLoading = false
            },
            onError = { message ->
                gpsMessage = message
                gpsLoading = false
            },
        )
    }
    val gpsPermissionLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) { permissions ->
        val granted = permissions[Manifest.permission.ACCESS_FINE_LOCATION] == true ||
            permissions[Manifest.permission.ACCESS_COARSE_LOCATION] == true
        if (granted) {
            captureGpsLocation()
        } else {
            gpsMessage = "Bez dozvole za lokaciju GPS se ne može upisati u potpis."
        }
    }
    LaunchedEffect(includeSignatureLocation, gpsRequestNonce) {
        if (!includeSignatureLocation || isLoading) {
            return@LaunchedEffect
        }

        if (hasSignatureLocationPermission(context)) {
            captureGpsLocation()
        } else {
            gpsMessage = "Dopusti lokaciju za GPS potpis."
            gpsPermissionLauncher.launch(
                arrayOf(
                    Manifest.permission.ACCESS_FINE_LOCATION,
                    Manifest.permission.ACCESS_COARSE_LOCATION,
                ),
            )
        }
    }
    val hasSignature = strokes.any { it.isNotEmpty() }
    val inkColor = MaterialTheme.colorScheme.primary

    AlertDialog(
        onDismissRequest = {
            if (!isLoading) onDismiss()
        },
        title = {
            Text("Potpiši radni nalog")
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text(
                    text = "Potpiši prstom u polje. Potpis se utiskuje dolje desno na PDF radnog naloga.",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
                )
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    SignatureMetadataCheckbox(
                        checked = includeSignerName,
                        enabled = !isLoading,
                        label = "Dodaj ime i prezime",
                        onCheckedChange = { includeSignerName = it },
                    )
                    SignatureMetadataCheckbox(
                        checked = includeSignedAt,
                        enabled = !isLoading,
                        label = "Dodaj datum i vrijeme",
                        onCheckedChange = { includeSignedAt = it },
                    )
                    SignatureMetadataCheckbox(
                        checked = includeSignatureLocation,
                        enabled = !isLoading,
                        label = "Dodaj GPS lokaciju",
                        onCheckedChange = {
                            includeSignatureLocation = it
                            if (it) {
                                gpsRequestNonce += 1
                            }
                        },
                    )
                }
                OutlinedTextField(
                    value = signerName,
                    onValueChange = { signerName = it },
                    modifier = Modifier.fillMaxWidth(),
                    enabled = !isLoading && includeSignerName,
                    singleLine = true,
                    label = { Text("Ime i prezime potpisnika") },
                )
                OutlinedTextField(
                    value = signatureLocation,
                    onValueChange = { signatureLocation = it },
                    modifier = Modifier.fillMaxWidth(),
                    enabled = !isLoading && includeSignatureLocation,
                    singleLine = true,
                    label = { Text("Lokacija potpisa") },
                    placeholder = { Text("GPS koordinate potpisa") },
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    if (gpsLoading && includeSignatureLocation) {
                        CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                    } else {
                        Icon(
                            Icons.Rounded.LocationOn,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                    }
                    Text(
                        text = if (!includeSignatureLocation) {
                            "GPS lokacija neće biti dodana u PDF."
                        } else {
                            gpsMessage.ifBlank { "GPS lokacija se automatski dodaje u PDF uz potpis." }
                        },
                        modifier = Modifier.weight(1f),
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                    )
                }
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(18.dp),
                    tonalElevation = 1.dp,
                    color = Color.White,
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(220.dp)
                            .clip(RoundedCornerShape(18.dp))
                            .background(Color.White)
                            .onSizeChanged { canvasSize = it }
                            .pointerInput(isLoading) {
                                if (!isLoading) {
                                    detectDragGestures(
                                        onDragStart = { offset ->
                                            currentStroke = listOf(offset)
                                            strokes.add(currentStroke)
                                        },
                                        onDrag = { change, _ ->
                                            change.consume()
                                            val nextStroke = currentStroke + change.position
                                            currentStroke = nextStroke
                                            if (strokes.isNotEmpty()) {
                                                strokes[strokes.lastIndex] = nextStroke
                                            }
                                        },
                                        onDragEnd = { currentStroke = emptyList() },
                                        onDragCancel = { currentStroke = emptyList() },
                                    )
                                }
                            },
                    ) {
                        Canvas(modifier = Modifier.fillMaxSize()) {
                            strokes.forEach { points ->
                                when {
                                    points.size == 1 -> drawCircle(
                                        color = inkColor,
                                        radius = 3.5f,
                                        center = points.first(),
                                    )
                                    points.size > 1 -> {
                                        val path = Path().apply {
                                            moveTo(points.first().x, points.first().y)
                                            points.drop(1).forEach { point -> lineTo(point.x, point.y) }
                                        }
                                        drawPath(
                                            path = path,
                                            color = inkColor,
                                            style = Stroke(width = 5.5f),
                                        )
                                    }
                                }
                            }
                        }
                        if (!hasSignature) {
                            Text(
                                text = "Potpis",
                                modifier = Modifier.align(Alignment.Center),
                                style = MaterialTheme.typography.headlineSmall,
                                color = Color(0xFF94A3B8),
                            )
                        }
                    }
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        text = workOrder.displayNumber,
                        style = MaterialTheme.typography.labelLarge,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                    )
                    TextButton(
                        onClick = {
                            strokes.clear()
                            currentStroke = emptyList()
                        },
                        enabled = !isLoading && hasSignature,
                    ) {
                        Text("Obriši")
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    onConfirm(
                        renderSignaturePng(
                            strokes = strokes.map { it.toList() },
                            widthPx = canvasSize.width,
                            heightPx = canvasSize.height,
                        ),
                        signerName.trim(),
                        signatureLocation.trim(),
                        includeSignerName,
                        includeSignedAt,
                        includeSignatureLocation,
                    )
                },
                enabled = !isLoading && hasSignature && canvasSize.width > 0 && canvasSize.height > 0,
            ) {
                Text("Potpiši i otvori PDF")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss, enabled = !isLoading) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun SignatureMetadataCheckbox(
    checked: Boolean,
    enabled: Boolean,
    label: String,
    onCheckedChange: (Boolean) -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(12.dp))
            .clickable(enabled = enabled) { onCheckedChange(!checked) }
            .padding(vertical = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Checkbox(
            checked = checked,
            onCheckedChange = onCheckedChange,
            enabled = enabled,
        )
        Text(
            text = label,
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = if (enabled) 0.86f else 0.42f),
        )
    }
}

private fun renderSignaturePng(
    strokes: List<List<Offset>>,
    widthPx: Int,
    heightPx: Int,
): ByteArray {
    val safeWidth = widthPx.coerceAtLeast(480)
    val safeHeight = heightPx.coerceAtLeast(220)
    val scaleX = safeWidth / widthPx.coerceAtLeast(1).toFloat()
    val scaleY = safeHeight / heightPx.coerceAtLeast(1).toFloat()
    val bitmap = Bitmap.createBitmap(safeWidth, safeHeight, Bitmap.Config.ARGB_8888)
    bitmap.eraseColor(AndroidColor.TRANSPARENT)
    val canvas = AndroidCanvas(bitmap)
    val paint = AndroidPaint(AndroidPaint.ANTI_ALIAS_FLAG).apply {
        color = AndroidColor.BLACK
        style = AndroidPaint.Style.STROKE
        strokeWidth = (safeWidth / 92f).coerceIn(4f, 8f)
        strokeCap = AndroidPaint.Cap.ROUND
        strokeJoin = AndroidPaint.Join.ROUND
    }
    val dotPaint = AndroidPaint(paint).apply {
        style = AndroidPaint.Style.FILL
    }

    strokes.filter { it.isNotEmpty() }.forEach { points ->
        if (points.size == 1) {
            val point = points.first()
            canvas.drawCircle(point.x * scaleX, point.y * scaleY, paint.strokeWidth / 2f, dotPaint)
        } else {
            val path = AndroidPath().apply {
                moveTo(points.first().x * scaleX, points.first().y * scaleY)
                points.drop(1).forEach { point ->
                    lineTo(point.x * scaleX, point.y * scaleY)
                }
            }
            canvas.drawPath(path, paint)
        }
    }

    return ByteArrayOutputStream().use { output ->
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, output)
        output.toByteArray()
    }
}

private fun hasSignatureLocationPermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED ||
        ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED

@SuppressLint("MissingPermission")
private fun requestSignatureGpsLocation(
    context: Context,
    onResult: (String) -> Unit,
    onError: (String) -> Unit,
) {
    if (!hasSignatureLocationPermission(context)) {
        onError("Nema dozvole za GPS lokaciju potpisa.")
        return
    }

    val locationManager = context.getSystemService(Context.LOCATION_SERVICE) as? LocationManager
    if (locationManager == null) {
        onError("GPS lokacija nije dostupna na ovom uređaju.")
        return
    }

    val hasFinePermission = ContextCompat.checkSelfPermission(
        context,
        Manifest.permission.ACCESS_FINE_LOCATION,
    ) == PackageManager.PERMISSION_GRANTED
    val candidateProviders = buildList {
        if (hasFinePermission) add(LocationManager.GPS_PROVIDER)
        add(LocationManager.NETWORK_PROVIDER)
        add(LocationManager.PASSIVE_PROVIDER)
    }.distinct()
    val enabledProviders = candidateProviders.filter { provider ->
        provider == LocationManager.PASSIVE_PROVIDER ||
            runCatching { locationManager.isProviderEnabled(provider) }.getOrDefault(false)
    }

    if (enabledProviders.isEmpty()) {
        onError("Uključi lokaciju na mobitelu pa ponovno dohvati GPS.")
        return
    }

    fun bestLocation(locations: List<Location>): Location? =
        locations
            .filter { it.latitude in -90.0..90.0 && it.longitude in -180.0..180.0 }
            .maxWithOrNull(
                compareBy<Location> { if (it.provider == LocationManager.GPS_PROVIDER) 2 else 1 }
                    .thenBy { if (it.hasAccuracy()) -it.accuracy else Float.NEGATIVE_INFINITY }
                    .thenBy { it.time },
            )

    val lastKnownLocations = enabledProviders.mapNotNull { provider ->
        runCatching { locationManager.getLastKnownLocation(provider) }.getOrNull()
    }
    val lastKnown = bestLocation(lastKnownLocations)
    val now = System.currentTimeMillis()
    if (
        lastKnown != null &&
        now - lastKnown.time <= 120_000L &&
        (!lastKnown.hasAccuracy() || lastKnown.accuracy <= 35f)
    ) {
        onResult(formatSignatureGpsLocation(lastKnown))
        return
    }

    val handler = Handler(Looper.getMainLooper())
    var completed = false
    var bestFreshLocation: Location? = lastKnown
    var timeoutRunnable: Runnable? = null
    lateinit var listener: LocationListener

    fun completeWith(location: Location?) {
        if (completed) return
        completed = true
        runCatching { locationManager.removeUpdates(listener) }
        timeoutRunnable?.let { handler.removeCallbacks(it) }
        if (location != null) {
            onResult(formatSignatureGpsLocation(location))
        } else {
            onError("GPS lokacija nije pronađena. Provjeri da je lokacija uključena.")
        }
    }

    listener = LocationListener { location ->
        bestFreshLocation = bestLocation(listOfNotNull(bestFreshLocation, location))
        val isPreciseGps = location.provider == LocationManager.GPS_PROVIDER &&
            (!location.hasAccuracy() || location.accuracy <= 50f)
        val isGoodEnough = location.hasAccuracy() && location.accuracy <= 35f
        if (isPreciseGps || isGoodEnough) {
            completeWith(location)
        }
    }

    var requestedAnyProvider = false
    enabledProviders
        .filter { it != LocationManager.PASSIVE_PROVIDER }
        .forEach { provider ->
            runCatching {
                locationManager.requestLocationUpdates(
                    provider,
                    1000L,
                    0f,
                    listener,
                    Looper.getMainLooper(),
                )
                requestedAnyProvider = true
            }
        }

    if (!requestedAnyProvider) {
        completeWith(lastKnown)
        return
    }

    val timeout = Runnable {
        completeWith(bestFreshLocation)
    }
    timeoutRunnable = timeout
    handler.postDelayed(timeout, 12_000L)
}

private fun formatSignatureGpsLocation(location: Location): String {
    val latitude = String.format(Locale.US, "%.6f", location.latitude)
    val longitude = String.format(Locale.US, "%.6f", location.longitude)
    val accuracy = if (location.hasAccuracy()) "±${Math.round(location.accuracy)} m" else "točnost nepoznata"
    val provider = when (location.provider) {
        LocationManager.GPS_PROVIDER -> "GPS"
        LocationManager.NETWORK_PROVIDER -> "mreža"
        LocationManager.PASSIVE_PROVIDER -> "zadnja lokacija"
        else -> location.provider.orEmpty().ifBlank { "lokacija" }
    }
    val timestamp = runCatching {
        LocalDateTime.ofInstant(
            Instant.ofEpochMilli(location.time.takeIf { it > 0L } ?: System.currentTimeMillis()),
            ZoneId.systemDefault(),
        ).format(DateTimeFormatter.ofPattern("dd.MM.yyyy. HH:mm"))
    }.getOrDefault(LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy. HH:mm")))
    return "$provider: $latitude, $longitude · $accuracy · dohvaćeno $timestamp"
}

@Composable
private fun SafeNexusLoadingScreen(
    rememberedUser: SafeNexusUser?,
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    listOf(Color(0xFF071326), Color(0xFF123B7A), Color(0xFFF3F7FD)),
                    startY = 0f,
                    endY = 1450f,
                ),
            )
            .padding(WindowInsets.safeDrawing.asPaddingValues())
            .padding(24.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(30.dp),
            color = Color.White.copy(alpha = 0.96f),
            shadowElevation = 18.dp,
        ) {
            Column(
                modifier = Modifier.padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp),
            ) {
                Surface(
                    modifier = Modifier.size(68.dp),
                    shape = RoundedCornerShape(22.dp),
                    color = Color(0xFFEAF2FF),
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        Text("SN", color = Color(0xFF1D4ED8), style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
                    }
                }
                Text(
                    "Učitavam SafeNexus",
                    style = MaterialTheme.typography.headlineSmall,
                    color = Color(0xFF0F172A),
                    fontWeight = FontWeight.Black,
                )
                Text(
                    rememberedUser?.displayName?.ifBlank { rememberedUser.email } ?: "Pripremam mobilni workspace",
                    style = MaterialTheme.typography.bodyMedium,
                    color = Color(0xFF64748B),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth(), color = Color(0xFF2563EB), trackColor = Color(0xFFE2E8F0))
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    LoadingChip("RN statusi")
                    LoadingChip("Dokumenti")
                    LoadingChip("Periodika")
                }
            }
        }
    }
}

@Composable
private fun LoadingChip(text: String) {
    Surface(shape = RoundedCornerShape(999.dp), color = Color(0xFFEFF6FF)) {
        Text(
            text,
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
            color = Color(0xFF1D4ED8),
            style = MaterialTheme.typography.labelMedium,
            fontWeight = FontWeight.Bold,
        )
    }
}

@Composable
private fun LoginScreen(
    isLoading: Boolean,
    error: String,
    rememberedUser: SafeNexusUser?,
    onLogin: (String, String, Boolean) -> Unit,
    onUnlockRememberedSession: () -> Unit,
) {
    var email by remember(rememberedUser?.email) { mutableStateOf(rememberedUser?.email.orEmpty()) }
    var password by remember { mutableStateOf("") }
    var rememberSession by remember { mutableStateOf(true) }
    var biometricError by remember { mutableStateOf("") }
    val context = LocalContext.current
    val displayedError = error.ifBlank { biometricError }
    val requestSavedLogin = {
        biometricError = ""
        requestBiometricLogin(
            context = context,
            onSuccess = onUnlockRememberedSession,
            onError = { biometricError = it },
        )
    }

    LaunchedEffect(rememberedUser?.email, displayedError) {
        if (rememberedUser != null && !isLoading && displayedError.isBlank()) {
            requestSavedLogin()
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    listOf(Color(0xFF061121), Color(0xFF0C2340), Color(0xFFEFF6FF)),
                    startY = 0f,
                    endY = 1500f,
                ),
            )
            .padding(WindowInsets.safeDrawing.asPaddingValues())
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 22.dp, vertical = 22.dp),
        verticalArrangement = Arrangement.Center,
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(20.dp),
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    BrandMark()
                    Surface(
                        shape = RoundedCornerShape(999.dp),
                        color = Color.White.copy(alpha = 0.12f),
                    ) {
                        Text(
                            text = "MOBILE",
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 7.dp),
                            style = MaterialTheme.typography.labelMedium,
                            color = Color(0xFFD7E8FF),
                            fontWeight = FontWeight.Black,
                        )
                    }
                }
                Text(
                    text = "SafeNexus",
                    style = MaterialTheme.typography.displaySmall,
                    color = Color.White,
                    fontWeight = FontWeight.Black,
                )
                Text(
                    text = "Radni nalozi, lokacije i rokovi spremni za teren.",
                    style = MaterialTheme.typography.titleMedium,
                    color = Color(0xFFC7D8EF),
                )
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    LoginMetricPill("RN")
                    LoginMetricPill("Karta")
                    LoginMetricPill("Sigurna sesija")
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(30.dp),
                colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.98f)),
                elevation = CardDefaults.cardElevation(defaultElevation = 16.dp),
            ) {
                Column(
                    modifier = Modifier.padding(22.dp),
                    verticalArrangement = Arrangement.spacedBy(15.dp),
                ) {
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Text(
                            text = "Prijava",
                            style = MaterialTheme.typography.headlineSmall,
                            fontWeight = FontWeight.Black,
                            color = Color(0xFF0F172A),
                        )
                        Text(
                            text = "Nastavi tamo gdje si stao.",
                            style = MaterialTheme.typography.bodyMedium,
                            color = Color(0xFF64748B),
                        )
                    }
                    if (rememberedUser != null) {
                        RememberedSessionCard(
                            user = rememberedUser,
                            isLoading = isLoading,
                            onBiometricLogin = requestSavedLogin,
                        )
                    }
                    OutlinedTextField(
                        value = email,
                        onValueChange = { email = it },
                        modifier = Modifier.fillMaxWidth(),
                        leadingIcon = { Icon(Icons.Rounded.Mail, contentDescription = null) },
                        label = { Text("Email") },
                        singleLine = true,
                        shape = RoundedCornerShape(18.dp),
                        keyboardOptions = KeyboardOptions(
                            keyboardType = KeyboardType.Email,
                            imeAction = ImeAction.Next,
                        ),
                    )
                    OutlinedTextField(
                        value = password,
                        onValueChange = { password = it },
                        modifier = Modifier.fillMaxWidth(),
                        leadingIcon = { Icon(Icons.Rounded.Lock, contentDescription = null) },
                        label = { Text("Lozinka") },
                        singleLine = true,
                        shape = RoundedCornerShape(18.dp),
                        visualTransformation = PasswordVisualTransformation(),
                        keyboardOptions = KeyboardOptions(
                            keyboardType = KeyboardType.Password,
                            imeAction = ImeAction.Done,
                        ),
                    )
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable(enabled = !isLoading) { rememberSession = !rememberSession }
                            .padding(vertical = 2.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Checkbox(
                            checked = rememberSession,
                            onCheckedChange = { rememberSession = it },
                            enabled = !isLoading,
                        )
                        Spacer(Modifier.width(6.dp))
                        Column {
                            Text("Zapamti prijavu", style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Bold)
                            Text(
                                "Automatski otvori RN-ove pri sljedecem ulasku.",
                                style = MaterialTheme.typography.labelMedium,
                                color = Color(0xFF64748B),
                            )
                        }
                    }
                    AnimatedVisibility(displayedError.isNotBlank(), enter = fadeIn(), exit = fadeOut()) {
                        MessageCard(text = displayedError, isError = true)
                    }
                    Button(
                        onClick = {
                            biometricError = ""
                            onLogin(email, password, rememberSession)
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(56.dp),
                        enabled = !isLoading,
                        shape = RoundedCornerShape(18.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2563EB)),
                    ) {
                        if (isLoading) {
                            CircularProgressIndicator(
                                modifier = Modifier.size(18.dp),
                                strokeWidth = 2.dp,
                                color = Color.White,
                            )
                        } else {
                            Text("Uđi u SafeNexus", fontWeight = FontWeight.Black)
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun LoginMetricPill(text: String) {
    Surface(
        shape = RoundedCornerShape(999.dp),
        color = Color.White.copy(alpha = 0.12f),
    ) {
        Text(
            text = text,
            modifier = Modifier.padding(horizontal = 11.dp, vertical = 7.dp),
            style = MaterialTheme.typography.labelMedium,
            color = Color(0xFFD7E8FF),
            fontWeight = FontWeight.Bold,
        )
    }
}

@Composable
private fun RememberedSessionCard(
    user: SafeNexusUser,
    isLoading: Boolean,
    onBiometricLogin: () -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(22.dp),
        color = Color(0xFFEFF6FF),
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = "Spremljena prijava",
                        style = MaterialTheme.typography.labelLarge,
                        color = Color(0xFF1D4ED8),
                        fontWeight = FontWeight.Black,
                    )
                    Text(
                        text = user.displayName.ifBlank { user.email },
                        style = MaterialTheme.typography.bodyMedium,
                        color = Color(0xFF0F172A),
                        fontWeight = FontWeight.Bold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Icon(
                    imageVector = Icons.Rounded.Fingerprint,
                    contentDescription = null,
                    tint = Color(0xFF2563EB),
                    modifier = Modifier.size(34.dp),
                )
            }
            Button(
                onClick = onBiometricLogin,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp),
                enabled = !isLoading,
                shape = RoundedCornerShape(16.dp),
                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0F172A)),
            ) {
                Icon(Icons.Rounded.Fingerprint, contentDescription = null)
                Spacer(Modifier.width(8.dp))
                Text("Otključaj otiskom", fontWeight = FontWeight.Black)
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun WorkOrderCreateScreen(
    data: BootstrapData,
    directoryCompanies: List<MobileRecord>,
    directoryCompanyTotal: Int,
    directoryCompanyLoading: Boolean,
    directoryCompanyHasMore: Boolean,
    directoryLocationsByCompany: Map<String, List<MobileRecord>>,
    directoryLocationLoading: Set<String>,
    directoryLocationHasMoreByCompany: Map<String, Boolean>,
    initialDraft: WorkOrderCreateDraft?,
    isLoading: Boolean,
    error: String,
    onBack: () -> Unit,
    onSave: (WorkOrderCreateDraft) -> Unit,
    onCreateLocation: (WorkOrderLocationCreateDraft, (WorkOrderLocationOption) -> Unit) -> Unit,
    onLoadMoreCompanies: () -> Unit,
    onLoadCompanyLocations: (MobileRecord) -> Unit,
    onLoadMoreCompanyLocations: (MobileRecord) -> Unit,
) {
    var companyId by remember(initialDraft) { mutableStateOf(initialDraft?.companyId.orEmpty()) }
    var locationId by remember(initialDraft) { mutableStateOf(initialDraft?.locationId.orEmpty()) }
    var status by remember(data.workOrderStatuses, initialDraft) { mutableStateOf(initialDraft?.status?.ifBlank { null } ?: data.workOrderStatuses.firstOrNull()?.value ?: "Otvoreni RN") }
    var openedDate by remember(initialDraft) { mutableStateOf(initialDraft?.openedDate?.ifBlank { null } ?: LocalDate.now().toString()) }
    var dueDate by remember(initialDraft) { mutableStateOf(initialDraft?.dueDate.orEmpty()) }
    var executionDate by remember(initialDraft) { mutableStateOf(initialDraft?.executionDate.orEmpty()) }
    var priority by remember(data.priorities, initialDraft) { mutableStateOf(initialDraft?.priority?.ifBlank { null } ?: data.priorities.firstOrNull { it.value == "Normal" }?.value ?: "Normal") }
    var serviceLine by remember(initialDraft) { mutableStateOf(initialDraft?.serviceLine.orEmpty()) }
    var description by remember(initialDraft) { mutableStateOf(initialDraft?.description.orEmpty()) }
    var selectedServiceIds by remember(initialDraft) { mutableStateOf(initialDraft?.serviceIds.orEmpty()) }
    var selectedExecutors by remember(initialDraft) { mutableStateOf(initialDraft?.executors.orEmpty()) }
    var contactName by remember(initialDraft) { mutableStateOf(initialDraft?.contactName.orEmpty()) }
    var contactPhone by remember(initialDraft) { mutableStateOf(initialDraft?.contactPhone.orEmpty()) }
    var contactEmail by remember(initialDraft) { mutableStateOf(initialDraft?.contactEmail.orEmpty()) }
    var selectedTags by remember(initialDraft) {
        mutableStateOf(initialDraft?.tagText.orEmpty().split(",", ";").map { it.trim().trim('#') }.filter { it.isNotBlank() })
    }
    var invoiceNote by remember(initialDraft) { mutableStateOf(initialDraft?.invoiceNote.orEmpty()) }
    var linkReference by remember(initialDraft) { mutableStateOf(initialDraft?.linkReference.orEmpty()) }
    var showNewLocationForm by remember { mutableStateOf(false) }
    var newLocationName by remember { mutableStateOf("") }
    var newLocationRegion by remember { mutableStateOf("") }
    var newLocationCoordinates by remember { mutableStateOf("") }
    var newLocationContactName by remember { mutableStateOf("") }
    var newLocationContactPhone by remember { mutableStateOf("") }
    var newLocationContactEmail by remember { mutableStateOf("") }
    var newLocationNote by remember { mutableStateOf("") }
    val companyRecordsById = remember(directoryCompanies) {
        directoryCompanies.associateBy { record -> record.id }
    }
    val companyOptionsForCreate = remember(directoryCompanies, data.workOrderCompanies) {
        (directoryCompanies.map { record -> record.toWorkOrderCompanyOption() } + data.workOrderCompanies.take(20))
            .distinctBy { it.id }
            .sortedBy { it.name.lowercase(Locale.getDefault()) }
    }
    val company = companyOptionsForCreate.firstOrNull { it.id == companyId }
    val selectedCompanyRecord = companyRecordsById[companyId]
    val availableLocations = remember(companyId, directoryLocationsByCompany, data.workOrderLocations) {
        val remoteLocations = directoryLocationsByCompany[companyId].orEmpty().map { record -> record.toWorkOrderLocationOption(companyId) }
        (remoteLocations + data.workOrderLocations.filter { location -> location.companyId == companyId }.take(20))
            .distinctBy { it.id }
            .sortedBy { it.name.lowercase(Locale.getDefault()) }
    }
    val selectedLocation = availableLocations.firstOrNull { it.id == locationId }
    val locationLoading = companyId in directoryLocationLoading
    val locationHasMore = directoryLocationHasMoreByCompany[companyId] ?: false
    val tagSuggestions = remember(data.workOrders) {
        (
            data.workOrders.flatMap { it.tags } +
                listOf("Teren", "Papir", "Hitno")
            )
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .sortedBy { it.lowercase(Locale.getDefault()) }
            .take(24)
    }
    val relatedWorkOrderOptions = remember(data.workOrders, companyId) {
        data.workOrders
            .filter { it.id.isNotBlank() || it.number.isNotBlank() }
            .sortedWith(
                compareByDescending<WorkOrder> { companyId.isNotBlank() && it.companyId == companyId }
                    .thenByDescending { it.parsedOpenedDate ?: it.parsedDueDate ?: LocalDate.MIN },
            )
            .take(80)
            .map { workOrder ->
                val numberLabel = workOrder.displayNumber
                WorkOrderPickerOption(
                    value = "RN $numberLabel",
                    label = "RN $numberLabel",
                    meta = listOf(workOrder.companyName, workOrder.locationName, workOrder.status)
                        .filter { it.isNotBlank() }
                        .joinToString(" · "),
                    searchText = listOf(numberLabel, workOrder.companyName, workOrder.locationName, workOrder.status)
                        .filter { it.isNotBlank() }
                        .joinToString(" "),
                )
            }
    }
    val serviceTabs = remember {
        listOf(
            WorkOrderServiceFilterTab("ispitivanja", "Ispitivanja", Icons.Rounded.Tune),
            WorkOrderServiceFilterTab("znr", "ZNR", Icons.Rounded.Work),
            WorkOrderServiceFilterTab("ostalo", "Ostalo", Icons.Rounded.FilterList),
        )
    }
    val serviceFilterById = remember(data.workOrderServices) {
        data.workOrderServices.associate { service -> service.id to service.workOrderServiceFilterKey() }
    }
    val serviceCounts = remember(data.workOrderServices) {
        serviceTabs.associate { tab ->
            tab.key to data.workOrderServices.count { service -> service.workOrderServiceFilterKey() == tab.key }
        }
    }
    var selectedServiceFilter by remember(data.workOrderServices) {
        mutableStateOf(serviceTabs.firstOrNull { tab -> (serviceCounts[tab.key] ?: 0) > 0 }?.key ?: "ispitivanja")
    }
    val filteredServices = remember(data.workOrderServices, selectedServiceFilter) {
        data.workOrderServices
            .filter { service -> service.workOrderServiceFilterKey() == selectedServiceFilter }
            .sortedBy { service -> service.name.lowercase(Locale.getDefault()) }
    }
    fun syncServiceLine(ids: List<String>) {
        val selectedNames = data.workOrderServices
            .filter { service -> service.id in ids }
            .map { service -> service.name.ifBlank { service.serviceCode } }
            .filter { it.isNotBlank() }
        serviceLine = selectedNames.joinToString(" · ")
    }
    fun setCreateServiceChecked(service: WorkOrderServiceOption, checked: Boolean) {
        val category = serviceFilterById[service.id] ?: service.workOrderServiceFilterKey()
        selectedServiceFilter = category
        val nextIds = if (checked) {
            selectedServiceIds.filter { serviceFilterById[it] == category } + service.id
        } else {
            selectedServiceIds - service.id
        }.distinct()
        selectedServiceIds = nextIds
        syncServiceLine(nextIds)
    }
    fun applyLocationSelection(location: WorkOrderLocationOption?) {
        locationId = location?.id.orEmpty()
        contactName = location?.contactName1.orEmpty()
        contactPhone = location?.contactPhone1.orEmpty()
        contactEmail = location?.contactEmail1.orEmpty()
    }
    fun clearNewLocationDraft() {
        newLocationName = ""
        newLocationRegion = ""
        newLocationCoordinates = ""
        newLocationContactName = ""
        newLocationContactPhone = ""
        newLocationContactEmail = ""
        newLocationNote = ""
    }

    LaunchedEffect(companyId, availableLocations) {
        if (companyId.isBlank()) return@LaunchedEffect
        selectedCompanyRecord?.let { companyRecord ->
            if (!directoryLocationsByCompany.containsKey(companyId) && companyId !in directoryLocationLoading) {
                onLoadCompanyLocations(companyRecord)
            }
        }
        if (locationId.isNotBlank() && availableLocations.none { it.id == locationId }) {
            applyLocationSelection(null)
        }
        if (locationId.isBlank() && availableLocations.size == 1) {
            applyLocationSelection(availableLocations.first())
        }
        if (availableLocations.isEmpty()) {
            showNewLocationForm = true
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
                    }
                },
                title = {
                    Column {
                        Text("Novi radni nalog", fontWeight = FontWeight.Bold)
                        Text("Broj RN-a dodjeljuje se automatski", style = MaterialTheme.typography.labelMedium)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.background),
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize(),
            contentPadding = PaddingValues(18.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            item {
                Card(
                    shape = RoundedCornerShape(26.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
                ) {
                    Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        Text("Osnovni podaci", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
                        DetailRow(Icons.Rounded.Work, "Broj radnog naloga", "Automatski nakon spremanja")
                        WorkOrderSearchSelectField(
                            label = "Naručitelj",
                            value = companyId,
                            valueLabel = company?.name.orEmpty(),
                            options = companyOptionsForCreate.map { companyOption ->
                                WorkOrderPickerOption(
                                    value = companyOption.id,
                                    label = companyOption.name,
                                    meta = listOf(
                                        companyOption.headquarters.takeIf { it.isNotBlank() },
                                        companyOption.oib.takeIf { it.isNotBlank() }?.let { "OIB $it" },
                                    ).filterNotNull().joinToString(" · "),
                                    searchText = listOf(companyOption.name, companyOption.headquarters, companyOption.oib)
                                        .filter { it.isNotBlank() }
                                        .joinToString(" "),
                                )
                            },
                            enabled = !isLoading,
                            icon = Icons.Rounded.Business,
                            searchPlaceholder = "Traži tvrtku, sjedište ili OIB",
                            emptyText = "Nema tvrtki za taj pojam.",
                            isLoadingMore = directoryCompanyLoading,
                            hasMore = directoryCompanyHasMore,
                            loadMoreLabel = if (directoryCompanyTotal > 0) {
                                "Učitaj još tvrtki (${companyOptionsForCreate.size}/$directoryCompanyTotal)"
                            } else {
                                "Učitaj još tvrtki"
                            },
                            onLoadMore = onLoadMoreCompanies,
                            onSelect = { next ->
                                val nextLocations = (
                                    directoryLocationsByCompany[next].orEmpty().map { record -> record.toWorkOrderLocationOption(next) } +
                                        data.workOrderLocations.filter { location -> location.companyId == next }.take(20)
                                    ).distinctBy { it.id }
                                companyId = next
                                clearNewLocationDraft()
                                showNewLocationForm = next.isNotBlank() && nextLocations.isEmpty() && next !in directoryLocationLoading
                                applyLocationSelection(nextLocations.singleOrNull())
                                companyRecordsById[next]?.let { companyRecord ->
                                    if (!directoryLocationsByCompany.containsKey(next)) {
                                        onLoadCompanyLocations(companyRecord)
                                    }
                                }
                            },
                        )
                        WorkOrderSearchSelectField(
                            label = "Lokacija",
                            value = locationId,
                            valueLabel = selectedLocation?.name.orEmpty(),
                            options = availableLocations.map { location ->
                                WorkOrderPickerOption(
                                    value = location.id,
                                    label = location.name,
                                    meta = listOf(location.region, location.coordinates).filter { it.isNotBlank() }.joinToString(" · "),
                                    searchText = listOf(
                                        location.name,
                                        location.region,
                                        location.coordinates,
                                        location.contactName1,
                                        location.contactPhone1,
                                        location.contactEmail1,
                                    ).filter { it.isNotBlank() }.joinToString(" "),
                                )
                            },
                            enabled = !isLoading && companyId.isNotBlank(),
                            icon = Icons.Rounded.LocationOn,
                            searchPlaceholder = "Traži lokaciju, regiju ili koordinate",
                            emptyText = if (companyId.isBlank()) "Prvo odaberi naručitelja." else if (locationLoading) "Učitavam lokacije..." else "Nema lokacija za taj pojam.",
                            isLoadingMore = locationLoading,
                            hasMore = locationHasMore,
                            loadMoreLabel = "Učitaj još lokacija",
                            onLoadMore = {
                                selectedCompanyRecord?.let(onLoadMoreCompanyLocations)
                            },
                            onSelect = { next ->
                                applyLocationSelection(availableLocations.firstOrNull { it.id == next })
                                showNewLocationForm = false
                            },
                        )
                        if (companyId.isNotBlank()) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    if (availableLocations.size == 1 && locationId.isNotBlank()) {
                                        "Jedina lokacija je automatski odabrana."
                                    } else {
                                        "${availableLocations.size} lokacija za naručitelja"
                                    },
                                    style = MaterialTheme.typography.labelMedium,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                )
                                TextButton(
                                    onClick = { showNewLocationForm = !showNewLocationForm },
                                    enabled = !isLoading,
                                ) {
                                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                                    Spacer(Modifier.width(4.dp))
                                    Text(if (showNewLocationForm) "Sakrij" else "Nova lokacija")
                                }
                            }
                        }
                        AnimatedVisibility(companyId.isNotBlank() && (showNewLocationForm || availableLocations.isEmpty())) {
                            Surface(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(20.dp),
                                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.78f),
                            ) {
                                Column(
