@Composable
private fun ExpandableFormSection(
    title: String,
    summary: String,
    initiallyExpanded: Boolean,
    content: @Composable ColumnScope.() -> Unit,
) {
    var expanded by remember { mutableStateOf(initiallyExpanded) }
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(22.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
    ) {
        Column(modifier = Modifier.padding(15.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { expanded = !expanded },
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                    Text(
                        summary.ifBlank { "Opcionalno" },
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Surface(shape = CircleShape, color = MaterialTheme.colorScheme.surfaceVariant) {
                    Text(
                        text = if (expanded) "-" else "+",
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
                        fontWeight = FontWeight.Black,
                    )
                }
            }
            AnimatedVisibility(expanded) {
                Column(verticalArrangement = Arrangement.spacedBy(11.dp), content = content)
            }
        }
    }
}

@Composable
private fun WorkOrderCreateTagSelector(
    selectedTags: List<String>,
    suggestions: List<String>,
    enabled: Boolean,
    onChange: (List<String>) -> Unit,
) {
    var draftTag by remember { mutableStateOf("") }
    var expanded by remember { mutableStateOf(false) }
    val normalizedSelected = remember(selectedTags) {
        selectedTags
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
    }
    val visibleSuggestions = remember(suggestions, normalizedSelected) {
        suggestions
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .filterNot { suggestion -> normalizedSelected.any { it.equals(suggestion, ignoreCase = true) } }
            .take(14)
    }

    fun setTags(tags: List<String>) {
        onChange(
            tags
                .map { it.trim().trim('#') }
                .filter { it.isNotBlank() }
                .distinctBy { it.lowercase(Locale.getDefault()) },
        )
    }

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Surface(
            modifier = Modifier
                .fillMaxWidth()
                .clickable(enabled = enabled) { expanded = !expanded },
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.surface,
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.38f)),
        ) {
            Row(
                modifier = Modifier.padding(horizontal = 14.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Icon(Icons.Rounded.FilterList, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    Text("Tagovi", fontWeight = FontWeight.Black)
                    if (normalizedSelected.isEmpty()) {
                        Text(
                            "Odaberi postojece ili dodaj novi tag",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    } else {
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            normalizedSelected.take(4).forEach { tag ->
                                WorkOrderHeaderMetaChip(
                                    label = tag,
                                    style = workOrderTagStyle(tag),
                                )
                            }
                            if (normalizedSelected.size > 4) {
                                WorkOrderHeaderMetaChip(
                                    label = "+${normalizedSelected.size - 4}",
                                    style = WorkOrderMetaChipStyle(
                                        background = Color(0xFFF8FAFC),
                                        border = Color(0xFFCBD5E1),
                                        content = Color(0xFF475569),
                                    ),
                                )
                            }
                        }
                    }
                }
                Icon(
                    if (expanded) Icons.Rounded.ExpandLess else Icons.Rounded.ExpandMore,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                )
            }
        }
        AnimatedVisibility(expanded) {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                if (normalizedSelected.isNotEmpty()) {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        normalizedSelected.forEach { tag ->
                            WorkOrderEditableTagChip(
                                tag = tag,
                                icon = Icons.Rounded.Close,
                                enabled = enabled,
                                onClick = { setTags(normalizedSelected.filterNot { it.equals(tag, ignoreCase = true) }) },
                            )
                        }
                    }
                }
                if (visibleSuggestions.isNotEmpty()) {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        visibleSuggestions.forEach { suggestion ->
                            WorkOrderEditableTagChip(
                                tag = suggestion,
                                icon = Icons.Rounded.Add,
                                enabled = enabled,
                                onClick = { setTags(normalizedSelected + suggestion) },
                            )
                        }
                    }
                }
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
                    OutlinedTextField(
                        value = draftTag,
                        onValueChange = { draftTag = it },
                        modifier = Modifier.weight(1f),
                        enabled = enabled,
                        label = { Text("Dodaj tag") },
                        singleLine = true,
                        shape = RoundedCornerShape(16.dp),
                    )
                    OutlinedButton(
                        onClick = {
                            setTags(normalizedSelected + draftTag)
                            draftTag = ""
                        },
                        enabled = enabled && draftTag.trim().trim('#').isNotBlank(),
                        shape = RoundedCornerShape(16.dp),
                        contentPadding = PaddingValues(horizontal = 14.dp, vertical = 14.dp),
                    ) {
                        Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                    }
                }
            }
        }
    }
}

@Composable
private fun WorkOrderTextField(
    label: String,
    value: String,
    onChange: (String) -> Unit,
    enabled: Boolean,
    singleLine: Boolean = true,
    minLines: Int = 1,
