        maxLines = maxLines,
        enabled = enabled,
        shape = RoundedCornerShape(16.dp),
    )
}

@Composable
private fun DocumentationMobileFieldShell(
    label: String,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    minHeight: Dp = 76.dp,
    onClick: (() -> Unit)? = null,
    trailing: (@Composable RowScope.() -> Unit)? = null,
    content: @Composable ColumnScope.() -> Unit,
) {
    val shape = RoundedCornerShape(17.dp)
    Surface(
        modifier = modifier
            .fillMaxWidth()
            .then(
                if (onClick != null) {
                    Modifier
                        .clip(shape)
                        .clickable(enabled = enabled, onClick = onClick)
                } else {
                    Modifier
                },
            ),
        shape = shape,
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.92f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.32f)),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = minHeight)
                .padding(horizontal = 14.dp, vertical = 10.dp),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(3.dp),
            ) {
                Text(
                    label,
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                content()
            }
            if (trailing != null) {
                trailing()
            }
        }
    }
}

@Composable
private fun DocumentationMobileTextField(
    label: String,
    value: String,
    onChange: (String) -> Unit,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    singleLine: Boolean = true,
    minLines: Int = 1,
    maxLines: Int = if (singleLine) 1 else 6,
    keyboardOptions: KeyboardOptions = KeyboardOptions.Default,
) {
    val valueStyle = if (singleLine) MaterialTheme.typography.bodyLarge else MaterialTheme.typography.bodyMedium
    DocumentationMobileFieldShell(
        label = label,
        modifier = modifier,
        enabled = enabled,
        minHeight = if (singleLine) 76.dp else 118.dp,
    ) {
        BasicTextField(
            value = value,
            onValueChange = onChange,
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = if (singleLine) 26.dp else 78.dp),
            enabled = enabled,
            singleLine = singleLine,
            minLines = minLines,
            maxLines = maxLines,
            keyboardOptions = keyboardOptions,
            textStyle = valueStyle.copy(
                color = MaterialTheme.colorScheme.onSurface,
                fontWeight = if (singleLine) FontWeight.SemiBold else FontWeight.Normal,
            ),
            cursorBrush = SolidColor(MaterialTheme.colorScheme.primary),
            decorationBox = { innerTextField ->
                Box(modifier = Modifier.fillMaxWidth()) {
                    if (value.isBlank()) {
                        Text(
                            "Upiši vrijednost",
                            style = valueStyle,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.36f),
                            maxLines = if (singleLine) 1 else maxLines,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    innerTextField()
                }
            },
        )
    }
}

@Composable
private fun DocumentationSprVoiceField(
    label: String,
    value: String,
    onChange: (String) -> Unit,
    onVoiceApply: (String, Boolean) -> Unit = { nextValue, _ -> onChange(nextValue) },
    onVoicePreview: (String) -> Unit = {},
    voicePreviewRows: List<SprVoiceAiRow> = emptyList(),
    voicePreviewLoading: Boolean = false,
    voicePreviewMessage: String = "",
    enabled: Boolean,
) {
    var message by remember { mutableStateOf("") }
    var pendingSpoken by remember { mutableStateOf("") }
    fun applySpoken(replaceExisting: Boolean) {
        val spoken = pendingSpoken.trim()
        if (spoken.isBlank()) return
        pendingSpoken = ""
        onVoiceApply(encodeSprVoiceAction(spoken, replaceExisting), replaceExisting)
        message = if (replaceExisting) {
            "Gridline tablica je zamijenjena diktatom: $spoken"
        } else {
            "Dodano ispod zadnjeg reda u Gridline tablici: $spoken"
        }
    }
    val launcher = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode != Activity.RESULT_OK) return@rememberLauncherForActivityResult
        val spoken = result.data
            ?.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)
            ?.firstOrNull()
            ?.trim()
            .orEmpty()
        if (spoken.isNotBlank()) {
            pendingSpoken = spoken
            onVoicePreview(spoken)
        }
    }
    fun startSpeechInput() {
        message = ""
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, "hr-HR")
            putExtra(RecognizerIntent.EXTRA_PROMPT, "Npr. Prodajni prostor 7 panika, skladiste 6")
        }
        try {
            launcher.launch(intent)
        } catch (_: ActivityNotFoundException) {
            message = "Glasovni unos nije dostupan na ovom uredaju."
        }
    }
    if (pendingSpoken.isNotBlank()) {
        val localPreviewRows = remember(pendingSpoken) { parseSprVoiceTranscriptToAiRows(pendingSpoken) }
        val dialogPreviewRows = voicePreviewRows.ifEmpty { localPreviewRows }
        val dialogPreviewLoading = voicePreviewLoading && dialogPreviewRows.isEmpty()
        AlertDialog(
            onDismissRequest = { pendingSpoken = "" },
            title = { Text("Provjeri diktat", fontWeight = FontWeight.Black) },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 420.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    Text(
                        pendingSpoken,
                        style = MaterialTheme.typography.bodyMedium,
                        fontWeight = FontWeight.SemiBold,
                    )
                    if (dialogPreviewLoading) {
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
                            CircularProgressIndicator(modifier = Modifier.size(17.dp), strokeWidth = 2.dp)
                            Text(
                                "NexAI priprema pregled...",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                            )
                        }
                    } else if (dialogPreviewRows.isNotEmpty()) {
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(14.dp),
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f),
                        ) {
                            Column(modifier = Modifier.padding(9.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                ) {
                                    Text(
                                        "Mjesto ispitivanja",
                                        modifier = Modifier.weight(1f),
                                        style = MaterialTheme.typography.labelSmall,
                                        fontWeight = FontWeight.Black,
                                    )
                                    Text(
                                        "Količina",
                                        modifier = Modifier.width(70.dp),
                                        style = MaterialTheme.typography.labelSmall,
                                        fontWeight = FontWeight.Black,
                                        textAlign = TextAlign.End,
                                    )
                                }
                                dialogPreviewRows.forEachIndexed { index, row ->
                                    val isSection = row.kind.equals("section", ignoreCase = true) || row.lampCount.isBlank()
                                    if (isSection) {
                                        Text(
                                            row.place,
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clip(RoundedCornerShape(11.dp))
                                                .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.12f))
                                                .padding(horizontal = 9.dp, vertical = 8.dp),
                                            style = MaterialTheme.typography.bodySmall,
                                            fontWeight = FontWeight.Black,
                                            color = MaterialTheme.colorScheme.primary,
                                        )
                                    } else {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clip(RoundedCornerShape(11.dp))
                                                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.82f))
                                                .padding(horizontal = 8.dp, vertical = 7.dp),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                        ) {
                                            Text(
                                                "${index + 1}. ${row.place}",
                                                modifier = Modifier.weight(1f),
                                                style = MaterialTheme.typography.bodySmall,
                                                fontWeight = FontWeight.SemiBold,
                                            )
                                            Text(
                                                row.lampCount,
                                                modifier = Modifier.width(70.dp),
                                                style = MaterialTheme.typography.bodySmall,
                                                fontWeight = FontWeight.Black,
                                                color = MaterialTheme.colorScheme.primary,
                                                textAlign = TextAlign.End,
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        Text(
                            "Nema prepoznatih redaka. Pokušaj diktirati kao: Prodajni prostor 7, skladište 6.",
                            style = MaterialTheme.typography.bodySmall,
                            color = Color(0xFFB91C1C),
                            fontWeight = FontWeight.SemiBold,
                        )
                    }
                    if (voicePreviewMessage.isNotBlank()) {
                        Text(
                            voicePreviewMessage,
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                        )
                    }
                    Text(
                        "Ovaj izbor vrijedi za Gridline tablicu. Dodaj u tablicu uvijek dodaje ispod zadnjeg popunjenog reda i ne mijenja postojeće nazive. Zamijeni tablicu briše samo kolone mjesto ispitivanja i količina pa upisuje ovaj pregled od prvog reda.",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                    )
                }
            },
            confirmButton = {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    OutlinedButton(
                        onClick = { applySpoken(replaceExisting = false) },
                        enabled = enabled && !dialogPreviewLoading && dialogPreviewRows.isNotEmpty(),
                        shape = RoundedCornerShape(14.dp),
                    ) {
                        Text("Dodaj", fontWeight = FontWeight.Bold)
                    }
                    Button(
                        onClick = { applySpoken(replaceExisting = true) },
                        enabled = enabled && !dialogPreviewLoading && dialogPreviewRows.isNotEmpty(),
                        shape = RoundedCornerShape(14.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDC2626)),
                    ) {
                        Text("Zamijeni", fontWeight = FontWeight.Bold)
                    }
                }
            },
        )
    }
    Column(verticalArrangement = Arrangement.spacedBy(7.dp)) {
        DocumentationMobileFieldShell(
            label = label,
            enabled = enabled,
            minHeight = 148.dp,
            trailing = {
                IconButton(onClick = ::startSpeechInput, enabled = enabled) {
                    Icon(Icons.Rounded.Mic, contentDescription = "Glasovni unos", tint = MaterialTheme.colorScheme.primary)
                }
            },
        ) {
            BasicTextField(
                value = value,
                onValueChange = onChange,
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(min = 88.dp),
                enabled = enabled,
                singleLine = false,
                minLines = 3,
                maxLines = 8,
                textStyle = MaterialTheme.typography.bodyMedium.copy(color = MaterialTheme.colorScheme.onSurface),
                cursorBrush = SolidColor(MaterialTheme.colorScheme.primary),
                decorationBox = { innerTextField ->
                    Box(modifier = Modifier.fillMaxWidth()) {
                        if (value.isBlank()) {
                            Text(
                                "Prodajni prostor 7 panika, skladiste 6",
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.36f),
                            )
                        }
                        innerTextField()
                    }
                },
            )
        }
        if (message.isNotBlank()) {
            Text(
                message,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.SemiBold,
            )
        }
    }
}

private fun appendSprVoiceTranscript(existing: String, spoken: String): String =
    listOf(existing.trim(), spoken.trim())
        .filter { it.isNotBlank() }
        .joinToString("\n")

@Composable
private fun DocumentationMobileDatePickerField(
    label: String,
    value: String,
    onChange: (String) -> Unit,
    enabled: Boolean,
    modifier: Modifier = Modifier,
) {
    var openPicker by remember { mutableStateOf(false) }
    DocumentationMobileFieldShell(
        label = label,
