@Composable
private fun WorkOrderSearchSelectField(
    label: String,
    value: String,
    valueLabel: String,
    options: List<WorkOrderPickerOption>,
    enabled: Boolean,
    onSelect: (String) -> Unit,
    modifier: Modifier = Modifier,
    icon: ImageVector = Icons.Rounded.Search,
    searchPlaceholder: String = "Traži",
    emptyText: String = "Nema rezultata.",
    isLoadingMore: Boolean = false,
    hasMore: Boolean = false,
    loadMoreLabel: String = "Učitaj još",
    onLoadMore: (() -> Unit)? = null,
) {
    var open by remember { mutableStateOf(false) }
    var query by remember { mutableStateOf("") }
    val filteredOptions = remember(options, query) {
        val normalizedQuery = query.normalizedPickerText()
        if (normalizedQuery.isBlank()) {
            options
        } else {
            options.filter { option -> option.matchesPickerQuery(normalizedQuery) }
        }
    }
    val visibleOptions = filteredOptions.take(120)

    OutlinedButton(
        onClick = {
            query = ""
            open = true
        },
        modifier = modifier.fillMaxWidth(),
        enabled = enabled && options.isNotEmpty(),
        shape = RoundedCornerShape(16.dp),
        contentPadding = PaddingValues(horizontal = 14.dp, vertical = 13.dp),
    ) {
        Icon(icon, contentDescription = null, modifier = Modifier.size(20.dp))
        Spacer(Modifier.width(10.dp))
        Column(modifier = Modifier.weight(1f), horizontalAlignment = Alignment.Start) {
            Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
            Text(
                valueLabel.ifBlank { "Odaberi" },
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }

    if (open) {
        AlertDialog(
            onDismissRequest = { open = false },
            title = { Text(label, fontWeight = FontWeight.Black) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    OutlinedTextField(
                        value = query,
                        onValueChange = { query = it },
                        modifier = Modifier.fillMaxWidth(),
                        label = { Text(searchPlaceholder) },
                        leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
                        shape = RoundedCornerShape(16.dp),
                    )
                    if (visibleOptions.isEmpty()) {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(emptyText, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
                            if (onLoadMore != null && (hasMore || isLoadingMore)) {
                                OutlinedButton(
                                    onClick = onLoadMore,
                                    enabled = !isLoadingMore && hasMore,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(14.dp),
                                ) {
                                    if (isLoadingMore) {
                                        CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                                        Spacer(Modifier.width(8.dp))
                                    }
                                    Text(if (isLoadingMore) "Učitavam..." else loadMoreLabel)
                                }
                            }
                        }
                    } else {
                        LazyColumn(
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(max = 420.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            items(visibleOptions, key = { option -> option.value }) { option ->
                                val selected = option.value == value
                                Surface(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(16.dp))
                                        .clickable {
                                            onSelect(option.value)
                                            open = false
                                        },
                                    shape = RoundedCornerShape(16.dp),
                                    color = if (selected) {
                                        MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.86f)
                                    } else {
                                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.48f)
                                    },
                                ) {
                                    Row(
                                        modifier = Modifier.padding(12.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                    ) {
                                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                                            Text(
                                                option.label.ifBlank { "Odaberi" },
                                                fontWeight = if (selected) FontWeight.Black else FontWeight.Bold,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis,
                                            )
                                            if (option.meta.isNotBlank()) {
                                                Text(
                                                    option.meta,
                                                    style = MaterialTheme.typography.bodySmall,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                                    maxLines = 2,
                                                    overflow = TextOverflow.Ellipsis,
                                                )
                                            }
                                        }
                                        if (selected) {
                                            Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                                        }
                                    }
                                }
                            }
                            if (filteredOptions.size > visibleOptions.size) {
                                item {
                                    Text(
                                        "Prikazano ${visibleOptions.size} od ${filteredOptions.size}; suzi pretragu za ostatak.",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                    )
                                }
                            }
                            if (onLoadMore != null && (hasMore || isLoadingMore)) {
                                item {
                                    OutlinedButton(
                                        onClick = onLoadMore,
                                        enabled = !isLoadingMore && hasMore,
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(14.dp),
                                    ) {
                                        if (isLoadingMore) {
                                            CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                                            Spacer(Modifier.width(8.dp))
                                        }
                                        Text(if (isLoadingMore) "Učitavam..." else loadMoreLabel)
                                    }
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                TextButton(onClick = { open = false }) {
                    Text("Zatvori")
                }
            },
        )
    }
}

private fun WorkOrderPickerOption.matchesPickerQuery(normalizedQuery: String): Boolean {
    val haystack = listOf(label, meta, searchText).joinToString(" ").normalizedPickerText()
    return normalizedQuery.split(' ')
        .filter { it.isNotBlank() }
        .all { token -> haystack.contains(token) }
}

private fun String.normalizedPickerText(): String =
    lowercase(Locale.getDefault())
        .replace("š", "s")
        .replace("ž", "z")
        .replace("č", "c")
        .replace("ć", "c")
        .replace("đ", "d")
        .trim()

@Composable
private fun WorkOrderMultiSelectChips(
    options: List<Pair<String, String>>,
    selected: List<String>,
    enabled: Boolean,
    emptyText: String,
    onToggle: (String) -> Unit,
) {
    if (options.isEmpty()) {
        Text(emptyText, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
        return
    }
    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        options.take(80).forEach { option ->
            FilterChip(
                selected = option.first in selected,
                onClick = { onToggle(option.first) },
                enabled = enabled,
                label = {
                    Text(option.second, maxLines = 1, overflow = TextOverflow.Ellipsis)
                },
            )
        }
    }
}

private fun fieldInquiryStatusLabel(status: String): String {
    val normalized = if (status == "next_week_job") "next_week" else status
    return fieldInquiryStatusOptions.firstOrNull { it.first == normalized }?.second ?: normalized.ifBlank { "Upit" }
}

private fun fieldInquiryId(record: MobileRecord): String =
    record.id.removePrefix("field-inquiry:").ifBlank { record.id }

private fun reminderStatusValue(record: MobileRecord): String =
    record.meta["statusValue"].orEmpty().ifBlank { record.status }.trim().lowercase(Locale.getDefault()).let { raw ->
        when (raw.normalizedPickerText().replace(" ", "_").replace("-", "_")) {
            "aktivan", "active", "otvoren", "otvoreno" -> "active"
            "odgoden", "odgodeno", "snoozed", "odlozen", "odlozeno" -> "snoozed"
            "gotov", "gotovo", "done", "completed", "zavrsen", "zavrseno" -> "done"
            else -> raw.ifBlank { "active" }
        }
    }

private fun reminderStatusLabel(status: String, options: List<OptionItem>): String =
    options.firstOrNull { it.value == status }?.label ?: fallbackReminderStatusOptions.firstOrNull { it.value == status }?.label ?: status

private fun reminderStatusAccent(status: String): Color = when (status) {
    "done" -> Color(0xFF16A34A)
    "snoozed" -> Color(0xFFB45309)
    else -> Color(0xFF64748B)
}

private fun filteredRemindersByStatus(records: List<MobileRecord>, status: String): List<MobileRecord> =
    records
        .filter { record -> status == "all" || reminderStatusValue(record) == status }
        .sortedWith(
            compareBy<MobileRecord> { if (reminderStatusValue(it) == "done") 1 else 0 }
                .thenBy { it.parsedDate ?: LocalDate.MAX }
                .thenByDescending { it.meta["updatedAt"].orEmpty() },
        )

private fun todoTaskStatusValue(record: MobileRecord): String =
    record.meta["statusValue"].orEmpty().ifBlank { record.status }.trim().lowercase(Locale.getDefault()).let { raw ->
        when (raw.normalizedPickerText().replace(" ", "_").replace("-", "_")) {
            "novo", "open", "otvoreno", "aktivan", "active" -> "open"
            "u_radu", "in_progress", "inprogress", "progress" -> "in_progress"
            "ceka_odgovor", "waiting", "odgoden", "odgodeno" -> "waiting"
            "gotov", "gotovo", "done", "completed", "zavrsen", "zavrseno" -> "done"
            else -> raw.ifBlank { "open" }
        }
    }

private fun todoTaskStatusLabel(status: String, options: List<OptionItem>): String =
    options.firstOrNull { it.value == status }?.label ?: fallbackTodoTaskStatusOptions.firstOrNull { it.value == status }?.label ?: status

private fun todoTaskStatusAccent(status: String): Color = when (status) {
    "done" -> Color(0xFF16A34A)
    "in_progress" -> Color(0xFF2563EB)
    "waiting" -> Color(0xFFB45309)
    else -> Color(0xFF64748B)
}

private fun todoTaskPriorityAccent(priority: String): Color = when (priority.trim().lowercase(Locale.getDefault())) {
    "urgent" -> Color(0xFFDC2626)
    "high" -> Color(0xFFEA580C)
    "niski prioritet" -> Color(0xFF0891B2)
    "bez prioriteta" -> Color(0xFF64748B)
    else -> Color(0xFF2563EB)
}

private fun todoTaskParticipantText(record: MobileRecord): String =
    listOf(
        record.meta["assignedToLabel"].orEmpty().takeIf { it.isNotBlank() }?.let { "Nositelj: $it" }.orEmpty(),
        record.meta["invitedUserLabels"].orEmpty().takeIf { it.isNotBlank() }?.let { "Pozvani: $it" }.orEmpty(),
    ).filter { it.isNotBlank() }.joinToString(" · ")

private fun todoTaskMatchesCurrentUser(record: MobileRecord, user: SafeNexusUser?): Boolean {
    val haystack = listOf(
        record.meta["assignedToLabel"].orEmpty(),
        record.meta["createdByLabel"].orEmpty(),
        record.meta["invitedUserLabels"].orEmpty(),
        record.meta["assignedToUserId"].orEmpty(),
        record.meta["createdByUserId"].orEmpty(),
        record.meta["invitedUserIds"].orEmpty(),
    ).joinToString(" ").normalizedPickerText()
    val userTokens = listOf(user?.id.orEmpty(), user?.displayName.orEmpty(), user?.email.orEmpty())
        .map { it.normalizedPickerText() }
        .filter { it.isNotBlank() }
    return userTokens.any { token -> haystack.contains(token) }
}

private fun filteredTodoTasks(
    records: List<MobileRecord>,
    scope: TodoTaskScope,
    user: SafeNexusUser?,
): List<MobileRecord> {
    val today = LocalDate.now()
    return records.filter { record ->
        val status = todoTaskStatusValue(record)
        when (scope) {
            TodoTaskScope.Mine -> todoTaskMatchesCurrentUser(record, user)
            TodoTaskScope.Invited -> {
                val invited = record.meta["invitedUserLabels"].orEmpty() + " " + record.meta["invitedUserIds"].orEmpty()
                val userTokens = listOf(user?.id.orEmpty(), user?.displayName.orEmpty(), user?.email.orEmpty())
                    .map { it.normalizedPickerText() }
                    .filter { it.isNotBlank() }
                userTokens.any { invited.normalizedPickerText().contains(it) }
            }
            TodoTaskScope.WorkOrders -> record.relatedId.isNotBlank() || record.meta["workOrderNumber"].orEmpty().isNotBlank()
            TodoTaskScope.Overdue -> status != "done" && record.parsedDate?.isBefore(today) == true
            TodoTaskScope.All -> true
        }
    }.sortedWith(
        compareBy<MobileRecord> { if (todoTaskStatusValue(it) == "done") 1 else 0 }
            .thenBy { it.parsedDate ?: LocalDate.MAX }
            .thenByDescending { it.meta["updatedAt"].orEmpty() },
    )
}

@Composable
private fun HomeTasksTabs(
    reminders: List<MobileRecord>,
    todoTasks: List<MobileRecord>,
    reminderStatusOptions: List<OptionItem>,
    todoStatusOptions: List<OptionItem>,
    priorityOptions: List<OptionItem>,
    users: List<WorkOrderUserOption>,
    workOrders: List<WorkOrder>,
    currentUser: SafeNexusUser?,
    onOpenRecord: (MobileRecord) -> Unit,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onCreateReminder: (String, String, String, String, String, String, String, String) -> Unit,
    onUpdateReminderStatus: (String, String) -> Unit,
    onCreateTodoTask: (String, String, String, String, String, String, List<String>, String, String, String) -> Unit,
) {
    var tab by remember { mutableStateOf(HomeTaskTab.Reminders) }
    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(22.dp),
            color = MaterialTheme.colorScheme.surface,
            tonalElevation = 1.dp,
        ) {
            Row(
                modifier = Modifier.padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                HomeTaskTab.entries.forEach { item ->
                    FilterChip(
                        selected = tab == item,
                        onClick = { tab = item },
                        label = {
                            val count = if (item == HomeTaskTab.Reminders) reminders.size else todoTasks.size
                            Text("${item.label} $count", maxLines = 1)
                        },
                        modifier = Modifier.weight(1f),
                    )
                }
            }
        }

        when (tab) {
            HomeTaskTab.Reminders -> RemindersContent(
                records = reminders,
                statusOptions = reminderStatusOptions,
                workOrders = workOrders,
                onOpenRecord = onOpenRecord,
                onOpenWorkOrder = onOpenWorkOrder,
                onCreateReminder = onCreateReminder,
                onUpdateReminderStatus = onUpdateReminderStatus,
            )
            HomeTaskTab.Todo -> TodoTasksContent(
                records = todoTasks,
                statusOptions = todoStatusOptions,
                priorityOptions = priorityOptions,
                users = users,
                workOrders = workOrders,
                currentUser = currentUser,
                onOpenRecord = onOpenRecord,
                onOpenWorkOrder = onOpenWorkOrder,
                onCreateTodoTask = onCreateTodoTask,
            )
        }
    }
}

@Composable
private fun RemindersContent(
    records: List<MobileRecord>,
    statusOptions: List<OptionItem>,
    workOrders: List<WorkOrder>,
    onOpenRecord: (MobileRecord) -> Unit,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onCreateReminder: (String, String, String, String, String, String, String, String) -> Unit,
    onUpdateReminderStatus: (String, String) -> Unit,
) {
    var statusFilter by remember { mutableStateOf("all") }
    var createOpen by remember { mutableStateOf(false) }
    val options = statusOptions.ifEmpty { fallbackReminderStatusOptions }
    val visible = remember(records, statusFilter) { filteredRemindersByStatus(records, statusFilter) }
    val activeCount = remember(records) { records.count { reminderStatusValue(it) == "active" } }
    val doneCount = remember(records) { records.count { reminderStatusValue(it) == "done" } }
    val overdueCount = remember(records) {
        records.count { reminderStatusValue(it) != "done" && it.parsedDate?.isBefore(LocalDate.now()) == true }
    }

    if (createOpen) {
        ReminderEditorDialog(
            statusOptions = options,
            workOrders = workOrders,
            onDismiss = { createOpen = false },
            onSave = { title, note, dueDate, status, repeatEveryDays, workOrderId ->
                val linked = workOrders.firstOrNull { it.id == workOrderId }
                onCreateReminder(
                    title,
                    note,
                    dueDate,
                    status,
                    repeatEveryDays,
                    workOrderId,
                    linked?.companyId.orEmpty(),
                    linked?.locationId.orEmpty(),
                )
                createOpen = false
            },
        )
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            SectionHeader(
                title = "Reminders",
                subtitle = "$activeCount aktivno · $overdueCount kasni · $doneCount gotovo",
                icon = Icons.Rounded.EventNote,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                TodoStatTile("Aktivno", activeCount, Color(0xFF64748B), Modifier.weight(1f))
                TodoStatTile("Kasni", overdueCount, Color(0xFFDC2626), Modifier.weight(1f))
                TodoStatTile("Gotovo", doneCount, Color(0xFF16A34A), Modifier.weight(1f))
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                FilterChip(
                    selected = statusFilter == "all",
                    onClick = { statusFilter = "all" },
                    label = { Text("Svi ${records.size}") },
                )
                options.forEach { option ->
                    FilterChip(
                        selected = statusFilter == option.value,
                        onClick = { statusFilter = option.value },
                        label = { Text("${option.label} ${records.count { reminderStatusValue(it) == option.value }}") },
                    )
                }
            }
            OutlinedButton(
                onClick = { createOpen = true },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
            ) {
                Icon(Icons.Rounded.Add, contentDescription = null)
                Spacer(Modifier.width(8.dp))
                Text("Novi reminder")
            }
            if (visible.isEmpty()) {
                Text("Nema reminders za ovaj filter.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f))
            } else {
                visible.forEach { record ->
                    ReminderCard(
                        record = record,
                        statusOptions = options,
                        onClick = { onOpenRecord(record) },
                        onOpenWorkOrder = {
                            val linked = workOrders.firstOrNull { it.id == record.relatedId }
                            if (linked != null) onOpenWorkOrder(linked)
                        },
                        onStatusChange = { next -> onUpdateReminderStatus(record.id, next) },
                    )
                }
            }
        }
    }
}

@Composable
private fun ReminderCard(
    record: MobileRecord,
    statusOptions: List<OptionItem>,
    onClick: () -> Unit,
    onOpenWorkOrder: () -> Unit,
    onStatusChange: (String) -> Unit,
) {
    val status = reminderStatusValue(record)
    val accent = reminderStatusAccent(status)
    Surface(
        modifier = Modifier.fillMaxWidth().clickable(onClick = onClick),
        shape = RoundedCornerShape(20.dp),
        color = accent.copy(alpha = if (status == "active") 0.06f else 0.09f),
        border = BorderStroke(1.dp, accent.copy(alpha = 0.2f)),
    ) {
        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Row(verticalAlignment = Alignment.Top, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Surface(shape = CircleShape, color = accent.copy(alpha = 0.13f)) {
                    Icon(Icons.Rounded.EventNote, contentDescription = null, tint = accent, modifier = Modifier.padding(9.dp).size(22.dp))
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(record.title.ifBlank { "Reminder" }, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                    if (record.subtitle.isNotBlank()) {
                        Text(record.subtitle, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f), maxLines = 2, overflow = TextOverflow.Ellipsis)
                    }
                }
                ReminderStatusMenu(status, statusOptions, onStatusChange)
            }
            record.meta["note"].orEmpty().takeIf { it.isNotBlank() }?.let { note ->
                Text(note, style = MaterialTheme.typography.bodyMedium, maxLines = 2, overflow = TextOverflow.Ellipsis)
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(7.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) {
                record.date.takeIf { it.isNotBlank() }?.let { TodoMiniPill(formatDateLabel(it).ifBlank { it.take(10) }, if (record.parsedDate?.isBefore(LocalDate.now()) == true && status != "done") Color(0xFFDC2626) else Color(0xFF475569)) }
                record.meta["repeatEveryDays"].orEmpty().takeIf { it.isNotBlank() && it != "0" }?.let { TodoMiniPill("Svakih $it dana", Color(0xFF7C3AED)) }
                record.meta["workOrderNumber"].orEmpty().takeIf { it.isNotBlank() }?.let { TodoMiniPill("RN $it", Color(0xFF2563EB)) }
            }
            if (record.relatedId.isNotBlank()) {
                OutlinedButton(onClick = onOpenWorkOrder, shape = RoundedCornerShape(14.dp)) {
                    Icon(Icons.Rounded.Work, contentDescription = null)
                    Spacer(Modifier.width(8.dp))
                    Text("Otvori RN")
                }
            }
        }
    }
}

@Composable
private fun ReminderStatusMenu(
    status: String,
    options: List<OptionItem>,
    onSelect: (String) -> Unit,
) {
    var expanded by remember { mutableStateOf(false) }
    val accent = reminderStatusAccent(status)
    Box {
        OutlinedButton(
            onClick = { expanded = true },
            shape = RoundedCornerShape(999.dp),
            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 6.dp),
        ) {
            Text(reminderStatusLabel(status, options), color = accent, style = MaterialTheme.typography.labelSmall, fontWeight = FontWeight.Bold)
            Icon(Icons.Rounded.ExpandMore, contentDescription = null, tint = accent, modifier = Modifier.size(16.dp))
        }
        DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            options.forEach { option ->
                DropdownMenuItem(
                    text = { Text(option.label) },
                    onClick = {
                        expanded = false
                        if (option.value != status) onSelect(option.value)
                    },
                )
            }
        }
    }
}

@Composable
private fun ReminderEditorDialog(
    statusOptions: List<OptionItem>,
    workOrders: List<WorkOrder>,
    onDismiss: () -> Unit,
    onSave: (String, String, String, String, String, String) -> Unit,
) {
    var title by remember { mutableStateOf("") }
    var note by remember { mutableStateOf("") }
    var dueDate by remember { mutableStateOf("") }
    var status by remember { mutableStateOf(statusOptions.firstOrNull()?.value ?: "active") }
    var repeatEveryDays by remember { mutableStateOf("") }
    var workOrderId by remember { mutableStateOf("") }

    AlertDialog(
        onDismissRequest = onDismiss,
        confirmButton = {
            Button(
                onClick = { onSave(title, note, dueDate, status, repeatEveryDays, workOrderId) },
                enabled = title.trim().isNotBlank(),
            ) { Text("Spremi") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Odustani") }
        },
        title = { Text("Novi reminder", fontWeight = FontWeight.Black) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.verticalScroll(rememberScrollState())) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Naslov") },
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                )
                WorkOrderDatePickerField("Datum", dueDate, { dueDate = it }, true)
                TodoOptionFlow("Status", statusOptions, status) { status = it }
                OutlinedTextField(
                    value = repeatEveryDays,
                    onValueChange = { repeatEveryDays = it.filter { char -> char.isDigit() }.take(3) },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Ponavljaj svakih dana") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number, imeAction = ImeAction.Next),
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                )
                TodoWorkOrderPicker(workOrders, workOrderId) { workOrderId = it }
                OutlinedTextField(
                    value = note,
                    onValueChange = { note = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Bilješka") },
                    minLines = 3,
                    maxLines = 5,
                    shape = RoundedCornerShape(16.dp),
                )
            }
        },
        properties = DialogProperties(usePlatformDefaultWidth = false),
        modifier = Modifier.padding(14.dp),
    )
}

@Composable
private fun TodoTasksContent(
    records: List<MobileRecord>,
    statusOptions: List<OptionItem>,
    priorityOptions: List<OptionItem>,
    users: List<WorkOrderUserOption>,
    workOrders: List<WorkOrder>,
    currentUser: SafeNexusUser?,
    onOpenRecord: (MobileRecord) -> Unit,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onCreateTodoTask: (String, String, String, String, String, String, List<String>, String, String, String) -> Unit,
) {
    var scope by remember { mutableStateOf(TodoTaskScope.Mine) }
    var statusFilter by remember { mutableStateOf("all") }
    var createOpen by remember { mutableStateOf(false) }
    val options = statusOptions.ifEmpty { fallbackTodoTaskStatusOptions }
    val scopedRecords = remember(records, scope, currentUser) { filteredTodoTasks(records, scope, currentUser) }
    val visible = remember(scopedRecords, statusFilter) {
        scopedRecords.filter { statusFilter == "all" || todoTaskStatusValue(it) == statusFilter }
    }
    val openCount = remember(records) { records.count { todoTaskStatusValue(it) != "done" } }
    val overdueCount = remember(records) {
        records.count { todoTaskStatusValue(it) != "done" && it.parsedDate?.isBefore(LocalDate.now()) == true }
    }

    if (createOpen) {
        TodoTaskEditorDialog(
            statusOptions = options,
            priorityOptions = priorityOptions,
            users = users,
            workOrders = workOrders,
            onDismiss = { createOpen = false },
            onSave = { title, message, status, priority, dueDate, assignedTo, invited, workOrder ->
                val linked = workOrders.firstOrNull { it.id == workOrder }
                onCreateTodoTask(
                    title,
                    message,
                    status,
                    priority,
                    dueDate,
                    assignedTo,
                    invited,
                    workOrder,
                    linked?.companyId.orEmpty(),
                    linked?.locationId.orEmpty(),
                )
                createOpen = false
            },
        )
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            SectionHeader(
                title = "ToDo",
                subtitle = "$openCount otvoreno · $overdueCount kasni · ${records.size} ukupno",
                icon = Icons.Rounded.ListAlt,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                TodoStatTile("Otvoreno", openCount, Color(0xFF2563EB), Modifier.weight(1f))
                TodoStatTile("Kasni", overdueCount, Color(0xFFDC2626), Modifier.weight(1f))
                TodoStatTile("Moje", filteredTodoTasks(records, TodoTaskScope.Mine, currentUser).size, Color(0xFF7C3AED), Modifier.weight(1f))
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                TodoTaskScope.entries.forEach { item ->
                    FilterChip(
                        selected = scope == item,
                        onClick = { scope = item },
                        label = { Text("${item.label} ${filteredTodoTasks(records, item, currentUser).size}") },
                    )
                }
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                FilterChip(
                    selected = statusFilter == "all",
                    onClick = { statusFilter = "all" },
                    label = { Text("Svi statusi ${scopedRecords.size}") },
                )
                options.forEach { option ->
                    FilterChip(
                        selected = statusFilter == option.value,
                        onClick = { statusFilter = option.value },
                        label = { Text("${option.label} ${scopedRecords.count { todoTaskStatusValue(it) == option.value }}") },
                    )
                }
            }
            OutlinedButton(
                onClick = { createOpen = true },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
            ) {
                Icon(Icons.Rounded.Add, contentDescription = null)
                Spacer(Modifier.width(8.dp))
                Text("Novi ToDo")
            }
            if (visible.isEmpty()) {
                Text("Nema ToDo tema za ovaj filter.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f))
            } else {
                visible.forEach { record ->
                    TodoTaskCard(
                        record = record,
                        statusOptions = options,
                        onClick = { onOpenRecord(record) },
                        onOpenWorkOrder = {
                            val linked = workOrders.firstOrNull { it.id == record.relatedId }
                            if (linked != null) onOpenWorkOrder(linked)
                        },
                    )
                }
            }
        }
    }
}

@Composable
private fun TodoStatTile(label: String, value: Int, color: Color, modifier: Modifier = Modifier) {
    Surface(
        modifier = modifier,
        shape = RoundedCornerShape(18.dp),
        color = color.copy(alpha = 0.11f),
    ) {
        Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) {
            Text(value.toString(), style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black, color = color)
            Text(label, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f))
        }
    }
}

@Composable
private fun TodoTaskCard(
    record: MobileRecord,
    statusOptions: List<OptionItem>,
    onClick: () -> Unit,
    onOpenWorkOrder: () -> Unit,
) {
    val status = todoTaskStatusValue(record)
    val accent = todoTaskStatusAccent(status)
    val priority = record.meta["priority"].orEmpty().ifBlank { "Normal" }
    Surface(
        modifier = Modifier.fillMaxWidth().clickable(onClick = onClick),
        shape = RoundedCornerShape(20.dp),
        color = accent.copy(alpha = 0.08f),
        border = BorderStroke(1.dp, accent.copy(alpha = 0.18f)),
    ) {
        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Row(verticalAlignment = Alignment.Top, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                Surface(shape = CircleShape, color = accent.copy(alpha = 0.14f)) {
                    Icon(Icons.Rounded.ListAlt, contentDescription = null, tint = accent, modifier = Modifier.padding(9.dp).size(22.dp))
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(record.title.ifBlank { "ToDo" }, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                    if (record.subtitle.isNotBlank()) {
                        Text(record.subtitle, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f), maxLines = 2, overflow = TextOverflow.Ellipsis)
                    }
                }
                Surface(shape = RoundedCornerShape(999.dp), color = accent.copy(alpha = 0.14f)) {
                    Text(
                        todoTaskStatusLabel(status, statusOptions),
                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 5.dp),
                        color = accent,
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Bold,
                    )
                }
            }
            val note = record.meta["note"].orEmpty()
            if (note.isNotBlank()) {
                Text(note, style = MaterialTheme.typography.bodyMedium, maxLines = 3, overflow = TextOverflow.Ellipsis)
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(7.dp), verticalArrangement = Arrangement.spacedBy(7.dp)) {
                TodoMiniPill(priority, todoTaskPriorityAccent(priority))
                record.date.takeIf { it.isNotBlank() }?.let { TodoMiniPill(formatDateLabel(it).ifBlank { it.take(10) }, Color(0xFF475569)) }
                record.meta["workOrderNumber"].orEmpty().takeIf { it.isNotBlank() }?.let { TodoMiniPill("RN $it", Color(0xFF2563EB)) }
                val commentCount = record.meta["commentCount"].orEmpty().toIntOrNull() ?: 0
                if (commentCount > 0) TodoMiniPill("$commentCount komentara", Color(0xFF7C3AED))
            }
            val participants = todoTaskParticipantText(record)
            if (participants.isNotBlank()) {
                Text(participants, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), maxLines = 2, overflow = TextOverflow.Ellipsis)
            }
            if (record.relatedId.isNotBlank()) {
                OutlinedButton(onClick = onOpenWorkOrder, shape = RoundedCornerShape(14.dp)) {
                    Icon(Icons.Rounded.Work, contentDescription = null)
                    Spacer(Modifier.width(8.dp))
                    Text("Otvori RN")
                }
            }
        }
    }
}

@Composable
private fun TodoMiniPill(label: String, color: Color) {
    Surface(shape = RoundedCornerShape(999.dp), color = color.copy(alpha = 0.11f)) {
        Text(
            label,
            modifier = Modifier.padding(horizontal = 9.dp, vertical = 5.dp),
            style = MaterialTheme.typography.labelSmall,
            color = color,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
        )
    }
}

@Composable
private fun TodoTaskEditorDialog(
    statusOptions: List<OptionItem>,
    priorityOptions: List<OptionItem>,
    users: List<WorkOrderUserOption>,
    workOrders: List<WorkOrder>,
    onDismiss: () -> Unit,
    onSave: (String, String, String, String, String, String, List<String>, String) -> Unit,
) {
    var title by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }
    var status by remember { mutableStateOf(statusOptions.firstOrNull()?.value ?: "open") }
    var priority by remember { mutableStateOf(priorityOptions.firstOrNull { it.value == "Normal" }?.value ?: "Normal") }
    var dueDate by remember { mutableStateOf("") }
    var assignedToUserId by remember { mutableStateOf("") }
    var invitedUserIds by remember { mutableStateOf<List<String>>(emptyList()) }
    var workOrderId by remember { mutableStateOf("") }

    AlertDialog(
        onDismissRequest = onDismiss,
        confirmButton = {
            Button(
                onClick = { onSave(title, message, status, priority, dueDate, assignedToUserId, invitedUserIds, workOrderId) },
                enabled = title.trim().isNotBlank(),
            ) { Text("Spremi") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Odustani") }
        },
        title = { Text("Novi ToDo", fontWeight = FontWeight.Black) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.verticalScroll(rememberScrollState())) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Naslov") },
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                )
                OutlinedTextField(
                    value = message,
                    onValueChange = { message = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Poruka") },
                    minLines = 3,
                    maxLines = 5,
                    shape = RoundedCornerShape(16.dp),
                )
                WorkOrderDatePickerField("Rok", dueDate, { dueDate = it }, true)
                TodoOptionFlow("Status", statusOptions, status) { status = it }
                TodoOptionFlow("Prioritet", priorityOptions.ifEmpty { listOf(OptionItem("Normal", "Normal")) }, priority) { priority = it }
                TodoSingleUserPicker("Nositelj", users, assignedToUserId) { assignedToUserId = it }
                TodoMultiUserPicker("Pozvani", users, invitedUserIds) { invitedUserIds = it }
                TodoWorkOrderPicker(workOrders, workOrderId) { workOrderId = it }
            }
        },
        properties = DialogProperties(usePlatformDefaultWidth = false),
        modifier = Modifier.padding(14.dp),
    )
}

@Composable
private fun TodoTaskDetailScreen(
    record: MobileRecord,
    statusOptions: List<OptionItem>,
    priorityOptions: List<OptionItem>,
    users: List<WorkOrderUserOption>,
    workOrders: List<WorkOrder>,
    isLoading: Boolean,
    onBack: () -> Unit,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onUpdateTodoTask: (String, String?, String?, String?, String?, List<String>?) -> Unit,
    onAddTodoTaskComment: (String, String) -> Unit,
) {
    var comment by remember(record.id) { mutableStateOf("") }
    val status = todoTaskStatusValue(record)
    val priority = record.meta["priority"].orEmpty().ifBlank { "Normal" }
    val linkedWorkOrder = workOrders.firstOrNull { it.id == record.relatedId }
    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text("ToDo", fontWeight = FontWeight.Black)
                        Text(record.title.ifBlank { "Tema" }, style = MaterialTheme.typography.bodySmall, maxLines = 1, overflow = TextOverflow.Ellipsis)
                    }
                },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.background),
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        LazyColumn(
            modifier = Modifier.padding(padding).fillMaxSize(),
            contentPadding = PaddingValues(horizontal = 18.dp, vertical = 14.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            item {
                Card(
                    shape = RoundedCornerShape(26.dp),
                    colors = CardDefaults.cardColors(containerColor = todoTaskStatusAccent(status).copy(alpha = 0.08f)),
                    border = BorderStroke(1.dp, todoTaskStatusAccent(status).copy(alpha = 0.18f)),
                ) {
                    Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(13.dp)) {
                        Text(record.title.ifBlank { "ToDo tema" }, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black)
                        if (record.meta["note"].orEmpty().isNotBlank()) {
                            Text(record.meta["note"].orEmpty(), style = MaterialTheme.typography.bodyLarge)
                        }
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            TodoMiniPill(todoTaskStatusLabel(status, statusOptions), todoTaskStatusAccent(status))
                            TodoMiniPill(priority, todoTaskPriorityAccent(priority))
                            record.date.takeIf { it.isNotBlank() }?.let { TodoMiniPill(formatDateLabel(it).ifBlank { it.take(10) }, Color(0xFF475569)) }
                            record.meta["workOrderNumber"].orEmpty().takeIf { it.isNotBlank() }?.let { TodoMiniPill("RN $it", Color(0xFF2563EB)) }
                        }
                        linkedWorkOrder?.let {
                            OutlinedButton(onClick = { onOpenWorkOrder(it) }, shape = RoundedCornerShape(16.dp), modifier = Modifier.fillMaxWidth()) {
                                Icon(Icons.Rounded.Work, contentDescription = null)
                                Spacer(Modifier.width(8.dp))
                                Text("Otvori povezani RN")
                            }
                        }
                    }
                }
            }
            item {
                Card(shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)) {
                    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        Text("Upravljanje", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                        TodoOptionFlow("Status", statusOptions, status) { next ->
                            onUpdateTodoTask(record.id, next, null, null, null, null)
                        }
                        TodoOptionFlow("Prioritet", priorityOptions.ifEmpty { listOf(OptionItem("Normal", "Normal")) }, priority) { next ->
                            onUpdateTodoTask(record.id, null, next, null, null, null)
                        }
                        WorkOrderDatePickerField("Rok", record.date, { next ->
                            onUpdateTodoTask(record.id, null, null, next, null, null)
                        }, !isLoading)
                        TodoSingleUserPicker("Nositelj", users, record.meta["assignedToUserId"].orEmpty()) { next ->
                            onUpdateTodoTask(record.id, null, null, null, next, null)
                        }
                    }
                }
            }
            item {
                Card(shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)) {
                    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        Text("Sudionici", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                        DetailRow(Icons.Rounded.Person, "Nositelj", record.meta["assignedToLabel"].orEmpty().ifBlank { "Nije dodijeljeno" })
                        DetailRow(Icons.Rounded.Groups, "Pozvani", record.meta["invitedUserLabels"].orEmpty().ifBlank { "Nema pozvanih" })
                        DetailRow(Icons.Rounded.Person, "Otvorio", record.meta["createdByLabel"].orEmpty().ifBlank { "Nije upisano" })
                    }
                }
            }
            item {
                Card(shape = RoundedCornerShape(24.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)) {
                    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                        Text("Komentari", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                        val preview = record.meta["commentsPreview"].orEmpty()
                        if (preview.isBlank()) {
                            Text("Nema komentara.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
                        } else {
                            preview.lines().filter { it.isNotBlank() }.forEach { line ->
                                Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.62f)) {
                                    Text(line, modifier = Modifier.padding(12.dp), style = MaterialTheme.typography.bodyMedium)
                                }
                            }
                        }
                        OutlinedTextField(
                            value = comment,
                            onValueChange = { comment = it },
                            modifier = Modifier.fillMaxWidth(),
                            label = { Text("Dodaj komentar") },
                            minLines = 2,
                            maxLines = 4,
                            shape = RoundedCornerShape(16.dp),
                        )
                        Button(
                            onClick = {
                                onAddTodoTaskComment(record.id, comment)
                                comment = ""
                            },
                            enabled = comment.trim().isNotBlank() && !isLoading,
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                        ) {
                            Text("Pošalji komentar")
                        }
                    }
                }
            }
            item {
                AnimatedVisibility(isLoading) {
                    LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                }
            }
        }
    }
}

@Composable
private fun TodoOptionFlow(
    title: String,
    options: List<OptionItem>,
    selected: String,
    onSelect: (String) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(title, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            options.forEach { option ->
                FilterChip(
                    selected = selected == option.value,
                    onClick = { onSelect(option.value) },
                    label = { Text(option.label, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                )
            }
        }
    }
}

@Composable
private fun TodoSingleUserPicker(
    title: String,
    users: List<WorkOrderUserOption>,
    selected: String,
    onSelect: (String) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text(title, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            FilterChip(
                selected = selected.isBlank(),
                onClick = { onSelect("") },
                label = { Text("Bez nositelja") },
            )
            users.take(16).forEach { user ->
                FilterChip(
                    selected = selected == user.id,
                    onClick = { onSelect(user.id) },
                    label = { Text(user.label, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                )
            }
        }
    }
}

@Composable
private fun TodoMultiUserPicker(
    title: String,
    users: List<WorkOrderUserOption>,
    selected: List<String>,
    onSelect: (List<String>) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Text(title, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, modifier = Modifier.weight(1f))
            AssistChip(onClick = {}, label = { Text("${selected.size} pozvanih") })
        }
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedButton(
                onClick = { onSelect(users.map { it.id }.filter { it.isNotBlank() }.distinct()) },
                shape = RoundedCornerShape(14.dp),
                modifier = Modifier.weight(1f),
            ) { Text("Svi") }
            OutlinedButton(
                onClick = { onSelect(emptyList()) },
                shape = RoundedCornerShape(14.dp),
                modifier = Modifier.weight(1f),
            ) { Text("Očisti") }
        }
        Column(verticalArrangement = Arrangement.spacedBy(7.dp)) {
            users.take(24).forEach { user ->
                val checked = user.id in selected
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(16.dp))
                        .clickable { onSelect(selected.toggleValue(user.id)) },
                    shape = RoundedCornerShape(16.dp),
                    color = if (checked) Color(0xFFEDE9FE) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                    border = BorderStroke(1.dp, if (checked) Color(0xFF7C3AED).copy(alpha = 0.35f) else MaterialTheme.colorScheme.outline.copy(alpha = 0.18f)),
                ) {
                    Row(
                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(9.dp),
                    ) {
                        Checkbox(checked = checked, onCheckedChange = { onSelect(selected.toggleValue(user.id)) })
                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                            Text(user.label.ifBlank { "Korisnik" }, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                            Text(user.email.ifBlank { user.oib.ifBlank { "SafeNexus" } }, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f), maxLines = 1, overflow = TextOverflow.Ellipsis)
                        }
                    }
                }
            }
            if (users.size > 24) {
                Text("+${users.size - 24} korisnika izostavljeno u brzom prikazu.", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f))
            }
        }
    }
}

@Composable
private fun TodoWorkOrderPicker(
    workOrders: List<WorkOrder>,
    selected: String,
    onSelect: (String) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
        Text("Povezani RN", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            FilterChip(selected = selected.isBlank(), onClick = { onSelect("") }, label = { Text("Bez RN") })
            workOrders.take(20).forEach { workOrder ->
                FilterChip(
                    selected = selected == workOrder.id,
                    onClick = { onSelect(workOrder.id) },
                    label = { Text(workOrder.displayNumber, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                )
            }
        }
    }
}

@Composable
private fun FieldInquiriesContent(
    records: List<MobileRecord>,
    onOpenRecord: (MobileRecord) -> Unit,
    onNewInquiry: () -> Unit,
    onEditInquiry: (MobileRecord) -> Unit,
    onConvertInquiry: (MobileRecord) -> Unit,
) {
    val today = remember { LocalDate.now() }
    val upcoming = remember(records, today) {
        records.count { record ->
            val date = record.parsedDate
            date != null && !date.isBefore(today) && !date.isAfter(today.plusDays(7))
        }
    }
    val linkedCount = remember(records) {
        records.count { it.meta["workOrderNumber"].orEmpty().isNotBlank() }
    }
    val sortedRecords = remember(records) {
        records.sortedWith(compareBy<MobileRecord> { it.parsedDate ?: LocalDate.MAX }.thenBy { it.title })
    }
    val groups = remember(sortedRecords, today) {
        val closedStatuses = setOf("rejected", "converted")
        val nextWeekStatuses = setOf("next_week", "next_week_job")
        val openRecords = sortedRecords.filter { it.status !in closedStatuses }
        listOf(
            Triple(
                "Bez datuma",
                "Dogovori koje treba smjestiti u plan.",
                openRecords.filter { it.parsedDate == null },
            ),
            Triple(
                "Idući tjedan",
                "Najbliži upiti i dogovori za teren.",
                openRecords.filter { record ->
                    record.status in nextWeekStatuses ||
                        record.parsedDate?.let { !it.isBefore(today) && !it.isAfter(today.plusDays(7)) } == true
                },
            ),
            Triple(
                "Zakazano",
                "Termini koji već imaju kasniji datum.",
                openRecords.filter { record ->
                    record.status !in nextWeekStatuses &&
                        record.parsedDate?.isAfter(today.plusDays(7)) == true
                },
            ),
            Triple(
                "Zatvoreno",
                "Pretvoreno u RN ili odbijeno.",
                sortedRecords.filter { it.status in closedStatuses },
            ),
        ).filter { it.third.isNotEmpty() }
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(modifier = Modifier.weight(1f)) {
                    Text("Plan terena", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
                    Text(
                        "${records.size} upita · $upcoming u idućih 7 dana · $linkedCount povezano s RN",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
                Button(onClick = onNewInquiry, shape = RoundedCornerShape(16.dp)) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Upit")
                }
            }

            if (sortedRecords.isEmpty()) {
                Text(
                    "Nema upita za teren. Dodaj brzi dogovor i kasnije ga poveži s RN-om.",
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            } else {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    AssistChip(onClick = {}, label = { Text("Bez datuma ${sortedRecords.count { it.parsedDate == null }}") })
                    AssistChip(onClick = {}, label = { Text("Idući tjedan $upcoming") })
                    AssistChip(onClick = {}, label = { Text("RN $linkedCount") })
                }
                groups.forEach { (title, description, groupRecords) ->
                    FieldInquiryGroupSection(
                        title = title,
                        description = description,
                        records = groupRecords,
                        onOpenRecord = onOpenRecord,
                        onEditInquiry = onEditInquiry,
                        onConvertInquiry = onConvertInquiry,
                    )
                }
            }
        }
    }
}

@Composable
private fun FieldInquiryGroupSection(
    title: String,
    description: String,
    records: List<MobileRecord>,
    onOpenRecord: (MobileRecord) -> Unit,
    onEditInquiry: (MobileRecord) -> Unit,
    onConvertInquiry: (MobileRecord) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                Text(description, style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f))
            }
            Surface(shape = RoundedCornerShape(999.dp), color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f)) {
                Text(
                    records.size.toString(),
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 5.dp),
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.Bold,
                )
            }
        }
        records.forEach { record ->
            FieldInquiryCard(
                record = record,
                onOpenRecord = { onOpenRecord(record) },
                onEdit = { onEditInquiry(record) },
                onConvert = { onConvertInquiry(record) },
            )
        }
    }
}

@Composable
private fun FieldInquiryCard(
    record: MobileRecord,
    onOpenRecord: () -> Unit,
    onEdit: () -> Unit,
    onConvert: () -> Unit,
) {
    val canConvert = record.status != "converted" && record.meta["companyId"].orEmpty().isNotBlank()
    val statusColor = calendarRecordColor("field_inquiry")
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(18.dp))
            .clickable(onClick = onOpenRecord),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.44f),
    ) {
        Column(modifier = Modifier.padding(13.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.Top,
            ) {
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(record.title.ifBlank { "Upit za teren" }, fontWeight = FontWeight.Black, maxLines = 2, overflow = TextOverflow.Ellipsis)
                    Text(
                        listOf(
                            formatDateLabel(record.date).ifBlank { record.date },
                            listOf(record.meta["timeFrom"].orEmpty(), record.meta["timeTo"].orEmpty()).filter { it.isNotBlank() }.joinToString("-"),
                            record.meta["companyName"].orEmpty().ifBlank { "Bez tvrtke" },
                        ).filter { it.isNotBlank() }.joinToString(" · "),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Surface(
                    shape = RoundedCornerShape(999.dp),
                    color = statusColor.copy(alpha = 0.14f),
                ) {
                    Text(
                        fieldInquiryStatusLabel(record.status),
                        modifier = Modifier.padding(horizontal = 9.dp, vertical = 5.dp),
                        style = MaterialTheme.typography.labelSmall,
                        color = statusColor,
                        fontWeight = FontWeight.Bold,
                    )
                }
            }

            val details = listOf(
                "Lokacija" to record.meta["locationName"].orEmpty(),
                "RN" to record.meta["workOrderNumber"].orEmpty(),
                "Ekipa" to record.meta["assignedUserLabels"].orEmpty(),
                "Vozilo" to record.meta["vehicleLabel"].orEmpty(),
                "Kontakt" to listOf(record.meta["contactName"].orEmpty(), record.meta["contactPhone"].orEmpty()).filter { it.isNotBlank() }.joinToString(" · "),
                "Usluga" to record.meta["serviceLine"].orEmpty(),
                "Dokumenti" to record.meta["documentNames"].orEmpty().ifBlank {
                    record.meta["documentCount"].orEmpty().takeIf { it.isNotBlank() && it != "0" }?.let { "$it priloga" }.orEmpty()
                },
            ).filter { it.second.isNotBlank() }

            if (details.isNotEmpty()) {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    details.forEach { (label, value) ->
                        AssistChip(
                            onClick = {},
                            label = {
                                Text("$label: $value", maxLines = 1, overflow = TextOverflow.Ellipsis)
                            },
                        )
                    }
                }
            }

            record.meta["note"].orEmpty().takeIf { it.isNotBlank() }?.let { note ->
                Text(note, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
            }

            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedButton(onClick = onEdit, shape = RoundedCornerShape(14.dp)) {
                    Text("Uredi")
                }
                OutlinedButton(
                    onClick = onConvert,
                    enabled = canConvert,
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Napravi RN")
                }
            }
        }
    }
}

@Composable
private fun FieldInquiryEditorDialog(
    record: MobileRecord?,
    data: BootstrapData,
    currentUserLabel: String,
    isLoading: Boolean,
    onPolishNote: (String, String, String, String, String, String, (String) -> Unit) -> Unit,
    onDismiss: () -> Unit,
    onSave: (FieldInquiryDraft) -> Unit,
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var documentDraft by remember(record?.id) { mutableStateOf<List<FieldInquiryDocumentDraft>>(emptyList()) }
    var documentDraftChanged by remember(record?.id) { mutableStateOf(false) }
    var documentError by remember(record?.id) { mutableStateOf("") }
    var documentsLoading by remember(record?.id) { mutableStateOf(false) }
    val documentPicker = rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            documentsLoading = true
            documentError = ""
            runCatching {
                buildFieldInquiryAttachmentFiles(context, uris, documentDraft.size)
            }.onSuccess { next ->
                documentDraft = documentDraft + next
                documentDraftChanged = true
            }.onFailure { error ->
                documentError = error.message ?: "Ne mogu učitati dokumente."
            }
            documentsLoading = false
        }
    }
    val initialAssigneeLabels = remember(record?.id) {
        record?.meta?.get("assignedUserLabels").orEmpty()
            .split(',')
            .map { it.trim() }
            .filter { it.isNotBlank() }
    }
    val initialAssigneeIdsFromMeta = remember(record?.id) {
        record?.meta?.get("assignedUserIds").orEmpty()
            .split(',')
            .map { it.trim() }
            .filter { it.isNotBlank() }
    }
    val userOptions = remember(data.workOrderUsers) {
        data.workOrderUsers.map { user -> user.id to user.label.ifBlank { user.fullName.ifBlank { user.email } } }
    }
    val initialAssigneeIds = remember(record?.id, initialAssigneeLabels, initialAssigneeIdsFromMeta, userOptions, currentUserLabel) {
        val optionIds = userOptions.map { it.first }.toSet()
        val byId = initialAssigneeIdsFromMeta.filter { it in optionIds }
        val byLabel = initialAssigneeLabels.mapNotNull { label ->
            userOptions.firstOrNull { option -> option.second.equals(label, ignoreCase = true) }?.first
        }
        byId.ifEmpty {
            byLabel
        }.ifEmpty {
            userOptions.firstOrNull { option -> option.second.equals(currentUserLabel, ignoreCase = true) }?.let { listOf(it.first) }
                ?: emptyList()
        }
    }

    var title by remember(record?.id) { mutableStateOf(record?.title.orEmpty()) }
    var status by remember(record?.id) {
        mutableStateOf(
            record?.status
                ?.ifBlank { "inquiry" }
                ?.let { if (it == "next_week_job") "next_week" else it }
                ?: "inquiry",
        )
    }
    var plannedDate by remember(record?.id) { mutableStateOf(record?.date?.take(10).orEmpty().ifBlank { LocalDate.now().toString() }) }
    var timeFrom by remember(record?.id) { mutableStateOf(record?.meta?.get("timeFrom").orEmpty()) }
    var timeTo by remember(record?.id) { mutableStateOf(record?.meta?.get("timeTo").orEmpty()) }
    var companyId by remember(record?.id) { mutableStateOf(record?.meta?.get("companyId").orEmpty()) }
    var locationId by remember(record?.id) { mutableStateOf(record?.meta?.get("locationId").orEmpty()) }
    var workOrderId by remember(record?.id) { mutableStateOf(record?.meta?.get("workOrderId").orEmpty()) }
    var vehicleId by remember(record?.id) { mutableStateOf(record?.meta?.get("vehicleId").orEmpty()) }
    var contactName by remember(record?.id) { mutableStateOf(record?.meta?.get("contactName").orEmpty()) }
    var contactPhone by remember(record?.id) { mutableStateOf(record?.meta?.get("contactPhone").orEmpty()) }
    var serviceLine by remember(record?.id) { mutableStateOf(record?.meta?.get("serviceLine").orEmpty()) }
    var note by remember(record?.id) { mutableStateOf(record?.meta?.get("note").orEmpty()) }
    var selectedAssigneeIds by remember(record?.id, initialAssigneeIds) { mutableStateOf(initialAssigneeIds) }

    val companyOptions = remember(data.workOrderCompanies) {
        listOf(WorkOrderPickerOption("", "Bez tvrtke", "Slobodni upit")) + data.workOrderCompanies.map { company ->
            WorkOrderPickerOption(
                value = company.id,
                label = company.name,
                meta = listOf(company.headquarters, company.oib.takeIf { it.isNotBlank() }?.let { "OIB $it" }).filterNotNull().filter { it.isNotBlank() }.joinToString(" · "),
                searchText = listOf(company.name, company.oib, company.headquarters).joinToString(" "),
            )
        }
    }
    val locationOptions = remember(data.workOrderLocations, companyId) {
        listOf(WorkOrderPickerOption("", "Bez lokacije")) + data.workOrderLocations
            .filter { companyId.isBlank() || it.companyId == companyId }
            .map { location ->
                WorkOrderPickerOption(
                    value = location.id,
                    label = location.name,
                    meta = listOf(location.region, location.coordinates).filter { it.isNotBlank() }.joinToString(" · "),
                    searchText = listOf(location.name, location.region, location.coordinates).joinToString(" "),
                )
            }
    }
    val workOrderOptions = remember(data.workOrders, companyId) {
        listOf(WorkOrderPickerOption("", "Bez RN-a")) + data.workOrders
            .filter { companyId.isBlank() || it.companyId == companyId }
            .take(250)
            .map { workOrder ->
                WorkOrderPickerOption(
                    value = workOrder.id,
                    label = workOrder.displayNumber,
                    meta = listOf(workOrder.companyName, workOrder.locationName, workOrder.displayService).filter { it.isNotBlank() }.joinToString(" · "),
                    searchText = listOf(workOrder.number, workOrder.companyName, workOrder.locationName, workOrder.serviceLine).joinToString(" "),
                )
            }
    }
    val vehicleOptions = remember(data.vehicles) {
        listOf("" to "Bez vozila") + data.vehicles.map { vehicle ->
            fieldInquiryId(vehicle) to listOf(vehicle.title, vehicle.subtitle).filter { it.isNotBlank() }.joinToString(" · ").ifBlank { vehicle.title }
        }
    }
    val selectedCompanyLabel = companyOptions.firstOrNull { it.value == companyId }?.label ?: "Bez tvrtke"
    val selectedLocationLabel = locationOptions.firstOrNull { it.value == locationId }?.label ?: "Bez lokacije"
    val selectedWorkOrderLabel = workOrderOptions.firstOrNull { it.value == workOrderId }?.label ?: "Bez RN-a"
    val selectedVehicleLabel = vehicleOptions.firstOrNull { it.first == vehicleId }?.second ?: "Bez vozila"

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(if (record == null) "Novi terenski upit" else "Uredi terenski upit", fontWeight = FontWeight.Black) },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 620.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Naziv / opis") },
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                )
                WorkOrderSelectField(
                    label = "Status",
                    value = status,
                    valueLabel = fieldInquiryStatusLabel(status),
                    options = fieldInquiryStatusOptions,
                    enabled = !isLoading,
                    onSelect = { status = it },
                )
                WorkOrderDatePickerField("Datum", plannedDate, { plannedDate = it }, !isLoading)
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    WorkOrderSelectField("Od", timeFrom, timeFrom.ifBlank { "Bez vremena" }, listOf("" to "Bez vremena") + reservationTimeOptions, !isLoading, { timeFrom = it }, Modifier.weight(1f))
                    WorkOrderSelectField("Do", timeTo, timeTo.ifBlank { "Bez vremena" }, listOf("" to "Bez vremena") + reservationTimeOptions, !isLoading, { timeTo = it }, Modifier.weight(1f))
                }
                WorkOrderSearchSelectField(
                    label = "Tvrtka",
                    value = companyId,
                    valueLabel = selectedCompanyLabel,
                    options = companyOptions,
                    enabled = !isLoading,
                    onSelect = {
                        companyId = it
                        locationId = ""
                        workOrderId = ""
                    },
                    icon = Icons.Rounded.Business,
                )
                WorkOrderSearchSelectField(
                    label = "Lokacija",
                    value = locationId,
                    valueLabel = selectedLocationLabel,
                    options = locationOptions,
                    enabled = !isLoading,
                    onSelect = { selected ->
                        locationId = selected
                        data.workOrderLocations.firstOrNull { it.id == selected }?.let { location ->
                            companyId = location.companyId
                        }
                    },
                    icon = Icons.Rounded.LocationOn,
                )
                WorkOrderSearchSelectField(
                    label = "Povezani RN",
                    value = workOrderId,
                    valueLabel = selectedWorkOrderLabel,
                    options = workOrderOptions,
                    enabled = !isLoading,
                    onSelect = { selected ->
                        workOrderId = selected
                        data.workOrders.firstOrNull { it.id == selected }?.let { workOrder ->
                            companyId = workOrder.companyId
                            locationId = workOrder.locationId
                            if (title.isBlank()) title = listOf(workOrder.displayNumber, workOrder.companyName).filter { it.isNotBlank() }.joinToString(" · ")
                            if (serviceLine.isBlank()) serviceLine = workOrder.displayService
                            if (contactName.isBlank()) contactName = workOrder.contactName
                            if (contactPhone.isBlank()) contactPhone = workOrder.contactPhone
                        }
                    },
                    icon = Icons.Rounded.Work,
                )
                WorkOrderSelectField(
                    label = "Vozilo",
                    value = vehicleId,
                    valueLabel = selectedVehicleLabel,
                    options = vehicleOptions,
                    enabled = !isLoading,
                    onSelect = { vehicleId = it },
                )
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("Ekipa", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
                    WorkOrderMultiSelectChips(
                        options = userOptions,
                        selected = selectedAssigneeIds,
                        enabled = !isLoading,
                        emptyText = "Nema dostupnih korisnika.",
                    ) { userId ->
                        selectedAssigneeIds = if (userId in selectedAssigneeIds) {
                            selectedAssigneeIds - userId
                        } else {
                            selectedAssigneeIds + userId
                        }
                    }
                }
                OutlinedTextField(contactName, { contactName = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Kontakt") }, singleLine = true, shape = RoundedCornerShape(16.dp))
                OutlinedTextField(contactPhone, { contactPhone = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Telefon") }, singleLine = true, shape = RoundedCornerShape(16.dp))
                OutlinedTextField(serviceLine, { serviceLine = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Usluga / tema") }, singleLine = true, shape = RoundedCornerShape(16.dp))
                VoiceTextField(
                    value = note,
                    onValueChange = { note = it },
                    label = "Opis / napomena",
                    placeholder = "Unesi ili izdiktiraj dogovor, napomenu, što treba pripremiti...",
                    enabled = !isLoading,
                    minLines = 3,
                )
                OutlinedButton(
                    onClick = {
                        onPolishNote(
                            note,
                            note,
                            title,
                            selectedCompanyLabel,
                            selectedLocationLabel,
                            serviceLine,
                        ) { polished -> note = polished }
                    },
                    enabled = !isLoading && note.trim().isNotBlank(),
                    shape = RoundedCornerShape(16.dp),
                    modifier = Modifier.fillMaxWidth(),
                ) {
                    Icon(Icons.Rounded.AutoAwesome, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(8.dp))
                    Text("NexAI sredi opis")
                }
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(18.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.44f),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.18f)),
                ) {
                    Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Dokumenti", fontWeight = FontWeight.Black)
                                Text(
                                    "PDF, slike, mailovi ili drugi prilozi uz plan.",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                )
                            }
                            OutlinedButton(
                                onClick = { documentPicker.launch(arrayOf("*/*")) },
                                enabled = !isLoading && !documentsLoading && documentDraft.size < FIELD_INQUIRY_ATTACHMENT_MAX_INLINE_FILES,
                                shape = RoundedCornerShape(14.dp),
                            ) {
                                Icon(Icons.Rounded.AttachFile, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Dodaj")
                            }
                        }

                        val existingCount = record?.meta?.get("documentCount").orEmpty()
                        val existingNames = record?.meta?.get("documentNames").orEmpty()
                        if (!documentDraftChanged && existingCount.isNotBlank() && existingCount != "0") {
                            Text(
                                listOf("$existingCount spremljeno", existingNames).filter { it.isNotBlank() }.joinToString(" · "),
                                style = MaterialTheme.typography.labelMedium,
                                color = MaterialTheme.colorScheme.primary,
                            )
                        }
                        if (documentDraft.isEmpty()) {
                            Text(
                                if (record == null) "Nema dodanih dokumenata." else "Dodaj novi dokument ili ostavi postojeće bez promjene.",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                            )
                        } else {
                            documentDraft.forEach { document ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(14.dp))
                                        .background(MaterialTheme.colorScheme.surface)
                                        .padding(horizontal = 10.dp, vertical = 8.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically,
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(document.fileName, maxLines = 1, overflow = TextOverflow.Ellipsis, fontWeight = FontWeight.Bold)
                                        Text(
                                            "${document.fileType.ifBlank { "datoteka" }} · ${formatFileSizeLabel(document.fileSize)}",
                                            style = MaterialTheme.typography.labelSmall,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                                        )
                                    }
                                    IconButton(
                                        onClick = {
                                            documentDraft = documentDraft.filterNot { it.id == document.id }
                                            documentDraftChanged = true
                                        },
                                        enabled = !isLoading,
                                    ) {
                                        Icon(Icons.Rounded.Delete, contentDescription = "Ukloni dokument", tint = Color(0xFFDC2626))
                                    }
                                }
                            }
                        }
                        if (documentsLoading) {
                            LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                        }
                        if (documentError.isNotBlank()) {
                            Text(documentError, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.error)
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val labelById = userOptions.toMap()
                    onSave(
                        FieldInquiryDraft(
                            id = record?.let(::fieldInquiryId).orEmpty(),
                            title = title.trim(),
                            status = status.ifBlank { "inquiry" },
                            plannedDate = plannedDate,
                            timeFrom = timeFrom,
                            timeTo = timeTo,
                            companyId = companyId,
                            locationId = locationId,
                            workOrderId = workOrderId,
                            vehicleId = vehicleId,
                            contactName = contactName.trim(),
                            contactPhone = contactPhone.trim(),
                            serviceLine = serviceLine.trim(),
                            note = note.trim(),
                            assignedUserIds = selectedAssigneeIds,
                            assignedUserLabels = selectedAssigneeIds.mapNotNull { labelById[it] },
                            syncWorkOrderExecutionDate = true,
                            documents = when {
                                record == null -> documentDraft
                                documentDraftChanged -> documentDraft
                                else -> null
                            },
                        ),
                    )
                },
                enabled = !isLoading && title.trim().isNotBlank(),
            ) {
                Text("Spremi")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun RiskAssessmentMobileContent(
    records: List<MobileRecord>,
    jobs: List<MobileRecord>,
    totalJobs: Int,
    onOpenRecord: (MobileRecord) -> Unit,
    onNewRiskAssessment: () -> Unit,
    onNewJob: () -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.primaryContainer) {
                    Icon(
                        Icons.Rounded.Badge,
                        contentDescription = null,
                        modifier = Modifier.size(44.dp).padding(10.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                }
                Spacer(Modifier.width(12.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text("Procjene rizika", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
                    Text(
                        "${records.size} procjena · $totalJobs Jobs u katalogu",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            }
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                Button(onClick = onNewRiskAssessment, shape = RoundedCornerShape(16.dp)) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Nova procjena")
                }
                OutlinedButton(onClick = onNewJob, shape = RoundedCornerShape(16.dp)) {
                    Icon(Icons.Rounded.Work, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Job")
                }
            }

            if (records.isEmpty()) {
                Text(
                    "Nema procjena za prikaz. Kreni s tvrtkom, lokacijom i Jobs radnim mjestima.",
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                )
            } else {
                records.take(12).forEach { record ->
                    RecordLine(
                        title = record.title,
                        subtitle = listOf(record.meta["companyName"].orEmpty(), record.meta["locationName"].orEmpty()).filter { it.isNotBlank() }.joinToString(" · ").ifBlank { record.subtitle },
                        status = record.status,
                        date = record.date,
                        icon = Icons.Rounded.Description,
                        onClick = { onOpenRecord(record) },
                    )
                }
            }

            Text("Jobs katalog", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
            if (jobs.isEmpty()) {
                Text("Nema Jobs stavki za trenutnu pretragu.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
            } else {
                jobs.take(8).forEach { job ->
                    RecordLine(
                        title = job.title,
                        subtitle = job.meta["description"].orEmpty().ifBlank { job.subtitle },
                        status = job.status,
                        date = "",
                        icon = Icons.Rounded.Work,
                        onClick = { onOpenRecord(job) },
                    )
                }
            }
        }
    }
}

@Composable
private fun JobEditorDialog(
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onSave: (JobCreateDraft) -> Unit,
) {
    var title by remember { mutableStateOf("") }
    var description by remember { mutableStateOf("") }
    var status by remember { mutableStateOf("draft") }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Novi Job", fontWeight = FontWeight.Black) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Naziv radnog mjesta / posla") },
                    singleLine = true,
                    shape = RoundedCornerShape(16.dp),
                )
                WorkOrderSelectField(
                    label = "Status",
                    value = status,
                    valueLabel = if (status == "active") "Aktivan" else "Skica",
                    options = listOf("draft" to "Skica", "active" to "Aktivan"),
                    enabled = !isLoading,
                    onSelect = { status = it },
                )
                VoiceTextField(
                    value = description,
                    onValueChange = { description = it },
                    label = "Opis posla",
                    placeholder = "Diktiraj ili upiši aktivnosti, radno okruženje i posebnosti posla.",
                    enabled = !isLoading,
                    minLines = 4,
                )
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    onSave(JobCreateDraft(title = title, status = status, description = description))
                },
                enabled = !isLoading && title.trim().isNotBlank(),
            ) {
                Text("Spremi Job")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun RiskAssessmentSectionTabs(
    sections: List<Pair<String, String>>,
    selected: String,
    enabled: Boolean,
    onSelect: (String) -> Unit,
) {
    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        sections.forEach { section ->
            FilterChip(
                selected = selected == section.first,
                onClick = { onSelect(section.first) },
                enabled = enabled,
                label = { Text(section.second, maxLines = 1, overflow = TextOverflow.Ellipsis) },
            )
        }
    }
}

@Composable
private fun RiskMobileSection(
    title: String,
    subtitle: String,
    icon: ImageVector,
    content: @Composable ColumnScope.() -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(22.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 1.dp,
    ) {
        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.primary.copy(alpha = 0.10f)) {
                    Icon(
                        icon,
                        contentDescription = null,
                        modifier = Modifier
                            .size(42.dp)
                            .padding(10.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                }
                Spacer(Modifier.width(10.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                    Text(
                        subtitle,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            }
            content()
        }
    }
}

@Composable
private fun RiskCompactTextField(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    minLines: Int = 1,
) {
    OutlinedTextField(
        value = value,
        onValueChange = onValueChange,
        modifier = modifier.fillMaxWidth(),
        enabled = enabled,
        label = { Text(label) },
        singleLine = minLines <= 1,
        minLines = minLines,
        maxLines = if (minLines <= 1) 1 else minLines + 3,
        shape = RoundedCornerShape(16.dp),
    )
}

@Composable
private fun RiskListLine(
    title: String,
    subtitle: String,
    onRemove: () -> Unit,
    enabled: Boolean,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.06f),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
            Spacer(Modifier.width(10.dp))
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(title.ifBlank { "Bez naziva" }, fontWeight = FontWeight.Bold, maxLines = 2, overflow = TextOverflow.Ellipsis)
                if (subtitle.isNotBlank()) {
                    Text(
                        subtitle,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
            IconButton(onClick = onRemove, enabled = enabled) {
                Icon(Icons.Rounded.Delete, contentDescription = "Ukloni")
            }
        }
    }
}

@Composable
private fun RiskSummaryLine(label: String, value: String) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(label, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
        Text(value.ifBlank { "-" }, fontWeight = FontWeight.Black, textAlign = TextAlign.End)
    }
}

@Composable
private fun RiskAssessmentEditorDialog(
    data: BootstrapData,
    currentUserLabel: String,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onSave: (RiskAssessmentCreateDraft) -> Unit,
    onNewJob: () -> Unit,
) {
    val today = remember { LocalDate.now().toString() }
    val sections = listOf(
        "basic" to "Osnovno",
        "texts" to "Tekst",
        "structure" to "Mjesta",
        "jobs" to "Jobs",
        "risks" to "Rizici",
        "measures" to "Mjere",
        "chemicals" to "Kemija",
        "biology" to "Biologija",
        "manual" to "Teret",
        "summary" to "Pregled",
    )
    var title by remember { mutableStateOf("") }
    var companyId by remember { mutableStateOf("") }
    var locationId by remember { mutableStateOf("") }
    var workOrderId by remember { mutableStateOf("") }
    var status by remember { mutableStateOf("draft") }
    var activeSection by remember { mutableStateOf("basic") }
    var assessmentNumber by remember { mutableStateOf("") }
    var assessmentDate by remember { mutableStateOf(today) }
    var completionDate by remember { mutableStateOf(today) }
    var revisionDate by remember { mutableStateOf("") }
    var teamLead by remember { mutableStateOf(currentUserLabel) }
    var collaborators by remember { mutableStateOf("") }
    var employerMbs by remember { mutableStateOf("") }
    var employerNkdActivity by remember { mutableStateOf("") }
    var employerEmployeeCount by remember { mutableStateOf("") }
    var employerDetachedLocations by remember { mutableStateOf("") }
    var znrServiceMode by remember { mutableStateOf("") }
    var znrExperts by remember { mutableStateOf("") }
    var znrRepresentatives by remember { mutableStateOf("") }
    var znrCommitteeParticipation by remember { mutableStateOf("") }
    var intro by remember { mutableStateOf("") }
    var workProcess by remember { mutableStateOf("") }
    var generalData by remember { mutableStateOf("") }
    var computerWorkplaces by remember { mutableStateOf("") }
    var basicRules by remember { mutableStateOf("") }
    var specialRules by remember { mutableStateOf("") }
    var omissionsBasic by remember { mutableStateOf("") }
    var omissionsSpecial by remember { mutableStateOf("") }
    var conclusion by remember { mutableStateOf("") }
    var biologicalHazards by remember { mutableStateOf("") }
    var clientNote by remember { mutableStateOf("") }
    var activeJobIndex by remember { mutableStateOf(0) }
    val organizationUnits = remember { mutableStateListOf<RiskAssessmentOrganizationUnitDraft>() }
    val selectedJobDrafts = remember { mutableStateListOf<RiskAssessmentJobDraft>() }
    val measures = remember { mutableStateListOf<RiskAssessmentMeasureDraft>() }
    val chemicals = remember { mutableStateListOf<RiskAssessmentChemicalDraft>() }
    val biologicalRisks = remember { mutableStateListOf<RiskAssessmentBiologicalDraft>() }
    val manualHandling = remember { mutableStateListOf<RiskAssessmentManualHandlingDraft>() }
    var unitName by remember { mutableStateOf("") }
    var unitType by remember { mutableStateOf("workplace") }
    var unitResponsible by remember { mutableStateOf("") }
    var unitWorkerCount by remember { mutableStateOf("") }
    var unitDescription by remember { mutableStateOf("") }
    var riskHazard by remember { mutableStateOf("") }
    var riskSource by remember { mutableStateOf("") }
    var riskConsequences by remember { mutableStateOf("") }
    var riskLevel by remember { mutableStateOf("Srednji") }
    var riskExistingMeasures by remember { mutableStateOf("") }
    var riskAdditionalMeasures by remember { mutableStateOf("") }
    var ppeName by remember { mutableStateOf("") }
    var ppeCategory by remember { mutableStateOf("") }
    var ppeNorm by remember { mutableStateOf("") }
    var ppeDescription by remember { mutableStateOf("") }
    var measureText by remember { mutableStateOf("") }
    var measureDeadline by remember { mutableStateOf("") }
    var measureResponsible by remember { mutableStateOf("") }
    var measureControl by remember { mutableStateOf("") }
    var chemicalName by remember { mutableStateOf("") }
    var chemicalCas by remember { mutableStateOf("") }
    var chemicalClassification by remember { mutableStateOf("") }
    var chemicalHazards by remember { mutableStateOf("") }
    var chemicalPpe by remember { mutableStateOf("") }
    var chemicalStorage by remember { mutableStateOf("") }
    var biologicalName by remember { mutableStateOf("") }
    var biologicalCategory by remember { mutableStateOf("") }
    var biologicalGroup by remember { mutableStateOf("") }
    var biologicalSource by remember { mutableStateOf("") }
    var biologicalConsequences by remember { mutableStateOf("") }
    var biologicalMeasures by remember { mutableStateOf("") }
    var manualActivity by remember { mutableStateOf("") }
    var manualJobTitle by remember { mutableStateOf("") }
    var manualWeight by remember { mutableStateOf("") }
    var manualFrequency by remember { mutableStateOf("") }
    var manualDistance by remember { mutableStateOf("") }
    var manualPosture by remember { mutableStateOf("upright") }
    var manualConditions by remember { mutableStateOf("good") }
    var manualNote by remember { mutableStateOf("") }

    val companyOptions = remember(data.workOrderCompanies) {
        data.workOrderCompanies.map { company ->
            WorkOrderPickerOption(
                value = company.id,
                label = company.name,
                meta = listOf(company.headquarters, company.oib.takeIf { it.isNotBlank() }?.let { "OIB $it" }).filterNotNull().joinToString(" · "),
                searchText = listOf(company.name, company.oib, company.headquarters).joinToString(" "),
            )
        }
    }
    val locationOptions = remember(data.workOrderLocations, companyId) {
        data.workOrderLocations
            .filter { companyId.isBlank() || it.companyId == companyId }
            .map { location ->
                WorkOrderPickerOption(
                    value = location.id,
                    label = location.name,
                    meta = location.region,
                    searchText = listOf(location.name, location.region, location.coordinates).joinToString(" "),
                )
            }
    }
    val workOrderOptions = remember(data.workOrders, companyId, locationId) {
        data.workOrders
            .filter { companyId.isBlank() || it.companyId == companyId }
            .filter { locationId.isBlank() || it.locationId == locationId }
            .take(250)
            .map { workOrder ->
                WorkOrderPickerOption(
                    value = workOrder.id,
                    label = workOrder.displayNumber,
                    meta = listOf(workOrder.companyName, workOrder.locationName, workOrder.displayService).filter { it.isNotBlank() }.joinToString(" · "),
                    searchText = listOf(workOrder.number, workOrder.companyName, workOrder.locationName, workOrder.displayService).joinToString(" "),
                )
            }
    }
    val selectedCompany = data.workOrderCompanies.firstOrNull { it.id == companyId }
    val selectedLocation = data.workOrderLocations.firstOrNull { it.id == locationId }
    val selectedWorkOrder = data.workOrders.firstOrNull { it.id == workOrderId }
    val jobOptions = remember(data.jobs) {
        data.jobs.map { job ->
            job.id to job.title.ifBlank { "Job" }
        }
    }
    val selectedCompanyAddress = selectedCompany?.headquarters.orEmpty()
    val selectedCompanyOib = selectedCompany?.oib.orEmpty()
    val selectedJobIds = selectedJobDrafts.map { it.sourceJobId }.filter { it.isNotBlank() }
    val activeJob = selectedJobDrafts.getOrNull(activeJobIndex.coerceIn(0, (selectedJobDrafts.size - 1).coerceAtLeast(0)))

    fun jobDraftFromRecord(record: MobileRecord): RiskAssessmentJobDraft {
        val description = record.meta["description"].orEmpty().ifBlank { record.subtitle }
        return RiskAssessmentJobDraft(
            sourceJobId = record.id,
            jobTitle = record.title.ifBlank { "Job" },
            description = description,
            tasks = description,
            workEnvironment = record.meta["environmentCount"].orEmpty(),
            workEquipment = "",
            note = record.status,
        )
    }

    fun updateJob(index: Int, next: RiskAssessmentJobDraft) {
        if (index in selectedJobDrafts.indices) {
            selectedJobDrafts[index] = next
        }
    }

    LaunchedEffect(selectedCompany?.id) {
        if (selectedCompany != null) {
            if (title.isBlank()) title = "Procjena rizika - ${selectedCompany.name}"
            if (employerDetachedLocations.isBlank()) employerDetachedLocations = selectedCompany.headquarters
        }
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false),
        modifier = Modifier.padding(14.dp),
        title = {
            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text("Mobilna procjena rizika", fontWeight = FontWeight.Black)
                Text("Isti blokovi kao web, složeni za mobitel.", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
            }
        },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 680.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(14.dp),
            ) {
                RiskAssessmentSectionTabs(sections, activeSection, !isLoading) { activeSection = it }

                when (activeSection) {
                    "basic" -> RiskMobileSection("Osnovno", "Tvrtka, RN, tim, poslodavac i ZNR organizacija.", Icons.Rounded.Business) {
                        WorkOrderSearchSelectField(
                            label = "Tvrtka",
                            value = companyId,
                            valueLabel = selectedCompany?.name ?: "Odaberi tvrtku",
                            options = companyOptions,
                            enabled = !isLoading,
                            onSelect = {
                                companyId = it
                                locationId = ""
                                workOrderId = ""
                                data.workOrderCompanies.firstOrNull { company -> company.id == it }?.let { company ->
                                    if (title.isBlank()) title = "Procjena rizika - ${company.name}"
                                }
                            },
                            icon = Icons.Rounded.Business,
                        )
                        WorkOrderSearchSelectField(
                            label = "Lokacija",
                            value = locationId,
                            valueLabel = selectedLocation?.name ?: "Sve lokacije / odaberi",
                            options = locationOptions,
                            enabled = !isLoading,
                            onSelect = { locationId = it },
                            icon = Icons.Rounded.LocationOn,
                        )
                        WorkOrderSearchSelectField(
                            label = "Povezani RN",
                            value = workOrderId,
                            valueLabel = selectedWorkOrder?.displayNumber ?: "Bez RN-a",
                            options = workOrderOptions,
                            enabled = !isLoading,
                            onSelect = { selected ->
                                workOrderId = selected
                                data.workOrders.firstOrNull { it.id == selected }?.let { workOrder ->
                                    companyId = workOrder.companyId
                                    locationId = workOrder.locationId
                                    if (title.isBlank()) title = "Procjena rizika - ${workOrder.companyName}"
                                }
                            },
                            icon = Icons.Rounded.Work,
                        )
                        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            WorkOrderSelectField(
                                label = "Status",
                                value = status,
                                valueLabel = if (status == "completed") "Završeno" else "Skica",
                                options = listOf("draft" to "Skica", "completed" to "Završeno"),
                                enabled = !isLoading,
                                onSelect = { status = it },
                                modifier = Modifier.weight(1f),
                            )
                            RiskCompactTextField(assessmentNumber, { assessmentNumber = it }, "Broj", !isLoading, Modifier.weight(1f))
                        }
                        RiskCompactTextField(title, { title = it }, "Naziv procjene", !isLoading)
                        WorkOrderDatePickerField("Datum procjene", assessmentDate, { assessmentDate = it }, !isLoading)
                        WorkOrderDatePickerField("Datum završetka", completionDate, { completionDate = it }, !isLoading)
                        WorkOrderDatePickerField("Rok / revizija", revisionDate, { revisionDate = it }, !isLoading)
                        RiskCompactTextField(teamLead, { teamLead = it }, "Voditelj izrade", !isLoading)
                        RiskCompactTextField(collaborators, { collaborators = it }, "Članovi / suradnici", !isLoading, minLines = 2)
                        RiskCompactTextField(selectedCompany?.name.orEmpty(), {}, "Poslodavac", false)
                        RiskCompactTextField(selectedCompanyOib, {}, "OIB", false)
                        RiskCompactTextField(selectedCompanyAddress, {}, "Adresa / sjedište", false, minLines = 2)
                        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            RiskCompactTextField(employerMbs, { employerMbs = it }, "MBS", !isLoading, Modifier.weight(1f))
                            RiskCompactTextField(employerEmployeeCount, { employerEmployeeCount = it }, "Broj radnika", !isLoading, Modifier.weight(1f))
                        }
                        VoiceTextField(employerNkdActivity, { employerNkdActivity = it }, "NKD / djelatnost", "Diktiraj djelatnost poslodavca.", !isLoading, minLines = 2)
                        VoiceTextField(employerDetachedLocations, { employerDetachedLocations = it }, "Izdvojene lokacije", "Navedi pogone, lokacije i prostore.", !isLoading, minLines = 2)
                        VoiceTextField(znrServiceMode, { znrServiceMode = it }, "Način obavljanja ZNR", "Interno, ovlaštena osoba ili kombinacija.", !isLoading, minLines = 2)
                        VoiceTextField(znrExperts, { znrExperts = it }, "Stručnjaci zaštite na radu", "Upiši ili diktiraj stručnjake.", !isLoading, minLines = 2)
                        VoiceTextField(znrRepresentatives, { znrRepresentatives = it }, "Povjerenici / predstavnici", "Upiši povjerenike i predstavnike radnika.", !isLoading, minLines = 2)
                        VoiceTextField(znrCommitteeParticipation, { znrCommitteeParticipation = it }, "Odbor ZNR", "Opiši način sudjelovanja odbora.", !isLoading, minLines = 2)
                    }

                    "texts" -> RiskMobileSection("Uvod i tekstovi", "Word/A4 logika weba, ali uz mikrofon.", Icons.Rounded.Description) {
                        VoiceTextField(intro, { intro = it }, "Uvod", "Diktiraj uvodni tekst procjene.", !isLoading, minLines = 4)
                        VoiceTextField(workProcess, { workProcess = it }, "Opis procesa rada", "Diktiraj stvarni proces rada i organizaciju.", !isLoading, minLines = 4)
                        VoiceTextField(generalData, { generalData = it }, "Opći podaci", "Dodatni podaci koji idu u osnovni dio.", !isLoading, minLines = 3)
                        VoiceTextField(computerWorkplaces, { computerWorkplaces = it }, "Rad s računalom", "Radna mjesta s računalom, trajanje i uvjeti.", !isLoading, minLines = 3)
                        VoiceTextField(basicRules, { basicRules = it }, "Osnovna pravila ZNR", "Prostor, instalacije, komunikacije, uvjeti rada.", !isLoading, minLines = 3)
                        VoiceTextField(specialRules, { specialRules = it }, "Posebna pravila ZNR", "Osposobljavanja, pregledi, OZO, upute.", !isLoading, minLines = 3)
                        VoiceTextField(omissionsBasic, { omissionsBasic = it }, "Propusti - osnovna pravila", "Ako nema propusta, ostavi prazno.", !isLoading, minLines = 2)
                        VoiceTextField(omissionsSpecial, { omissionsSpecial = it }, "Propusti - posebna pravila", "Ako nema propusta, ostavi prazno.", !isLoading, minLines = 2)
                        VoiceTextField(conclusion, { conclusion = it }, "Zaključak", "Kratki zaključak ili napomena.", !isLoading, minLines = 3)
                        VoiceTextField(clientNote, { clientNote = it }, "Interna napomena", "Ne mora ići u dokument.", !isLoading, minLines = 2)
                    }

                    "structure" -> RiskMobileSection("Organizacija i mjesta", "Hijerarhija, radna mjesta i broj radnika.", Icons.Rounded.Badge) {
                        WorkOrderSelectField(
                            label = "Tip",
                            value = unitType,
                            valueLabel = if (unitType == "workplace") "Radno mjesto" else "Organizacijska jedinica",
                            options = listOf("workplace" to "Radno mjesto", "unit" to "Organizacijska jedinica"),
                            enabled = !isLoading,
                            onSelect = { unitType = it },
                        )
                        RiskCompactTextField(unitName, { unitName = it }, "Naziv", !isLoading)
                        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            RiskCompactTextField(unitResponsible, { unitResponsible = it }, "Odgovorna osoba", !isLoading, Modifier.weight(1f))
                            RiskCompactTextField(unitWorkerCount, { unitWorkerCount = it }, "Radnika", !isLoading, Modifier.weight(1f))
                        }
                        VoiceTextField(unitDescription, { unitDescription = it }, "Opis", "Opiši jedinicu ili radno mjesto.", !isLoading, minLines = 2)
                        Button(
                            onClick = {
                                organizationUnits.add(RiskAssessmentOrganizationUnitDraft(unitName, unitType, unitResponsible, unitWorkerCount, unitDescription))
                                unitName = ""; unitResponsible = ""; unitWorkerCount = ""; unitDescription = ""
                            },
                            enabled = !isLoading && unitName.trim().isNotBlank(),
                            shape = RoundedCornerShape(16.dp),
                        ) {
                            Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("Dodaj mjesto")
                        }
                        organizationUnits.forEachIndexed { index, unit ->
                            RiskListLine(
                                title = unit.name,
                                subtitle = listOf(if (unit.type == "workplace") "Radno mjesto" else "Jedinica", unit.workerCount.takeIf { it.isNotBlank() }?.let { "$it radnika" }).filterNotNull().joinToString(" · "),
                                onRemove = { organizationUnits.removeAt(index) },
                                enabled = !isLoading,
                            )
                        }
                    }

                    "jobs" -> RiskMobileSection("Jobs", "Odaberi iz kataloga pa doradi detalje za procjenu.", Icons.Rounded.Work) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text("Katalog", modifier = Modifier.weight(1f), fontWeight = FontWeight.Black)
                            OutlinedButton(onClick = onNewJob, enabled = !isLoading, shape = RoundedCornerShape(14.dp)) {
                                Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                                Spacer(Modifier.width(4.dp))
                                Text("Novi Job")
                            }
                        }
                        WorkOrderMultiSelectChips(
                            options = jobOptions,
                            selected = selectedJobIds,
                            enabled = !isLoading,
                            emptyText = "Jobs katalog je prazan. Dodaj novi Job.",
                        ) { jobId ->
                            val existingIndex = selectedJobDrafts.indexOfFirst { it.sourceJobId == jobId }
                            if (existingIndex >= 0) {
                                selectedJobDrafts.removeAt(existingIndex)
                                activeJobIndex = activeJobIndex.coerceAtMost((selectedJobDrafts.size - 1).coerceAtLeast(0))
                            } else {
                                data.jobs.firstOrNull { it.id == jobId }?.let { record ->
                                    selectedJobDrafts.add(jobDraftFromRecord(record))
                                    activeJobIndex = selectedJobDrafts.lastIndex
                                }
                            }
                        }
                        if (selectedJobDrafts.isEmpty()) {
                            Text("Odaberi barem jedan Job da se mogu unositi rizici i OZO.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
                        } else {
                            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                selectedJobDrafts.forEachIndexed { index, job ->
                                    FilterChip(
                                        selected = index == activeJobIndex,
                                        onClick = { activeJobIndex = index },
                                        label = { Text(job.jobTitle, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                                    )
                                }
                            }
                            activeJob?.let { job ->
                                val index = activeJobIndex.coerceIn(selectedJobDrafts.indices)
                                RiskCompactTextField(job.jobTitle, { updateJob(index, job.copy(jobTitle = it)) }, "Naziv radnog mjesta", !isLoading)
                                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                    RiskCompactTextField(job.workerCount, { updateJob(index, job.copy(workerCount = it)) }, "Radnika", !isLoading, Modifier.weight(1f))
                                    RiskCompactTextField(job.workSchedule, { updateJob(index, job.copy(workSchedule = it)) }, "Radno vrijeme", !isLoading, Modifier.weight(1f))
                                }
                                VoiceTextField(job.description, { updateJob(index, job.copy(description = it)) }, "Opis posla", "Opis radnog mjesta.", !isLoading, minLines = 3)
                                VoiceTextField(job.tasks, { updateJob(index, job.copy(tasks = it)) }, "Poslovi i zadaci", "Diktiraj poslove koje radnik obavlja.", !isLoading, minLines = 3)
                                VoiceTextField(job.workOrganization, { updateJob(index, job.copy(workOrganization = it)) }, "Organizacija rada", "Smjene, terenski rad, rad samostalno ili u timu.", !isLoading, minLines = 2)
                                VoiceTextField(job.workEnvironment, { updateJob(index, job.copy(workEnvironment = it)) }, "Radni okoliš", "Prostori, mikroklima, buka, osvjetljenje i drugi uvjeti.", !isLoading, minLines = 2)
                                VoiceTextField(job.workEquipment, { updateJob(index, job.copy(workEquipment = it)) }, "Radna oprema", "Strojevi, uređaji, alati i instalacije.", !isLoading, minLines = 2)
                                VoiceTextField(job.workSubstances, { updateJob(index, job.copy(workSubstances = it)) }, "Tvari", "Kemikalije, biološki agensi i ostale tvari.", !isLoading, minLines = 2)
                                VoiceTextField(job.trainings, { updateJob(index, job.copy(trainings = it)) }, "Osposobljavanja", "Koja osposobljavanja se traže.", !isLoading, minLines = 2)
                                VoiceTextField(job.medicalExams, { updateJob(index, job.copy(medicalExams = it)) }, "Liječnički pregledi", "Posebni uvjeti rada i pregledi.", !isLoading, minLines = 2)
                                VoiceTextField(job.ppeText, { updateJob(index, job.copy(ppeText = it)) }, "OZO tekst", "Opiši osobnu zaštitnu opremu.", !isLoading, minLines = 2)
                            }
                        }
                    }

                    "risks" -> RiskMobileSection("Rizici i OZO", "Mobilni unos rizika za aktivni Job.", Icons.Rounded.ErrorOutline) {
                        if (activeJob == null) {
                            Text("Prvo odaberi Job u kartici Jobs.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
                        } else {
                            val index = activeJobIndex.coerceIn(selectedJobDrafts.indices)
                            Text(activeJob.jobTitle, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                            RiskCompactTextField(riskHazard, { riskHazard = it }, "Opasnost / štetnost", !isLoading)
                            RiskCompactTextField(riskSource, { riskSource = it }, "Izvor", !isLoading)
                            VoiceTextField(riskConsequences, { riskConsequences = it }, "Moguće posljedice", "Što se može dogoditi.", !isLoading, minLines = 2)
                            WorkOrderSelectField(
                                label = "Razina rizika",
                                value = riskLevel,
                                valueLabel = riskLevel,
                                options = listOf("Nizak" to "Nizak", "Srednji" to "Srednji", "Visok" to "Visok"),
                                enabled = !isLoading,
                                onSelect = { riskLevel = it },
                            )
                            VoiceTextField(riskExistingMeasures, { riskExistingMeasures = it }, "Postojeće mjere", "Mjere koje već postoje.", !isLoading, minLines = 2)
                            VoiceTextField(riskAdditionalMeasures, { riskAdditionalMeasures = it }, "Dodatne mjere", "Što treba dodatno napraviti.", !isLoading, minLines = 2)
                            Button(
                                onClick = {
                                    val nextRows = activeJob.riskRows + RiskAssessmentRiskRowDraft(riskHazard, riskSource, riskConsequences, riskLevel, riskExistingMeasures, riskAdditionalMeasures, riskAdditionalMeasures)
                                    updateJob(index, activeJob.copy(riskRows = nextRows))
                                    riskHazard = ""; riskSource = ""; riskConsequences = ""; riskExistingMeasures = ""; riskAdditionalMeasures = ""
                                },
                                enabled = !isLoading && riskHazard.trim().isNotBlank(),
                                shape = RoundedCornerShape(16.dp),
                            ) {
                                Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Dodaj rizik")
                            }
                            activeJob.riskRows.forEachIndexed { riskIndex, risk ->
                                RiskListLine(
                                    title = risk.hazard,
                                    subtitle = listOf(risk.source, risk.riskLevel).filter { it.isNotBlank() }.joinToString(" · "),
                                    enabled = !isLoading,
                                    onRemove = {
                                        updateJob(index, activeJob.copy(riskRows = activeJob.riskRows.filterIndexed { rowIndex, _ -> rowIndex != riskIndex }))
                                    },
                                )
                            }
                            Text("Osobna zaštitna oprema", fontWeight = FontWeight.Black)
                            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                RiskCompactTextField(ppeName, { ppeName = it }, "OZO", !isLoading, Modifier.weight(1f))
                                RiskCompactTextField(ppeCategory, { ppeCategory = it }, "Kategorija", !isLoading, Modifier.weight(1f))
                            }
                            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                RiskCompactTextField(ppeNorm, { ppeNorm = it }, "Norma", !isLoading, Modifier.weight(1f))
                                RiskCompactTextField(ppeDescription, { ppeDescription = it }, "Opis", !isLoading, Modifier.weight(1f))
                            }
                            Button(
