@Composable
private fun VoiceTextField(
    value: String,
    onValueChange: (String) -> Unit,
    label: String,
    placeholder: String,
    enabled: Boolean,
    minLines: Int = 3,
) {
    val context = LocalContext.current
    var voiceError by remember { mutableStateOf("") }
    var pendingLaunch by remember { mutableStateOf(false) }
    val speechLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            val spoken = result.data
                ?.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)
                ?.firstOrNull()
                .orEmpty()
                .trim()
            if (spoken.isNotBlank()) {
                val separator = if (value.isBlank() || value.endsWith(" ") || value.endsWith("\n")) "" else " "
                onValueChange(value + separator + spoken)
            }
        }
        pendingLaunch = false
    }
    val permissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) {
            pendingLaunch = true
        } else {
            voiceError = "Mikrofon nije dopušten."
        }
    }

    LaunchedEffect(pendingLaunch) {
        if (!pendingLaunch) return@LaunchedEffect
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH)
            .putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            .putExtra(RecognizerIntent.EXTRA_LANGUAGE, "hr-HR")
            .putExtra(RecognizerIntent.EXTRA_PROMPT, label)
        runCatching { speechLauncher.launch(intent) }
            .onFailure {
                voiceError = "Govorni unos nije dostupan na ovom uređaju."
                pendingLaunch = false
            }
    }

    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        OutlinedTextField(
            value = value,
            onValueChange = onValueChange,
            modifier = Modifier.fillMaxWidth(),
            label = { Text(label) },
            placeholder = { Text(placeholder) },
            enabled = enabled,
            minLines = minLines,
            maxLines = (minLines + 4).coerceAtLeast(5),
            shape = RoundedCornerShape(16.dp),
            trailingIcon = {
                IconButton(
                    enabled = enabled,
                    onClick = {
                        voiceError = ""
                        val granted = ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED
                        if (granted) {
                            pendingLaunch = true
                        } else {
                            permissionLauncher.launch(Manifest.permission.RECORD_AUDIO)
                        }
                    },
                ) {
                    Icon(Icons.Rounded.Mic, contentDescription = "Diktiraj tekst")
                }
            },
        )
        if (voiceError.isNotBlank()) {
            Text(voiceError, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.error)
        }
    }
}

@Composable
private fun DocumentationMultiSelectField(
    label: String,
    options: List<WorkOrderDocumentationOption>,
    selectedIds: Set<String>,
    enabled: Boolean,
    emptyText: String,
    singleSelection: Boolean = false,
    maxVisibleItems: Int = 96,
    onChange: (Set<String>) -> Unit,
) {
    val visibleOptions = if (maxVisibleItems > 0) {
        options.take(maxVisibleItems)
    } else {
        options
    }
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(label, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
            if (selectedIds.isNotEmpty()) {
                Text(
                    "${selectedIds.size} odabrano",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.Bold,
                )
            }
        }
        if (options.isEmpty()) {
            Text(emptyText, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
            return
        }
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            visibleOptions.forEach { option ->
                val selected = option.id in selectedIds
                FilterChip(
                    selected = selected,
                    onClick = {
                        onChange(
                            if (selected) {
                                selectedIds - option.id
                            } else if (singleSelection) {
                                setOf(option.id)
                            } else {
                                selectedIds + option.id
                            },
                        )
                    },
                    enabled = enabled,
                    leadingIcon = if (selected) {
                        {
                            Icon(
                                Icons.Rounded.CheckCircle,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp),
                            )
                        }
                    } else {
                        null
                    },
                    label = {
                        Column {
                            Text(option.label, maxLines = 1, overflow = TextOverflow.Ellipsis)
                            val subtitle = listOf(option.subtitle, option.status)
                                .map { it.trim() }
                                .filter { it.isNotBlank() }
                                .distinct()
                                .joinToString(" · ")
                            if (subtitle.isNotBlank()) {
                                Text(
                                    subtitle,
                                    style = MaterialTheme.typography.labelSmall,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                )
                            }
                        }
                    },
                )
            }
        }
        if (maxVisibleItems > 0 && options.size > maxVisibleItems) {
            Text(
                "Prikazano prvih $maxVisibleItems stavki. Za kraći prikaz koristi grupu opreme ili pretraživanje u webu.",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
            )
        }
    }
}

@Composable
private fun DocumentationReadOnlyOptionList(
    label: String,
    options: List<WorkOrderDocumentationOption>,
    emptyText: String,
