                                Text(
                                    subtitle,
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                    maxLines = 2,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                    }
                }
            }
        }
        if (options.size > 32) {
            Text(
                "Prikazano prvih 32 stavki za brzi mobilni pregled.",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
            )
        }
    }
}

private enum class DocumentationWorkEquipmentFilter(val label: String) {
    All("Sva oprema"),
    Overdue("Istekla"),
    Upcoming("Uskoro"),
    NoDeadline("Bez roka"),
    Satisfactory("Zadovoljava"),
    Unsatisfactory("Ne zadovoljava"),
}

private enum class DocumentationWorkEquipmentScope(val label: String) {
    Employer("Poslodavac"),
    Location("Lokacija RN-a"),
}

private fun WorkOrderDocumentationOption.workEquipmentDeadline(): LocalDate? =
    parseDateOrNull(meta["deadlineForNextExamination"].orEmpty())

private fun WorkOrderDocumentationOption.workEquipmentFinalGradeText(): String =
    listOf(meta["finalGrade"].orEmpty(), status)
        .firstOrNull { it.isNotBlank() }
        .orEmpty()

private fun WorkOrderDocumentationOption.matchesWorkEquipmentFilter(
    filter: DocumentationWorkEquipmentFilter,
    today: LocalDate,
): Boolean {
    val deadline = workEquipmentDeadline()
    val grade = normalizeDocumentationWorkEquipmentText(workEquipmentFinalGradeText())
    return when (filter) {
        DocumentationWorkEquipmentFilter.All -> true
        DocumentationWorkEquipmentFilter.Overdue -> deadline?.isBefore(today) == true
        DocumentationWorkEquipmentFilter.Upcoming -> deadline != null && !deadline.isBefore(today) && !deadline.isAfter(today.plusDays(30))
        DocumentationWorkEquipmentFilter.NoDeadline -> deadline == null
        DocumentationWorkEquipmentFilter.Satisfactory -> grade.contains("zadovoljava") && !grade.contains("ne zadovoljava")
        DocumentationWorkEquipmentFilter.Unsatisfactory -> grade.contains("ne zadovoljava") || grade.contains("nezadovoljava")
    }
}

private fun WorkOrderDocumentationOption.matchesWorkEquipmentSearch(query: String): Boolean {
    val tokens = normalizeSprVoiceLookup(query)
        .split(" ")
        .map { it.trim() }
        .filter { it.isNotBlank() }
    if (tokens.isEmpty()) return true
    val haystack = normalizeSprVoiceLookup(
        listOf(
            label,
            subtitle,
            status,
            meta["equipmentName"].orEmpty(),
            meta["manufacturer"].orEmpty(),
            meta["model"].orEmpty(),
            meta["serialNumber"].orEmpty(),
            meta["inventoryNumber"].orEmpty(),
            meta["location"].orEmpty(),
            meta["locationName"].orEmpty(),
            meta["testingLocation"].orEmpty(),
            meta["deadlineForNextExamination"].orEmpty(),
            meta["equipmentsTechnicalData"].orEmpty(),
        ).joinToString(" "),
    )
    return tokens.all { token -> haystack.contains(token) }
}

private fun workEquipmentFilterCount(
    options: List<WorkOrderDocumentationOption>,
    filter: DocumentationWorkEquipmentFilter,
    today: LocalDate,
): Int = options.count { it.matchesWorkEquipmentFilter(filter, today) }

private fun WorkOrderDocumentationOption.matchesWorkEquipmentLocation(locationName: String): Boolean {
    val target = locationName.normalizedPickerText()
    if (target.isBlank()) return false
    return matchesWorkEquipmentLocationKey(target)
}

private data class DocumentationWorkEquipmentLocationGroup(
    val key: String,
    val label: String,
    val count: Int,
    val rnLocation: Boolean,
)

private fun WorkOrderDocumentationOption.workEquipmentLocationLabel(): String =
    listOf(
        meta["location"].orEmpty(),
        meta["locationName"].orEmpty(),
        meta["testingLocation"].orEmpty(),
        subtitle,
    )
        .map { it.trim() }
        .firstOrNull { it.isNotBlank() }
        .orEmpty()

private fun workEquipmentLocationKey(value: String): String =
    value.normalizedPickerText().ifBlank { "bez-lokacije" }

private fun WorkOrderDocumentationOption.matchesWorkEquipmentLocationKey(locationKey: String): Boolean {
    val target = locationKey.trim()
    if (target.isBlank()) return true
    val candidate = workEquipmentLocationKey(workEquipmentLocationLabel())
    return candidate == target || candidate.contains(target) || target.contains(candidate)
}

private fun buildDocumentationWorkEquipmentLocationGroups(
    options: List<WorkOrderDocumentationOption>,
    rnLocationName: String,
): List<DocumentationWorkEquipmentLocationGroup> {
    val rnKey = rnLocationName.normalizedPickerText()
    return options
        .groupBy { option -> workEquipmentLocationKey(option.workEquipmentLocationLabel()) }
        .map { (key, groupedOptions) ->
            val rawLabel = groupedOptions.firstOrNull()?.workEquipmentLocationLabel().orEmpty()
            DocumentationWorkEquipmentLocationGroup(
                key = key,
                label = rawLabel.ifBlank { "Bez lokacije" },
                count = groupedOptions.size,
                rnLocation = rnKey.isNotBlank() && (key == rnKey || key.contains(rnKey) || rnKey.contains(key)),
            )
        }
        .sortedWith(
            compareByDescending<DocumentationWorkEquipmentLocationGroup> { it.rnLocation }
                .thenBy { it.label.lowercase(Locale.getDefault()) },
        )
}

private fun defaultDocumentationWorkEquipmentLocationKey(groups: List<DocumentationWorkEquipmentLocationGroup>): String =
    groups.firstOrNull { it.rnLocation }?.key ?: groups.firstOrNull()?.key.orEmpty()

private enum class DocumentationPhysicalFactorsFilter(val label: String) {
    All("Svi FC"),
    Overdue("Istekli"),
    Upcoming("Uskoro"),
    NoDeadline("Bez roka"),
    Satisfactory("Zadovoljava"),
    Unsatisfactory("Ne zadovoljava"),
}

private fun WorkOrderDocumentationOption.physicalFactorsDeadline(): LocalDate? =
    parseDateOrNull(meta["deadlineForNextExamination"].orEmpty())

private fun WorkOrderDocumentationOption.physicalFactorsFinalGradeText(): String =
    listOf(meta["finalGrade"].orEmpty(), status)
        .firstOrNull { it.isNotBlank() }
        .orEmpty()

private fun WorkOrderDocumentationOption.matchesPhysicalFactorsFilter(
    filter: DocumentationPhysicalFactorsFilter,
    today: LocalDate,
): Boolean {
    val deadline = physicalFactorsDeadline()
    val grade = normalizeDocumentationWorkEquipmentText(physicalFactorsFinalGradeText())
    return when (filter) {
        DocumentationPhysicalFactorsFilter.All -> true
        DocumentationPhysicalFactorsFilter.Overdue -> deadline?.isBefore(today) == true
        DocumentationPhysicalFactorsFilter.Upcoming -> deadline != null && !deadline.isBefore(today) && !deadline.isAfter(today.plusDays(30))
        DocumentationPhysicalFactorsFilter.NoDeadline -> deadline == null
        DocumentationPhysicalFactorsFilter.Satisfactory -> grade.contains("zadovoljava") && !grade.contains("ne zadovoljava")
        DocumentationPhysicalFactorsFilter.Unsatisfactory -> grade.contains("ne zadovoljava") || grade.contains("nezadovoljava")
    }
}

private fun physicalFactorsFilterCount(
    options: List<WorkOrderDocumentationOption>,
    filter: DocumentationPhysicalFactorsFilter,
    today: LocalDate,
): Int = options.count { it.matchesPhysicalFactorsFilter(filter, today) }

