                    max = draft.handArmVibrationMax,
                    enabled = enabled,
                    onAllowedChange = { draft = draft.copy(handArmVibrationLimit = it) },
                    onMinChange = { draft = draft.copy(handArmVibrationMin = it) },
                    onMaxChange = { draft = draft.copy(handArmVibrationMax = it) },
                )
                WorkOrderTextField("Upozoravajuća vrijednost šaka-ruka", draft.handArmVibrationWarning, { draft = draft.copy(handArmVibrationWarning = it) }, enabled)
                PhysicalFactorsLimitFields(
                    title = "Vibracije cijelo tijelo A(8)",
                    allowedLabel = "Granična vrijednost",
                    allowed = draft.wholeBodyVibrationLimit,
                    min = draft.wholeBodyVibrationMin,
                    max = draft.wholeBodyVibrationMax,
                    enabled = enabled,
                    onAllowedChange = { draft = draft.copy(wholeBodyVibrationLimit = it) },
                    onMinChange = { draft = draft.copy(wholeBodyVibrationMin = it) },
                    onMaxChange = { draft = draft.copy(wholeBodyVibrationMax = it) },
                )
                WorkOrderTextField("Upozoravajuća vrijednost cijelo tijelo", draft.wholeBodyVibrationWarning, { draft = draft.copy(wholeBodyVibrationWarning = it) }, enabled)
            }
        },
        confirmButton = {
            Button(
                onClick = { onConfirm(target, draft.copy(name = draft.name.trim())) },
                enabled = enabled && draft.name.trim().isNotBlank(),
                shape = RoundedCornerShape(16.dp),
            ) {
                Text("Spremi prostor", fontWeight = FontWeight.Black)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun DocumentationManualPhysicalFactorsBlocks(
    value: IsznrManualPhysicalFactors,
    measurementTemplates: List<WorkOrderDocumentationTemplate>,
    measurementSheets: Map<String, WorkOrderMeasurementSheet>,
    enabled: Boolean,
    onChange: (IsznrManualPhysicalFactors) -> Unit,
    onMeasurementSheetChange: (String, WorkOrderMeasurementSheet) -> Unit,
) {
    val derivedSpaceGrades = remember(value.spaces, value.measurements, measurementTemplates, measurementSheets) {
        val sheetMeasurements = buildPhysicalFactorsMeasurementsFromSheets(value, measurementTemplates, measurementSheets)
        physicalFactorsDerivedSpaceGrades(
            spaces = value.spaces,
            measurements = sheetMeasurements.ifEmpty { value.measurements },
        )
    }
    var spaceDialogTarget by remember { mutableStateOf<PhysicalFactorsSpaceDialogTarget?>(null) }

    fun editableSpaces(): List<IsznrFcSpaceDraft> =
        if (value.spaces.size == 1 && value.spaces.first().isBlankPhysicalFactorsSpaceDraft()) {
            emptyList()
        } else {
            value.spaces
        }

    fun syncMeasurementSheetsWithSpaces(spaces: List<IsznrFcSpaceDraft>) {
        measurementTemplates
            .flatMap { documentationTemplate -> documentationTemplate.measurementTables.map { table -> documentationTemplate to table } }
            .filter { (_, table) -> table.id == PHYSICAL_FACTORS_BUILT_IN_TABLE_ID || table.sheet.isBuiltInPhysicalFactorsSheet() }
            .forEach { (documentationTemplate, table) ->
                val stateKey = measurementSheetStateKey(documentationTemplate, table)
                val currentSheet = measurementSheets[stateKey] ?: table.sheet
                val nextSheet = currentSheet.withPhysicalFactorsSyncedSpaces(spaces)
                if (nextSheet != currentSheet) {
                    onMeasurementSheetChange(stateKey, nextSheet)
                }
            }
    }

    fun addMeasurementRowFromSpace(space: IsznrFcSpaceDraft, originalName: String = "") {
        val measurementTable = measurementTemplates
            .flatMap { documentationTemplate -> documentationTemplate.measurementTables.map { table -> documentationTemplate to table } }
            .firstOrNull { (_, table) -> table.id == PHYSICAL_FACTORS_BUILT_IN_TABLE_ID || table.sheet.isBuiltInPhysicalFactorsSheet() }
            ?: return
        val (documentationTemplate, table) = measurementTable
        val stateKey = measurementSheetStateKey(documentationTemplate, table)
        val currentSheet = measurementSheets[stateKey] ?: table.sheet
        val nextSheet = currentSheet.withPhysicalFactorsSpaceDraftRows(space, originalName)
        if (nextSheet != currentSheet) {
            onMeasurementSheetChange(stateKey, nextSheet)
        }
    }

    LaunchedEffect(value.spaces, measurementTemplates) {
        syncMeasurementSheetsWithSpaces(editableSpaces())
    }

    fun openTemplateDialog(template: PhysicalFactorsSpaceTemplate) {
        val timestamp = System.currentTimeMillis()
        val nextSpace = template
            .toSpaceDraft("manual-space-${template.id}-${editableSpaces().size + 1}-$timestamp")
            .withPhysicalFactorsCommonConditions(value.airTemperature, value.relativeAirHumidity, value.airFlowSpeed)
        spaceDialogTarget = PhysicalFactorsSpaceDialogTarget(
            title = "Dodaj prostor - ${template.name}",
            index = null,
            originalName = "",
            draft = nextSpace,
        )
    }

    fun openBlankSpaceDialog() {
        val nextIndex = editableSpaces().size + 1
        spaceDialogTarget = PhysicalFactorsSpaceDialogTarget(
            title = "Dodaj prazan prostor",
            index = null,
            originalName = "",
            draft = defaultPhysicalFactorsSpaceDraft(
                id = "manual-space-$nextIndex-${System.currentTimeMillis()}",
                name = "Prostor $nextIndex",
            ).withPhysicalFactorsCommonConditions(value.airTemperature, value.relativeAirHumidity, value.airFlowSpeed),
        )
    }

    fun saveSpaceDialog(target: PhysicalFactorsSpaceDialogTarget, draft: IsznrFcSpaceDraft) {
        val normalizedDraft = draft.copy(id = draft.id.ifBlank { "manual-space-${System.currentTimeMillis()}" })
        val nextSpaces = if (target.index == null) {
            editableSpaces() + normalizedDraft
        } else {
            value.spaces.mapIndexed { index, space -> if (index == target.index) normalizedDraft else space }
        }
        onChange(value.copy(spaces = nextSpaces))
        addMeasurementRowFromSpace(normalizedDraft, target.originalName)
        spaceDialogTarget = null
    }

    spaceDialogTarget?.let { target ->
        PhysicalFactorsSpaceDialog(
            target = target,
            enabled = enabled,
            onDismiss = { spaceDialogTarget = null },
            onConfirm = ::saveSpaceDialog,
        )
    }

    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(18.dp),
            color = Color(0xFFEFF6FF),
            tonalElevation = 0.dp,
        ) {
            Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text("Novi FC unos", fontWeight = FontWeight.Black)
                Text(
                    "Unesi novi zapisnik po blokovima. Mjerenja koriste ugrađenu RO-F.3 tablicu iz Excel logike.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                )
            }
        }
        ManualPhysicalFactorsBlock(title = "1. Osnovni podaci") {
            WorkOrderTextField("Mjesto ispitivanja", value.location, { onChange(value.copy(location = it)) }, enabled)
            WorkOrderDatePickerField("Datum početka", value.startDate, { onChange(value.copy(startDate = it)) }, enabled)
            WorkOrderDatePickerField("Datum završetka", value.endDate, { onChange(value.copy(endDate = it)) }, enabled)
            WorkOrderDatePickerField(
                "Rok sljedećeg ispitivanja",
                value.deadlineForNextExamination,
                { onChange(value.copy(deadlineForNextExamination = it)) },
                enabled,
            )
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                physicalFactorsTypeOptions.forEach { option ->
                    val selected = value.typesOfExamination.contains(option.first)
                    FilterChip(
                        selected = selected,
                        enabled = enabled,
                        onClick = {
                            val nextTypes = if (selected) {
                                value.typesOfExamination.filterNot { it == option.first }
                            } else {
                                value.typesOfExamination + option.first
                            }
                            onChange(value.copy(typesOfExamination = nextTypes.distinct()))
                        },
                        label = { Text(option.second) },
                    )
                }
            }
            WorkOrderTextField("Tehnička dokumentacija", value.technicalDocumentation, { onChange(value.copy(technicalDocumentation = it)) }, enabled)
            WorkOrderTextField("Metode, postupci i norme", value.methodsProceduresAndNorms, { onChange(value.copy(methodsProceduresAndNorms = it)) }, enabled)
            WorkOrderTextField("Uvjeti procesa rada", value.workProcessConditions, { onChange(value.copy(workProcessConditions = it)) }, enabled)
            WorkOrderTextField(
                "Temperatura zraka",
                value.airTemperature,
                { onChange(value.withPhysicalFactorsCommonConditions(airTemperature = it)) },
                enabled,
            )
            WorkOrderTextField(
                "Relativna vlaga",
                value.relativeAirHumidity,
                { onChange(value.withPhysicalFactorsCommonConditions(relativeHumidity = it)) },
                enabled,
            )
            WorkOrderTextField(
                "Brzina strujanja zraka",
                value.airFlowSpeed,
                { onChange(value.withPhysicalFactorsCommonConditions(airFlowSpeed = it)) },
                enabled,
            )
        }
        ManualPhysicalFactorsBlock(title = "2. Prostori") {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
                color = Color(0xFFF8FAFC),
                tonalElevation = 0.dp,
            ) {
                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        Icon(Icons.Rounded.Description, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                        Column(modifier = Modifier.weight(1f)) {
                            Text("Predlošci prostora", fontWeight = FontWeight.Black)
                            Text(
                                "Ubaci gotov naziv, opis namjene, proces rada, opremu i mjerne vrijednosti.",
                                style = MaterialTheme.typography.labelMedium,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                            )
                        }
                    }
                    OutlinedButton(
                        onClick = { openBlankSpaceDialog() },
                        enabled = enabled,
                        shape = RoundedCornerShape(16.dp),
                    ) {
                        Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(Modifier.width(8.dp))
                        Text("Novi prostor")
                    }
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        physicalFactorsSpaceTemplates.forEach { template ->
                            AssistChip(
                                onClick = { openTemplateDialog(template) },
                                enabled = enabled,
                                label = {
                                    Column {
                                        Text(template.name, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                        Text(
                                            "${template.illuminationAllowed} lx · ${template.noiseAllowed} dB",
                                            style = MaterialTheme.typography.labelSmall,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                        )
                                    }
                                },
                                leadingIcon = {
                                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                                },
                            )
                        }
                    }
                }
            }
            value.spaces.forEachIndexed { index, space ->
                val effectiveFinalGrade = derivedSpaceGrades[space.id].orEmpty().ifBlank { space.finalGrade.ifBlank { "1" } }
                val finalGradePositive = effectiveFinalGrade != "0"
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surface.copy(alpha = 0.74f),
                    tonalElevation = 0.dp,
                ) {
                    Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text("Prostor ${index + 1}", modifier = Modifier.weight(1f), fontWeight = FontWeight.Bold)
                            IconButton(
                                enabled = enabled && value.spaces.size > 1,
                                onClick = {
                                    val nextSpaces = value.spaces.filterIndexed { spaceIndex, _ -> spaceIndex != index }
                                    val validSpaceIds = nextSpaces.map { it.id }.toSet()
                                    val nextMeasurements = value.measurements.filter { measurement ->
                                        measurement.spaceId.isBlank() || validSpaceIds.contains(measurement.spaceId)
                                    }
                                    onChange(value.copy(spaces = nextSpaces, measurements = nextMeasurements))
                                    syncMeasurementSheetsWithSpaces(nextSpaces)
                                },
                            ) {
                                Icon(Icons.Rounded.Delete, contentDescription = "Ukloni prostor", tint = Color(0xFFDC2626))
                            }
                            TextButton(
                                enabled = enabled,
                                onClick = {
                                    spaceDialogTarget = PhysicalFactorsSpaceDialogTarget(
                                        title = "Uredi prostor - ${space.name.ifBlank { "Prostor ${index + 1}" }}",
                                        index = index,
                                        originalName = space.name,
                                        draft = space,
                                    )
                                },
                            ) {
                                Text("Vrijednosti")
                            }
                        }
                        WorkOrderTextField("Naziv prostora *", space.name, { next ->
                            onChange(value.copy(spaces = value.spaces.mapIndexed { i, item -> if (i == index) item.copy(name = next) else item }))
                        }, enabled)
                        OutlinedButton(
                            onClick = {
                                onChange(value.copy(spaces = value.spaces.mapIndexed { i, item ->
                                    if (i == index) item.withAiPhysicalFactorsSpaceDescription() else item
                                }))
                            },
                            enabled = enabled && space.name.trim().isNotBlank(),
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.Fingerprint, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(8.dp))
                            Text("NexAI opis")
                        }
                        WorkOrderTextField(
                            "Opis prostora",
                            space.description,
                            { next -> onChange(value.copy(spaces = value.spaces.mapIndexed { i, item -> if (i == index) item.copy(description = next) else item })) },
                            enabled,
                            singleLine = false,
                            minLines = 3,
                            maxLines = 7,
                        )
                        WorkOrderTextField(
                            "Proces rada",
                            space.workProcess,
                            { next -> onChange(value.copy(spaces = value.spaces.mapIndexed { i, item -> if (i == index) item.copy(workProcess = next) else item })) },
                            enabled,
                            singleLine = false,
                            minLines = 3,
                            maxLines = 7,
                        )
                        WorkOrderTextField(
                            "Radna oprema u prostoru",
                            space.workEquipment,
                            { next -> onChange(value.copy(spaces = value.spaces.mapIndexed { i, item -> if (i == index) item.copy(workEquipment = next) else item })) },
                            enabled,
                            singleLine = false,
                            minLines = 3,
                            maxLines = 7,
                        )
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(14.dp),
                            color = if (finalGradePositive) Color(0xFFE8F7EF) else Color(0xFFFFEBEE),
                            tonalElevation = 0.dp,
                        ) {
                            Row(
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                            ) {
                                Icon(
                                    if (finalGradePositive) Icons.Rounded.CheckCircle else Icons.Rounded.ErrorOutline,
                                    contentDescription = null,
                                    tint = if (finalGradePositive) Color(0xFF15803D) else Color(0xFFDC2626),
                                )
                                Column(modifier = Modifier.weight(1f)) {
                                    Text("Zaključna ocjena prostora", fontWeight = FontWeight.Black)
                                    Text(
                                        if (finalGradePositive) "Sva mjerna mjesta zadovoljavaju" else "Postoji mjerno mjesto koje ne zadovoljava",
                                        style = MaterialTheme.typography.labelMedium,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                                    )
                                }
                                Text(
                                    if (finalGradePositive) "Zadovoljava" else "Ne zadovoljava",
                                    fontWeight = FontWeight.Black,
                                    color = if (finalGradePositive) Color(0xFF15803D) else Color(0xFFDC2626),
                                )
                            }
                        }
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            AssistChip(onClick = {}, label = { Text(if (finalGradePositive) "Zadovoljava" else "Ne zadovoljava") })
                            if (space.workEquipment.isNotBlank()) {
                                AssistChip(onClick = {}, label = { Text("Oprema upisana") })
                            }
                            if (space.workProcess.isNotBlank()) {
                                AssistChip(onClick = {}, label = { Text("Proces rada") })
                            }
                        }
                    }
                }
            }
            OutlinedButton(
                onClick = { openBlankSpaceDialog() },
                enabled = enabled,
                shape = RoundedCornerShape(16.dp),
            ) {
                Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(8.dp))
                Text("Novi prostor bez predloška")
            }
        }
        ManualPhysicalFactorsBlock(title = "3. Mjerenja") {
            Text(
                "Prva kolona koristi samo prostore dodane u bloku Prostori. Kod novog zapisnika po starim papirima dodani prostori se automatski ponavljaju u mjernoj tablici.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
            )
            if (measurementTemplates.isEmpty()) {
                Text(
                    "FC mjerna tablica nije dostupna.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                )
            } else {
                measurementTemplates.forEach { template ->
                    template.measurementTables.forEach { table ->
                        val stateKey = measurementSheetStateKey(template, table)
                        MeasurementTableEditor(
                            template = template,
                            table = table,
                            sheet = measurementSheets[stateKey] ?: table.sheet,
                            enabled = enabled,
                            spaceOptions = editableSpaces()
                                .map { space -> space.name.trim() }
                                .filter { it.isNotBlank() }
                                .distinctBy { it.lowercase(Locale.getDefault()) }
                                .map { name -> name to name },
                            requireSpaceSelection = true,
                            onSheetChange = { nextSheet -> onMeasurementSheetChange(stateKey, nextSheet) },
                        )
                    }
                }
            }
        }
    }
}

