}

@Composable
private fun DocumentationWorkEquipmentOptionList(
    options: List<WorkOrderDocumentationOption>,
    companyName: String,
    locationName: String,
    emptyText: String,
    statusMessage: String = "",
    postDraftStatus: Map<String, String> = emptyMap(),
    mechanicalOptions: List<WorkOrderDocumentationOption> = emptyList(),
    electricalOptions: List<WorkOrderDocumentationOption> = emptyList(),
    hazardOptions: List<WorkOrderDocumentationOption> = emptyList(),
    harmfulnessOptions: List<WorkOrderDocumentationOption> = emptyList(),
    strainOptions: List<WorkOrderDocumentationOption> = emptyList(),
    selectedItemIds: Set<String>,
    manualEquipments: List<IsznrManualWorkEquipment>,
    enabled: Boolean = true,
    onSelectedItemIdsChange: (Set<String>) -> Unit,
    onManualEquipmentsChange: (List<IsznrManualWorkEquipment>) -> Unit,
    onRecognizeWorkEquipmentImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onRecognizeWorkEquipmentBatchImages: (
        List<IsznrManualWorkEquipment>,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
) {
    val today = remember { LocalDate.now() }
    var selectedFilter by remember(options) { mutableStateOf(DocumentationWorkEquipmentFilter.All) }
    var workEquipmentQuery by rememberSaveable(options) { mutableStateOf("") }
    var selectedScope by remember(options, locationName) {
        mutableStateOf(if (locationName.isNotBlank()) DocumentationWorkEquipmentScope.Location else DocumentationWorkEquipmentScope.Employer)
    }
    var hasSeededWorkEquipmentColumns by remember(options, locationName) { mutableStateOf(false) }
    var activeManualEquipmentIndex by remember(options, locationName) { mutableStateOf(0) }
    val filteredOptions = remember(options, selectedFilter, today) {
        options
            .filter { option -> option.matchesWorkEquipmentFilter(selectedFilter, today) }
            .sortedWith(
                compareBy<WorkOrderDocumentationOption> { option ->
                    option.workEquipmentDeadline() ?: LocalDate.MAX
                }.thenBy { option -> option.label.lowercase(Locale.getDefault()) },
            )
    }
    val searchedOptions = remember(filteredOptions, workEquipmentQuery) {
        filteredOptions.filter { option -> option.matchesWorkEquipmentSearch(workEquipmentQuery) }
    }
    val locationGroups = remember(options, locationName) {
        buildDocumentationWorkEquipmentLocationGroups(options, locationName)
    }
    var selectedLocationKey by remember(options, locationName) {
        mutableStateOf(defaultDocumentationWorkEquipmentLocationKey(locationGroups))
    }
    LaunchedEffect(locationGroups, selectedScope) {
        if (selectedScope == DocumentationWorkEquipmentScope.Location && locationGroups.none { it.key == selectedLocationKey }) {
            selectedLocationKey = defaultDocumentationWorkEquipmentLocationKey(locationGroups)
        }
    }
    val selectedLocationGroup = remember(locationGroups, selectedLocationKey) {
        locationGroups.firstOrNull { it.key == selectedLocationKey }
    }
    val locationOptions = remember(filteredOptions, selectedLocationKey) {
        filteredOptions.filter { option -> option.matchesWorkEquipmentLocationKey(selectedLocationKey) }
    }
    val visibleOptions = remember(searchedOptions) { searchedOptions }
    val overdueCount = remember(options, today) { workEquipmentFilterCount(options, DocumentationWorkEquipmentFilter.Overdue, today) }
    val upcomingCount = remember(options, today) { workEquipmentFilterCount(options, DocumentationWorkEquipmentFilter.Upcoming, today) }
    val postDraftMissingLabels = postDraftStatus["postDraftMissingLabels"].orEmpty()
        .split(",")
        .map { it.trim() }
        .filter { it.isNotBlank() }
    val postDraftBlockingKeys = postDraftStatus["postDraftMissingKeys"].orEmpty()
        .split(",")
        .map { it.trim() }
        .filter { it.isNotBlank() && it != "equipments" }
    val readyManualEquipments = manualEquipments.filter { it.isReadyForIsznrPost() }
    val selectedTotal = selectedItemIds.size + readyManualEquipments.size
    val seedOptions = remember(selectedItemIds, visibleOptions) {
        val selectedOptions = visibleOptions.filter { option -> option.id.isNotBlank() && selectedItemIds.contains(option.id) }
        selectedOptions.ifEmpty { visibleOptions }
    }
    LaunchedEffect(seedOptions, manualEquipments.size, hasSeededWorkEquipmentColumns) {
        if (!hasSeededWorkEquipmentColumns && manualEquipments.isEmpty() && seedOptions.isNotEmpty()) {
            val seededIds = seedOptions.map { it.id }.filter { it.isNotBlank() }.toSet()
            hasSeededWorkEquipmentColumns = true
            activeManualEquipmentIndex = 0
            onSelectedItemIdsChange(selectedItemIds - seededIds)
            onManualEquipmentsChange(seedOptions.map { it.toManualWorkEquipment() })
        }
    }
    LaunchedEffect(manualEquipments.size) {
        activeManualEquipmentIndex = when {
            manualEquipments.isEmpty() -> 0
            activeManualEquipmentIndex < 0 -> 0
            activeManualEquipmentIndex > manualEquipments.lastIndex -> manualEquipments.lastIndex
            else -> activeManualEquipmentIndex
        }
    }

    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text("Pregled radne opreme", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
                Text(
                    "${options.size} stavki · $overdueCount isteklo · $upcomingCount uskoro",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            }
            Surface(shape = RoundedCornerShape(12.dp), color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f)) {
                Text(
                    "${visibleOptions.size}",
                    modifier = Modifier.padding(horizontal = 11.dp, vertical = 7.dp),
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.Black,
                )
            }
        }
        if (statusMessage.isNotBlank()) {
            Text(
                statusMessage,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
            )
        }
        if (options.isEmpty()) {
            Text(emptyText, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
        }
        OutlinedTextField(
            value = workEquipmentQuery,
            onValueChange = { workEquipmentQuery = it },
            modifier = Modifier.fillMaxWidth(),
            label = { Text("Traži radnu opremu") },
            placeholder = { Text("Naziv, proizvođač, model, lokacija, serijski...") },
            leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
            trailingIcon = {
                if (workEquipmentQuery.isNotBlank()) {
                    IconButton(onClick = { workEquipmentQuery = "" }) {
                        Icon(Icons.Rounded.Close, contentDescription = "Očisti pretragu")
                    }
                }
            },
            singleLine = true,
            enabled = enabled,
            keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
            shape = RoundedCornerShape(18.dp),
        )
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            DocumentationWorkEquipmentFilter.entries.forEach { filter ->
                val count = workEquipmentFilterCount(options, filter, today)
                FilterChip(
                    selected = selectedFilter == filter,
                    onClick = { selectedFilter = filter },
                    label = { Text("${filter.label} ($count)") },
                    enabled = count > 0 || filter == DocumentationWorkEquipmentFilter.All,
                )
            }
        }
        if (workEquipmentQuery.isNotBlank()) {
            Text(
                "Pronađeno ${visibleOptions.size} od ${filteredOptions.size} stavki za ovu pretragu.",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
            )
        }
        WorkEquipmentBatchNexAiUploadCard(
            enabled = enabled,
            manualEquipments = manualEquipments,
            onRecognizeBatchImages = onRecognizeWorkEquipmentBatchImages,
            onApply = { nextEquipments, focusIndex ->
                onManualEquipmentsChange(nextEquipments)
                activeManualEquipmentIndex = focusIndex.coerceIn(0, nextEquipments.lastIndex.coerceAtLeast(0))
            },
        )
        if (manualEquipments.isNotEmpty()) {
            val safeIndex = activeManualEquipmentIndex.coerceIn(0, manualEquipments.lastIndex)
            ManualWorkEquipmentRowList(
                equipments = manualEquipments,
                activeIndex = safeIndex,
                enabled = enabled,
                onSelect = { index -> activeManualEquipmentIndex = index },
            )
        }
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.45f),
        ) {
            Column(
                modifier = Modifier.padding(10.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Text(
                        if (selectedTotal == 0) "Kolone RO zapisnika" else "$selectedTotal stupaca odabrano",
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface,
                    )
                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        OutlinedButton(
                            onClick = {
                                onSelectedItemIdsChange(selectedItemIds + visibleOptions.map { it.id }.filter { it.isNotBlank() })
                            },
                            enabled = enabled && visibleOptions.isNotEmpty(),
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                        ) {
                            Text("Dodaj prikazane")
                        }
                        OutlinedButton(
                            onClick = {
                                onSelectedItemIdsChange(emptySet())
                                onManualEquipmentsChange(emptyList())
                            },
                            enabled = enabled && (selectedItemIds.isNotEmpty() || manualEquipments.isNotEmpty()),
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                        ) {
                            Text("Poništi")
                        }
                        OutlinedButton(
                            onClick = {
                                onManualEquipmentsChange(manualEquipments + IsznrManualWorkEquipment())
                                activeManualEquipmentIndex = manualEquipments.size
                            },
                            enabled = enabled,
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                        ) {
                            Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Dodaj stupac")
                        }
                    }
                }
                if (postDraftBlockingKeys.isNotEmpty()) {
                    Text(
                        "Fali prije slanja: ${postDraftMissingLabels.filterNot { it.equals("Odabrana radna oprema", ignoreCase = true) }.joinToString(", ")}",
                        style = MaterialTheme.typography.labelSmall,
                        color = Color(0xFFB45309),
                    )
                }
                Text(
                    "Slanje RO zapisnika je u Sažetku.",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            }
        }
        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            if (manualEquipments.isEmpty()) {
                Text(
                    if (visibleOptions.isEmpty()) {
                        "Nema radne opreme za ovaj filter ili tab."
                    } else {
                        "Pripremam stupce radne opreme..."
                    },
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            } else {
                val safeIndex = activeManualEquipmentIndex.coerceIn(0, manualEquipments.lastIndex)
                val activeEquipment = manualEquipments[safeIndex]
                ManualWorkEquipmentInlineEditor(
                    equipment = activeEquipment,
                    columnIndex = safeIndex,
                    columnCount = manualEquipments.size,
                    enabled = enabled,
                    mechanicalOptions = mechanicalOptions,
                    electricalOptions = electricalOptions,
                    hazardOptions = hazardOptions,
                    harmfulnessOptions = harmfulnessOptions,
                    strainOptions = strainOptions,
                    onPrevious = { activeManualEquipmentIndex = (safeIndex - 1).coerceAtLeast(0) },
                    onNext = { activeManualEquipmentIndex = (safeIndex + 1).coerceAtMost(manualEquipments.lastIndex) },
                    onAddColumn = {
                        onManualEquipmentsChange(manualEquipments + IsznrManualWorkEquipment())
                        activeManualEquipmentIndex = manualEquipments.size
                    },
                    onRemove = {
                        onManualEquipmentsChange(manualEquipments.filterIndexed { index, _ -> index != safeIndex })
                        activeManualEquipmentIndex = (safeIndex - 1).coerceAtLeast(0)
                    },
                    onRecognizeImages = { equipmentForRecognition, files, onSuccess, onFailure ->
                        onRecognizeWorkEquipmentImages(equipmentForRecognition, files, onSuccess, onFailure)
                    },
                    onEquipmentChange = { updatedEquipment ->
                        onManualEquipmentsChange(
                            manualEquipments.mapIndexed { index, item ->
                                if (index == safeIndex) updatedEquipment else item
                            },
                        )
                    },
                )
            }
        }
    }
}

