@Composable
private fun DocumentationEquipmentInspectionLocalList(
    manualEquipments: List<IsznrManualWorkEquipment>,
    serviceCode: String = "STROJEVI",
    enabled: Boolean = true,
    mechanicalOptions: List<WorkOrderDocumentationOption> = emptyList(),
    electricalOptions: List<WorkOrderDocumentationOption> = emptyList(),
    hazardOptions: List<WorkOrderDocumentationOption> = emptyList(),
    harmfulnessOptions: List<WorkOrderDocumentationOption> = emptyList(),
    strainOptions: List<WorkOrderDocumentationOption> = emptyList(),
    onManualEquipmentsChange: (List<IsznrManualWorkEquipment>) -> Unit,
    onRecognizeWorkEquipmentImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
) {
    var activeManualEquipmentIndex by rememberSaveable { mutableStateOf(0) }
    val isStrojeviTemplate = normalizeDocumentationServiceCodeToken(serviceCode) == "STROJEVI"
    val resolvedMechanicalOptions = remember(mechanicalOptions, isStrojeviTemplate) {
        if (isStrojeviTemplate) {
            emptyList()
        } else {
            mechanicalOptions.ifEmpty { defaultEquipmentInspectionMechanicalOptions() }
        }
    }
    val resolvedElectricalOptions = remember(electricalOptions, isStrojeviTemplate) {
        if (isStrojeviTemplate) {
            emptyList()
        } else {
            electricalOptions.ifEmpty { defaultEquipmentInspectionElectricalOptions() }
        }
    }
    LaunchedEffect(manualEquipments.size) {
        if (manualEquipments.isEmpty()) {
            onManualEquipmentsChange(listOf(IsznrManualWorkEquipment()))
            activeManualEquipmentIndex = 0
        } else {
            activeManualEquipmentIndex = activeManualEquipmentIndex.coerceIn(0, manualEquipments.lastIndex)
        }
    }

    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(18.dp),
            color = Color(0xFFF0F9FF),
            border = BorderStroke(1.dp, Color(0xFFBAE6FD)),
            tonalElevation = 0.dp,
        ) {
            Column(
                modifier = Modifier.padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Surface(shape = CircleShape, color = Color(0xFFDBEAFE), modifier = Modifier.size(40.dp)) {
                        Box(contentAlignment = Alignment.Center) {
                            Icon(Icons.Rounded.Work, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                        }
                    }
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(if (isStrojeviTemplate) "STROJEVI - nadzor opreme" else "Nadzor opreme", fontWeight = FontWeight.Black)
                        Text(
                            if (isStrojeviTemplate) {
                                "Lokalni predložak iz STROJEVI.1. Ispitne stavke su proizvoljne i idu u STROJEVI.2 izlaz."
                            } else {
                                "Lokalni predložak. Unosiš opremu po stupcima, bez IS ZNR slanja i bez obaveznog NexAI troška."
                            },
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                        )
                    }
                }
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    AssistChip(onClick = {}, enabled = false, label = { Text("${manualEquipments.size.coerceAtLeast(1)} stupac(a)") })
                    AssistChip(
                        onClick = {},
                        enabled = false,
                        label = { Text(if (isStrojeviTemplate) "slobodne stavke" else "${resolvedMechanicalOptions.size} stavki") },
                    )
                    if (!isStrojeviTemplate) {
                        AssistChip(onClick = {}, enabled = false, label = { Text("${resolvedElectricalOptions.size} elektro") })
                    }
                }
            }
        }

        if (manualEquipments.isNotEmpty()) {
            val safeIndex = activeManualEquipmentIndex.coerceIn(0, manualEquipments.lastIndex)
            ManualWorkEquipmentRowList(
                equipments = manualEquipments,
                activeIndex = safeIndex,
                enabled = enabled,
                recordLabel = if (isStrojeviTemplate) "STROJEVI" else "NO",
                defaultTitle = if (isStrojeviTemplate) "Stroj / uređaj" else "Oprema",
                onSelect = { index -> activeManualEquipmentIndex = index },
            )
            ManualWorkEquipmentInlineEditor(
                equipment = manualEquipments[safeIndex],
                columnIndex = safeIndex,
                columnCount = manualEquipments.size,
                enabled = enabled,
                recordTitle = if (isStrojeviTemplate) "Stroj / uređaj" else "Oprema",
                recordLabel = if (isStrojeviTemplate) "STROJEVI" else "NO",
                isStrojeviTemplate = isStrojeviTemplate,
                showRecognition = false,
                showRiskRegisters = !isStrojeviTemplate,
                mechanicalOptions = resolvedMechanicalOptions,
                electricalOptions = resolvedElectricalOptions,
                hazardOptions = hazardOptions,
                harmfulnessOptions = harmfulnessOptions,
                strainOptions = strainOptions,
                onPrevious = { activeManualEquipmentIndex = (safeIndex - 1).coerceAtLeast(0) },
                onNext = { activeManualEquipmentIndex = (safeIndex + 1).coerceAtMost(manualEquipments.lastIndex) },
                onAddColumn = {
                    onManualEquipmentsChange(manualEquipments + IsznrManualWorkEquipment())
                    activeManualEquipmentIndex = manualEquipments.size
                },
                onRemove = {
                    val nextEquipments = manualEquipments.filterIndexed { index, _ -> index != safeIndex }
                    onManualEquipmentsChange(nextEquipments.ifEmpty { listOf(IsznrManualWorkEquipment()) })
                    activeManualEquipmentIndex = (safeIndex - 1).coerceAtLeast(0)
                },
                onRecognizeImages = onRecognizeWorkEquipmentImages,
                onEquipmentChange = { updatedEquipment ->
                    onManualEquipmentsChange(
                        manualEquipments.mapIndexed { index, item ->
                            if (index == safeIndex) updatedEquipment else item
                        },
                    )
                },
            )
        }
    }
}

@Composable
private fun ManualWorkEquipmentRowList(
    equipments: List<IsznrManualWorkEquipment>,
    activeIndex: Int,
    enabled: Boolean,
    recordLabel: String = "RO",
    defaultTitle: String = "Radna oprema",
    onSelect: (Int) -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.44f),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(10.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    Text("Popis opreme", fontWeight = FontWeight.Black)
                    Text(
                        "Jedan red = jedan stupac $recordLabel zapisnika.",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
                AssistChip(onClick = {}, label = { Text("${equipments.size}") })
            }
            equipments.forEachIndexed { index, equipment ->
                val selected = index == activeIndex
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable(enabled = enabled) { onSelect(index) },
                    shape = RoundedCornerShape(15.dp),
                    color = if (selected) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.82f) else MaterialTheme.colorScheme.surface,
                    border = BorderStroke(
                        1.dp,
                        if (selected) MaterialTheme.colorScheme.primary.copy(alpha = 0.42f) else MaterialTheme.colorScheme.outline.copy(alpha = 0.16f),
                    ),
                    tonalElevation = 0.dp,
                ) {
                    Row(
                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 9.dp),
                        horizontalArrangement = Arrangement.spacedBy(9.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Surface(
                            modifier = Modifier.size(30.dp),
                            shape = CircleShape,
                            color = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.7f),
                        ) {
                            Box(contentAlignment = Alignment.Center) {
                                Text(
                                    "${index + 1}",
                                    color = if (selected) Color.White else MaterialTheme.colorScheme.primary,
                                    fontWeight = FontWeight.Black,
                                    style = MaterialTheme.typography.labelMedium,
                                )
                            }
                        }
                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                            Text(
                                equipment.name.ifBlank { "$defaultTitle ${index + 1}" },
                                fontWeight = FontWeight.Black,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                            Text(
                                equipment.subtitle().ifBlank { "Stupac ${index + 1} · dopuni podatke" },
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                            )
                        }
                        Surface(
                            shape = RoundedCornerShape(999.dp),
                            color = when {
                                selected -> MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)
                                equipment.isReadyForIsznrPost() -> Color(0xFFDCFCE7)
                                else -> Color(0xFFFFF7ED)
                            },
                        ) {
                            Text(
                                if (selected) "Otvoreno" else if (equipment.isReadyForIsznrPost()) "Spremno" else "Dopuni",
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                style = MaterialTheme.typography.labelSmall,
                                color = when {
                                    selected -> MaterialTheme.colorScheme.primary
                                    equipment.isReadyForIsznrPost() -> Color(0xFF047857)
                                    else -> Color(0xFFB45309)
                                },
                                fontWeight = FontWeight.Bold,
                            )
                        }
                    }
                }
            }
        }
    }
}

private fun WorkOrderDocumentationOption.toManualWorkEquipment(): IsznrManualWorkEquipment {
    val labelParts = label.split(" - ").map { it.trim() }.filter { it.isNotBlank() }
    val grade = workEquipmentFinalGradeText()
    return IsznrManualWorkEquipment(
        name = meta["equipmentName"].orEmpty().ifBlank { labelParts.getOrNull(0).orEmpty().ifBlank { label } },
        manufacturer = meta["manufacturer"].orEmpty().ifBlank { labelParts.getOrNull(1).orEmpty() },
        model = meta["model"].orEmpty().ifBlank { labelParts.getOrNull(2).orEmpty() },
        serialNumber = meta["serialNumber"].orEmpty(),
        inventoryNumber = meta["inventoryNumber"].orEmpty(),
        note = meta["note"].orEmpty(),
        technicalData = meta["equipmentsTechnicalData"].orEmpty(),
        purposeDescription = meta["equipmentsPurposeDescription"].orEmpty(),
        workspacePosition = meta["equipmentsWorkspacePosition"].orEmpty().ifBlank { meta["location"].orEmpty() },
        workingSubstancesAndRawMaterials = meta["workingSubstancesAndRawMaterials"].orEmpty(),
        useAndMaintenance = meta["useAndMaintenance"].orEmpty(),
        methodsProceduresAndNorms = meta["methodsProceduresAndNorms"].orEmpty(),
        deficiencies = meta["deficiencies"].orEmpty(),
        measuresToEliminateDeficiencies = meta["measuresToEliminateDeficiencies"].orEmpty(),
        finalGrade = if (grade.contains("ne zadovoljava", ignoreCase = true) || grade.contains("nezadovoljava", ignoreCase = true)) "0" else "1",
    )
}

private fun IsznrManualWorkEquipment.isReadyForIsznrPostPart(): Boolean =
    name.isNotBlank() && listOf(manufacturer, model, serialNumber, inventoryNumber, note).any { it.isNotBlank() }

private fun IsznrManualWorkEquipment.isReadyForIsznrPost(): Boolean =
    isReadyForIsznrPostPart() || parts.any { it.isReadyForIsznrPostPart() }

private fun IsznrFcSpaceDraft.isReadyForPhysicalFactorsPost(): Boolean =
    name.trim().isNotBlank()

private fun IsznrFcMeasurementDraft.isReadyForPhysicalFactorsPost(): Boolean =
    measuringPlace.trim().isNotBlank() && measuredValue.trim().isNotBlank()

private fun IsznrManualPhysicalFactors.isReadyForPhysicalFactorsPost(): Boolean =
    spaces.any { it.isReadyForPhysicalFactorsPost() } && measurements.any { it.isReadyForPhysicalFactorsPost() }

private fun defaultManualPhysicalFactorsDraft(
    workOrder: WorkOrder,
    inspectionDate: String,
    issuedDate: String,
    testingLocation: String,
    outsideTemperature: String,
    relativeHumidity: String,
    airflowSpeed: String,
): IsznrManualPhysicalFactors {
    val spaceId = "manual-space-1"
    val defaultSpaceName = workOrder.objectName
        .ifBlank { workOrder.locationName }
        .ifBlank { "Prostor 1" }
    return IsznrManualPhysicalFactors(
        location = testingLocation.ifBlank { workOrder.locationName },
        startDate = inspectionDate,
        endDate = issuedDate.ifBlank { inspectionDate },
        deadlineForNextExamination = workOrder.dueDate,
        technicalDocumentation = "Tehnička dokumentacija i podaci zatečeni na mjestu ispitivanja.",
        methodsProceduresAndNorms = "Ispitivanje je provedeno prema važećim propisima, normama i pravilima struke.",
        workProcessConditions = "Ispitivanje je provedeno u uvjetima redovitog procesa rada.",
        airTemperature = outsideTemperature,
        relativeAirHumidity = relativeHumidity,
        airFlowSpeed = airflowSpeed,
        spaces = listOf(
            defaultPhysicalFactorsSpaceDraft(spaceId, defaultSpaceName).copy(
                description = workOrder.locationName,
                workProcess = workOrder.description,
            ).withPhysicalFactorsCommonConditions(outsideTemperature, relativeHumidity, airflowSpeed),
        ),
        measurements = listOf(
            IsznrFcMeasurementDraft(
                id = "manual-measurement-1",
                spaceId = spaceId,
            ),
        ),
    )
}

private fun IsznrManualWorkEquipment.subtitle(): String =
    listOf(
        manufacturer,
        model,
        serialNumber.takeIf { it.isNotBlank() }?.let { "Ser. $it" }.orEmpty(),
        inventoryNumber.takeIf { it.isNotBlank() }?.let { "Inv. $it" }.orEmpty(),
        (mechanicalItems.size + electricalItems.size).takeIf { it > 0 }?.let { "$it stručnih stavki" }.orEmpty(),
        (hazardRegisterIris.size + harmfulnessRegisterIris.size + strainRegisterIris.size).takeIf { it > 0 }?.let { "$it rizika" }.orEmpty(),
        attachments.count { it.isRoImageAttachment() }.takeIf { it > 0 }?.let { "$it slika" }.orEmpty(),
        attachments.count { it.isRoPdfAttachment() }.takeIf { it > 0 }?.let { "$it PDF" }.orEmpty(),
        parts.size.takeIf { it > 0 }?.let { "$it dijelova" }.orEmpty(),
    )
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .joinToString(" · ")

private fun IsznrRoAttachmentFile.isRoImageAttachment(): Boolean =
    fileType.startsWith("image/", ignoreCase = true) || contentDataUrl.startsWith("data:image/", ignoreCase = true)

private fun IsznrRoAttachmentFile.isRoPdfAttachment(): Boolean =
    fileType.equals("application/pdf", ignoreCase = true) || contentDataUrl.startsWith("data:application/pdf", ignoreCase = true)

private fun roAttachmentRoleLabel(role: String): String =
    when (role.trim().lowercase(Locale.getDefault())) {
        "machine" -> "Cijeli stroj"
        "plate" -> "Pločica"
        "detail" -> "Detalj"
        "document" -> "PDF prilog"
        else -> "Slika"
    }

private fun roAttachmentRoleColor(role: String): Color =
    when (role.trim().lowercase(Locale.getDefault())) {
        "machine" -> Color(0xFFDCFCE7)
        "plate" -> Color(0xFFE0F2FE)
        "detail" -> Color(0xFFFEF3C7)
        "document" -> Color(0xFFFEE2E2)
        else -> Color(0xFFF1F5F9)
    }

private fun withDefaultRoImageRoles(
    existing: List<IsznrRoAttachmentFile>,
    added: List<IsznrRoAttachmentFile>,
): List<IsznrRoAttachmentFile> {
    val existingImages = existing.count { it.isRoImageAttachment() }
    return added.mapIndexed { index, file ->
        if (!file.isRoImageAttachment()) {
            file.copy(role = "document")
        } else {
            val imageIndex = existingImages + index
            file.copy(
                role = when (imageIndex) {
                    0 -> "machine"
                    1 -> "plate"
                    else -> "detail"
                },
                includeInReport = true,
            )
        }
    }
}

private fun tagRoAttachmentRolesForEquipment(files: List<IsznrRoAttachmentFile>): List<IsznrRoAttachmentFile> =
    files.mapIndexed { index, file ->
        if (!file.isRoImageAttachment()) {
            file.copy(role = "document")
        } else {
            file.copy(
                role = when (index) {
                    0 -> "machine"
                    1 -> "plate"
                    else -> "detail"
                },
                includeInReport = true,
            )
        }
    }

private fun distributeRoImagesAcrossEquipmentParts(
    equipment: IsznrManualWorkEquipment,
    addedFiles: List<IsznrRoAttachmentFile>,
): IsznrManualWorkEquipment {
    val addedImages = addedFiles.filter { it.isRoImageAttachment() }
    val addedDocuments = addedFiles.filterNot { it.isRoImageAttachment() }
    val hasPartsMode = equipment.hasParts || equipment.parts.isNotEmpty()
    if (!hasPartsMode || addedImages.size <= 1) {
        return equipment.copy(
            attachments = equipment.attachments + withDefaultRoImageRoles(equipment.attachments, addedFiles),
        )
    }

    val mainAlreadyHasMachineImage = equipment.attachments.any {
        it.isRoImageAttachment() && it.role.equals("machine", ignoreCase = true)
    }
    val mainImageCount = if (mainAlreadyHasMachineImage) 0 else 1
    val mainImages = addedImages.take(mainImageCount).map { it.copy(role = "machine", includeInReport = true) }
    val partImages = addedImages.drop(mainImageCount)
    val requiredPartCount = ((partImages.size + 1) / 2).coerceAtLeast(1)
    val currentParts = equipment.parts.ifEmpty { emptyList() }
    val nextParts = currentParts.toMutableList()
    while (nextParts.size < requiredPartCount) {
        nextParts += defaultWorkEquipmentPart(nextParts.size + 1)
    }

    partImages.chunked(2).forEachIndexed { partIndex, chunk ->
        val existingPart = nextParts[partIndex]
        val taggedChunk = chunk.mapIndexed { imageIndex, file ->
            file.copy(
                role = if (imageIndex == 0) "machine" else "plate",
                includeInReport = true,
            )
        }
        nextParts[partIndex] = existingPart.copy(
            attachments = existingPart.attachments + taggedChunk,
        )
    }

    return equipment.copy(
        attachments = equipment.attachments + mainImages + addedDocuments.map { it.copy(role = "document", includeInReport = true) },
        hasParts = true,
        parts = nextParts,
    )
}

private fun decodeRoAttachmentBitmap(file: IsznrRoAttachmentFile): Bitmap? =
    runCatching {
        val raw = file.contentDataUrl.substringAfter("base64,", "")
        if (raw.isBlank()) return@runCatching null
        val bytes = Base64.getDecoder().decode(raw)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }.getOrNull()

private fun sameRoAttachment(first: IsznrRoAttachmentFile, second: IsznrRoAttachmentFile): Boolean =
    first.id.ifBlank { first.fileName } == second.id.ifBlank { second.fileName } &&
        first.fileSize == second.fileSize

@Composable
private fun WorkEquipmentAttachmentGallery(
    title: String,
    subtitle: String,
    attachments: List<IsznrRoAttachmentFile>,
    enabled: Boolean,
    loadingImages: Boolean,
    loadingDocuments: Boolean,
    onAddImages: () -> Unit,
    onAddDocuments: () -> Unit,
    onAttachmentsChange: (List<IsznrRoAttachmentFile>) -> Unit,
) {
    val images = attachments.filter { it.isRoImageAttachment() }
    val documents = attachments.filter { it.isRoPdfAttachment() }

    fun replaceAttachment(target: IsznrRoAttachmentFile, next: IsznrRoAttachmentFile) {
        onAttachmentsChange(attachments.map { file -> if (sameRoAttachment(file, target)) next else file })
    }

    fun removeAttachment(target: IsznrRoAttachmentFile) {
        onAttachmentsChange(attachments.filterNot { file -> sameRoAttachment(file, target) })
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = Color(0xFFF8FAFC),
        border = BorderStroke(1.dp, Color(0xFFD7E3F7)),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Surface(shape = CircleShape, color = Color(0xFFE0F2FE), modifier = Modifier.size(40.dp)) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(Icons.Rounded.Image, contentDescription = null, tint = Color(0xFF2563EB), modifier = Modifier.size(21.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(title, fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                    Text(subtitle, style = MaterialTheme.typography.bodySmall, color = Color(0xFF475569))
                }
            }

            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedButton(
                    onClick = onAddImages,
                    enabled = enabled && !loadingImages && attachments.size < ISZNR_RO_ATTACHMENT_MAX_INLINE_FILES,
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 9.dp),
                ) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (loadingImages) "Učitavam..." else "Dodaj slike")
                }
                OutlinedButton(
                    onClick = onAddDocuments,
                    enabled = enabled && !loadingDocuments && attachments.size < ISZNR_RO_ATTACHMENT_MAX_INLINE_FILES,
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 9.dp),
                ) {
                    Icon(Icons.Rounded.PictureAsPdf, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (loadingDocuments) "Učitavam..." else "Dodaj PDF")
                }
            }

            Text(
                "${attachments.count { it.includeInReport }}/${attachments.size} označeno za zapisnik · ${images.size} slika · ${documents.size} PDF",
                style = MaterialTheme.typography.labelSmall,
                color = Color(0xFF475569),
                fontWeight = FontWeight.Bold,
            )

            if (images.isEmpty()) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = Color.White.copy(alpha = 0.76f),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                ) {
                    Text(
                        "Još nema slika. Dodaj barem sliku cijelog stroja i sliku pločice.",
                        modifier = Modifier.padding(12.dp),
                        style = MaterialTheme.typography.bodySmall,
                        color = Color(0xFF64748B),
                    )
                }
            } else {
                LazyRow(
                    modifier = Modifier
                        .fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    items(images.size) { index ->
                        val file = images[index]
                        val bitmap = remember(file.contentDataUrl) { decodeRoAttachmentBitmap(file) }
                        Surface(
                            modifier = Modifier.width(178.dp),
                            shape = RoundedCornerShape(18.dp),
                            color = if (file.includeInReport) Color.White else Color(0xFFF1F5F9),
                            border = BorderStroke(
                                1.dp,
                                if (file.includeInReport) Color(0xFFBFDBFE) else Color(0xFFCBD5E1),
                            ),
                        ) {
                            Column(
                                modifier = Modifier.padding(9.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp),
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(112.dp)
                                        .clip(RoundedCornerShape(14.dp))
                                        .background(Color(0xFFE2E8F0)),
                                    contentAlignment = Alignment.Center,
                                ) {
                                    if (bitmap != null) {
                                        ComposeImage(
                                            bitmap = bitmap.asImageBitmap(),
                                            contentDescription = file.fileName,
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = ContentScale.Crop,
                                        )
                                    } else {
                                        Icon(Icons.Rounded.Image, contentDescription = null, tint = Color(0xFF64748B), modifier = Modifier.size(30.dp))
                                    }
                                    Surface(
                                        modifier = Modifier
                                            .align(Alignment.TopStart)
                                            .padding(6.dp),
                                        shape = RoundedCornerShape(999.dp),
                                        color = roAttachmentRoleColor(file.role),
                                    ) {
                                        Text(
                                            roAttachmentRoleLabel(file.role),
                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                                            style = MaterialTheme.typography.labelSmall,
                                            fontWeight = FontWeight.Black,
                                            color = Color(0xFF0F172A),
                                        )
                                    }
                                }
                                Text(
                                    file.fileName.ifBlank { "Slika ${index + 1}" },
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                    fontWeight = FontWeight.Bold,
                                )
                                FlowRow(horizontalArrangement = Arrangement.spacedBy(5.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                                    listOf("machine", "plate", "detail").forEach { role ->
                                        FilterChip(
                                            selected = file.role.equals(role, ignoreCase = true),
                                            onClick = { replaceAttachment(file, file.copy(role = role, includeInReport = true)) },
                                            enabled = enabled,
                                            label = { Text(roAttachmentRoleLabel(role)) },
                                        )
                                    }
                                }
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically,
                                ) {
                                    FilterChip(
                                        selected = file.includeInReport,
                                        onClick = { replaceAttachment(file, file.copy(includeInReport = !file.includeInReport)) },
                                        enabled = enabled,
                                        label = { Text(if (file.includeInReport) "Šalji" else "Ne šalji") },
                                    )
                                    IconButton(
                                        onClick = { removeAttachment(file) },
                                        enabled = enabled,
                                        modifier = Modifier.size(32.dp),
                                    ) {
                                        Icon(Icons.Rounded.Delete, contentDescription = "Ukloni sliku", tint = Color(0xFFDC2626), modifier = Modifier.size(18.dp))
                                    }
                                }
                            }
                        }
                    }
                }
            }

            if (documents.isNotEmpty()) {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("PDF prilozi", fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                    documents.forEachIndexed { index, file ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(14.dp))
                                .background(Color.White.copy(alpha = 0.82f))
                                .padding(horizontal = 9.dp, vertical = 8.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Icon(Icons.Rounded.PictureAsPdf, contentDescription = null, tint = Color(0xFFDC2626), modifier = Modifier.size(20.dp))
                            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                                Text(file.fileName.ifBlank { "PDF prilog ${index + 1}" }, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                Text(formatFileSizeLabel(file.fileSize), style = MaterialTheme.typography.labelSmall, color = Color(0xFF64748B))
                            }
                            FilterChip(
                                selected = file.includeInReport,
                                onClick = { replaceAttachment(file, file.copy(role = "document", includeInReport = !file.includeInReport)) },
                                enabled = enabled,
                                label = { Text(if (file.includeInReport) "Šalji" else "Ne šalji") },
                            )
                            IconButton(
                                onClick = { removeAttachment(file) },
                                enabled = enabled,
                                modifier = Modifier.size(32.dp),
                            ) {
                                Icon(Icons.Rounded.Delete, contentDescription = "Ukloni PDF", tint = Color(0xFFDC2626), modifier = Modifier.size(18.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}

private fun WorkEquipmentImageRecognitionResult.hasRecognizedWorkEquipmentData(): Boolean =
    listOf(
        name,
        manufacturer,
        model,
        serialNumber,
        inventoryNumber,
        technicalData,
        purposeDescription,
        workspacePosition,
        deficiencies,
    ).any { it.isNotBlank() } ||
        mechanicalItems.isNotEmpty() ||
        electricalItems.isNotEmpty() ||
        hazardRegisterIris.isNotEmpty() ||
        harmfulnessRegisterIris.isNotEmpty() ||
        strainRegisterIris.isNotEmpty()

private fun WorkEquipmentImageRecognitionResult.recognizedWorkEquipmentItems(): List<WorkEquipmentImageRecognitionResult> =
    workEquipments.ifEmpty { listOf(this) }.filter { it.hasRecognizedWorkEquipmentData() }

private fun batchFilesForRecognitionItem(
    files: List<IsznrRoAttachmentFile>,
    item: WorkEquipmentImageRecognitionResult,
    index: Int,
    total: Int,
): List<IsznrRoAttachmentFile> {
    val byIndex = item.imageIndexes
        .mapNotNull { imageIndex -> files.getOrNull(imageIndex - 1) }
        .distinctBy { it.id.ifBlank { it.fileName } }
    if (byIndex.isNotEmpty()) return tagRoAttachmentRolesForEquipment(byIndex.take(5))

    val nameSet = item.sourceImageNames.map { it.trim().lowercase(Locale.getDefault()) }.filter { it.isNotBlank() }.toSet()
    val byName = if (nameSet.isEmpty()) {
        emptyList()
    } else {
        files.filter { file -> nameSet.contains(file.fileName.trim().lowercase(Locale.getDefault())) }
    }
    if (byName.isNotEmpty()) return tagRoAttachmentRolesForEquipment(byName.take(5))

    if (total <= 1) return tagRoAttachmentRolesForEquipment(files.take(5))
    val chunkSize = ((files.size + total - 1) / total).coerceAtLeast(1)
    return tagRoAttachmentRolesForEquipment(files.drop(index * chunkSize).take(chunkSize).take(5))
}

private fun WorkEquipmentImageRecognitionResult.toManualWorkEquipmentFromBatch(
    files: List<IsznrRoAttachmentFile>,
    index: Int,
    total: Int,
): IsznrManualWorkEquipment {
    val resolvedName = name.ifBlank {
        listOf(manufacturer, model)
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .joinToString(" ")
            .ifBlank { "Radna oprema ${index + 1}" }
    }
    return IsznrManualWorkEquipment(
        name = resolvedName,
        manufacturer = manufacturer,
        model = model,
        serialNumber = serialNumber,
        inventoryNumber = inventoryNumber,
        technicalData = technicalData,
        purposeDescription = purposeDescription,
        workspacePosition = workspacePosition,
        workingSubstancesAndRawMaterials = workingSubstancesAndRawMaterials,
        useAndMaintenance = useAndMaintenance,
        methodsProceduresAndNorms = methodsProceduresAndNorms,
        deficiencies = deficiencies,
        measuresToEliminateDeficiencies = measuresToEliminateDeficiencies,
        finalGrade = finalGrade.ifBlank { "1" },
        mechanicalItems = mechanicalItems,
        electricalItems = electricalItems,
        hazardRegisterIris = hazardRegisterIris,
        harmfulnessRegisterIris = harmfulnessRegisterIris,
        strainRegisterIris = strainRegisterIris,
        note = matchedSource.takeIf { it.isNotBlank() }?.let { "NexAI izvor: $it" }.orEmpty(),
        attachments = batchFilesForRecognitionItem(files, this, index, total),
    )
}

private enum class WorkEquipmentImportAction(val label: String) {
    Update("Ažuriraj"),
    Add("Novo"),
    Skip("Preskoči"),
}

private data class WorkEquipmentImportMatch(
    val recognizedIndex: Int,
    val recognized: WorkEquipmentImageRecognitionResult,
    val manual: IsznrManualWorkEquipment,
    val existingIndex: Int?,
    val score: Int,
    val reason: String,
    val defaultAction: WorkEquipmentImportAction,
)

private fun normalizeWorkEquipmentMatchText(value: String): String =
    Normalizer.normalize(value.trim().lowercase(Locale.getDefault()), Normalizer.Form.NFD)
        .replace("[\\u0300-\\u036f]".toRegex(), "")
        .replace("đ", "d")
        .replace("[^a-z0-9]+".toRegex(), " ")
        .trim()

private fun normalizeWorkEquipmentIdentifier(value: String): String =
    normalizeWorkEquipmentMatchText(value).replace(" ", "")

private fun workEquipmentMatchTokens(vararg values: String): Set<String> =
    values
        .flatMap { normalizeWorkEquipmentMatchText(it).split(" ") }
        .map { it.trim() }
        .filter { it.length >= 3 && it !in setOf("rad", "oprema", "uredaj", "stroj") }
        .toSet()

private fun scoreWorkEquipmentMatch(
    recognized: WorkEquipmentImageRecognitionResult,
    existing: IsznrManualWorkEquipment,
): Pair<Int, String> {
    val recognizedSerial = normalizeWorkEquipmentIdentifier(recognized.serialNumber)
    val existingSerial = normalizeWorkEquipmentIdentifier(existing.serialNumber)
    if (recognizedSerial.length >= 4 && recognizedSerial == existingSerial) {
        return 100 to "Serijski broj"
    }

    val recognizedInventory = normalizeWorkEquipmentIdentifier(recognized.inventoryNumber)
    val existingInventory = normalizeWorkEquipmentIdentifier(existing.inventoryNumber)
    if (recognizedInventory.length >= 3 && recognizedInventory == existingInventory) {
        return 96 to "Inventarski broj"
    }

    val recognizedManufacturer = normalizeWorkEquipmentMatchText(recognized.manufacturer)
    val existingManufacturer = normalizeWorkEquipmentMatchText(existing.manufacturer)
    val recognizedModel = normalizeWorkEquipmentIdentifier(recognized.model)
    val existingModel = normalizeWorkEquipmentIdentifier(existing.model)
    if (
        recognizedManufacturer.isNotBlank()
        && existingManufacturer.isNotBlank()
        && recognizedModel.length >= 3
        && recognizedModel == existingModel
        && (recognizedManufacturer == existingManufacturer
            || recognizedManufacturer.contains(existingManufacturer)
            || existingManufacturer.contains(recognizedManufacturer))
    ) {
        return 90 to "Proizvođač + model"
    }
    if (recognizedModel.length >= 4 && recognizedModel == existingModel) {
        return 82 to "Model / tip"
    }

    val recognizedTokens = workEquipmentMatchTokens(
        recognized.name,
        recognized.manufacturer,
        recognized.model,
        recognized.technicalData,
    )
    val existingTokens = workEquipmentMatchTokens(
        existing.name,
        existing.manufacturer,
        existing.model,
        existing.technicalData,
    )
    if (recognizedTokens.isEmpty() || existingTokens.isEmpty()) {
        return 0 to ""
    }
    val overlap = recognizedTokens.intersect(existingTokens).size
    if (overlap == 0) {
        return 0 to ""
    }
    val denominator = minOf(recognizedTokens.size, existingTokens.size).coerceAtLeast(1)
    val score = (55 + (35 * overlap / denominator)).coerceAtMost(80)
    return score to "Naziv / tip (${overlap} poklapanja)"
}

private fun buildWorkEquipmentImportMatches(
    existingEquipments: List<IsznrManualWorkEquipment>,
    recognizedItems: List<WorkEquipmentImageRecognitionResult>,
    files: List<IsznrRoAttachmentFile>,
): List<WorkEquipmentImportMatch> {
    val usedExisting = mutableSetOf<Int>()
    return recognizedItems.mapIndexed { recognizedIndex, item ->
        val manual = item.toManualWorkEquipmentFromBatch(files, recognizedIndex, recognizedItems.size)
        val best = existingEquipments
            .mapIndexed { existingIndex, existing ->
                val (score, reason) = scoreWorkEquipmentMatch(item, existing)
                Triple(existingIndex, score, reason)
            }
            .filter { it.second >= 55 }
            .maxByOrNull { it.second }
        val existingIndex = best?.first
        val defaultAction = when {
            existingIndex != null && existingIndex !in usedExisting && best.second >= 55 -> {
                usedExisting += existingIndex
                WorkEquipmentImportAction.Update
            }
            existingIndex != null && existingIndex in usedExisting -> WorkEquipmentImportAction.Skip
            else -> WorkEquipmentImportAction.Add
        }
        WorkEquipmentImportMatch(
            recognizedIndex = recognizedIndex,
            recognized = item,
            manual = manual,
            existingIndex = existingIndex,
            score = best?.second ?: 0,
            reason = best?.third.orEmpty(),
            defaultAction = defaultAction,
        )
    }
}

private fun mergeWorkEquipmentAttachmentFiles(
    first: List<IsznrRoAttachmentFile>,
    second: List<IsznrRoAttachmentFile>,
): List<IsznrRoAttachmentFile> =
    (first + second).distinctBy { file ->
        listOf(file.id, file.fileName, file.fileSize.toString())
            .joinToString("|")
            .lowercase(Locale.getDefault())
    }

private fun mergeRoAssessmentItems(
    existing: List<IsznrRoAssessmentItem>,
    recognized: List<IsznrRoAssessmentItem>,
): List<IsznrRoAssessmentItem> =
    (recognized + existing).distinctBy { item ->
        listOf(item.registerIri, item.label, item.customContent, item.measuredValue)
            .joinToString("|")
            .lowercase(Locale.getDefault())
    }

private fun mergeStringValues(
    existing: List<String>,
    recognized: List<String>,
): List<String> =
    (recognized + existing)
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }

private fun mergeRecognizedWorkEquipment(
    existing: IsznrManualWorkEquipment,
    recognized: IsznrManualWorkEquipment,
): IsznrManualWorkEquipment =
    existing.copy(
        name = recognized.name.takeIf { it.isNotBlank() && !it.startsWith("Radna oprema ") } ?: existing.name,
        manufacturer = recognized.manufacturer.ifBlank { existing.manufacturer },
        model = recognized.model.ifBlank { existing.model },
        serialNumber = recognized.serialNumber.ifBlank { existing.serialNumber },
        inventoryNumber = recognized.inventoryNumber.ifBlank { existing.inventoryNumber },
        technicalData = recognized.technicalData.ifBlank { existing.technicalData },
        purposeDescription = recognized.purposeDescription.ifBlank { existing.purposeDescription },
        workspacePosition = recognized.workspacePosition.ifBlank { existing.workspacePosition },
        workingSubstancesAndRawMaterials = recognized.workingSubstancesAndRawMaterials.ifBlank { existing.workingSubstancesAndRawMaterials },
        useAndMaintenance = recognized.useAndMaintenance.ifBlank { existing.useAndMaintenance },
        methodsProceduresAndNorms = recognized.methodsProceduresAndNorms.ifBlank { existing.methodsProceduresAndNorms },
        deficiencies = recognized.deficiencies.ifBlank { existing.deficiencies },
        measuresToEliminateDeficiencies = recognized.measuresToEliminateDeficiencies.ifBlank { existing.measuresToEliminateDeficiencies },
        finalGrade = recognized.finalGrade.ifBlank { existing.finalGrade }.ifBlank { "1" },
        mechanicalItems = mergeRoAssessmentItems(existing.mechanicalItems, recognized.mechanicalItems),
        electricalItems = mergeRoAssessmentItems(existing.electricalItems, recognized.electricalItems),
        hazardRegisterIris = mergeStringValues(existing.hazardRegisterIris, recognized.hazardRegisterIris),
        harmfulnessRegisterIris = mergeStringValues(existing.harmfulnessRegisterIris, recognized.harmfulnessRegisterIris),
        strainRegisterIris = mergeStringValues(existing.strainRegisterIris, recognized.strainRegisterIris),
        note = listOf(existing.note, recognized.note)
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinct()
            .joinToString("\n"),
        attachments = mergeWorkEquipmentAttachmentFiles(existing.attachments, recognized.attachments),
    )

private fun applyWorkEquipmentImportMatches(
    existingEquipments: List<IsznrManualWorkEquipment>,
    matches: List<WorkEquipmentImportMatch>,
    actions: Map<Int, WorkEquipmentImportAction>,
): Pair<List<IsznrManualWorkEquipment>, Int> {
    val next = existingEquipments.toMutableList()
    var focusIndex = next.lastIndex.coerceAtLeast(0)
    matches.forEach { match ->
        when (actions[match.recognizedIndex] ?: match.defaultAction) {
            WorkEquipmentImportAction.Update -> {
                val targetIndex = match.existingIndex
                if (targetIndex != null && targetIndex in next.indices) {
                    next[targetIndex] = mergeRecognizedWorkEquipment(next[targetIndex], match.manual)
                    focusIndex = targetIndex
                } else {
                    next += match.manual
                    focusIndex = next.lastIndex
                }
            }
            WorkEquipmentImportAction.Add -> {
                next += match.manual
                focusIndex = next.lastIndex
            }
            WorkEquipmentImportAction.Skip -> Unit
        }
    }
    return next to focusIndex
}

private const val WORK_EQUIPMENT_REPORT_TEMPLATE_PREFS = "safe_nexus_ro_report_templates"
private const val WORK_EQUIPMENT_REPORT_TEMPLATE_ITEMS_KEY = "items"

private data class WorkEquipmentReportTemplate(
    val id: String,
    val title: String,
    val equipment: IsznrManualWorkEquipment,
)

private fun IsznrManualWorkEquipment.asReportTemplatePart(): IsznrManualWorkEquipment =
    copy(
        serialNumber = "",
        inventoryNumber = "",
        attachments = emptyList(),
        hasParts = false,
        parts = emptyList(),
    )

private fun IsznrManualWorkEquipment.asReportTemplateEquipment(): IsznrManualWorkEquipment =
    copy(
        serialNumber = "",
        inventoryNumber = "",
        attachments = emptyList(),
        hasParts = hasParts || parts.isNotEmpty(),
        parts = parts.map { it.asReportTemplatePart() },
    )

private fun IsznrManualWorkEquipment.applyReportTemplate(template: IsznrManualWorkEquipment): IsznrManualWorkEquipment =
    copy(
        name = template.name.ifBlank { name },
        manufacturer = template.manufacturer.ifBlank { manufacturer },
        model = template.model.ifBlank { model },
        note = template.note,
        technicalData = template.technicalData,
        purposeDescription = template.purposeDescription,
        workspacePosition = template.workspacePosition,
        workingSubstancesAndRawMaterials = template.workingSubstancesAndRawMaterials,
        useAndMaintenance = template.useAndMaintenance,
        methodsProceduresAndNorms = template.methodsProceduresAndNorms,
        deficiencies = template.deficiencies,
        measuresToEliminateDeficiencies = template.measuresToEliminateDeficiencies,
        finalGrade = template.finalGrade.ifBlank { finalGrade },
        mechanicalItems = template.mechanicalItems,
        electricalItems = template.electricalItems,
        hazardRegisterIris = template.hazardRegisterIris,
        harmfulnessRegisterIris = template.harmfulnessRegisterIris,
        strainRegisterIris = template.strainRegisterIris,
        hasParts = hasParts || template.hasParts || template.parts.isNotEmpty(),
        parts = template.parts.takeIf { it.isNotEmpty() } ?: parts,
    )

private fun Context.loadWorkEquipmentReportTemplates(): List<WorkEquipmentReportTemplate> =
    runCatching {
        val raw = getSharedPreferences(WORK_EQUIPMENT_REPORT_TEMPLATE_PREFS, Context.MODE_PRIVATE)
            .getString(WORK_EQUIPMENT_REPORT_TEMPLATE_ITEMS_KEY, "[]")
            .orEmpty()
        val array = JSONArray(raw.ifBlank { "[]" })
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val id = item.optString("id").trim().ifBlank { "ro-template-$index" }
                val title = item.optString("title").trim().ifBlank { "RO predložak ${index + 1}" }
                val equipment = item.optJSONObject("equipment").toWorkEquipmentReportTemplateEquipment()
                add(WorkEquipmentReportTemplate(id = id, title = title, equipment = equipment.asReportTemplateEquipment()))
            }
        }
    }.getOrDefault(emptyList())

private fun Context.saveWorkEquipmentReportTemplates(templates: List<WorkEquipmentReportTemplate>) {
    val array = JSONArray()
    templates.forEach { template ->
        array.put(
            JSONObject()
                .put("id", template.id)
                .put("title", template.title)
                .put("equipment", template.equipment.asReportTemplateEquipment().toWorkEquipmentReportTemplateJson()),
        )
    }
    getSharedPreferences(WORK_EQUIPMENT_REPORT_TEMPLATE_PREFS, Context.MODE_PRIVATE)
        .edit()
        .putString(WORK_EQUIPMENT_REPORT_TEMPLATE_ITEMS_KEY, array.toString())
        .apply()
}

private fun IsznrManualWorkEquipment.toWorkEquipmentReportTemplateJson(): JSONObject =
    JSONObject()
        .put("name", name)
        .put("manufacturer", manufacturer)
        .put("model", model)
        .put("note", note)
        .put("technicalData", technicalData)
        .put("purposeDescription", purposeDescription)
        .put("workspacePosition", workspacePosition)
        .put("workingSubstancesAndRawMaterials", workingSubstancesAndRawMaterials)
        .put("useAndMaintenance", useAndMaintenance)
        .put("methodsProceduresAndNorms", methodsProceduresAndNorms)
        .put("deficiencies", deficiencies)
        .put("measuresToEliminateDeficiencies", measuresToEliminateDeficiencies)
        .put("finalGrade", finalGrade)
        .put("mechanicalItems", mechanicalItems.toRoAssessmentJsonArray())
        .put("electricalItems", electricalItems.toRoAssessmentJsonArray())
        .put("hazardRegisterIris", hazardRegisterIris.toJsonArray())
        .put("harmfulnessRegisterIris", harmfulnessRegisterIris.toJsonArray())
        .put("strainRegisterIris", strainRegisterIris.toJsonArray())
        .put("hasParts", hasParts || parts.isNotEmpty())
        .put("parts", JSONArray().apply {
            parts.map { it.asReportTemplatePart() }.forEach { part ->
                put(part.toWorkEquipmentReportTemplateJson())
            }
        })

private fun JSONObject?.toWorkEquipmentReportTemplateEquipment(): IsznrManualWorkEquipment {
    val item = this ?: JSONObject()
    return IsznrManualWorkEquipment(
        name = item.optString("name").trim(),
        manufacturer = item.optString("manufacturer").trim(),
        model = item.optString("model").trim(),
        note = item.optString("note").trim(),
        technicalData = item.optString("technicalData").trim(),
        purposeDescription = item.optString("purposeDescription").trim(),
        workspacePosition = item.optString("workspacePosition").trim(),
        workingSubstancesAndRawMaterials = item.optString("workingSubstancesAndRawMaterials").trim(),
        useAndMaintenance = item.optString("useAndMaintenance").trim(),
        methodsProceduresAndNorms = item.optString("methodsProceduresAndNorms").trim(),
        deficiencies = item.optString("deficiencies").trim(),
        measuresToEliminateDeficiencies = item.optString("measuresToEliminateDeficiencies").trim(),
        finalGrade = item.optString("finalGrade").trim().ifBlank { "1" },
        mechanicalItems = item.optJSONArray("mechanicalItems").toRoAssessmentItemList(),
        electricalItems = item.optJSONArray("electricalItems").toRoAssessmentItemList(),
        hazardRegisterIris = item.optJSONArray("hazardRegisterIris").toPlainStringList(),
        harmfulnessRegisterIris = item.optJSONArray("harmfulnessRegisterIris").toPlainStringList(),
        strainRegisterIris = item.optJSONArray("strainRegisterIris").toPlainStringList(),
        hasParts = item.optBoolean("hasParts", false),
        parts = item.optJSONArray("parts").toWorkEquipmentReportTemplatePartList(),
    )
}

private fun JSONArray?.toWorkEquipmentReportTemplatePartList(): List<IsznrManualWorkEquipment> {
    val array = this ?: return emptyList()
    return buildList {
        for (index in 0 until array.length()) {
            val item = array.optJSONObject(index) ?: continue
            add(item.toWorkEquipmentReportTemplateEquipment().asReportTemplatePart())
        }
    }
}

private fun List<IsznrRoAssessmentItem>.toRoAssessmentJsonArray(): JSONArray =
    JSONArray().also { array ->
        forEach { item ->
            array.put(
                JSONObject()
                    .put("registerIri", item.registerIri)
                    .put("label", item.label)
                    .put("customContent", item.customContent)
                    .put("measuredValue", item.measuredValue)
                    .put("meetsConditions", item.meetsConditions),
            )
        }
    }

private fun JSONArray?.toRoAssessmentItemList(): List<IsznrRoAssessmentItem> {
    val array = this ?: return emptyList()
    return buildList {
        for (index in 0 until array.length()) {
            val item = array.optJSONObject(index) ?: continue
            add(
                IsznrRoAssessmentItem(
                    registerIri = item.optString("registerIri").trim(),
                    label = item.optString("label").trim(),
                    customContent = item.optString("customContent").trim(),
                    measuredValue = item.optString("measuredValue").trim(),
                    meetsConditions = item.optBoolean("meetsConditions", true),
                ),
            )
        }
    }
}

private fun List<String>.toJsonArray(): JSONArray =
    JSONArray().also { array ->
        map { it.trim() }
            .filter { it.isNotBlank() }
            .distinct()
            .forEach { array.put(it) }
    }

private fun JSONArray?.toPlainStringList(): List<String> {
    val array = this ?: return emptyList()
    return buildList {
        for (index in 0 until array.length()) {
            val value = array.optString(index).trim()
            if (value.isNotBlank()) add(value)
        }
    }.distinct()
}

