private fun normalizedRoVerificationQuestions(questions: List<String>, limit: Int = 8): List<String> =
    questions
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }
        .take(limit)

@Composable
private fun WorkEquipmentVerificationQuestionsPanel(
    title: String,
    subtitle: String,
    questions: List<String>,
    verificationAnswers: Map<String, String>,
    onAnswer: (String, String) -> Unit,
    groupIndex: Int = 0,
    groupCount: Int = 1,
    onPreviousGroup: (() -> Unit)? = null,
    onNextGroup: (() -> Unit)? = null,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = Color(0xFFEFF6FF),
        border = BorderStroke(1.dp, Color(0xFF93C5FD).copy(alpha = 0.65f)),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(shape = CircleShape, color = Color.White, modifier = Modifier.size(34.dp)) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = Color(0xFF2563EB), modifier = Modifier.size(20.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    Text(title, color = Color(0xFF0F172A), fontWeight = FontWeight.Black)
                    Text(subtitle, style = MaterialTheme.typography.labelSmall, color = Color(0xFF475569))
                }
                if (groupCount > 1 && onPreviousGroup != null && onNextGroup != null) {
                    Row(horizontalArrangement = Arrangement.spacedBy(2.dp), verticalAlignment = Alignment.CenterVertically) {
                        IconButton(onClick = onPreviousGroup, modifier = Modifier.size(32.dp)) {
                            Icon(Icons.Rounded.ArrowBack, contentDescription = "Prethodna oprema", tint = Color(0xFF2563EB), modifier = Modifier.size(18.dp))
                        }
                        Text(
                            "${groupIndex + 1}/$groupCount",
                            style = MaterialTheme.typography.labelSmall,
                            color = Color(0xFF1D4ED8),
                            fontWeight = FontWeight.Black,
                        )
                        IconButton(onClick = onNextGroup, modifier = Modifier.size(32.dp)) {
                            Icon(Icons.Rounded.ArrowForward, contentDescription = "Sljedeća oprema", tint = Color(0xFF2563EB), modifier = Modifier.size(18.dp))
                        }
                    }
                }
            }
            questions.forEach { question ->
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    color = Color.White.copy(alpha = 0.86f),
                    border = BorderStroke(1.dp, Color(0xFFBFDBFE)),
                ) {
                    Column(
                        modifier = Modifier.padding(10.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        Text(
                            question,
                            style = MaterialTheme.typography.bodySmall,
                            color = Color(0xFF0F172A),
                            fontWeight = FontWeight.Bold,
                        )
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            listOf("Da", "Ne").forEach { answer ->
                                FilterChip(
                                    selected = verificationAnswers[question].orEmpty().ifBlank { "Da" } == answer,
                                    onClick = { onAnswer(question, answer) },
                                    label = { Text(answer) },
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun WorkEquipmentBatchNexAiUploadCard(
    enabled: Boolean,
    manualEquipments: List<IsznrManualWorkEquipment>,
    onRecognizeBatchImages: (
        List<IsznrManualWorkEquipment>,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onApply: (List<IsznrManualWorkEquipment>, Int) -> Unit,
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var files by remember { mutableStateOf(emptyList<IsznrRoAttachmentFile>()) }
    var loadingFiles by remember { mutableStateOf(false) }
    var recognizing by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf("") }
    var preview by remember(files) { mutableStateOf<WorkEquipmentImageRecognitionResult?>(null) }
    val imagePicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            loadingFiles = true
            message = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = files.size,
                    maxFiles = ISZNR_RO_BATCH_ATTACHMENT_MAX_INLINE_FILES,
                )
            }
                .onSuccess { addedFiles ->
                    files = files + addedFiles
                    message = if (addedFiles.isEmpty()) {
                        "Nije dodana nijedna slika."
                    } else {
                        "${addedFiles.size} slika dodano za NexAI raspored po kolonama."
                    }
                }
                .onFailure { error ->
                    message = error.message ?: "Ne mogu učitati slike."
                }
            loadingFiles = false
        }
    }

    fun applyPreview(
        result: WorkEquipmentImageRecognitionResult,
        actions: Map<Int, WorkEquipmentImportAction>,
        matches: List<WorkEquipmentImportMatch>,
        replaceAll: Boolean = false,
        verificationAnswers: Map<String, String> = emptyMap(),
    ) {
        val items = result.recognizedWorkEquipmentItems()
        if (items.isEmpty()) {
            message = "NexAI nije vratio sigurne RO kolone."
            return
        }
        val (nextEquipments, focusIndex) = if (replaceAll) {
            items.mapIndexed { index, item -> item.toManualWorkEquipmentFromBatch(files, index, items.size) } to 0
        } else {
            applyWorkEquipmentImportMatches(manualEquipments, matches, actions)
        }
        onApply(nextEquipments, focusIndex)
        preview = null
        files = emptyList()
        message = if (replaceAll) {
            "RO kolone su zamijenjene s ${items.size} prepoznatih strojeva."
        } else {
            val updated = matches.count { actions[it.recognizedIndex] == WorkEquipmentImportAction.Update }
            val added = matches.count { actions[it.recognizedIndex] == WorkEquipmentImportAction.Add }
            val skipped = matches.count { actions[it.recognizedIndex] == WorkEquipmentImportAction.Skip }
            listOf(
                updated.takeIf { it > 0 }?.let { "$it ažurirano" },
                added.takeIf { it > 0 }?.let { "$it novo" },
                skipped.takeIf { it > 0 }?.let { "$it preskočeno" },
                verificationAnswers.count { it.value.isNotBlank() }.takeIf { it > 0 }?.let { "$it potvrda" },
            ).filterNotNull().joinToString(" · ").ifBlank { "RO popis je provjeren bez promjena." }
        }
    }

    preview?.let { result ->
        val items = result.recognizedWorkEquipmentItems()
        val matches = remember(result, manualEquipments, files) {
            buildWorkEquipmentImportMatches(manualEquipments, items, files)
        }
        var actionOverrides by remember(result, manualEquipments, files) {
            mutableStateOf(matches.associate { it.recognizedIndex to it.defaultAction })
        }
        val questionGroups = remember(result, items) {
            val itemGroups = items.mapIndexedNotNull { index, item ->
                val questions = normalizedRoVerificationQuestions(item.verificationQuestions, limit = 8)
                if (questions.isEmpty()) {
                    null
                } else {
                    val name = item.name.ifBlank { item.model.ifBlank { "Oprema ${index + 1}" } }
                    "${index + 1}. $name" to questions
                }
            }
            val groupedQuestions = itemGroups
                .flatMap { it.second }
                .map { it.lowercase(Locale.getDefault()) }
                .toSet()
            val globalQuestions = normalizedRoVerificationQuestions(result.verificationQuestions, limit = 12)
                .filter { it.lowercase(Locale.getDefault()) !in groupedQuestions }
            itemGroups + listOfNotNull(globalQuestions.takeIf { it.isNotEmpty() }?.let { "Opće potvrde" to it })
        }
        val previewQuestions = remember(questionGroups) {
            questionGroups.flatMap { it.second }.distinctBy { it.lowercase(Locale.getDefault()) }
        }
        var questionGroupIndex by remember(result) { mutableStateOf(0) }
        val safeQuestionGroupIndex = questionGroupIndex.coerceIn(0, questionGroups.lastIndex.coerceAtLeast(0))
        val activeQuestionGroup = questionGroups.getOrNull(safeQuestionGroupIndex)
        var verificationAnswers by remember(result) {
            mutableStateOf(previewQuestions.associateWith { "Da" })
        }
        val questionsAnswered = previewQuestions.all { verificationAnswers[it].orEmpty().isNotBlank() }
        AlertDialog(
            onDismissRequest = { preview = null },
            title = { Text("Provjeri RO popis") },
            text = {
                Column(
                    modifier = Modifier
                        .heightIn(max = 440.dp)
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    Text(
                        result.message.ifBlank { "NexAI je pripremio ${items.size} RO stavki. Provjeri da nema duplikata prije upisa." },
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
                    )
                    if (activeQuestionGroup != null) {
                        WorkEquipmentVerificationQuestionsPanel(
                            title = "Potvrdi prije upisa",
                            subtitle = "${activeQuestionGroup.first} · Da je odabrano po defaultu",
                            questions = activeQuestionGroup.second,
                            verificationAnswers = verificationAnswers,
                            onAnswer = { question, answer -> verificationAnswers = verificationAnswers + (question to answer) },
                            groupIndex = safeQuestionGroupIndex,
                            groupCount = questionGroups.size,
                            onPreviousGroup = if (questionGroups.size > 1) {
                                { questionGroupIndex = if (safeQuestionGroupIndex == 0) questionGroups.lastIndex else safeQuestionGroupIndex - 1 }
                            } else {
                                null
                            },
                            onNextGroup = if (questionGroups.size > 1) {
                                { questionGroupIndex = if (safeQuestionGroupIndex >= questionGroups.lastIndex) 0 else safeQuestionGroupIndex + 1 }
                            } else {
                                null
                            },
                        )
                    }
                    if (matches.isNotEmpty()) {
                        val updateCount = matches.count { (actionOverrides[it.recognizedIndex] ?: it.defaultAction) == WorkEquipmentImportAction.Update }
                        val addCount = matches.count { (actionOverrides[it.recognizedIndex] ?: it.defaultAction) == WorkEquipmentImportAction.Add }
                        val skipCount = matches.count { (actionOverrides[it.recognizedIndex] ?: it.defaultAction) == WorkEquipmentImportAction.Skip }
                        Text(
                            "Plan: $updateCount ažuriraj · $addCount novo · $skipCount preskoči",
                            style = MaterialTheme.typography.labelMedium,
                            color = Color(0xFF1D4ED8),
                            fontWeight = FontWeight.Black,
                        )
                    }
                    if (items.isEmpty()) {
                        Text(
                            "Nema sigurnih strojeva za upis. Dodaj jasnije slike cijelog stroja i pločice.",
                            color = Color(0xFFB45309),
                            fontWeight = FontWeight.Bold,
                        )
                    }
                    matches.forEach { match ->
                        val index = match.recognizedIndex
                        val item = match.recognized
                        val selectedAction = actionOverrides[index] ?: match.defaultAction
                        val existing = match.existingIndex?.let { manualEquipments.getOrNull(it) }
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            color = when (selectedAction) {
                                WorkEquipmentImportAction.Update -> Color(0xFFEFF6FF)
                                WorkEquipmentImportAction.Add -> Color(0xFFF0FDF4)
                                WorkEquipmentImportAction.Skip -> MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.38f)
                            },
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.16f)),
                        ) {
                            Column(
                                modifier = Modifier.padding(10.dp),
                                verticalArrangement = Arrangement.spacedBy(5.dp),
                            ) {
                                Text(
                                    "${index + 1}. ${item.name.ifBlank { "Radna oprema" }}",
                                    fontWeight = FontWeight.Black,
                                )
                                if (existing != null) {
                                    Text(
                                        "Nađeno u postojećem popisu: ${existing.name.ifBlank { "Radna oprema" }}${match.reason.takeIf { it.isNotBlank() }?.let { " · $it ${match.score}%" }.orEmpty()}",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = Color(0xFF1D4ED8),
                                        fontWeight = FontWeight.Bold,
                                    )
                                } else {
                                    Text(
                                        "Nema poklapanja u trenutnom popisu - ide kao nova oprema.",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = Color(0xFF15803D),
                                        fontWeight = FontWeight.Bold,
                                    )
                                }
                                listOf(
                                    "Proizvođač" to item.manufacturer,
                                    "Model / tip" to item.model,
                                    "Serijski broj" to item.serialNumber,
                                    "Inventarski broj" to item.inventoryNumber,
                                    "Tehnički podaci" to item.technicalData,
                                    "Strojarski dio" to item.mechanicalItems.size.takeIf { it > 0 }?.let { "$it stavki" }.orEmpty(),
                                    "Elektro dio" to item.electricalItems.size.takeIf { it > 0 }?.let { "$it stavki" }.orEmpty(),
                                    "Opasnosti/štetnosti/napori" to listOf(
                                        item.hazardRegisterIris.size,
                                        item.harmfulnessRegisterIris.size,
                                        item.strainRegisterIris.size,
                                    ).sum().takeIf { it > 0 }?.let { "$it oznaka" }.orEmpty(),
                                    "Izvor / baza" to item.matchedSource,
                                ).filter { it.second.isNotBlank() }.forEach { (label, value) ->
                                    Text(
                                        "$label: $value",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
                                    )
                                }
                                val assignedFiles = batchFilesForRecognitionItem(files, item, index, items.size)
                                if (assignedFiles.isNotEmpty()) {
                                    Text(
                                        "Slike: ${assignedFiles.joinToString(", ") { it.fileName.ifBlank { "slika" } }}",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.primary,
                                        maxLines = 2,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                }
                                FlowRow(
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    verticalArrangement = Arrangement.spacedBy(6.dp),
                                ) {
                                    WorkEquipmentImportAction.values().forEach { action ->
                                        FilterChip(
                                            selected = selectedAction == action,
                                            onClick = {
                                                actionOverrides = actionOverrides + (index to action)
                                            },
                                            label = { Text(action.label) },
                                            enabled = action != WorkEquipmentImportAction.Update || existing != null,
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { applyPreview(result, actionOverrides, matches, verificationAnswers = verificationAnswers) },
                    enabled = items.isNotEmpty() && questionsAnswered,
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Primijeni popis")
                }
            },
            dismissButton = {
                Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                    TextButton(onClick = { preview = null }) {
                        Text("Zatvori")
                    }
                    TextButton(
                        onClick = { applyPreview(result, actionOverrides, matches, replaceAll = true, verificationAnswers = verificationAnswers) },
                        enabled = items.isNotEmpty() && questionsAnswered,
                    ) {
                        Text(if (manualEquipments.isEmpty()) "Postavi" else "Zamijeni sve")
                    }
                }
            },
        )
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(20.dp),
        color = Color(0xFFEFF6FF),
        border = BorderStroke(1.dp, Color(0xFFBFDBFE)),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Surface(shape = CircleShape, color = Color(0xFFDBEAFE), modifier = Modifier.size(42.dp)) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(Icons.Rounded.AutoAwesome, contentDescription = null, tint = Color(0xFF2563EB), modifier = Modifier.size(22.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text("NexAI upload opreme", fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                    Text(
                        "Dodaj više slika iz obilaska. NexAI prepoznaje strojeve, pločice i raspoređuje ih u RO kolone.",
                        style = MaterialTheme.typography.bodySmall,
                        color = Color(0xFF475569),
                    )
                }
            }
            Text(
                "Redoslijed za batch: stroj izdaleka, pločica, detalji; zatim sljedeći stroj.",
                style = MaterialTheme.typography.labelSmall,
                color = Color(0xFF1D4ED8),
                fontWeight = FontWeight.Bold,
            )
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                OutlinedButton(
                    onClick = { imagePicker.launch("image/*") },
                    enabled = enabled && !loadingFiles && files.size < ISZNR_RO_BATCH_ATTACHMENT_MAX_INLINE_FILES,
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 10.dp),
                ) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (loadingFiles) "Učitavam..." else "Dodaj slike")
                }
                Button(
                    onClick = {
                        recognizing = true
                        message = "NexAI prepoznaje i priprema RO kolone..."
                        onRecognizeBatchImages(
                            manualEquipments,
                            files,
                            { result ->
                                recognizing = false
                                preview = result
                                val count = result.recognizedWorkEquipmentItems().size
                                message = if (count > 0) "Pronađeno $count RO kolona. Provjeri prije upisa." else result.message
                            },
                            { errorMessage ->
                                recognizing = false
                                message = errorMessage
                            },
                        )
                    },
                    enabled = enabled && !recognizing && files.any { it.contentDataUrl.isNotBlank() },
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 10.dp),
                ) {
                    if (recognizing) {
                        CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
                    } else {
                        Icon(Icons.Rounded.AutoAwesome, contentDescription = null, modifier = Modifier.size(16.dp))
                    }
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Prepoznaj")
                }
            }
            if (recognizing) {
                WorkEquipmentAiStatusPanel(
                    title = "NexAI analizira obilazak",
                    subtitle = "Prepoznajem strojeve i razdvajam slike po RO kolonama.",
                    details = "Gledam redoslijed slika, pločice, proizvođača, tip/model i moguće podatke iz baze.",
                )
            }
            Text(
                "${files.size}/$ISZNR_RO_BATCH_ATTACHMENT_MAX_INLINE_FILES slika · max 8 MB po slici · ciljaj oko 5 slika po opremi",
                style = MaterialTheme.typography.labelSmall,
                color = Color(0xFF475569),
            )
            if (message.isNotBlank()) {
                val warningMessage = listOf("greška", "nema", "nije", "ne mogu", "ne može").any { marker ->
                    message.contains(marker, ignoreCase = true)
                }
                Text(
                    message,
                    style = MaterialTheme.typography.labelSmall,
                    color = if (warningMessage) Color(0xFFB45309) else Color(0xFF0F766E),
                    fontWeight = FontWeight.Bold,
                )
            }
            if (files.isNotEmpty()) {
                LazyRow(
                    modifier = Modifier
                        .fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                ) {
                    items(files.size) { index ->
                        val file = files[index]
                        val bitmap = remember(file.contentDataUrl) { decodeRoAttachmentBitmap(file) }
                        Surface(
                            modifier = Modifier.width(154.dp),
                            shape = RoundedCornerShape(18.dp),
                            color = Color.White.copy(alpha = 0.82f),
                            border = BorderStroke(1.dp, Color(0xFFBFDBFE)),
                        ) {
                            Column(
                                modifier = Modifier.padding(8.dp),
                                verticalArrangement = Arrangement.spacedBy(7.dp),
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(96.dp)
                                        .clip(RoundedCornerShape(14.dp))
                                        .background(Color(0xFFE2E8F0)),
                                    contentAlignment = Alignment.Center,
                                ) {
                                    if (bitmap != null) {
                                        ComposeImage(
                                            bitmap = bitmap.asImageBitmap(),
                                            contentDescription = file.fileName,
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = ContentScale.Crop,
                                        )
                                    } else {
                                        Icon(Icons.Rounded.Image, contentDescription = null, tint = Color(0xFF64748B), modifier = Modifier.size(28.dp))
                                    }
                                    Surface(
                                        modifier = Modifier
                                            .align(Alignment.TopStart)
                                            .padding(6.dp),
                                        shape = RoundedCornerShape(999.dp),
                                        color = Color(0xFFDBEAFE),
                                    ) {
                                        Text(
                                            "${index + 1}",
                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                                            style = MaterialTheme.typography.labelSmall,
                                            fontWeight = FontWeight.Black,
                                            color = Color(0xFF1D4ED8),
                                        )
                                    }
                                }
                                Text(
                                    file.fileName.ifBlank { "Slika ${index + 1}" },
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                    fontWeight = FontWeight.Bold,
                                )
                                OutlinedButton(
                                    onClick = { files = files.filterIndexed { itemIndex, _ -> itemIndex != index } },
                                    enabled = enabled,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 6.dp),
                                ) {
                                    Icon(Icons.Rounded.Delete, contentDescription = null, tint = Color(0xFFDC2626), modifier = Modifier.size(15.dp))
                                    Spacer(modifier = Modifier.width(5.dp))
                                    Text("Ukloni")
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentationWorkEquipmentBasicsCard(
    companyName: String,
    locationName: String,
    statusMessage: String,
    postDraftStatus: Map<String, String>,
) {
    val postDraftReady = postDraftStatus["postDraftReady"].equals("true", ignoreCase = true)
    val postDraftReadyCount = postDraftStatus["postDraftReadyCount"].orEmpty()
    val postDraftMissingCount = postDraftStatus["postDraftMissingCount"].orEmpty()
    val postDraftMissingLabels = postDraftStatus["postDraftMissingLabels"].orEmpty()
        .split(",")
        .map { it.trim() }
        .filter { it.isNotBlank() }
    val expertLabels = postDraftStatus["postDraftExpertLabels"].orEmpty()
    val signedByLabels = postDraftStatus["postDraftSignedByLabels"].orEmpty()
    val expertCount = postDraftStatus["postDraftExpertCount"].orEmpty().ifBlank { "0" }
    val signedByCount = postDraftStatus["postDraftSignedByCount"].orEmpty().ifBlank { "0" }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.52f),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Icon(Icons.Rounded.Work, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text("RO - osnovno", fontWeight = FontWeight.Black)
                    Text(
                        "Ovi podaci se koriste za zapisnik radne opreme i IS ZNR slanje.",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
                if (postDraftReadyCount.isNotBlank() || postDraftMissingCount.isNotBlank()) {
                    AssistChip(
                        onClick = {},
                        label = {
                            Text(
                                if (postDraftReady) {
                                    "$postDraftReadyCount spremno"
                                } else {
                                    "Fali $postDraftMissingCount"
                                },
                            )
                        },
                    )
                }
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                DocumentationWorkEquipmentInfoPill("Poslodavac", companyName.ifBlank { "Nije upisano" })
                DocumentationWorkEquipmentInfoPill("Lokacija RN-a", locationName.ifBlank { "Nije upisana" })
            }
            if (statusMessage.isNotBlank()) {
                Text(
                    statusMessage,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            }
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                color = if (postDraftReady) Color(0xFFECFDF5) else Color(0xFFFFF7ED),
                tonalElevation = 0.dp,
            ) {
                Column(
                    modifier = Modifier.padding(10.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp),
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            if (postDraftReady) Icons.Rounded.CheckCircle else Icons.Rounded.Info,
                            contentDescription = null,
                            tint = if (postDraftReady) Color(0xFF059669) else Color(0xFFB45309),
                            modifier = Modifier.size(20.dp),
                        )
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                if (postDraftReady) "IS ZNR POST priprema spremna" else "IS ZNR POST priprema",
                                fontWeight = FontWeight.Bold,
                            )
                            Text(
                                "Slanje se pokreće u Sažetku.",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                            )
                        }
                    }
                    if (postDraftMissingLabels.isNotEmpty()) {
                        Text(
                            "Fali: ${postDraftMissingLabels.take(4).joinToString(", ")}",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                        )
                    }
                }
            }
            DocumentationWorkEquipmentPeopleRow(
                label = "Ispitivači / stručnjaci ZNR",
                count = expertCount,
                names = expertLabels,
                required = "min. 1",
            )
            DocumentationWorkEquipmentPeopleRow(
                label = "Nositelji / potpisnici",
                count = signedByCount,
                names = signedByLabels,
                required = "min. 2",
            )
        }
    }
}

