@Composable
private fun ManualWorkEquipmentInlineEditor(
    equipment: IsznrManualWorkEquipment,
    columnIndex: Int,
    columnCount: Int,
    enabled: Boolean,
    recordTitle: String = "Radna oprema",
    recordLabel: String = "RO",
    isStrojeviTemplate: Boolean = false,
    showRecognition: Boolean = true,
    showRiskRegisters: Boolean = true,
    mechanicalOptions: List<WorkOrderDocumentationOption>,
    electricalOptions: List<WorkOrderDocumentationOption>,
    hazardOptions: List<WorkOrderDocumentationOption>,
    harmfulnessOptions: List<WorkOrderDocumentationOption>,
    strainOptions: List<WorkOrderDocumentationOption>,
    onPrevious: () -> Unit,
    onNext: () -> Unit,
    onAddColumn: () -> Unit,
    onRemove: () -> Unit,
    onRecognizeImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onEquipmentChange: (IsznrManualWorkEquipment) -> Unit,
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var attachmentMessage by remember(equipment.attachments) { mutableStateOf("") }
    var attachmentsLoading by remember(equipment.attachments) { mutableStateOf(false) }
    var recognitionLoading by remember(equipment.attachments) { mutableStateOf(false) }
    var recognitionMessage by remember(equipment.attachments) { mutableStateOf("") }
    var recognitionPreview by remember(equipment.attachments) { mutableStateOf<WorkEquipmentImageRecognitionResult?>(null) }
    var documentsLoading by remember(equipment.attachments) { mutableStateOf(false) }
    var reportTemplates by remember { mutableStateOf(context.loadWorkEquipmentReportTemplates()) }
    var templateMenuOpen by remember { mutableStateOf(false) }
    var saveTemplateDialogOpen by remember { mutableStateOf(false) }
    var templateMessage by remember { mutableStateOf("") }
    var templateTitle by remember(equipment.name, equipment.manufacturer, equipment.model) {
        mutableStateOf(
            listOf(equipment.name, equipment.manufacturer, equipment.model)
                .map { it.trim() }
                .filter { it.isNotBlank() }
                .joinToString(" - ")
                .ifBlank { "$recordLabel predložak" },
        )
    }
    val imagePicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            attachmentsLoading = true
            attachmentMessage = ""
            recognitionMessage = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = equipment.attachments.size,
                )
            }
                .onSuccess { files ->
                    val distributedEquipment = distributeRoImagesAcrossEquipmentParts(equipment, files)
                    onEquipmentChange(distributedEquipment)
                    attachmentMessage = if (files.isEmpty()) {
                        "Nije dodana nijedna slika."
                    } else if ((equipment.hasParts || equipment.parts.isNotEmpty()) && files.count { it.isRoImageAttachment() } > 1) {
                        "${files.size} slika raspoređeno: prva kao glavna, ostale po dijelovima u parovima."
                    } else {
                        "${files.size} slika dodano za $recordLabel privitke."
                    }
                }
                .onFailure { error ->
                    attachmentMessage = error.message ?: "Ne mogu učitati slike."
                }
            attachmentsLoading = false
        }
    }
    val pdfPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            documentsLoading = true
            attachmentMessage = ""
            recognitionMessage = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = equipment.attachments.size,
                    mode = WorkOrderDocumentInputMode.Pdf,
                    role = "document",
                    allowPdf = true,
                )
            }
                .onSuccess { files ->
                    onEquipmentChange(equipment.copy(attachments = equipment.attachments + files.map { it.copy(role = "document") }))
                    attachmentMessage = if (files.isEmpty()) {
                        "Nije dodan nijedan PDF prilog."
                    } else {
                        "${files.size} PDF prilog(a) dodano za $recordLabel zapisnik."
                    }
                }
                .onFailure { error ->
                    attachmentMessage = error.message ?: "Ne mogu učitati PDF priloge."
                }
            documentsLoading = false
        }
    }

    if (saveTemplateDialogOpen) {
        AlertDialog(
            onDismissRequest = { saveTemplateDialogOpen = false },
            title = { Text("Spremi $recordLabel predložak") },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Text(
                        "Predložak sprema sve osim serijskog broja, inventarnog broja i slika.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                    )
                    OutlinedTextField(
                        value = templateTitle,
                        onValueChange = { templateTitle = it },
                        modifier = Modifier.fillMaxWidth(),
                        label = { Text("Naziv predloška") },
                        singleLine = true,
                        shape = RoundedCornerShape(14.dp),
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val title = templateTitle.trim().ifBlank { "$recordLabel predložak" }
                        val nextTemplates = reportTemplates
                            .filterNot { it.title.equals(title, ignoreCase = true) }
                            .plus(
                                WorkEquipmentReportTemplate(
                                    id = "ro-template-${System.currentTimeMillis()}",
                                    title = title,
                                    equipment = equipment.asReportTemplateEquipment(),
                                ),
                            )
                        context.saveWorkEquipmentReportTemplates(nextTemplates)
                        reportTemplates = nextTemplates
                        templateMessage = "Predložak \"$title\" je spremljen bez serijskog, inventarnog broja i slika."
                        saveTemplateDialogOpen = false
                    },
                    enabled = templateTitle.trim().isNotBlank(),
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Spremi")
                }
            },
            dismissButton = {
                TextButton(onClick = { saveTemplateDialogOpen = false }) {
                    Text("Odustani")
                }
            },
        )
    }

    fun applyRecognition(result: WorkEquipmentImageRecognitionResult, verificationAnswers: Map<String, String> = emptyMap()) {
        onEquipmentChange(
            equipment.copy(
                name = result.name.ifBlank { equipment.name },
                manufacturer = result.manufacturer.ifBlank { equipment.manufacturer },
                model = result.model.ifBlank { equipment.model },
                serialNumber = result.serialNumber.ifBlank { equipment.serialNumber },
                inventoryNumber = result.inventoryNumber.ifBlank { equipment.inventoryNumber },
                technicalData = result.technicalData.ifBlank { equipment.technicalData },
            ),
        )
        recognitionPreview = null
        recognitionMessage = listOf(
            result.message.ifBlank { "Prepoznati podaci su primijenjeni." },
            result.matchedSource.takeIf { it.isNotBlank() }?.let { "Baza: $it" }.orEmpty(),
            verificationAnswers.count { it.value.isNotBlank() }.takeIf { it > 0 }?.let { "$it potvrda uneseno" }.orEmpty(),
        ).filter { it.isNotBlank() }.joinToString(" ")
    }

    recognitionPreview?.let { result ->
        val previewQuestions = remember(result) {
            normalizedRoVerificationQuestions(result.verificationQuestions, limit = 8)
        }
        var verificationAnswers by remember(result) {
            mutableStateOf(previewQuestions.associateWith { "Da" })
        }
        val questionsAnswered = previewQuestions.all { verificationAnswers[it].orEmpty().isNotBlank() }
        AlertDialog(
            onDismissRequest = { recognitionPreview = null },
            title = { Text("Provjeri prepoznavanje") },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        result.message.ifBlank { "NexAI je pročitao slike stroja i pločice." },
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
                    )
                    if (previewQuestions.isNotEmpty()) {
                        WorkEquipmentVerificationQuestionsPanel(
                            title = "Potvrdi prije upisa",
                            subtitle = "Da je odabrano po defaultu",
                            questions = previewQuestions,
                            verificationAnswers = verificationAnswers,
                            onAnswer = { question, answer -> verificationAnswers = verificationAnswers + (question to answer) },
                        )
                    }
                    listOf(
                        "Naziv" to result.name,
                        "Proizvođač" to result.manufacturer,
                        "Model / tip" to result.model,
                        "Serijski broj" to result.serialNumber,
                        "Inventarski broj" to result.inventoryNumber,
                        "Tehnički podaci" to result.technicalData,
                        "Izvor / baza" to result.matchedSource,
                    ).filter { it.second.isNotBlank() }.forEach { (label, value) ->
                        Column(verticalArrangement = Arrangement.spacedBy(1.dp)) {
                            Text(label, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f))
                            Text(value, fontWeight = FontWeight.Bold)
                        }
                    }
                    if (listOf(result.name, result.manufacturer, result.model, result.serialNumber, result.inventoryNumber, result.technicalData).all { it.isBlank() }) {
                        Text(
                            "Nema sigurnih polja za upis. Dodaj jasniju sliku pločice ili stroja izdaleka.",
                            color = Color(0xFFB45309),
                            style = MaterialTheme.typography.bodySmall,
                        )
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { applyRecognition(result, verificationAnswers) },
                    enabled = listOf(result.name, result.manufacturer, result.model, result.serialNumber, result.inventoryNumber, result.technicalData).any { it.isNotBlank() } && questionsAnswered,
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Primijeni")
                }
            },
            dismissButton = {
                TextButton(onClick = { recognitionPreview = null }) {
                    Text("Zatvori")
                }
            },
        )
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surface,
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.22f)),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(16.dp))
                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.34f))
                    .pointerInput(enabled, columnIndex, columnCount) {
                        var totalHorizontalDrag = 0f
                        detectDragGestures(
                            onDragStart = { totalHorizontalDrag = 0f },
                            onDragCancel = { totalHorizontalDrag = 0f },
                            onDragEnd = {
                                if (enabled && columnCount > 1) {
                                    when {
                                        totalHorizontalDrag > 76f && columnIndex > 0 -> onPrevious()
                                        totalHorizontalDrag < -76f && columnIndex < columnCount - 1 -> onNext()
                                    }
                                }
                                totalHorizontalDrag = 0f
                            },
                        ) { change, dragAmount ->
                            if (enabled && columnCount > 1 && abs(dragAmount.x) > abs(dragAmount.y) * 1.6f) {
                                totalHorizontalDrag += dragAmount.x
                                change.consume()
                            }
                        }
                    }
                    .padding(horizontal = 4.dp, vertical = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                IconButton(
                    onClick = onPrevious,
                    enabled = enabled && columnIndex > 0,
                    modifier = Modifier.size(42.dp),
                ) {
                    Icon(Icons.Rounded.ArrowBack, contentDescription = "Prethodna oprema")
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(
                        equipment.name.ifBlank { "$recordTitle ${columnIndex + 1}" },
                        fontWeight = FontWeight.Black,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        "Stupac ${columnIndex + 1}/$columnCount · sve vrijednosti su otvorene ispod",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
                IconButton(
                    onClick = onNext,
                    enabled = enabled && columnIndex < columnCount - 1,
                    modifier = Modifier.size(42.dp),
                ) {
                    Icon(Icons.Rounded.ArrowForward, contentDescription = "Sljedeća oprema")
                }
            }

            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedButton(
                    onClick = onAddColumn,
                    enabled = enabled,
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                ) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Nova kolona")
                }
                OutlinedButton(
                    onClick = onRemove,
                    enabled = enabled && columnCount > 1,
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                ) {
                    Icon(Icons.Rounded.Delete, contentDescription = null, modifier = Modifier.size(16.dp), tint = Color(0xFFDC2626))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Ukloni")
                }
            }

            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
                color = Color(0xFFF8FAFC),
                border = BorderStroke(1.dp, Color(0xFFCBD5E1)),
                tonalElevation = 0.dp,
            ) {
                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        verticalAlignment = Alignment.Top,
                    ) {
                        Surface(shape = CircleShape, color = Color(0xFFE0F2FE), modifier = Modifier.size(40.dp)) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Rounded.Description, contentDescription = null, tint = Color(0xFF0369A1), modifier = Modifier.size(21.dp))
                            }
                        }
                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                            Text("Predlošci zapisnika", fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                            Text(
                                "Primijeni isti sadržaj zapisnika bez serijskog, inventarnog broja i slika.",
                                style = MaterialTheme.typography.bodySmall,
                                color = Color(0xFF475569),
                            )
                        }
                    }
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Box(modifier = Modifier.weight(1f)) {
                            OutlinedButton(
                                onClick = { templateMenuOpen = true },
                                enabled = enabled && reportTemplates.isNotEmpty(),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.ListAlt, contentDescription = null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(if (reportTemplates.isEmpty()) "Nema predložaka" else "Odaberi predložak")
                            }
                            DropdownMenu(
                                expanded = templateMenuOpen,
                                onDismissRequest = { templateMenuOpen = false },
                            ) {
                                reportTemplates.forEach { template ->
                                    DropdownMenuItem(
                                        text = {
                                            Column(verticalArrangement = Arrangement.spacedBy(1.dp)) {
                                                Text(template.title, fontWeight = FontWeight.Bold)
                                                Text(
                                                    template.equipment.subtitle().ifBlank { "Sadržaj $recordLabel zapisnika" },
                                                    style = MaterialTheme.typography.labelSmall,
                                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                                    maxLines = 1,
                                                    overflow = TextOverflow.Ellipsis,
                                                )
                                            }
                                        },
                                        onClick = {
                                            onEquipmentChange(equipment.applyReportTemplate(template.equipment))
                                            templateMenuOpen = false
                                            templateMessage = "Primijenjen predložak \"${template.title}\". Serijski, inventarni broj i slike su ostali iz trenutne kolone."
                                        },
                                    )
                                }
                            }
                        }
                        OutlinedButton(
                            onClick = { saveTemplateDialogOpen = true },
                            enabled = enabled,
                            shape = RoundedCornerShape(14.dp),
                            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 10.dp),
                        ) {
                            Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Spremi")
                        }
                    }
                    if (templateMessage.isNotBlank()) {
                        Text(
                            templateMessage,
                            style = MaterialTheme.typography.labelSmall,
                            color = Color(0xFF0F766E),
                            fontWeight = FontWeight.Bold,
                        )
                    }
                }
            }

            WorkEquipmentPartsToggle(
                equipment = equipment,
                enabled = enabled,
                onEquipmentChange = onEquipmentChange,
            )

            WorkEquipmentAttachmentGallery(
                title = "Slike i PDF prilozi",
                subtitle = if (isStrojeviTemplate) {
                    "Slika stroja, pločica i PDF prilozi idu u lokalni STROJEVI zapisnik."
                } else {
                    "Prve slike označi kao cijeli stroj i pločicu. PDF prilozi idu odvojeno na kraj zapisnika."
                },
                attachments = equipment.attachments,
                enabled = enabled,
                loadingImages = attachmentsLoading,
                loadingDocuments = documentsLoading,
                onAddImages = { imagePicker.launch("image/*") },
                onAddDocuments = { pdfPicker.launch("application/pdf") },
                onAttachmentsChange = { nextAttachments -> onEquipmentChange(equipment.copy(attachments = nextAttachments)) },
            )

            if (showRecognition) {
                val recognitionImages = equipment.attachments.filter { it.includeInReport && it.isRoImageAttachment() }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Button(
                        onClick = {
                            recognitionLoading = true
                            recognitionMessage = "Čitam slike stroja i pločice..."
                            onRecognizeImages(
                                equipment,
                                recognitionImages,
                                { result ->
                                    recognitionLoading = false
                                    recognitionPreview = result
                                    recognitionMessage = result.message.ifBlank { "Provjeri prepoznate podatke prije primjene." }
                                },
                                { message ->
                                    recognitionLoading = false
                                    recognitionMessage = message
                                },
                            )
                        },
                        enabled = enabled && !recognitionLoading && recognitionImages.any { it.contentDataUrl.isNotBlank() },
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(14.dp),
                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 10.dp),
                    ) {
                        if (recognitionLoading) {
                            CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
                        } else {
                            Icon(Icons.Rounded.AutoAwesome, contentDescription = null, modifier = Modifier.size(16.dp))
                        }
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Prepoznaj iz označenih slika")
                    }
                }
                if (recognitionLoading) {
                    WorkEquipmentAiStatusPanel(
                        title = "NexAI čita otvorenu kolonu",
                        subtitle = "Prepoznajem stroj i pločicu samo iz slika koje šalješ u zapisnik.",
                        details = "PDF prilozi se ne koriste za vizualno prepoznavanje stroja.",
                    )
                }
            }
            listOf(attachmentMessage, recognitionMessage).filter { it.isNotBlank() }.forEach { message ->
                Text(
                    message,
                    style = MaterialTheme.typography.labelSmall,
                    color = if (message.contains("ne", ignoreCase = true) || message.contains("greška", ignoreCase = true)) Color(0xFFB45309) else Color(0xFF0F766E),
                )
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    "Osnovni podaci",
                    modifier = Modifier.weight(1f),
                    style = MaterialTheme.typography.labelLarge,
                    fontWeight = FontWeight.Black,
                    color = MaterialTheme.colorScheme.primary,
                )
                AssistChip(
                    onClick = {
                        val nextParts = equipment.parts.ifEmpty { listOf(defaultWorkEquipmentPart(1)) }
                        onEquipmentChange(equipment.copy(hasParts = true, parts = nextParts))
                    },
                    enabled = enabled,
                    leadingIcon = {
                        Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                    },
                    label = { Text(if (equipment.parts.isEmpty()) "Dio" else "${equipment.parts.size} dijelova") },
                )
            }
            WorkEquipmentPartsCompactEditor(
                equipment = equipment,
                enabled = enabled,
                onEquipmentChange = onEquipmentChange,
                onRecognizeImages = onRecognizeImages,
            )
            OutlinedTextField(equipment.name, { onEquipmentChange(equipment.copy(name = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Naziv strojeva/uređaja" else "Naziv") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.manufacturer, { onEquipmentChange(equipment.copy(manufacturer = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Proizvođač") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.model, { onEquipmentChange(equipment.copy(model = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Tip" else "Model / tip") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.serialNumber, { onEquipmentChange(equipment.copy(serialNumber = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Serijski broj") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.inventoryNumber, { onEquipmentChange(equipment.copy(inventoryNumber = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Inv.br." else "Inventarski broj") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.note, { onEquipmentChange(equipment.copy(note = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Napomena") }, minLines = 2, maxLines = 4, enabled = enabled, shape = RoundedCornerShape(14.dp))

            ManualWorkEquipmentSectionTitle("Opisna polja")
            OutlinedTextField(equipment.technicalData, { onEquipmentChange(equipment.copy(technicalData = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Tehnički podaci") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.purposeDescription, { onEquipmentChange(equipment.copy(purposeDescription = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Namjena opreme" else "Namjena radne opreme") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.workspacePosition, { onEquipmentChange(equipment.copy(workspacePosition = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Položaj opreme" else "Položaj u radnom prostoru") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.workingSubstancesAndRawMaterials, { onEquipmentChange(equipment.copy(workingSubstancesAndRawMaterials = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Sirovine/radne tvari" else "Radne tvari i sirovine") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.useAndMaintenance, { onEquipmentChange(equipment.copy(useAndMaintenance = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Dokumentacija" else "Uporaba i održavanje") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.methodsProceduresAndNorms, { onEquipmentChange(equipment.copy(methodsProceduresAndNorms = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text(if (isStrojeviTemplate) "Metode korištene prilikom pregleda i ispitivanja" else "Metode, postupci i norme") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))

            if (isStrojeviTemplate) {
                ManualStrojeviSequentialInspectionEditor(
                    title = "Ispitne stavke",
                    items = equipment.mechanicalItems,
                    onItemsChange = { onEquipmentChange(equipment.copy(mechanicalItems = it)) },
                    enabled = enabled,
                )
            } else {
                ManualWorkEquipmentAssessmentEditor(
                    title = "Strojarski dio",
                    options = mechanicalOptions,
                    items = equipment.mechanicalItems,
                    onItemsChange = { onEquipmentChange(equipment.copy(mechanicalItems = it)) },
                )
                ManualWorkEquipmentAssessmentEditor(
                    title = "Elektro dio",
                    options = electricalOptions,
                    items = equipment.electricalItems,
                    onItemsChange = { onEquipmentChange(equipment.copy(electricalItems = it)) },
                )
            }

            if (showRiskRegisters) {
                ManualWorkEquipmentSectionTitle("Opasnosti, štetnosti i napori")
                ManualWorkEquipmentRegisterChips(
                    title = "Opasnosti",
                    options = hazardOptions,
                    selectedIris = equipment.hazardRegisterIris,
                    onSelectedIrisChange = { onEquipmentChange(equipment.copy(hazardRegisterIris = it)) },
                )
                ManualWorkEquipmentRegisterChips(
                    title = "Štetnosti",
                    options = harmfulnessOptions,
                    selectedIris = equipment.harmfulnessRegisterIris,
                    onSelectedIrisChange = { onEquipmentChange(equipment.copy(harmfulnessRegisterIris = it)) },
                )
                ManualWorkEquipmentRegisterChips(
                    title = "Napori",
                    options = strainOptions,
                    selectedIris = equipment.strainRegisterIris,
                    onSelectedIrisChange = { onEquipmentChange(equipment.copy(strainRegisterIris = it)) },
                )
            }

            ManualWorkEquipmentSectionTitle("Zaključak")
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                FilterChip(selected = equipment.finalGrade != "0", onClick = { onEquipmentChange(equipment.copy(finalGrade = "1")) }, enabled = enabled, label = { Text("Zadovoljava") })
                FilterChip(selected = equipment.finalGrade == "0", onClick = { onEquipmentChange(equipment.copy(finalGrade = "0")) }, enabled = enabled, label = { Text("Ne zadovoljava") })
            }
            OutlinedTextField(equipment.deficiencies, { onEquipmentChange(equipment.copy(deficiencies = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Nedostaci") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(equipment.measuresToEliminateDeficiencies, { onEquipmentChange(equipment.copy(measuresToEliminateDeficiencies = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Mjere za otklanjanje nedostataka") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))
        }
    }
}

private fun defaultWorkEquipmentPart(index: Int): IsznrManualWorkEquipment =
    IsznrManualWorkEquipment(
        name = "",
        note = "",
    )

@Composable
private fun WorkEquipmentPartsToggle(
    equipment: IsznrManualWorkEquipment,
    enabled: Boolean,
    onEquipmentChange: (IsznrManualWorkEquipment) -> Unit,
) {
    val hasParts = equipment.hasParts || equipment.parts.isNotEmpty()
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = if (hasParts) Color(0xFFF0FDF4) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.34f),
        border = BorderStroke(
            1.dp,
            if (hasParts) Color(0xFF86EFAC) else MaterialTheme.colorScheme.outline.copy(alpha = 0.18f),
        ),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Checkbox(
                    checked = hasParts,
                    onCheckedChange = { checked ->
                        onEquipmentChange(
                            equipment.copy(
                                hasParts = checked,
                                parts = if (checked) equipment.parts else emptyList(),
                            ),
                        )
                    },
                    enabled = enabled,
                )
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text("Dijelovi uz slike", fontWeight = FontWeight.Black)
                    Text(
                        if (hasParts) {
                            "Slike se mogu vezati uz dijelove. Unos dijelova otvara se na + kod osnovnih podataka."
                        } else {
                            "Uključi kad jedna radna oprema ima zasebne dijelove i slike dijelova."
                        },
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                    )
                }
                AssistChip(onClick = {}, enabled = false, label = { Text("${equipment.parts.size}") })
            }
        }
    }
}

@Composable
private fun WorkEquipmentPartsCompactEditor(
    equipment: IsznrManualWorkEquipment,
    enabled: Boolean,
    onEquipmentChange: (IsznrManualWorkEquipment) -> Unit,
    onRecognizeImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
) {
    val parts = equipment.parts
    if (parts.isEmpty()) return
    var activePartIndex by remember { mutableStateOf(0) }
    LaunchedEffect(parts.size) {
        activePartIndex = when {
            parts.isEmpty() -> 0
            activePartIndex > parts.lastIndex -> parts.lastIndex
            else -> activePartIndex
        }
    }

    fun addPart() {
        activePartIndex = parts.size
        onEquipmentChange(
            equipment.copy(
                hasParts = true,
                parts = parts + defaultWorkEquipmentPart(parts.size + 1),
            ),
        )
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(20.dp),
        color = Color(0xFFF0FDF4),
        border = BorderStroke(1.dp, Color(0xFF86EFAC)),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(shape = CircleShape, color = Color(0xFFDCFCE7), modifier = Modifier.size(38.dp)) {
                    Box(contentAlignment = Alignment.Center) {
                        Icon(Icons.Rounded.Add, contentDescription = null, tint = Color(0xFF15803D), modifier = Modifier.size(20.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text("Dijelovi opreme", fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                    Text(
                        if (parts.isEmpty()) {
                            "Dodaj prvi dio kad ova RO kolona ima zaseban sklop, nastavak ili priključak."
                        } else {
                            "Jedan dio je otvoren. Strelicama ili povlačenjem lijevo/desno prebaci dio."
                        },
                        style = MaterialTheme.typography.labelSmall,
                        color = Color(0xFF166534),
                    )
                }
                Button(
                    onClick = { addPart() },
                    enabled = enabled,
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 8.dp),
                ) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(5.dp))
                    Text("Dio")
                }
            }

            if (parts.isEmpty()) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = Color.White.copy(alpha = 0.84f),
                    border = BorderStroke(1.dp, Color(0xFFBBF7D0)),
                ) {
                    Text(
                        "Kad dodaš dio, otvara se dodatni unos s vlastitim slikama, pločicom, nazivom, tipom i napomenom.",
                        modifier = Modifier.padding(12.dp),
                        style = MaterialTheme.typography.labelSmall,
                        color = Color(0xFF166534),
                        fontWeight = FontWeight.Bold,
                    )
                }
                return@Column
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(16.dp))
                    .background(Color.White.copy(alpha = 0.84f))
                    .pointerInput(activePartIndex, parts.size, enabled) {
                        var totalHorizontalDrag = 0f
                        detectDragGestures(
                            onDragStart = { totalHorizontalDrag = 0f },
                            onDragCancel = { totalHorizontalDrag = 0f },
                            onDragEnd = {
                                if (enabled && parts.size > 1) {
                                    when {
                                        totalHorizontalDrag > 64f && activePartIndex > 0 -> activePartIndex -= 1
                                        totalHorizontalDrag < -64f && activePartIndex < parts.lastIndex -> activePartIndex += 1
                                    }
                                }
                                totalHorizontalDrag = 0f
                            },
                        ) { change, dragAmount ->
                            if (enabled && parts.size > 1 && abs(dragAmount.x) > abs(dragAmount.y) * 1.5f) {
                                totalHorizontalDrag += dragAmount.x
                                change.consume()
                            }
                        }
                    }
                    .padding(horizontal = 6.dp, vertical = 5.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                IconButton(
                    onClick = { activePartIndex = (activePartIndex - 1).coerceAtLeast(0) },
                    enabled = enabled && activePartIndex > 0,
                    modifier = Modifier.size(38.dp),
                ) {
                    Icon(Icons.Rounded.ArrowBack, contentDescription = "Prethodni dio")
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    Text(
                        parts.getOrNull(activePartIndex)?.name?.ifBlank { "Dio opreme ${activePartIndex + 1}" }.orEmpty(),
                        fontWeight = FontWeight.Black,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        "Dio ${activePartIndex + 1}/${parts.size} · slike, pločica i podaci su ispod",
                        style = MaterialTheme.typography.labelSmall,
                        color = Color(0xFF166534),
                    )
                }
                IconButton(
                    onClick = { activePartIndex = (activePartIndex + 1).coerceAtMost(parts.lastIndex) },
                    enabled = enabled && activePartIndex < parts.lastIndex,
                    modifier = Modifier.size(38.dp),
                ) {
                    Icon(Icons.Rounded.ArrowForward, contentDescription = "Sljedeći dio")
                }
            }

            parts.getOrNull(activePartIndex)?.let { part ->
                WorkEquipmentPartCard(
                    index = activePartIndex,
                    part = part,
                    enabled = enabled,
                    onPartChange = { updatedPart ->
                        onEquipmentChange(
                            equipment.copy(
                                hasParts = true,
                                parts = parts.mapIndexed { partIndex, current ->
                                    if (partIndex == activePartIndex) updatedPart else current
                                },
                            ),
                        )
                    },
                    onRemove = {
                        val nextParts = parts.filterIndexed { partIndex, _ -> partIndex != activePartIndex }
                        activePartIndex = activePartIndex.coerceAtMost((nextParts.size - 1).coerceAtLeast(0))
                        onEquipmentChange(equipment.copy(hasParts = nextParts.isNotEmpty(), parts = nextParts))
                    },
                    onRecognizeImages = onRecognizeImages,
                )
            }
        }
    }
}

@Composable
private fun WorkEquipmentPartCard(
    index: Int,
    part: IsznrManualWorkEquipment,
    enabled: Boolean,
    onPartChange: (IsznrManualWorkEquipment) -> Unit,
    onRemove: () -> Unit,
    onRecognizeImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var loadingFiles by remember(part.attachments) { mutableStateOf(false) }
    var loadingDocuments by remember(part.attachments) { mutableStateOf(false) }
    var recognizing by remember(part.attachments) { mutableStateOf(false) }
    var message by remember(part.attachments) { mutableStateOf("") }
    var preview by remember(part.attachments) { mutableStateOf<WorkEquipmentImageRecognitionResult?>(null) }
    val picker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            loadingFiles = true
            message = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = part.attachments.size,
                )
            }
                .onSuccess { files ->
                    val taggedFiles = withDefaultRoImageRoles(part.attachments, files)
                    onPartChange(part.copy(attachments = part.attachments + taggedFiles))
                    message = if (files.isEmpty()) "Nije dodana nijedna slika." else "${files.size} slika dodano za dio opreme."
                }
                .onFailure { error ->
                    message = error.message ?: "Ne mogu učitati slike dijela."
                }
            loadingFiles = false
        }
    }
    val pdfPicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            loadingDocuments = true
            message = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = part.attachments.size,
                    mode = WorkOrderDocumentInputMode.Pdf,
                    role = "document",
                    allowPdf = true,
                )
            }
                .onSuccess { files ->
                    onPartChange(part.copy(attachments = part.attachments + files.map { it.copy(role = "document") }))
                    message = if (files.isEmpty()) "Nije dodan nijedan PDF prilog." else "${files.size} PDF prilog(a) dodano za dio opreme."
                }
                .onFailure { error ->
                    message = error.message ?: "Ne mogu učitati PDF priloge dijela."
                }
            loadingDocuments = false
        }
    }

    fun applyPartRecognition(result: WorkEquipmentImageRecognitionResult) {
        val generatedNote = listOf(
            result.message,
            result.technicalData,
        )
            .map { it.trim() }
            .firstOrNull { it.isNotBlank() }
            .orEmpty()
            .take(255)
        onPartChange(
            part.copy(
                name = result.name.ifBlank { part.name },
                manufacturer = result.manufacturer.ifBlank { part.manufacturer },
                model = result.model.ifBlank { part.model },
                serialNumber = result.serialNumber.ifBlank { part.serialNumber },
                inventoryNumber = result.inventoryNumber.ifBlank { part.inventoryNumber },
                technicalData = result.technicalData.ifBlank { part.technicalData },
                note = part.note.ifBlank { generatedNote.ifBlank { "Dio opreme prepoznat prema fotografiji." } },
            ),
        )
        preview = null
        message = "Podaci dijela su primijenjeni."
    }

    preview?.let { result ->
        AlertDialog(
            onDismissRequest = { preview = null },
            title = { Text("Provjeri dio opreme") },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        result.message.ifBlank { "NexAI je pročitao slike dijela opreme." },
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                    )
                    listOf(
                        "Naziv dijela" to result.name,
                        "Proizvođač" to result.manufacturer,
                        "Model / tip" to result.model,
                        "Serijski broj" to result.serialNumber,
                        "Inventarski broj" to result.inventoryNumber,
                        "Tehnički podaci" to result.technicalData,
                    ).filter { it.second.isNotBlank() }.forEach { (label, value) ->
                        Column(verticalArrangement = Arrangement.spacedBy(1.dp)) {
                            Text(label, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f))
                            Text(value, fontWeight = FontWeight.Bold)
                        }
                    }
                    if (listOf(result.name, result.manufacturer, result.model, result.serialNumber, result.inventoryNumber, result.technicalData).all { it.isBlank() }) {
                        Text(
                            "Nema sigurnih polja. Možeš svejedno ostaviti ručni opis dijela.",
                            color = Color(0xFFB45309),
                            style = MaterialTheme.typography.bodySmall,
                        )
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { applyPartRecognition(result) },
                    enabled = listOf(result.name, result.manufacturer, result.model, result.serialNumber, result.inventoryNumber, result.technicalData, result.message).any { it.isNotBlank() },
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Primijeni")
                }
            },
            dismissButton = {
                TextButton(onClick = { preview = null }) {
                    Text("Zatvori")
                }
            },
        )
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = Color.White.copy(alpha = 0.9f),
        border = BorderStroke(1.dp, Color(0xFFBBF7D0)),
        tonalElevation = 0.dp,
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(shape = CircleShape, color = Color(0xFFDCFCE7), modifier = Modifier.size(34.dp)) {
                    Box(contentAlignment = Alignment.Center) {
                        Text("${index + 1}", color = Color(0xFF15803D), fontWeight = FontWeight.Black)
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                    Text(part.name.ifBlank { "Dio opreme ${index + 1}" }, fontWeight = FontWeight.Black)
                    Text(
                        part.subtitle().ifBlank { "Slika dijela + pločica ako postoji" },
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                IconButton(onClick = onRemove, enabled = enabled, modifier = Modifier.size(34.dp)) {
                    Icon(Icons.Rounded.Delete, contentDescription = "Ukloni dio", tint = Color(0xFFDC2626), modifier = Modifier.size(18.dp))
                }
            }

            OutlinedTextField(part.name, { onPartChange(part.copy(name = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Naziv dijela") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(part.manufacturer, { onPartChange(part.copy(manufacturer = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Proizvođač") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(part.model, { onPartChange(part.copy(model = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Model / tip") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(part.serialNumber, { onPartChange(part.copy(serialNumber = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Serijski broj") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(part.inventoryNumber, { onPartChange(part.copy(inventoryNumber = it)) }, modifier = Modifier.fillMaxWidth(), label = { Text("Inventarski broj") }, singleLine = true, enabled = enabled, shape = RoundedCornerShape(14.dp))
            OutlinedTextField(part.note, { onPartChange(part.copy(note = it.take(255))) }, modifier = Modifier.fillMaxWidth(), label = { Text("Napomena / procjena") }, minLines = 2, maxLines = 5, enabled = enabled, shape = RoundedCornerShape(14.dp))

            WorkEquipmentAttachmentGallery(
                title = "Slike i PDF prilog dijela",
                subtitle = "Dodaj sliku dijela, pločicu ako postoji i PDF prilog ako ga treba nastaviti iza zapisnika.",
                attachments = part.attachments,
                enabled = enabled,
                loadingImages = loadingFiles,
                loadingDocuments = loadingDocuments,
                onAddImages = { picker.launch("image/*") },
                onAddDocuments = { pdfPicker.launch("application/pdf") },
                onAttachmentsChange = { nextAttachments -> onPartChange(part.copy(attachments = nextAttachments)) },
            )
            val recognitionImages = part.attachments.filter { it.includeInReport && it.isRoImageAttachment() }
            Button(
                onClick = {
                    recognizing = true
                    message = "NexAI čita dio opreme..."
                    onRecognizeImages(
                        part,
                        recognitionImages,
                        { result ->
                            recognizing = false
                            preview = result
                            message = result.message.ifBlank { "Provjeri podatke dijela prije primjene." }
                        },
                        { errorMessage ->
                            recognizing = false
                            message = errorMessage
                        },
                    )
                },
                enabled = enabled && !recognizing && recognitionImages.any { it.contentDataUrl.isNotBlank() },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(14.dp),
                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 9.dp),
            ) {
                if (recognizing) {
                    CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary)
                } else {
                    Icon(Icons.Rounded.AutoAwesome, contentDescription = null, modifier = Modifier.size(16.dp))
                }
                Spacer(modifier = Modifier.width(6.dp))
                Text("Prepoznaj iz označenih slika")
            }
            if (message.isNotBlank()) {
                Text(
                    message,
                    style = MaterialTheme.typography.labelSmall,
                    color = if (message.contains("ne", ignoreCase = true) || message.contains("greška", ignoreCase = true)) Color(0xFFB45309) else Color(0xFF0F766E),
                    fontWeight = FontWeight.Bold,
                )
            }
        }
    }
}

@Composable
private fun ManualWorkEquipmentDialog(
    title: String,
    initialEquipment: IsznrManualWorkEquipment,
    mechanicalOptions: List<WorkOrderDocumentationOption>,
    electricalOptions: List<WorkOrderDocumentationOption>,
    hazardOptions: List<WorkOrderDocumentationOption>,
    harmfulnessOptions: List<WorkOrderDocumentationOption>,
    strainOptions: List<WorkOrderDocumentationOption>,
    onDismiss: () -> Unit,
    onAdd: (IsznrManualWorkEquipment) -> Unit,
) {
    val steps = listOf("Osnovno", "RO opis", "Kontrole", "Rizici", "Slike", "Zaključak")
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    var stepIndex by remember(initialEquipment) { mutableStateOf(0) }
    var name by remember(initialEquipment) { mutableStateOf(initialEquipment.name) }
    var manufacturer by remember(initialEquipment) { mutableStateOf(initialEquipment.manufacturer) }
    var model by remember(initialEquipment) { mutableStateOf(initialEquipment.model) }
    var serialNumber by remember(initialEquipment) { mutableStateOf(initialEquipment.serialNumber) }
    var inventoryNumber by remember(initialEquipment) { mutableStateOf(initialEquipment.inventoryNumber) }
    var note by remember(initialEquipment) { mutableStateOf(initialEquipment.note) }
    var technicalData by remember(initialEquipment) { mutableStateOf(initialEquipment.technicalData) }
    var purposeDescription by remember(initialEquipment) { mutableStateOf(initialEquipment.purposeDescription) }
    var workspacePosition by remember(initialEquipment) { mutableStateOf(initialEquipment.workspacePosition) }
    var workingSubstancesAndRawMaterials by remember(initialEquipment) { mutableStateOf(initialEquipment.workingSubstancesAndRawMaterials) }
    var useAndMaintenance by remember(initialEquipment) { mutableStateOf(initialEquipment.useAndMaintenance) }
    var methodsProceduresAndNorms by remember(initialEquipment) { mutableStateOf(initialEquipment.methodsProceduresAndNorms) }
    var deficiencies by remember(initialEquipment) { mutableStateOf(initialEquipment.deficiencies) }
    var measuresToEliminateDeficiencies by remember(initialEquipment) { mutableStateOf(initialEquipment.measuresToEliminateDeficiencies) }
    var finalGrade by remember(initialEquipment) { mutableStateOf(initialEquipment.finalGrade.ifBlank { "1" }) }
    val mechanicalItems = remember(initialEquipment) {
        mutableStateListOf<IsznrRoAssessmentItem>().apply { addAll(initialEquipment.mechanicalItems) }
    }
    val electricalItems = remember(initialEquipment) {
        mutableStateListOf<IsznrRoAssessmentItem>().apply { addAll(initialEquipment.electricalItems) }
    }
    val attachmentFiles = remember(initialEquipment) {
        mutableStateListOf<IsznrRoAttachmentFile>().apply { addAll(initialEquipment.attachments) }
    }
    var attachmentMessage by remember(initialEquipment) { mutableStateOf("") }
    var attachmentsLoading by remember(initialEquipment) { mutableStateOf(false) }
    val imagePicker = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        coroutineScope.launch {
            attachmentsLoading = true
            attachmentMessage = ""
            runCatching {
                buildIsznrRoAttachmentFiles(
                    context = context.applicationContext,
                    uris = uris,
                    existingCount = attachmentFiles.size,
                )
            }
                .onSuccess { files ->
                    attachmentFiles.addAll(files)
                    attachmentMessage = if (files.isEmpty()) {
                        "Nije dodana nijedna slika."
                    } else {
                        "${files.size} slika dodano za IS ZNR privitke."
                    }
                }
                .onFailure { error ->
                    attachmentMessage = error.message ?: "Ne mogu učitati slike."
                }
            attachmentsLoading = false
        }
    }
    var hazardRegisterIris by remember(initialEquipment) { mutableStateOf(initialEquipment.hazardRegisterIris) }
    var harmfulnessRegisterIris by remember(initialEquipment) { mutableStateOf(initialEquipment.harmfulnessRegisterIris) }
    var strainRegisterIris by remember(initialEquipment) { mutableStateOf(initialEquipment.strainRegisterIris) }
    val equipment = IsznrManualWorkEquipment(
        name = name.trim(),
        manufacturer = manufacturer.trim(),
        model = model.trim(),
        serialNumber = serialNumber.trim(),
        inventoryNumber = inventoryNumber.trim(),
        note = note.trim(),
        technicalData = technicalData.trim(),
        purposeDescription = purposeDescription.trim(),
        workspacePosition = workspacePosition.trim(),
        workingSubstancesAndRawMaterials = workingSubstancesAndRawMaterials.trim(),
        useAndMaintenance = useAndMaintenance.trim(),
        methodsProceduresAndNorms = methodsProceduresAndNorms.trim(),
        deficiencies = deficiencies.trim(),
        measuresToEliminateDeficiencies = measuresToEliminateDeficiencies.trim(),
        finalGrade = finalGrade,
        mechanicalItems = mechanicalItems.toList(),
        electricalItems = electricalItems.toList(),
        hazardRegisterIris = hazardRegisterIris,
        harmfulnessRegisterIris = harmfulnessRegisterIris,
        strainRegisterIris = strainRegisterIris,
        attachments = attachmentFiles.toList(),
    )

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(title)
                Text(
                    "${stepIndex + 1}/${steps.size} · ${steps[stepIndex]}",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            }
        },
        text = {
            Column(
                modifier = Modifier.verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    steps.forEachIndexed { index, step ->
                        FilterChip(
                            selected = stepIndex == index,
                            onClick = { stepIndex = index },
                            label = { Text(step) },
                        )
                    }
                }
                when (stepIndex) {
                    0 -> {
                        ManualWorkEquipmentSectionTitle("Osnovni podaci")
                        Text(
                            "Jedna nova radna oprema = jedan stupac u RO zapisniku.",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                        OutlinedTextField(name, { name = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Naziv") }, singleLine = true, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(manufacturer, { manufacturer = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Proizvođač") }, singleLine = true, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(model, { model = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Model / tip") }, singleLine = true, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(serialNumber, { serialNumber = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Serijski broj") }, singleLine = true, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(inventoryNumber, { inventoryNumber = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Inventarski broj") }, singleLine = true, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(note, { note = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Napomena") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                    }
                    1 -> {
                        ManualWorkEquipmentSectionTitle("Opisna RO polja")
                        OutlinedTextField(technicalData, { technicalData = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Tehnički podaci") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(purposeDescription, { purposeDescription = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Namjena radne opreme") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(workspacePosition, { workspacePosition = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Položaj u radnom prostoru") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(workingSubstancesAndRawMaterials, { workingSubstancesAndRawMaterials = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Radne tvari i sirovine") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(useAndMaintenance, { useAndMaintenance = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Uporaba i održavanje") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(methodsProceduresAndNorms, { methodsProceduresAndNorms = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Metode, postupci i norme") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                    }
                    2 -> {
                        ManualWorkEquipmentAssessmentEditor(
                            title = "Strojarski dio",
                            options = mechanicalOptions,
                            items = mechanicalItems,
                            onItemsChange = { nextItems ->
                                mechanicalItems.clear()
                                mechanicalItems.addAll(nextItems)
                            },
                        )
                        ManualWorkEquipmentAssessmentEditor(
                            title = "Elektro dio",
                            options = electricalOptions,
                            items = electricalItems,
                            onItemsChange = { nextItems ->
                                electricalItems.clear()
                                electricalItems.addAll(nextItems)
                            },
                        )
                    }
                    3 -> {
                        ManualWorkEquipmentSectionTitle("Opasnosti, štetnosti i napori")
                        ManualWorkEquipmentRegisterChips(
                            title = "Opasnosti",
                            options = hazardOptions,
                            selectedIris = hazardRegisterIris,
                            onSelectedIrisChange = { hazardRegisterIris = it },
                        )
                        ManualWorkEquipmentRegisterChips(
                            title = "Štetnosti",
                            options = harmfulnessOptions,
                            selectedIris = harmfulnessRegisterIris,
                            onSelectedIrisChange = { harmfulnessRegisterIris = it },
                        )
                        ManualWorkEquipmentRegisterChips(
                            title = "Napori",
                            options = strainOptions,
                            selectedIris = strainRegisterIris,
                            onSelectedIrisChange = { strainRegisterIris = it },
                        )
                    }
                    4 -> {
                        ManualWorkEquipmentSectionTitle("Slike radne opreme")
                        Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f)) {
                            Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                ) {
                                    Icon(Icons.Rounded.Image, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text("Privici za IS ZNR", fontWeight = FontWeight.Bold)
                                        Text(
                                            "${attachmentFiles.size}/$ISZNR_RO_ATTACHMENT_MAX_INLINE_FILES slika · max 8 MB po slici",
                                            style = MaterialTheme.typography.labelSmall,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                        )
                                    }
                                }
                                OutlinedButton(
                                    onClick = { imagePicker.launch("image/*") },
                                    enabled = !attachmentsLoading && attachmentFiles.size < ISZNR_RO_ATTACHMENT_MAX_INLINE_FILES,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(14.dp),
                                ) {
                                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(if (attachmentsLoading) "Učitavam..." else "Dodaj slike")
                                }
                                if (attachmentMessage.isNotBlank()) {
                                    Text(
                                        attachmentMessage,
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                    )
                                }
                                if (attachmentFiles.isEmpty()) {
                                    Text(
                                        "Slike nisu obavezne. Ako ih dodaš, SafeNexus ih šalje kao RO privitke nakon kreiranja zapisnika.",
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                    )
                                }
                                attachmentFiles.forEachIndexed { index, file ->
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                    ) {
                                        Icon(Icons.Rounded.Image, contentDescription = null, tint = Color(0xFF0F766E), modifier = Modifier.size(18.dp))
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(file.fileName.ifBlank { "Slika ${index + 1}" }, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                            Text(
                                                listOf(file.fileType, formatFileSizeLabel(file.fileSize)).filter { it.isNotBlank() }.joinToString(" · "),
                                                style = MaterialTheme.typography.labelSmall,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                            )
                                        }
                                        IconButton(onClick = { attachmentFiles.removeAt(index) }, modifier = Modifier.size(32.dp)) {
                                            Icon(Icons.Rounded.Delete, contentDescription = "Ukloni sliku", tint = Color(0xFFDC2626), modifier = Modifier.size(18.dp))
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else -> {
                        ManualWorkEquipmentSectionTitle("Zaključak")
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            FilterChip(selected = finalGrade == "1", onClick = { finalGrade = "1" }, label = { Text("Zadovoljava") })
                            FilterChip(selected = finalGrade == "0", onClick = { finalGrade = "0" }, label = { Text("Ne zadovoljava") })
                        }
                        OutlinedTextField(deficiencies, { deficiencies = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Nedostaci") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                        OutlinedTextField(measuresToEliminateDeficiencies, { measuresToEliminateDeficiencies = it }, modifier = Modifier.fillMaxWidth(), label = { Text("Mjere za otklanjanje nedostataka") }, minLines = 2, maxLines = 4, shape = RoundedCornerShape(14.dp))
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    if (stepIndex < steps.lastIndex) {
                        stepIndex += 1
                    } else {
                        onAdd(equipment)
                    }
                },
                enabled = stepIndex < steps.lastIndex || equipment.isReadyForIsznrPost(),
                shape = RoundedCornerShape(14.dp),
            ) {
                Text(if (stepIndex < steps.lastIndex) "Dalje" else "Dodaj")
            }
        },
        dismissButton = {
            TextButton(onClick = {
                if (stepIndex > 0) {
                    stepIndex -= 1
                } else {
                    onDismiss()
                }
            }) {
                Text(if (stepIndex > 0) "Natrag" else "Odustani")
            }
        },
    )
}

