                                points = mapPoints,
                                totalWorkOrders = filtered.size,
                                statusOptions = if (isClientPortal) emptyList() else state.data.workOrderStatuses.map { it.value }.ifEmpty { workOrderStatusOptions },
                                mapHeight = 560.dp,
                                onOpenWorkOrder = onOpenWorkOrder,
                                onStatusChange = if (isClientPortal) ({ _, _ -> }) else onStatusChange,
                            )
                        }
                    }
                }
            } else if (filtered.isEmpty() && !state.isLoading) {
                item {
                    EmptyWorkOrders()
                }
            } else {
                items(filtered, key = { it.id }) { workOrder ->
                    WorkOrderCard(
                        workOrder = workOrder,
                        isLoading = state.isLoading,
                        statusOptions = if (isClientPortal) emptyList() else state.data.workOrderStatuses.map { it.value }.ifEmpty { workOrderStatusOptions },
                        onClick = { onOpenWorkOrder(workOrder) },
                        onStatusChange = { status -> if (!isClientPortal) onStatusChange(workOrder, status) },
                        onAddDocumentation = { if (!isClientPortal) onAddDocumentation(workOrder) },
                        readOnly = isClientPortal,
                    )
                }
            }
            }
        }
    }

    if (fieldInquiryDialogOpen) {
        FieldInquiryEditorDialog(
            record = fieldInquiryDialogRecord,
            data = state.data,
            currentUserLabel = state.user?.displayName.orEmpty(),
            isLoading = state.isLoading,
            onPolishNote = onPolishFieldInquiryNote,
            onDismiss = {
                fieldInquiryDialogOpen = false
                fieldInquiryDialogRecord = null
            },
            onSave = { draft ->
                fieldInquiryDialogOpen = false
                fieldInquiryDialogRecord = null
                onSaveFieldInquiry(draft)
            },
        )
    }
    if (riskAssessmentDialogOpen) {
        RiskAssessmentEditorDialog(
            data = state.data,
            currentUserLabel = state.user?.displayName.orEmpty(),
            isLoading = state.isLoading,
            onDismiss = { riskAssessmentDialogOpen = false },
            onSave = { draft ->
                riskAssessmentDialogOpen = false
                onCreateRiskAssessment(draft)
            },
            onNewJob = { jobDialogOpen = true },
        )
    }
    if (jobDialogOpen) {
        JobEditorDialog(
            isLoading = state.isLoading,
            onDismiss = { jobDialogOpen = false },
            onSave = { draft ->
                jobDialogOpen = false
                onCreateJob(draft)
            },
        )
    }
}

