@Composable
private fun MainMenuDropdown(
    expanded: Boolean,
    currentSection: AppSection,
    currentMoreFocus: MoreSectionFocus,
    isClientPortal: Boolean,
    onDismiss: () -> Unit,
    onSectionChange: (AppSection, MoreSectionFocus?) -> Unit,
    onLogout: () -> Unit,
) {
    val shortcuts = remember(isClientPortal) {
        val allShortcuts = listOf(
            MainMenuShortcut("Home", "Istekli rokovi i nadolazeći teren", AppSection.Operations, Icons.Rounded.Home),
            MainMenuShortcut("Radni nalozi", "Lista, karta, statusi i skeniranje RN-a", AppSection.WorkOrders, Icons.Rounded.CheckCircle),
            MainMenuShortcut("Vozila", "Pregled vozila, servisa i rezervacija", AppSection.Vehicles, Icons.Rounded.Business),
            MainMenuShortcut("ToDo", "Zadaci i teme", AppSection.More, Icons.Rounded.ListAlt, MoreSectionFocus.Todo),
            MainMenuShortcut("Plan terena", "Upiti i dogovori prije RN-a", AppSection.More, Icons.Rounded.EventNote, MoreSectionFocus.FieldInquiries),
            MainMenuShortcut("Ponude", "Pregled poslanih i primljenih ponuda", AppSection.More, Icons.Rounded.Description, MoreSectionFocus.Offers),
            MainMenuShortcut("Tvrtke", "Klijenti, kontakti i povezani podaci", AppSection.More, Icons.Rounded.Business, MoreSectionFocus.Companies),
            MainMenuShortcut("Dokumenti", "Explorer po tvrtki, lokaciji i RN-u", AppSection.More, Icons.Rounded.Folder, MoreSectionFocus.Documents),
            MainMenuShortcut("Periodika", "Rokovi, pregledi i isteci", AppSection.More, Icons.Rounded.CalendarMonth, MoreSectionFocus.Periodics),
            MainMenuShortcut("Zakonska regulativa", "Legal Framework propisi i povezani dokumenti", AppSection.More, Icons.Rounded.Description, MoreSectionFocus.LegalFrameworks),
            MainMenuShortcut("People", "Korisnici, OIB i IS ZNR status", AppSection.More, Icons.Rounded.Person, MoreSectionFocus.People),
            MainMenuShortcut("Mjerna oprema", "Popis opreme i ISZNR oznake", AppSection.More, Icons.Rounded.Work, MoreSectionFocus.MeasurementEquipment),
            MainMenuShortcut("Procjene rizika", "Jobs, radna mjesta i mobilni unos", AppSection.More, Icons.Rounded.Badge, MoreSectionFocus.RiskAssessments),
            MainMenuShortcut("Osposobljavanja", "ZOS, liječnički pregledi i uvjerenja", AppSection.More, Icons.Rounded.Fingerprint, MoreSectionFocus.Training),
        )
        if (!isClientPortal) {
            allShortcuts
        } else {
            listOf(MainMenuShortcut("Client Portal", "Dokumenti i podaci tvoje tvrtke", AppSection.Operations, Icons.Rounded.Business))
        }
    }

    DropdownMenu(
        expanded = expanded,
        onDismissRequest = onDismiss,
        modifier = Modifier.width(318.dp),
    ) {
        shortcuts.forEach { shortcut ->
            val selected = if (shortcut.section == AppSection.More) {
                currentSection == AppSection.More && currentMoreFocus == shortcut.moreFocus
            } else {
                currentSection == shortcut.section
            }
            DropdownMenuItem(
                text = {
                    Column {
                        Text(
                            shortcut.label,
                            fontWeight = if (selected) FontWeight.Bold else FontWeight.SemiBold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                        Text(
                            shortcut.description,
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                },
                leadingIcon = {
                    Icon(
                        shortcut.icon,
                        contentDescription = null,
                        tint = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                },
                trailingIcon = {
                    if (selected) {
                        Text(
                            "Aktivno",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            fontWeight = FontWeight.Bold,
                        )
                    }
                },
                onClick = {
                    onSectionChange(shortcut.section, shortcut.moreFocus)
                    onDismiss()
                },
            )
        }
        DropdownMenuItem(
            text = {
                Column {
                    Text("Odjava", fontWeight = FontWeight.Bold)
                    Text(
                        "Zatvori trenutnu prijavu",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    )
                }
            },
            leadingIcon = { Icon(Icons.Rounded.Lock, contentDescription = null) },
            onClick = {
                onDismiss()
                onLogout()
            },
        )
    }
}

@Composable
private fun WorkOrdersListSummary(
    total: Int,
    query: String,
    onQueryChange: (String) -> Unit,
) {
    var showSearch by remember { mutableStateOf(query.isNotBlank()) }

    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                "Ukupno:",
                style = MaterialTheme.typography.bodyMedium,
                color = Color(0xFF334155),
                fontWeight = FontWeight.SemiBold,
            )
            Spacer(Modifier.width(5.dp))
            Text(
                total.toString(),
                style = MaterialTheme.typography.bodyMedium,
                color = Color(0xFF0B63E5),
                fontWeight = FontWeight.Black,
            )
            Spacer(Modifier.weight(1f))
            TextButton(onClick = { showSearch = !showSearch }) {
                Icon(Icons.Rounded.Search, contentDescription = null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(6.dp))
                Text(if (showSearch) "Sakrij" else "Traži")
            }
        }

        AnimatedVisibility(showSearch) {
            OutlinedTextField(
                value = query,
                onValueChange = onQueryChange,
                modifier = Modifier.fillMaxWidth(),
                leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
                label = { Text("Pretraga RN, klijent, lokacija, usluga") },
                singleLine = true,
            )
        }
    }
}

@Composable
private fun WorkOrderTabs(
    selected: WorkOrderFilter,
    onFilterChange: (WorkOrderFilter) -> Unit,
) {
    val scrollState = rememberScrollState()
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .horizontalScroll(scrollState),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        WorkOrderFilter.entries.forEach { filter ->
            val isSelected = selected == filter
            val accent = workOrderFilterAccentColor(filter)
            Surface(
                modifier = Modifier
                    .clickable { onFilterChange(filter) }
                    .heightIn(min = 38.dp),
                shape = RoundedCornerShape(999.dp),
                color = if (isSelected) accent.copy(alpha = 0.16f) else Color(0xFFF8FAFC),
                tonalElevation = if (isSelected) 1.dp else 0.dp,
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 9.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(7.dp),
                ) {
                    if (filter == WorkOrderFilter.Mine) {
                        Icon(
                            Icons.Rounded.Person,
                            contentDescription = null,
                            modifier = Modifier.size(16.dp),
                            tint = if (isSelected) accent else Color(0xFF64748B),
                        )
                    }
                    Text(
                        filter.label,
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.Black,
                        color = if (isSelected) accent else Color(0xFF475569),
                        maxLines = 1,
                    )
                }
            }
        }
    }
}

@Composable
private fun WorkOrderQuickActionsFab(
    expanded: Boolean,
    filter: WorkOrderFilter,
    viewMode: WorkOrderViewMode,
    onToggle: () -> Unit,
    onNewWorkOrder: () -> Unit,
    onRefresh: () -> Unit,
    onViewModeChange: (WorkOrderViewMode) -> Unit,
    onFilterChange: (WorkOrderFilter) -> Unit,
) {
    Column(
        horizontalAlignment = Alignment.End,
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        AnimatedVisibility(expanded) {
            Card(
                shape = RoundedCornerShape(18.dp),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
            ) {
                Column(
                    modifier = Modifier.padding(10.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    QuickActionButton(
                        label = "Novi nalog",
                        icon = Icons.Rounded.Add,
                        isPrimary = true,
                        onClick = onNewWorkOrder,
                    )
                    QuickActionButton(
                        label = if (viewMode == WorkOrderViewMode.Map) "Prikaži listu" else "Prikaži kartu",
                        icon = if (viewMode == WorkOrderViewMode.Map) Icons.Rounded.ListAlt else Icons.Rounded.Map,
                        onClick = {
                            onViewModeChange(
                                if (viewMode == WorkOrderViewMode.Map) WorkOrderViewMode.List else WorkOrderViewMode.Map,
                            )
                        },
                    )
                    QuickActionButton(
                        label = "Osvježi RN",
                        icon = Icons.Rounded.Refresh,
                        onClick = onRefresh,
                    )
                    QuickActionDivider()
                    WorkOrderFilter.entries.forEach { option ->
                        QuickFilterAction(option.label, option, filter, onFilterChange)
                    }
                }
            }
        }

        FloatingActionButton(
            onClick = onToggle,
            containerColor = Color(0xFF0B63E5),
            contentColor = Color.White,
        ) {
            Icon(
                if (expanded) Icons.Rounded.ArrowBack else Icons.Rounded.Add,
                contentDescription = if (expanded) "Zatvori brze akcije" else "Brze akcije",
            )
        }
    }
}

@Composable
private fun QuickFilterAction(
    label: String,
    value: WorkOrderFilter,
    selected: WorkOrderFilter,
    onFilterChange: (WorkOrderFilter) -> Unit,
) {
    QuickActionButton(
        label = label,
        icon = when {
            selected == value -> Icons.Rounded.CheckCircle
            value == WorkOrderFilter.Mine -> Icons.Rounded.Person
            else -> Icons.Rounded.FilterList
        },
        isSelected = selected == value,
        onClick = { onFilterChange(value) },
    )
}

@Composable
private fun QuickActionButton(
    label: String,
    icon: ImageVector,
    isPrimary: Boolean = false,
    isSelected: Boolean = false,
    onClick: () -> Unit,
) {
    val background = when {
        isPrimary -> Color(0xFF0B63E5)
        isSelected -> Color(0xFFEAF2FF)
        else -> Color(0xFFF8FAFC)
    }
    val contentColor = when {
        isPrimary -> Color.White
        isSelected -> Color(0xFF0B63E5)
        else -> Color(0xFF0F172A)
    }

    Surface(
        modifier = Modifier
            .width(190.dp)
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(14.dp),
        color = background,
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 11.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(icon, contentDescription = null, modifier = Modifier.size(19.dp), tint = contentColor)
            Spacer(Modifier.width(10.dp))
            Text(
                label,
                color = contentColor,
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
            )
        }
    }
}

@Composable
private fun QuickActionDivider() {
    Box(
        modifier = Modifier
            .width(190.dp)
            .height(1.dp)
            .background(Color(0xFFE2E8F0)),
    )
}

@Composable
private fun MainBottomBar(
    selected: AppSection,
    currentMoreFocus: MoreSectionFocus,
    isClientPortal: Boolean,
    onSectionChange: (AppSection, MoreSectionFocus?) -> Unit,
) {
    if (isClientPortal) return
    val visibleSections = remember {
        listOf(
            MainMenuShortcut("Home", "Home", AppSection.Operations, Icons.Rounded.Home),
            MainMenuShortcut("RN", "Radni nalozi", AppSection.WorkOrders, Icons.Rounded.CheckCircle),
            MainMenuShortcut("Dokumenti", "Dokumenti", AppSection.More, Icons.Rounded.Folder, MoreSectionFocus.Documents),
            MainMenuShortcut("Periodika", "Periodika", AppSection.More, Icons.Rounded.CalendarMonth, MoreSectionFocus.Periodics),
        )
    }
    NavigationBar(containerColor = MaterialTheme.colorScheme.surface) {
        visibleSections.forEach { shortcut ->
            val itemSelected = if (shortcut.section == AppSection.More) {
                selected == AppSection.More && currentMoreFocus == shortcut.moreFocus
            } else {
                selected == shortcut.section
            }
            NavigationBarItem(
                selected = itemSelected,
                onClick = { onSectionChange(shortcut.section, shortcut.moreFocus) },
                icon = {
                    Icon(
                        imageVector = shortcut.icon,
                        contentDescription = shortcut.description,
                    )
                },
                label = {
                    Text(
                        shortcut.label,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                },
            )
        }
    }
}

private fun AppSection.icon(): ImageVector = when (this) {
    AppSection.Operations -> Icons.Rounded.Home
    AppSection.WorkOrders -> Icons.Rounded.CheckCircle
    AppSection.Calendar -> Icons.Rounded.CalendarMonth
    AppSection.Vehicles -> Icons.Rounded.Business
    AppSection.More -> Icons.Rounded.Map
}

@Composable
private fun OperationsContent(
    data: BootstrapData,
    user: SafeNexusUser?,
    workOrders: List<WorkOrder>,
    reminders: List<MobileRecord>,
    todoTasks: List<MobileRecord>,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onOpenRecord: (MobileRecord) -> Unit,
    onCreateReminder: (String, String, String, String, String, String, String, String) -> Unit,
    onUpdateReminderStatus: (String, String) -> Unit,
    onCreateTodoTask: (String, String, String, String, String, String, List<String>, String, String, String) -> Unit,
    isLoading: Boolean,
    onSaveClientPortalRecord: (ClientPortalRecordDraft, () -> Unit) -> Unit,
) {
    if (user?.isClientPortalUser == true) {
        ClientPortalHomeContent(
            summary = data.clientHome,
            portalRecords = data.clientPortalRecords,
            locations = data.locations,
            user = user,
            isLoading = isLoading,
            onSaveRecord = onSaveClientPortalRecord,
        )
    } else {
        HomeContent(
            user = user,
            workOrders = workOrders,
            reminders = reminders,
            todoTasks = todoTasks,
            reminderStatusOptions = data.reminderStatuses.ifEmpty { fallbackReminderStatusOptions },
            todoStatusOptions = data.todoTaskStatuses.ifEmpty { fallbackTodoTaskStatusOptions },
            priorityOptions = data.priorities,
            users = data.workOrderUsers,
            onOpenWorkOrder = onOpenWorkOrder,
            onOpenRecord = onOpenRecord,
            onCreateReminder = onCreateReminder,
            onUpdateReminderStatus = onUpdateReminderStatus,
            onCreateTodoTask = onCreateTodoTask,
        )
    }
}

@Composable
private fun ClientPortalHomeContent(
    summary: ClientHomeSummary,
    portalRecords: List<MobileRecord>,
    locations: List<MobileRecord>,
    user: SafeNexusUser,
    isLoading: Boolean,
    onSaveRecord: (ClientPortalRecordDraft, () -> Unit) -> Unit,
) {
    val title = summary.title.ifBlank { "Client Portal" }
    val subtitle = summary.subtitle.ifBlank { "Dokumenti i evidencije tvoje tvrtke" }
    var activeListType by remember { mutableStateOf<String?>(null) }
    var editorType by remember { mutableStateOf<String?>(null) }
    var editorRecord by remember { mutableStateOf<MobileRecord?>(null) }
    val activeDefinition = activeListType?.let(::clientPortalRecordDefinitionFor)
    val editorDefinition = editorType?.let(::clientPortalRecordDefinitionFor)
    val recordsByType = remember(portalRecords) { portalRecords.groupBy { it.clientPortalRecordType() } }

    Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(28.dp),
            color = Color(0xFFEAF2FF),
            tonalElevation = 1.dp,
            shadowElevation = 2.dp,
        ) {
            Column(
                modifier = Modifier.padding(18.dp),
                verticalArrangement = Arrangement.spacedBy(14.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Surface(shape = RoundedCornerShape(16.dp), color = Color.White.copy(alpha = 0.86f)) {
                        Icon(
                            Icons.Rounded.Business,
                            contentDescription = null,
                            modifier = Modifier
                                .size(46.dp)
                                .padding(11.dp),
                            tint = Color(0xFF2563EB),
                        )
                    }
                    Spacer(Modifier.width(12.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(title, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black)
                        Text(
                            subtitle,
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                FlowRow(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    StatusCountPill("Lokacije", summary.locationsTotal, Color(0xFF7C3AED))
                    StatusCountPill("Dokumenti", summary.documentsTotal, Color(0xFF1D4ED8))
                    StatusCountPill("Procjene", summary.riskAssessmentsTotal, Color(0xFFD97706))
                    StatusCountPill("Ospos.", summary.trainingsTotal, Color(0xFF059669))
                }
            }
        }

        ClientPortalRecordBlocksSection(
            records = portalRecords,
            onOpenType = { definition -> activeListType = definition.type },
            onOpenRecord = { record ->
                activeListType = record.clientPortalRecordType()
                editorType = record.clientPortalRecordType()
                editorRecord = record
            },
        )
    }

    if (activeDefinition != null && editorDefinition == null) {
        ClientPortalRecordListDialog(
            definition = activeDefinition,
            records = recordsByType[activeDefinition.type].orEmpty(),
            onDismiss = { activeListType = null },
            onAdd = {
                editorType = activeDefinition.type
                editorRecord = null
            },
            onEdit = { record ->
                editorType = activeDefinition.type
                editorRecord = record
            },
        )
    }

    if (editorDefinition != null) {
        ClientPortalRecordEditorDialog(
            definition = editorDefinition,
            record = editorRecord,
            locations = locations,
            user = user,
            isLoading = isLoading,
            onDismiss = {
                editorType = null
                editorRecord = null
            },
            onSave = { draft ->
                onSaveRecord(draft) {
                    editorType = null
                    editorRecord = null
                }
            },
        )
    }
}

