private fun clientPortalRecordEditableMeta(record: MobileRecord?): Map<String, String> {
    if (record == null) return emptyMap()
    val nonDetailKeys = setOf(
        "companyId",
        "companyName",
        "locationId",
        "locationName",
        "type",
        "attachmentCount",
        "attachmentNames",
    )
    return record.meta.filterKeys { key -> key !in nonDetailKeys }
}

private fun clientPortalRecordDisplayTitle(record: MobileRecord): String =
    record.title.ifBlank {
        record.metaValue(
            "fullName",
            "vehicleName",
            "plateNumber",
            "code",
            "defectTitle",
            "inspectionTitle",
            "documentName",
            "deadlineName",
            "ppeName",
        ).ifBlank { "Zapis" }
    }

private fun clientPortalRecordDisplaySubtitle(record: MobileRecord): String =
    listOf(
        record.metaValue("locationName", "locationText").ifBlank { record.subtitle },
        clientPortalRecordStatusLabel(record.status),
        clientPortalDateLabel(record.metaValue("dueDate").ifBlank { record.date }).takeIf { it != "-" }.orEmpty(),
    ).filter { it.isNotBlank() }.joinToString(" · ")

private fun clientPortalLocationOptions(locations: List<MobileRecord>, record: MobileRecord?): List<Pair<String, String>> {
    val currentLocationId = record?.metaValue("locationId").orEmpty()
    val currentLocationName = record?.metaValue("locationName").orEmpty()
    return buildList {
        add("" to "Sve lokacije / bez lokacije")
        if (currentLocationId.isNotBlank() && currentLocationName.isNotBlank()) {
            add(currentLocationId to currentLocationName)
        }
        locations.forEach { location ->
            add(location.id to location.title.ifBlank { location.subtitle }.ifBlank { "Lokacija" })
        }
    }.distinctBy { it.first }
}

private fun MobileRecord.clientPortalRecordType(): String =
    meta["type"].orEmpty().ifBlank { kind }.ifBlank { "deadline" }

private fun MobileRecord.isOpenClientPortalRecord(): Boolean =
    status.lowercase() !in setOf("done", "inactive", "gotovo", "neaktivno")

private fun MobileRecord.isAttentionClientPortalRecord(today: LocalDate = LocalDate.now()): Boolean {
    if (!isOpenClientPortalRecord()) return false
    val normalizedStatus = status.lowercase()
    if (normalizedStatus in setOf("attention", "paznja", "pažnja")) return true
    val dueDate = parsedDate ?: parseDateOrNull(meta["dueDate"].orEmpty()) ?: return false
    return dueDate.isBefore(today) || (!dueDate.isBefore(today.plusDays(-10)) && !dueDate.isAfter(today.plusDays(30)))
}

@Composable
private fun ClientPortalRecordBlocksSection(
    records: List<MobileRecord>,
    onOpenType: (ClientPortalRecordBlockDefinition) -> Unit,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val today = remember { LocalDate.now() }
    val recordsByType = remember(records) {
        records.groupBy { it.clientPortalRecordType() }
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Surface(shape = RoundedCornerShape(14.dp), color = Color(0xFFE0F2FE)) {
                    Icon(
                        Icons.Rounded.ListAlt,
                        contentDescription = null,
                        modifier = Modifier
                            .size(40.dp)
                            .padding(10.dp),
                        tint = Color(0xFF0369A1),
                    )
                }
                Spacer(Modifier.width(12.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text("Evidencije klijenta", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                    Text(
                        "Vatrogasni aparati, OZO, nadzori, rokovi i ostale evidencije",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            }

            clientPortalRecordBlockDefinitions.chunked(2).forEach { rowItems ->
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    rowItems.forEach { definition ->
                        val typedRecords = recordsByType[definition.type].orEmpty()
                        val attentionCount = typedRecords.count { it.isAttentionClientPortalRecord(today) }
                        ClientPortalRecordBlockCard(
                            definition = definition,
                            count = typedRecords.size,
                            attentionCount = attentionCount,
                            modifier = Modifier.weight(1f),
                            onClick = { onOpenType(definition) },
                        )
                    }
                    if (rowItems.size == 1) {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }

            ClientPortalFireExtinguisherSection(
                records = recordsByType["fire_extinguisher"].orEmpty(),
                onOpenRecord = onOpenRecord,
            )
            ClientPortalVehicleFleetSection(
                records = recordsByType["vehicle"].orEmpty(),
                onOpenRecord = onOpenRecord,
            )
        }
    }
}

@Composable
private fun ClientPortalRecordBlockCard(
    definition: ClientPortalRecordBlockDefinition,
    count: Int,
    attentionCount: Int,
    modifier: Modifier = Modifier,
    onClick: () -> Unit,
) {
    val detail = when {
        attentionCount > 0 -> "$attentionCount za pažnju"
        count > 0 -> "uredno"
        else -> "nema zapisa"
    }
    Surface(
        modifier = modifier
            .heightIn(min = 104.dp)
            .clip(RoundedCornerShape(18.dp))
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(18.dp),
        color = definition.accent.copy(alpha = if (count > 0) 0.12f else 0.06f),
        border = BorderStroke(1.dp, definition.accent.copy(alpha = if (attentionCount > 0) 0.36f else 0.14f)),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Surface(shape = RoundedCornerShape(12.dp), color = Color.White.copy(alpha = 0.78f)) {
                    Icon(
                        definition.icon,
                        contentDescription = null,
                        modifier = Modifier
                            .size(34.dp)
                            .padding(8.dp),
                        tint = definition.accent,
                    )
                }
                Text(
                    count.toString(),
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Black,
                    color = definition.accent,
                )
            }
            Text(
                definition.label,
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Black,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
            )
            Text(
                detail,
                style = MaterialTheme.typography.labelMedium,
                color = if (attentionCount > 0) Color(0xFFB45309) else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

private fun MobileRecord.metaValue(vararg keys: String): String {
    keys.forEach { key ->
        val value = meta[key].orEmpty()
        if (value.isNotBlank()) return value
    }
    return ""
}

private fun clientPortalDateLabel(value: String): String =
    formatDateLabel(value).ifBlank { value.ifBlank { "-" } }

