private data class MobileVehicleReservation(
    val id: String,
    val status: String,
    val purpose: String,
    val startAt: String,
    val endAt: String,
    val destination: String,
    val userLabel: String,
    val userIds: List<String> = emptyList(),
)

private data class MobileVehicleTrip(
    val id: String,
    val departureAt: String,
    val returnAt: String,
    val destination: String,
    val drivers: String,
    val driverUserIds: List<String>,
    val startKm: String,
    val endKm: String,
    val condition: String,
    val status: String,
    val reservationId: String,
    val linkedWorkOrderId: String,
    val linkedWorkOrderNumber: String,
    val documentCount: Int,
    val documentLabels: String,
)

private fun vehicleBaseStatus(vehicle: MobileRecord): String =
    vehicle.meta["baseStatus"].orEmpty().ifBlank { vehicle.status.ifBlank { "available" } }.lowercase()

private fun vehicleAvailabilityStatus(vehicle: MobileRecord): String {
    val baseStatus = vehicleBaseStatus(vehicle)
    if (baseStatus == "service" || baseStatus == "inactive") return baseStatus
    val activeReservation = parseVehicleReservations(vehicle).firstOrNull { vehicleReservationIsActiveNow(it) }
    if (activeReservation != null) {
        return if (activeReservation.status.equals("checked_out", ignoreCase = true)) "checked_out" else "reserved"
    }
    return "available"
}

private fun vehicleStatusLabel(status: String): String = when (status.lowercase()) {
    "reserved" -> "Zauzeto"
    "checked_out" -> "Na terenu"
    "service", "inactive" -> "Servis"
    else -> "Dostupno"
}

private fun vehicleStatusColor(status: String): Color = when (status.lowercase()) {
    "reserved", "checked_out" -> Color(0xFFB45309)
    "service", "inactive" -> Color(0xFF64748B)
    else -> Color(0xFF059669)
}

private fun parseVehicleReservations(vehicle: MobileRecord): List<MobileVehicleReservation> {
    val raw = vehicle.meta["reservationsJson"].orEmpty()
    if (raw.isBlank()) return emptyList()
    return runCatching {
        val array = JSONArray(raw)
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val labels = item.optJSONArray("reservedForLabels")
                val label = if (labels != null && labels.length() > 0) {
                    (0 until labels.length()).mapNotNull { labels.optString(it).trim().takeIf(String::isNotBlank) }.joinToString(", ")
                } else {
                    item.optString("reservedForLabel").trim()
                }
                val userIdsArray = item.optJSONArray("reservedForUserIds")
                val userIds = if (userIdsArray != null && userIdsArray.length() > 0) {
                    (0 until userIdsArray.length()).mapNotNull { userIdsArray.optString(it).trim().takeIf(String::isNotBlank) }
                } else {
                    listOf(item.optString("reservedForUserId").trim()).filter(String::isNotBlank)
                }
                add(
                    MobileVehicleReservation(
                        id = item.optString("id").trim(),
                        status = item.optString("status", "reserved").trim(),
                        purpose = item.optString("purpose", "Rezervacija").trim(),
                        startAt = item.optString("startAt").trim(),
                        endAt = item.optString("endAt").trim(),
                        destination = item.optString("destination").trim(),
                        userLabel = label,
                        userIds = userIds,
                    ),
                )
            }
        }
    }.getOrDefault(emptyList())
}

private fun extractVehicleTripNoteValue(note: String, label: String): String {
    val normalizedLabel = label.trim()
    if (note.isBlank() || normalizedLabel.isBlank()) return ""
    return note
        .lineSequence()
        .map { it.trim() }
        .firstOrNull { line -> line.startsWith(normalizedLabel, ignoreCase = true) }
        ?.substringAfter(":", "")
        ?.trim()
        .orEmpty()
}

private fun getVehicleTripDestination(item: JSONObject): String =
    item.optString("destination").trim()
        .ifBlank { item.optString("route").trim() }
        .ifBlank { item.optString("location").trim() }
        .ifBlank { extractVehicleTripNoteValue(item.optString("note").trim(), "Destinacija:") }
        .ifBlank { extractVehicleTripNoteValue(item.optString("note").trim(), "Lokacija:") }

private fun parseVehicleStringArray(item: JSONObject, key: String): List<String> {
    val array = item.optJSONArray(key) ?: return emptyList()
    return (0 until array.length())
        .mapNotNull { index -> array.optString(index).trim().takeIf(String::isNotBlank) }
        .distinctBy { it.lowercase(Locale.getDefault()) }
}

private fun getVehicleTripWorkOrderLabel(item: JSONObject): String {
    val numbers = (
        parseVehicleStringArray(item, "linkedWorkOrderNumbers") +
            listOf(
                item.optString("linkedWorkOrderNumber", item.optString("workOrderNumber")).trim(),
            )
        )
        .filter { it.isNotBlank() }
    if (numbers.isNotEmpty()) {
        return numbers.distinctBy { it.lowercase(Locale.getDefault()) }.joinToString(", ")
    }
    return (
        parseVehicleStringArray(item, "linkedWorkOrderIds") +
            listOf(item.optString("linkedWorkOrderId", item.optString("workOrderId")).trim())
        )
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }
        .joinToString(", ") { id -> "RN $id" }
}

private fun parseVehicleTrips(vehicle: MobileRecord): List<MobileVehicleTrip> {
    val raw = vehicle.meta["activityItemsJson"].orEmpty()
    if (raw.isBlank()) return emptyList()
    return runCatching {
        val array = JSONArray(raw)
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val activityType = item.optString("activityType").trim().lowercase(Locale.getDefault())
                if (activityType != "vehicle_trip") continue

                val driverLabels = item.optJSONArray("driverLabels")
                val drivers = if (driverLabels != null && driverLabels.length() > 0) {
                    (0 until driverLabels.length())
                        .mapNotNull { driverLabels.optString(it).trim().takeIf(String::isNotBlank) }
                        .joinToString(", ")
                } else {
                    item.optString("performedBy").trim()
                }
                val condition = listOf(
                    item.optString("returnCondition").trim(),
                    item.optString("vehicleCondition").trim(),
                    item.optString("departureCondition").trim(),
                    item.optString("note").trim(),
                ).firstOrNull { it.isNotBlank() }.orEmpty()
                val documents = item.optJSONArray("documents") ?: item.optJSONArray("attachments")
                val documentLabels = if (documents != null && documents.length() > 0) {
                    (0 until documents.length())
                        .mapNotNull { documentIndex ->
                            val documentItem = documents.optJSONObject(documentIndex) ?: return@mapNotNull null
                            val category = documentItem.optString("documentCategory", documentItem.optString("category")).trim()
                            val fileName = documentItem.optString("fileName", documentItem.optString("name")).trim()
                            listOf(category, fileName)
                                .filter { it.isNotBlank() }
                                .joinToString(": ")
                                .takeIf { it.isNotBlank() }
                        }
                        .joinToString(", ")
                } else {
                    ""
                }
                add(
                    MobileVehicleTrip(
                        id = item.optString("id").trim(),
                        departureAt = item.optString("departureAt").trim()
                            .ifBlank { item.optString("createdAt").trim() }
                            .ifBlank { item.optString("performedOn").trim() },
                        returnAt = item.optString("returnAt").trim()
                            .ifBlank { item.optString("completedAt").trim() },
                        destination = getVehicleTripDestination(item),
                        drivers = drivers,
                        driverUserIds = parseVehicleStringArray(item, "driverUserIds"),
                        startKm = item.optString("startKm").trim(),
                        endKm = item.optString("endKm").trim(),
                        condition = condition,
                        status = item.optString("tripStatus").trim(),
                        reservationId = item.optString("reservationId").trim(),
                        linkedWorkOrderId = parseVehicleStringArray(item, "linkedWorkOrderIds").firstOrNull()
                            ?: item.optString("linkedWorkOrderId", item.optString("workOrderId")).trim(),
                        linkedWorkOrderNumber = getVehicleTripWorkOrderLabel(item),
                        documentCount = documents?.length() ?: 0,
                        documentLabels = documentLabels,
                    ),
                )
            }
        }.sortedByDescending { trip -> trip.departureAt.ifBlank { trip.id } }
    }.getOrDefault(emptyList())
}

private fun parseVehicleDateTime(value: String): LocalDateTime? {
    val normalized = value.trim()
    if (normalized.isBlank()) return null
    return runCatching { LocalDateTime.parse(normalized.take(19)) }.getOrNull()
        ?: runCatching { Instant.parse(normalized).atZone(ZoneId.systemDefault()).toLocalDateTime() }.getOrNull()
}

private fun formatVehicleTripDatePart(value: String): String {
    val parsed = parseVehicleDateTime(value)
    if (parsed != null) return parsed.format(DateTimeFormatter.ofPattern("dd.MM.yyyy."))
    return formatDateLabel(value).ifBlank { value.take(10) }
}

private fun formatVehicleTripTimePart(value: String): String {
    val parsed = parseVehicleDateTime(value) ?: return value.substringAfter('T', "").take(5)
    return parsed.format(DateTimeFormatter.ofPattern("HH:mm"))
}

private fun vehiclePersonMatchesCurrentUser(value: String, currentUserLabel: String): Boolean {
    val person = value.trim().lowercase(Locale.getDefault())
    val current = currentUserLabel.trim().lowercase(Locale.getDefault())
    if (person.isBlank() || current.isBlank()) return false
    return person == current || person.contains(current) || current.contains(person)
}

private fun vehicleUserOptionLabel(user: WorkOrderUserOption): String =
    user.label.ifBlank { user.fullName.ifBlank { user.email } }

private fun vehicleCurrentUserOption(users: List<WorkOrderUserOption>, currentUserLabel: String): WorkOrderUserOption? {
    val current = currentUserLabel.trim().lowercase(Locale.getDefault())
    if (current.isBlank()) return null
    return users.firstOrNull { user ->
        listOf(user.id, user.label, user.fullName, user.email)
            .map { it.trim().lowercase(Locale.getDefault()) }
            .filter { it.isNotBlank() }
            .any { value -> value == current || value.contains(current) || current.contains(value) }
    }
}

private fun vehicleReservationBelongsToCurrentUser(
    reservation: MobileVehicleReservation,
    currentUserLabel: String,
    currentUserId: String,
): Boolean {
    if (currentUserId.isNotBlank() && reservation.userIds.any { it == currentUserId }) return true
    return vehiclePersonMatchesCurrentUser(reservation.userLabel, currentUserLabel)
}

private fun vehicleReservationBelongsToCurrentUser(reservation: MobileVehicleReservation, currentUserLabel: String): Boolean =
    vehiclePersonMatchesCurrentUser(reservation.userLabel, currentUserLabel)

private fun vehicleTripBelongsToCurrentUser(
    trip: MobileVehicleTrip,
    currentUserLabel: String,
    currentUserId: String,
): Boolean {
    if (currentUserId.isNotBlank() && trip.driverUserIds.any { it == currentUserId }) return true
    return vehiclePersonMatchesCurrentUser(trip.drivers, currentUserLabel)
}

private fun vehicleUserLabelsForIds(users: List<WorkOrderUserOption>, selectedIds: List<String>): List<String> {
    val labelsById = users.associate { user -> user.id to vehicleUserOptionLabel(user) }
    return selectedIds
        .mapNotNull { id -> labelsById[id]?.trim()?.takeIf(String::isNotBlank) }
        .distinctBy { it.lowercase(Locale.getDefault()) }
}

private fun vehicleReservationIsActiveNow(reservation: MobileVehicleReservation, now: LocalDateTime = LocalDateTime.now()): Boolean {
    val start = parseVehicleDateTime(reservation.startAt) ?: return false
    val end = parseVehicleDateTime(reservation.endAt) ?: return false
    val status = reservation.status.trim().lowercase(Locale.getDefault())
    if (status != "reserved" && status != "checked_out") return false
    return !now.isBefore(start) && !now.isAfter(end)
}

private fun vehicleReservationAllowsMyTripNow(reservation: MobileVehicleReservation, now: LocalDateTime = LocalDateTime.now()): Boolean {
    val start = parseVehicleDateTime(reservation.startAt) ?: return false
    val end = parseVehicleDateTime(reservation.endAt) ?: return false
    val status = reservation.status.trim().lowercase(Locale.getDefault())
    if (status != "reserved" && status != "checked_out") return false
    return !now.isBefore(start.minusHours(1)) && !now.isAfter(end.plusHours(1))
}

private fun vehicleTripIsOpen(trip: MobileVehicleTrip): Boolean =
    trip.returnAt.isBlank() && !trip.status.equals("completed", ignoreCase = true)

private fun vehicleOpenTripForCurrentUser(vehicle: MobileRecord, currentUserLabel: String): MobileVehicleTrip? =
    parseVehicleTrips(vehicle).firstOrNull { trip ->
        vehicleTripIsOpen(trip) && vehiclePersonMatchesCurrentUser(trip.drivers, currentUserLabel)
    }

private fun vehicleHasOpenTripForOtherUser(vehicle: MobileRecord, currentUserLabel: String): Boolean =
    parseVehicleTrips(vehicle).any { trip ->
        vehicleTripIsOpen(trip) && !vehiclePersonMatchesCurrentUser(trip.drivers, currentUserLabel)
    }

private fun vehicleEligibleReservationForCurrentUser(vehicle: MobileRecord, currentUserLabel: String): MobileVehicleReservation? =
    parseVehicleReservations(vehicle).firstOrNull { reservation ->
        vehicleReservationBelongsToCurrentUser(reservation, currentUserLabel) &&
            vehicleReservationAllowsMyTripNow(reservation)
    }

private fun vehicleCanUseMyTrip(vehicle: MobileRecord, currentUserLabel: String): Boolean {
    val baseStatus = vehicleBaseStatus(vehicle)
    if (currentUserLabel.isBlank() || baseStatus == "service" || baseStatus == "inactive") return false
    if (vehicleOpenTripForCurrentUser(vehicle, currentUserLabel) != null) return true
    if (vehicleHasOpenTripForOtherUser(vehicle, currentUserLabel)) return false
    return vehicleEligibleReservationForCurrentUser(vehicle, currentUserLabel) != null
}

private fun vehicleUserTripLabel(vehicle: MobileRecord, currentUserLabel: String): String {
    if (currentUserLabel.isBlank()) return ""
    if (vehicleOpenTripForCurrentUser(vehicle, currentUserLabel) != null) return "Moj put"
    return if (vehicleEligibleReservationForCurrentUser(vehicle, currentUserLabel) != null) "Moja rezervacija" else ""
}

private fun vehicleReservationOverlapsHour(reservation: MobileVehicleReservation, date: LocalDate, hour: Int): Boolean {
    val start = parseVehicleDateTime(reservation.startAt) ?: return false
    val end = parseVehicleDateTime(reservation.endAt) ?: return false
    val slotStart = date.atTime(hour, 0)
    val slotEnd = slotStart.plusHours(1)
    return start < slotEnd && end > slotStart
}

@Composable
private fun VehicleFleetContent(
    vehicles: List<MobileRecord>,
    currentUserLabel: String,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val today = remember { LocalDate.now() }
    val available = vehicles.count { vehicleAvailabilityStatus(it) == "available" }
    val reserved = vehicles.count { vehicleAvailabilityStatus(it) in setOf("reserved", "checked_out") }
    val service = vehicles.count { vehicleAvailabilityStatus(it) == "service" }
    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
        ) {
            Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Surface(shape = RoundedCornerShape(14.dp), color = MaterialTheme.colorScheme.primaryContainer) {
                        Icon(
                            Icons.Rounded.Business,
                            contentDescription = null,
                            modifier = Modifier.size(40.dp).padding(10.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                    }
                    Spacer(Modifier.width(12.dp))
                    Column(Modifier.weight(1f)) {
                        Text("Status vozila", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                        Text(
                            "${vehicles.size} vozila u floti",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                }
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                    VehicleStatusMetric("Dostupno", available, Color(0xFF059669), Modifier.weight(1f))
                    VehicleStatusMetric("Zauzeto", reserved, Color(0xFFB45309), Modifier.weight(1f))
                    VehicleStatusMetric("Servis", service, Color(0xFF64748B), Modifier.weight(1f))
                }
            }
        }

        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
        ) {
            Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text("Raspored danas", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                if (vehicles.isEmpty()) {
                    Text("Nema vozila za prikaz.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f))
                } else {
                    VehicleScheduleGrid(vehicles = vehicles, date = today, onOpenRecord = onOpenRecord)
                }
            }
        }

        Card(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(24.dp),
            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
        ) {
            Column(Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text("Vozila", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
                if (vehicles.isEmpty()) {
                    Text("Nema vozila za prikaz.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f))
                } else {
                    vehicles.take(80).forEach { vehicle ->
                        VehicleFleetRow(
                            vehicle = vehicle,
                            currentUserLabel = currentUserLabel,
                            onClick = { onOpenRecord(vehicle) },
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun VehicleStatusMetric(label: String, count: Int, color: Color, modifier: Modifier = Modifier) {
    Surface(
        modifier = modifier.height(70.dp),
        shape = RoundedCornerShape(18.dp),
        color = color.copy(alpha = 0.12f),
    ) {
        Column(Modifier.padding(10.dp), verticalArrangement = Arrangement.Center) {
            Text(count.toString(), color = color, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
            Text(label, style = MaterialTheme.typography.labelMedium, color = Color(0xFF334155), maxLines = 1)
        }
    }
}

@Composable
private fun VehicleScheduleGrid(
    vehicles: List<MobileRecord>,
    date: LocalDate,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val hours = remember { (7..18).toList() }
    Column(
        modifier = Modifier.horizontalScroll(rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
            Spacer(Modifier.width(96.dp))
            hours.forEach { hour ->
                Text(
                    "${hour.toString().padStart(2, '0')}:00",
                    modifier = Modifier.width(42.dp),
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    textAlign = TextAlign.Center,
                )
            }
        }
        vehicles.take(12).forEach { vehicle ->
            val reservations = parseVehicleReservations(vehicle)
            Row(
                modifier = Modifier
                    .height(44.dp)
                    .clickable { onOpenRecord(vehicle) },
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Column(Modifier.width(96.dp)) {
                    Text(vehicle.title, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                    Text(vehicleStatusLabel(vehicleAvailabilityStatus(vehicle)), style = MaterialTheme.typography.labelSmall, color = vehicleStatusColor(vehicleAvailabilityStatus(vehicle)))
                }
                hours.forEach { hour ->
                    val busy = reservations.any { vehicleReservationOverlapsHour(it, date, hour) }
                    Surface(
                        modifier = Modifier.size(width = 42.dp, height = 30.dp),
                        shape = RoundedCornerShape(8.dp),
                        color = if (busy) Color(0xFFF59E0B).copy(alpha = 0.28f) else Color(0xFFE2E8F0).copy(alpha = 0.68f),
                        border = if (busy) androidx.compose.foundation.BorderStroke(1.dp, Color(0xFFF59E0B)) else null,
                    ) {}
                }
            }
        }
    }
}

@Composable
private fun VehicleFleetRow(vehicle: MobileRecord, currentUserLabel: String, onClick: () -> Unit) {
    val status = vehicleAvailabilityStatus(vehicle)
    val statusColor = vehicleStatusColor(status)
    val userTripLabel = vehicleUserTripLabel(vehicle, currentUserLabel)
    val nextPurpose = vehicle.meta["nextReservationPurpose"].orEmpty()
    val nextStart = vehicle.meta["nextReservationStartAt"].orEmpty()
    val nextUser = vehicle.meta["nextReservationUser"].orEmpty()
    val nextText = listOf(
        nextPurpose,
        if (nextStart.isNotBlank()) formatDateTimeLabel(nextStart) else "",
        nextUser,
    ).filter { it.isNotBlank() }.joinToString(" - ")
    Surface(
        modifier = Modifier.fillMaxWidth().clickable(onClick = onClick),
        shape = RoundedCornerShape(18.dp),
        color = statusColor.copy(alpha = 0.08f),
    ) {
        Row(
            modifier = Modifier.padding(12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Surface(shape = RoundedCornerShape(14.dp), color = statusColor.copy(alpha = 0.14f)) {
                Icon(Icons.Rounded.Business, contentDescription = null, modifier = Modifier.size(38.dp).padding(9.dp), tint = statusColor)
            }
            Column(Modifier.weight(1f)) {
                Text(vehicle.title, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                Text(
                    listOf(vehicle.subtitle, "${vehicle.meta["odometerKm"].orEmpty()} km".takeIf { vehicle.meta["odometerKm"].orEmpty().isNotBlank() }).filterNotNull().joinToString(" - "),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                if (nextText.isNotBlank()) {
                    Text(nextText, style = MaterialTheme.typography.labelSmall, color = statusColor, maxLines = 1, overflow = TextOverflow.Ellipsis)
                }
            }
            Column(horizontalAlignment = Alignment.End, verticalArrangement = Arrangement.spacedBy(6.dp)) {
                if (userTripLabel.isNotBlank()) {
                    AssistChip(
                        onClick = onClick,
                        label = { Text(userTripLabel, fontWeight = FontWeight.Black) },
                        leadingIcon = {
                            Icon(Icons.Rounded.Person, contentDescription = null, modifier = Modifier.size(16.dp))
                        },
                    )
                }
                AssistChip(onClick = {}, label = { Text(vehicleStatusLabel(status)) })
            }
        }
    }
}

private fun formatDateTimeLabel(value: String): String {
    val parsed = parseVehicleDateTime(value) ?: return formatDateLabel(value).ifBlank { value.take(16) }
    return parsed.format(DateTimeFormatter.ofPattern("dd.MM. HH:mm"))
}

