private data class CompanyDirectoryBundle(
    val company: MobileRecord,
    val locations: List<MobileRecord>,
    val totalLocationCount: Int,
)

private fun companyDirectoryKey(company: MobileRecord): String =
    company.id.ifBlank { normalizeMobileDocumentFolderKey(company.title) }.ifBlank { "company" }

private fun locationBelongsToCompany(location: MobileRecord, company: MobileRecord): Boolean {
    val companyId = company.id.trim()
    val locationCompanyId = location.relatedId.ifBlank { location.meta["companyId"].orEmpty() }.trim()
    if (companyId.isNotBlank() && locationCompanyId.isNotBlank() && companyId == locationCompanyId) {
        return true
    }
    val companyName = company.title.trim()
    val locationCompanyName = location.meta["companyName"].orEmpty()
        .ifBlank { location.subtitle.substringBefore(" - ").trim() }
    return companyName.isNotBlank() && locationCompanyName.equals(companyName, ignoreCase = true)
}

private fun companyDirectorySummary(company: MobileRecord): String =
    listOf(
        company.meta["headquarters"].orEmpty().ifBlank { company.subtitle },
        company.meta["oib"].orEmpty().takeIf { it.isNotBlank() }?.let { "OIB $it" }.orEmpty(),
        company.meta["contactPhone"].orEmpty(),
        company.meta["contactEmail"].orEmpty(),
    ).filter { it.isNotBlank() && !isRawMobileMetaValue(it) }.distinct().joinToString(" - ").ifBlank { "Bez dodatnih podataka" }

private fun companyDirectoryLocationSummary(location: MobileRecord): String =
    listOf(
        location.meta["region"].orEmpty(),
        location.meta["contactName1"].orEmpty(),
        location.meta["contactPhone1"].orEmpty(),
        location.meta["contactEmail1"].orEmpty(),
    ).filter { it.isNotBlank() && !isRawMobileMetaValue(it) }.distinct().joinToString(" - ").ifBlank {
        location.subtitle.takeIf { !isRawMobileMetaValue(it) }.orEmpty().ifBlank { "Otvori detalje lokacije" }
    }

private data class PeriodicEntry(
    val title: String,
    val subtitle: String,
    val status: String,
    val date: String,
    val kind: String,
    val icon: ImageVector,
    val record: MobileRecord,
) {
    val parsedDate: LocalDate? = parseDateOrNull(date)
}

private fun buildPeriodicEntries(
    data: BootstrapData,
    workOrders: List<WorkOrder>,
    query: String,
): List<PeriodicEntry> {
    val entries = mutableListOf<PeriodicEntry>()
    fun addRecord(record: MobileRecord, fallbackKind: String, icon: ImageVector) {
        if (record.date.isBlank()) return
        if (query.isNotBlank() && !record.matchesSearch(query)) return
        val normalizedKind = record.kind.ifBlank { fallbackKind }
        entries += PeriodicEntry(
            title = record.title,
            subtitle = record.subtitle.ifBlank { recordKindLabel(normalizedKind) },
            status = record.status,
            date = record.date,
            kind = normalizedKind,
            icon = icon,
            record = record.copy(kind = normalizedKind),
        )
    }

    data.documentRecords.forEach { addRecord(it, "document", Icons.Rounded.Description) }
    data.clientPortalRecords.forEach { addRecord(it, "client_portal", Icons.Rounded.Map) }
    data.peopleTrainingRecords.forEach { addRecord(it, "training", Icons.Rounded.Fingerprint) }
    data.rulebooks.forEach { addRecord(it, "rulebook", Icons.Rounded.Lock) }
    data.legalFrameworks.forEach { addRecord(it, "legal_framework", Icons.Rounded.Description) }
    data.vehicles.forEach { addRecord(it, "vehicle", Icons.Rounded.Business) }
    fun addWorkOrderDate(workOrder: WorkOrder, date: String, kind: String, label: String) {
        if (date.isBlank()) return
        val subtitle = listOf(workOrder.companyName, workOrder.locationName, workOrder.displayService)
            .filter { it.isNotBlank() }
            .joinToString(" - ")
        entries += PeriodicEntry(
            title = workOrder.displayNumber,
            subtitle = subtitle,
            status = workOrder.status,
            date = date,
            kind = kind,
            icon = Icons.Rounded.Work,
            record = MobileRecord(
                id = "${kind.replace('_', '-')}:${workOrder.id}",
                title = workOrder.displayNumber,
                subtitle = subtitle,
                status = workOrder.status,
                kind = kind,
                date = date,
                relatedId = workOrder.id,
                coordinates = workOrder.coordinates,
                meta = mapOf(
                    "companyName" to workOrder.companyName,
                    "locationName" to workOrder.locationName,
                    "service" to workOrder.displayService,
                    "calendarLabel" to label,
                ),
            ),
        )
    }
    workOrders.forEach { workOrder ->
        val searchText = listOf(
            workOrder.displayNumber,
            workOrder.companyName,
            workOrder.locationName,
            workOrder.status,
            workOrder.displayService,
        ).joinToString(" ")
        if (query.isNotBlank() && !searchText.contains(query, ignoreCase = true)) return@forEach
        addWorkOrderDate(workOrder, workOrder.dueDate, "work_order_due", "Rok")
        addWorkOrderDate(workOrder, workOrder.executionDate, "work_order_execution", "Izvršenje")
    }

    return entries
        .distinctBy { "${it.kind}:${it.title}:${it.date}:${it.subtitle}" }
        .sortedWith(compareBy<PeriodicEntry> { it.parsedDate ?: LocalDate.MAX }.thenBy { it.title.lowercase(Locale.getDefault()) })
}

@Composable
private fun PeriodicsPreview(entries: List<PeriodicEntry>) {
    val today = remember { LocalDate.now() }
    val overdue = remember(entries, today) { entries.count { entry -> entry.parsedDate?.isBefore(today) == true } }
    val next30 = remember(entries, today) {
        entries.count { entry ->
            val date = entry.parsedDate ?: return@count false
            !date.isBefore(today) && !date.isAfter(today.plusDays(30))
        }
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(13.dp),
        ) {
            SectionHeader(
                title = "Periodika",
                subtitle = "Rokovi po dokumentima, RN-ovima, vozilima i osposobljavanjima",
                icon = Icons.Rounded.CalendarMonth,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                PeriodicStatTile("Ukupno", entries.size, Color(0xFF2563EB), Modifier.weight(1f))
                PeriodicStatTile("Kasni", overdue, Color(0xFFDC2626), Modifier.weight(1f))
                PeriodicStatTile("30 dana", next30, Color(0xFFB45309), Modifier.weight(1f))
            }
            if (entries.isEmpty()) {
                Text("Nema periodičkih rokova za prikaz.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f))
            } else {
                entries.take(8).forEach { entry -> PeriodicLine(entry, today) }
            }
        }
    }
}

private data class PeriodicCategoryOption(
    val id: String,
    val label: String,
    val count: Int,
    val icon: ImageVector,
    val accent: Color,
)

private fun periodicCategoryId(kind: String): String = when (kind) {
    "work_order", "work_order_due", "work_order_execution", "todo_task" -> "work_orders"
    "training", "people_training" -> "people"
    "vehicle", "periodic_vehicle" -> "vehicles"
    "measurement_equipment", "periodic_equipment" -> "equipment"
    "document", "periodic_document" -> "documents"
    "rulebook", "periodic_rulebook", "risk_assessment", "periodic_risk_assessment", "client_portal" -> "foundation"
    "legal_framework", "periodic_legal_framework" -> "legal"
    else -> "other"
}

private fun periodicCategoryLabel(id: String): String = when (id) {
    "all" -> "Sve"
    "work_orders" -> "RN"
    "people" -> "Osposobljavanja"
    "vehicles" -> "Vozila"
    "equipment" -> "Oprema"
    "documents" -> "Dokumenti"
    "foundation" -> "Temeljna"
    "legal" -> "Zakonska"
    else -> "Ostalo"
}

private fun periodicCategoryIcon(id: String): ImageVector = when (id) {
    "work_orders" -> Icons.Rounded.Work
    "people" -> Icons.Rounded.Fingerprint
    "vehicles" -> Icons.Rounded.Business
    "equipment" -> Icons.Rounded.Work
    "documents" -> Icons.Rounded.Description
    "foundation" -> Icons.Rounded.Lock
    "legal" -> Icons.Rounded.Description
    else -> Icons.Rounded.CalendarMonth
}

private fun periodicCategoryAccent(id: String): Color = when (id) {
    "work_orders" -> Color(0xFF2563EB)
    "people" -> Color(0xFF7C3AED)
    "vehicles" -> Color(0xFF0891B2)
    "equipment" -> Color(0xFF0F766E)
    "documents" -> Color(0xFF4F46E5)
    "foundation" -> Color(0xFFB45309)
    "legal" -> Color(0xFF334155)
    else -> Color(0xFF64748B)
}

private fun buildPeriodicCategoryOptions(entries: List<PeriodicEntry>): List<PeriodicCategoryOption> {
    val groupedCounts = entries.groupingBy { periodicCategoryId(it.kind) }.eachCount()
    val order = listOf("work_orders", "people", "documents", "foundation", "legal", "equipment", "vehicles", "other")
    return buildList {
        add(
            PeriodicCategoryOption(
                id = "all",
                label = periodicCategoryLabel("all"),
                count = entries.size,
                icon = Icons.Rounded.CalendarMonth,
                accent = Color(0xFF2563EB),
            ),
        )
        order.forEach { id ->
            val count = groupedCounts[id] ?: return@forEach
            add(
                PeriodicCategoryOption(
                    id = id,
                    label = periodicCategoryLabel(id),
                    count = count,
                    icon = periodicCategoryIcon(id),
                    accent = periodicCategoryAccent(id),
                ),
            )
        }
    }
}

@Composable
private fun PeriodicsContent(
    entries: List<PeriodicEntry>,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val today = remember { LocalDate.now() }
    var viewMode by remember { mutableStateOf(PeriodicsViewMode.List) }
    var selectedCategory by remember { mutableStateOf("all") }
    val overdue = remember(entries, today) { entries.count { entry -> entry.parsedDate?.isBefore(today) == true } }
    val next30 = remember(entries, today) {
        entries.count { entry ->
            val date = entry.parsedDate ?: return@count false
            !date.isBefore(today) && !date.isAfter(today.plusDays(30))
        }
    }
    val categories = remember(entries) { buildPeriodicCategoryOptions(entries) }
    LaunchedEffect(categories) {
        if (categories.none { it.id == selectedCategory }) selectedCategory = "all"
    }
    val visibleEntries = remember(entries, selectedCategory) {
        if (selectedCategory == "all") {
            entries
        } else {
            entries.filter { periodicCategoryId(it.kind) == selectedCategory }
        }
    }
    var visibleListLimit by remember(entries, selectedCategory) { mutableStateOf(PERIODICS_INITIAL_VISIBLE_COUNT) }
    val displayedEntries = remember(visibleEntries, visibleListLimit) {
        visibleEntries.take(visibleListLimit)
    }
    val calendarRecords = remember(visibleEntries, viewMode) {
        if (viewMode == PeriodicsViewMode.Calendar) visibleEntries.map { it.record } else emptyList()
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            SectionHeader(
                title = "Periodika",
                subtitle = "Lista i kalendar rokova iz RN-ova, dokumenata, opreme, vozila i osposobljavanja",
                icon = Icons.Rounded.CalendarMonth,
            )
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                PeriodicStatTile("Ukupno", entries.size, Color(0xFF2563EB), Modifier.weight(1f))
                PeriodicStatTile("Kasni", overdue, Color(0xFFDC2626), Modifier.weight(1f))
                PeriodicStatTile("30 dana", next30, Color(0xFFB45309), Modifier.weight(1f))
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                PeriodicsViewMode.entries.forEach { mode ->
                    FilterChip(
                        selected = viewMode == mode,
                        onClick = { viewMode = mode },
                        label = { Text(mode.label, fontWeight = FontWeight.Bold) },
                        leadingIcon = {
                            Icon(
                                if (mode == PeriodicsViewMode.Calendar) Icons.Rounded.CalendarMonth else Icons.Rounded.ListAlt,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp),
                            )
                        },
                    )
                }
            }
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                categories.forEach { category ->
                    val selected = selectedCategory == category.id
                    FilterChip(
                        selected = selected,
                        onClick = { selectedCategory = category.id },
                        label = { Text("${category.label} ${category.count}", fontWeight = FontWeight.Bold) },
                        leadingIcon = {
                            Icon(
                                category.icon,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp),
                                tint = if (selected) category.accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                            )
                        },
                    )
                }
            }
            if (entries.isEmpty()) {
                Text("Nema periodičkih rokova za prikaz.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f))
            } else if (viewMode == PeriodicsViewMode.Calendar) {
                CalendarContent(records = calendarRecords, onOpenRecord = onOpenRecord)
            } else {
                PeriodicsListView(
                    entries = displayedEntries,
                    totalCount = visibleEntries.size,
                    today = today,
                    onOpenRecord = onOpenRecord,
                    onShowMore = {
                        visibleListLimit = (visibleListLimit + PERIODICS_VISIBLE_INCREMENT).coerceAtMost(visibleEntries.size)
                    },
                )
            }
        }
    }
}

@Composable
private fun PeriodicsListView(
    entries: List<PeriodicEntry>,
    totalCount: Int,
    today: LocalDate,
    onOpenRecord: (MobileRecord) -> Unit,
    onShowMore: () -> Unit,
) {
    val groups = remember(entries, today) {
        listOf(
            "Kasni" to entries.filter { it.parsedDate?.isBefore(today) == true },
            "Sljedećih 30 dana" to entries.filter { entry ->
                val date = entry.parsedDate ?: return@filter false
                !date.isBefore(today) && !date.isAfter(today.plusDays(30))
            },
            "Kasnije" to entries.filter { entry ->
                val date = entry.parsedDate ?: return@filter false
                date.isAfter(today.plusDays(30))
            },
            "Bez datuma" to entries.filter { it.parsedDate == null },
        ).filter { it.second.isNotEmpty() }
    }
    if (totalCount == 0) {
        Text("Nema rokova za odabrani filter.", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f))
        return
    }
    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
        Text(
            "Prikazano ${entries.size} od $totalCount rokova. Najstariji datumi su prvi.",
            style = MaterialTheme.typography.labelMedium,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
        )
        groups.forEach { (label, groupEntries) ->
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(label, style = MaterialTheme.typography.titleSmall, fontWeight = FontWeight.Black)
                Surface(shape = RoundedCornerShape(999.dp), color = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)) {
                    Text(
                        groupEntries.size.toString(),
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp),
                        style = MaterialTheme.typography.labelSmall,
                        fontWeight = FontWeight.Black,
                        color = MaterialTheme.colorScheme.primary,
                    )
                }
            }
            groupEntries.forEach { entry ->
                PeriodicLine(entry = entry, today = today, onClick = { onOpenRecord(entry.record) })
            }
        }
        if (entries.size < totalCount) {
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                onClick = onShowMore,
                shape = RoundedCornerShape(16.dp),
            ) {
                Text(
                    "Prikaži još ${minOf(PERIODICS_VISIBLE_INCREMENT, totalCount - entries.size)}",
                    fontWeight = FontWeight.Black,
                )
            }
        }
    }
}

@Composable
private fun PeriodicStatTile(
    label: String,
    count: Int,
    accent: Color,
    modifier: Modifier,
) {
    Surface(modifier = modifier, shape = RoundedCornerShape(16.dp), color = accent.copy(alpha = 0.1f)) {
        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(count.toString(), color = accent, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black)
            Text(label, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f))
        }
    }
}

@Composable
private fun PeriodicLine(
    entry: PeriodicEntry,
    today: LocalDate,
    onClick: (() -> Unit)? = null,
) {
    val parsedDate = entry.parsedDate
    val accent = when {
        parsedDate == null -> Color(0xFF475569)
        parsedDate.isBefore(today) -> Color(0xFFDC2626)
        !parsedDate.isAfter(today.plusDays(30)) -> Color(0xFFB45309)
        else -> Color(0xFF059669)
    }
    val dueText = when {
        parsedDate == null -> entry.date
        parsedDate.isBefore(today) -> "Kasni ${today.toEpochDay() - parsedDate.toEpochDay()} dana"
        parsedDate == today -> "Danas"
        else -> "Za ${parsedDate.toEpochDay() - today.toEpochDay()} dana"
    }

    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .then(if (onClick == null) Modifier else Modifier.clickable(onClick = onClick)),
        shape = RoundedCornerShape(18.dp),
        color = accent.copy(alpha = 0.08f),
    ) {
        Row(
            modifier = Modifier.padding(12.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(entry.icon, contentDescription = null, modifier = Modifier.size(22.dp), tint = accent)
            Spacer(Modifier.width(12.dp))
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Text(entry.title.ifBlank { recordKindLabel(entry.kind) }, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                Text(
                    listOf(entry.subtitle, formatDateLabel(entry.date).ifBlank { entry.date.take(10) }).filter { it.isNotBlank() }.joinToString(" - "),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            Surface(shape = RoundedCornerShape(999.dp), color = accent.copy(alpha = 0.12f)) {
                Text(
                    dueText,
                    modifier = Modifier.padding(horizontal = 9.dp, vertical = 5.dp),
                    color = accent,
                    style = MaterialTheme.typography.labelSmall,
                    fontWeight = FontWeight.Black,
                    maxLines = 1,
                )
            }
        }
    }
}

private data class MobileDocumentCompanyFolder(
    val key: String,
    val label: String,
    val records: List<MobileRecord>,
    val foundationRecords: List<MobileRecord>,
    val locations: List<MobileDocumentLocationFolder>,
)

private data class MobileDocumentLocationFolder(
    val key: String,
    val label: String,
    val records: List<MobileRecord>,
    val workOrders: List<MobileDocumentWorkOrderFolder>,
)

private data class MobileDocumentWorkOrderFolder(
    val key: String,
    val label: String,
    val records: List<MobileRecord>,
)

@Composable
private fun DocumentRegisterPreview(
    records: List<MobileRecord>,
    onOpenRecord: (MobileRecord) -> Unit,
    onDownloadDocument: (MobileRecord) -> Unit,
) {
    var selectedCompanyKey by remember(records) { mutableStateOf("") }
    var selectedLocationKey by remember(records) { mutableStateOf("") }
    var selectedWorkOrderKey by remember(records) { mutableStateOf("") }
    var showFoundation by remember(records) { mutableStateOf(false) }
    val companies = remember(records) { buildMobileDocumentCompanyFolders(records) }
    val selectedCompany = companies.firstOrNull { it.key == selectedCompanyKey }
    val selectedLocation = selectedCompany?.locations?.firstOrNull { it.key == selectedLocationKey }
    val selectedWorkOrder = selectedLocation?.workOrders?.firstOrNull { it.key == selectedWorkOrderKey }

    val goBackInDocuments = {
        when {
            selectedWorkOrderKey.isNotBlank() -> selectedWorkOrderKey = ""
            selectedLocationKey.isNotBlank() -> selectedLocationKey = ""
            showFoundation -> showFoundation = false
            selectedCompanyKey.isNotBlank() -> selectedCompanyKey = ""
        }
    }
    BackHandler(enabled = selectedCompanyKey.isNotBlank()) {
        goBackInDocuments()
    }

    LaunchedEffect(companies, selectedCompanyKey, selectedLocationKey, selectedWorkOrderKey, showFoundation) {
        if (selectedCompanyKey.isNotBlank() && selectedCompany == null) {
            selectedCompanyKey = ""
            selectedLocationKey = ""
            selectedWorkOrderKey = ""
            showFoundation = false
        } else if (selectedLocationKey.isNotBlank() && selectedLocation == null) {
            selectedLocationKey = ""
            selectedWorkOrderKey = ""
        } else if (selectedWorkOrderKey.isNotBlank() && selectedWorkOrder == null) {
            selectedWorkOrderKey = ""
        } else if (showFoundation && selectedCompany?.foundationRecords.isNullOrEmpty()) {
            showFoundation = false
        }
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            SectionHeader(
                title = "Dokumenti",
                subtitle = "${records.size} dokumenata po tvrtki, lokaciji i RN-u",
                icon = Icons.Rounded.Folder,
            )

            when {
                selectedWorkOrder != null -> {
                    DocumentRegisterBreadcrumb(
                        title = selectedWorkOrder.label,
                        subtitle = selectedLocation?.label.orEmpty(),
                        onBack = goBackInDocuments,
                    )
                    selectedWorkOrder.records.forEach { record ->
                        MobileDocumentLine(
                            record = record,
                            onOpenRecord = onOpenRecord,
                            onDownloadDocument = onDownloadDocument,
                        )
                    }
                }
                selectedLocation != null -> {
                    DocumentRegisterBreadcrumb(
                        title = selectedLocation.label,
                        subtitle = selectedCompany?.label.orEmpty(),
                        onBack = goBackInDocuments,
                    )
                    selectedLocation.workOrders.forEach { workOrder ->
                        DocumentFolderRow(
                            icon = Icons.Rounded.Work,
                            title = workOrder.label,
                            subtitle = "${workOrder.records.size} dokumenata",
                            count = workOrder.records.size,
                            onClick = { selectedWorkOrderKey = workOrder.key },
                        )
                    }
                }
                selectedCompany != null && showFoundation -> {
                    DocumentRegisterBreadcrumb(
                        title = "Temeljna dokumentacija",
                        subtitle = selectedCompany.label,
                        onBack = goBackInDocuments,
                    )
                    selectedCompany.foundationRecords.forEach { record ->
                        MobileDocumentLine(
                            record = record,
                            onOpenRecord = onOpenRecord,
                            onDownloadDocument = onDownloadDocument,
                        )
                    }
                }
                selectedCompany != null -> {
                    DocumentRegisterBreadcrumb(
                        title = selectedCompany.label,
                        subtitle = "${selectedCompany.locations.size} lokacija - ${selectedCompany.records.size} dokumenata",
                        onBack = goBackInDocuments,
                    )
                    DocumentFolderRow(
                        icon = Icons.Rounded.Description,
                        title = "Temeljna dokumentacija",
                        subtitle = "Procjene rizika, pravilnici i ostali dokumenti tvrtke",
                        count = selectedCompany.foundationRecords.size,
                        enabled = selectedCompany.foundationRecords.isNotEmpty(),
                        onClick = { showFoundation = true },
                    )
                    selectedCompany.locations.forEach { location ->
                        val rnCount = location.workOrders.size
                        DocumentFolderRow(
                            icon = Icons.Rounded.LocationOn,
                            title = location.label,
                            subtitle = "$rnCount RN - ${location.records.size} dokumenata",
                            count = location.records.size,
                            onClick = { selectedLocationKey = location.key },
                        )
                    }
                    if (selectedCompany.locations.isEmpty() && selectedCompany.foundationRecords.isEmpty()) {
                        Text(
                            "Nema lokacija ni temeljne dokumentacije za ovu tvrtku.",
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                        )
                    }
                }
                else -> {
                    if (companies.isEmpty()) {
                        Text(
                            "Nema dokumenata za prikaz.",
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                        )
                    } else {
                        companies.forEach { company ->
                            val rnCount = company.locations.sumOf { it.workOrders.size }
                            DocumentFolderRow(
                                icon = Icons.Rounded.Business,
                                title = company.label,
                                subtitle = "${company.foundationRecords.size} temeljnih - ${company.locations.size} lokacija - $rnCount RN",
                                count = company.records.size,
                                onClick = { selectedCompanyKey = company.key },
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentRegisterBreadcrumb(
    title: String,
    subtitle: String,
    onBack: () -> Unit,
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        IconButton(onClick = onBack) {
            Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
        }
        Column(modifier = Modifier.weight(1f)) {
            Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Black)
            if (subtitle.isNotBlank()) {
                Text(
                    subtitle,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
    }
}

