data class MobileTrainingDocument(
    val id: String,
    val fileName: String,
    val fileType: String,
    val category: String,
    val createdAt: String,
    val isCertificate: Boolean,
)

data class FieldInquiryDocument(
    val id: String,
    val fileName: String,
    val fileType: String,
    val fileSize: Long,
    val category: String,
    val description: String,
)

private data class MobileTrainingItem(
    val id: String,
    val label: String,
    val shortLabel: String,
    val serviceCode: String,
    val status: String,
    val passedOn: String,
    val validUntil: String,
    val validForever: Boolean,
    val deadlineLabel: String,
    val examModeLabel: String,
    val certificateNumber: String,
    val provider: String,
    val workOrderNumber: String,
    val documentId: String,
    val documentName: String,
    val documentFileType: String,
    val documentCategory: String,
)

private fun parseTrainingItems(record: MobileRecord): List<MobileTrainingItem> {
    val raw = record.meta["trainingItemsJson"].orEmpty()
    if (raw.isBlank()) return emptyList()
    return runCatching {
        val array = JSONArray(raw)
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                add(
                    MobileTrainingItem(
                        id = item.optString("id").trim(),
                        label = item.optString("label").trim().ifBlank { "Osposobljavanje" },
                        shortLabel = item.optString("shortLabel").trim(),
                        serviceCode = item.optString("serviceCode").trim(),
                        status = item.optString("status").trim().ifBlank { "Evidencija" },
                        passedOn = item.optString("passedOn").trim(),
                        validUntil = item.optString("validUntil").trim(),
                        validForever = item.optBoolean("validForever", false) || item.optString("validForever").equals("true", ignoreCase = true),
                        deadlineLabel = item.optString("deadlineLabel").trim(),
                        examModeLabel = item.optString("examModeLabel").trim(),
                        certificateNumber = item.optString("certificateNumber").trim(),
                        provider = item.optString("provider").trim(),
                        workOrderNumber = item.optString("workOrderNumber").trim(),
                        documentId = item.optString("documentId").trim(),
                        documentName = item.optString("documentName").trim(),
                        documentFileType = item.optString("documentFileType").trim().ifBlank { "application/octet-stream" },
                        documentCategory = item.optString("documentCategory").trim(),
                    ),
                )
            }
        }
    }.getOrDefault(emptyList())
}

private fun parseTrainingDocuments(record: MobileRecord): List<MobileTrainingDocument> {
    val raw = record.meta["documentsJson"].orEmpty()
    if (raw.isBlank()) return emptyList()
    return runCatching {
        val array = JSONArray(raw)
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val id = item.optString("id").trim()
                val fileName = item.optString("fileName").trim()
                if (id.isBlank() && fileName.isBlank()) continue
                add(
                    MobileTrainingDocument(
                        id = id,
                        fileName = fileName.ifBlank { "Dokument" },
                        fileType = item.optString("fileType").trim().ifBlank { "application/octet-stream" },
                        category = item.optString("documentCategory").trim(),
                        createdAt = item.optString("createdAt").trim(),
                        isCertificate = item.optBoolean("isCertificate", false) || item.optString("isCertificate").equals("true", ignoreCase = true),
                    ),
                )
            }
        }
    }.getOrDefault(emptyList())
}

private fun parseFieldInquiryDocuments(record: MobileRecord): List<FieldInquiryDocument> {
    val raw = record.meta["documentsJson"].orEmpty()
    if (raw.isBlank()) return emptyList()
    return runCatching {
        val array = JSONArray(raw)
        buildList {
            for (index in 0 until array.length()) {
                val item = array.optJSONObject(index) ?: continue
                val id = item.optString("id").trim().ifBlank { index.toString() }
                val fileName = item.optString("fileName").trim()
                if (fileName.isBlank()) continue
                add(
                    FieldInquiryDocument(
                        id = id,
                        fileName = fileName,
                        fileType = item.optString("fileType").trim().ifBlank { "application/octet-stream" },
                        fileSize = item.optLong("fileSize", 0L),
                        category = item.optString("category").trim(),
                        description = item.optString("description").trim(),
                    ),
                )
            }
        }
    }.getOrDefault(emptyList())
}

private fun trainingStatusColor(status: String): Color {
    val normalized = status.lowercase(Locale.getDefault())
    return when {
        normalized.contains("istek") -> Color(0xFFDC2626)
        normalized.contains("uskoro") -> Color(0xFFB45309)
        normalized.contains("nedost") || normalized.contains("gres") || normalized.contains("greš") -> Color(0xFF64748B)
        normalized.contains("trajno") || normalized.contains("vrijed") || normalized.contains("aktiv") || normalized.contains("znr") -> Color(0xFF059669)
        else -> Color(0xFF2563EB)
    }
}

private fun compactTrainingDate(value: String, keepTrailingDot: Boolean = true): String {
    val formatted = formatDateLabel(value).ifBlank { value.take(10) }
    return if (keepTrailingDot) formatted else formatted.removeSuffix(".")
}

private fun trainingItemPeriodText(item: MobileTrainingItem): String = when {
    item.validForever -> "trajno"
    item.passedOn.isNotBlank() && item.validUntil.isNotBlank() ->
        "${compactTrainingDate(item.passedOn, keepTrailingDot = false)}-${compactTrainingDate(item.validUntil)}"
    item.validUntil.isNotBlank() -> compactTrainingDate(item.validUntil)
    item.passedOn.isNotBlank() -> compactTrainingDate(item.passedOn)
    else -> ""
}

private fun trainingItemDocument(item: MobileTrainingItem): MobileTrainingDocument? {
    if (item.documentId.isBlank()) return null
    return MobileTrainingDocument(
        id = item.documentId,
        fileName = item.documentName.ifBlank { "${item.label.ifBlank { "Osposobljavanje" }}.pdf" },
        fileType = item.documentFileType.ifBlank { "application/octet-stream" },
        category = item.documentCategory,
        createdAt = item.passedOn,
        isCertificate = true,
    )
}

private fun trainingCompanyLabel(record: MobileRecord): String =
    record.meta["companyName"].orEmpty().ifBlank {
        record.subtitle.split(" - ", " · ").firstOrNull().orEmpty().trim()
    }.ifBlank { "Bez tvrtke" }

private fun trainingPersonOibLabel(record: MobileRecord): String =
    normalizePeopleOib(record.meta["oib"].orEmpty()).ifBlank { record.meta["oib"].orEmpty().trim() }

private fun normalizePeopleOib(value: String): String = value.filter { it.isDigit() }.take(11)

private fun parsePeopleIsznrTags(value: String): List<String> {
    val normalized = value.trim()
    if (normalized.isBlank()) return emptyList()
    if (normalized.startsWith("[")) {
        return runCatching {
            val array = JSONArray(normalized)
            buildList {
                for (index in 0 until array.length()) {
                    val tag = array.optString(index).trim()
                    if (tag.isNotBlank()) add(tag)
                }
            }
        }.getOrDefault(emptyList())
    }
    return normalized.split(",", " ", "\n", "\t")
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinct()
}

private fun getPeopleIsznrTags(user: WorkOrderUserOption, record: MobileRecord?): List<String> =
    (user.isznrTags + parsePeopleIsznrTags(record?.meta?.get("isznrTagsJson").orEmpty()) + parsePeopleIsznrTags(record?.meta?.get("isznrTags").orEmpty()))
        .map { it.trim() }
        .filter { it.startsWith("IsZNR") }
        .distinct()

@Composable
private fun PeopleDirectoryContent(
    users: List<WorkOrderUserOption>,
    isznrRecords: List<MobileRecord>,
    totalCount: Int,
    isznrLoading: Boolean,
    isznrLoaded: Boolean,
    isznrError: String,
    displayLimit: Int,
    onLoadIsznr: (Boolean) -> Unit,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val isznrByOib = remember(isznrRecords) {
        isznrRecords
            .mapNotNull { record ->
                val oib = normalizePeopleOib(record.meta["oib"].orEmpty())
                if (oib.isBlank()) null else oib to record
            }
            .toMap()
    }
    val linkedIsznrCount = remember(isznrRecords) {
        isznrRecords.count { record -> record.meta["isznrLinked"].equals("true", ignoreCase = true) }
    }
    val usersWithOib = remember(users) { users.count { user -> normalizePeopleOib(user.oib).isNotBlank() } }
    val visibleUsers = remember(users, displayLimit) { users.take(displayLimit.coerceAtLeast(1)) }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(13.dp),
        ) {
            SectionHeader(
                title = "People",
                subtitle = "$totalCount korisnika · $usersWithOib s OIB-om · $linkedIsznrCount IS ZNR povezano",
                icon = Icons.Rounded.Person,
            )
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    if (isznrLoaded) "IS ZNR oznake su upisane na People osobe." else "Osvježi za provjeru OIB-a i dodjelu IS ZNR oznaka.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = { onLoadIsznr(true) }, enabled = !isznrLoading) {
                    Icon(Icons.Rounded.Refresh, contentDescription = "Osvježi IS ZNR oznake")
                }
            }
            AnimatedVisibility(isznrLoading) {
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
            }
            AnimatedVisibility(isznrError.isNotBlank()) {
                MessageCard(text = isznrError, isError = true)
            }
            if (users.isEmpty()) {
                Text(
                    "Nema People korisnika za prikaz.",
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                )
            } else {
                visibleUsers.forEach { user ->
                    val oib = normalizePeopleOib(user.oib)
                    PeopleUserLine(
                        user = user,
                        isznrRecord = isznrByOib[oib],
                        isznrLoaded = isznrLoaded,
                        onOpenRecord = onOpenRecord,
                    )
                }
                if (users.size > visibleUsers.size) {
                    Text(
                        "Prikazano je prvih ${visibleUsers.size}. Koristi pretragu za sužavanje popisa.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            }
        }
    }
}

@Composable
private fun PeopleUserLine(
    user: WorkOrderUserOption,
    isznrRecord: MobileRecord?,
    isznrLoaded: Boolean,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val oib = normalizePeopleOib(user.oib)
    val tags = getPeopleIsznrTags(user, isznrRecord)
    val linked = (
        isznrRecord?.meta?.get("isznrLinked").equals("true", ignoreCase = true)
            || tags.isNotEmpty()
    )
    val hasError = isznrRecord?.meta?.get("isznrError").orEmpty().isNotBlank()
    val accent = when {
        oib.isBlank() -> Color(0xFF64748B)
        linked -> Color(0xFF059669)
        hasError -> Color(0xFFDC2626)
        isznrLoaded -> Color(0xFFB45309)
        else -> Color(0xFF2563EB)
    }
    val statusText = when {
        oib.isBlank() -> "Bez OIB-a"
        linked -> tags.firstOrNull() ?: isznrRecord?.status?.ifBlank { "Povezano" } ?: "Povezano"
        hasError -> "Greška IS ZNR"
        isznrLoaded -> "Nije pronađeno"
        else -> "Nije provjereno"
    }
    val rowModifier = Modifier
        .fillMaxWidth()
        .then(if (isznrRecord != null) Modifier.clickable { onOpenRecord(isznrRecord) } else Modifier)

    Surface(
        modifier = rowModifier,
        shape = RoundedCornerShape(18.dp),
        color = accent.copy(alpha = 0.07f),
    ) {
        Row(
            modifier = Modifier.padding(12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Surface(shape = CircleShape, color = accent.copy(alpha = 0.14f)) {
                Icon(
                    if (linked) Icons.Rounded.CheckCircle else Icons.Rounded.Person,
                    contentDescription = null,
                    modifier = Modifier
                        .size(38.dp)
                        .padding(9.dp),
                    tint = accent,
                )
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                Text(user.label.ifBlank { user.fullName.ifBlank { user.email.ifBlank { "People korisnik" } } }, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                Text(
                    listOf(user.email, user.fullName.takeIf { it != user.label }).filterNotNull().filter { it.isNotBlank() }.joinToString(" · ").ifBlank { "People modul" },
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
                FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    if (oib.isNotBlank()) {
                        TrainingMiniChip("OIB $oib", Color(0xFF64748B))
                    }
                    tags.forEach { tag -> TrainingMiniChip(tag, Color(0xFF059669)) }
                    isznrRecord?.meta?.get("isznrIds")?.takeIf { it.isNotBlank() }?.let { TrainingMiniChip(it, Color(0xFF2563EB)) }
                }
            }
            TrainingMiniChip(statusText, accent)
        }
    }
}

@Composable
private fun TrainingContent(
    records: List<MobileRecord>,
    totalCount: Int,
    displayLimit: Int,
    onOpenRecord: (MobileRecord) -> Unit,
    onDownloadDocument: (MobileRecord, MobileTrainingDocument) -> Unit,
) {
    var selectedCompany by remember(records) { mutableStateOf("") }
    var companyMenuOpen by remember { mutableStateOf(false) }
    val companyOptions = remember(records) {
        records
            .map(::trainingCompanyLabel)
            .filter { it.isNotBlank() }
            .distinct()
            .sortedBy { it.lowercase(Locale.getDefault()) }
    }
    val companyFilteredRecords = remember(records, selectedCompany) {
        if (selectedCompany.isBlank()) {
            records
        } else {
            records.filter { record -> trainingCompanyLabel(record).equals(selectedCompany, ignoreCase = true) }
        }
    }
    val visibleRecords = remember(companyFilteredRecords, displayLimit) { companyFilteredRecords.take(displayLimit.coerceAtLeast(1)) }
    val validTotal = remember(companyFilteredRecords) {
        companyFilteredRecords.sumOf { record -> record.meta["validCount"].orEmpty().toIntOrNull() ?: 0 }
    }
    val expiringTotal = remember(companyFilteredRecords) {
        companyFilteredRecords.sumOf { record -> record.meta["expiringCount"].orEmpty().toIntOrNull() ?: 0 }
    }
    val expiredTotal = remember(companyFilteredRecords) {
        companyFilteredRecords.sumOf { record -> record.meta["expiredCount"].orEmpty().toIntOrNull() ?: 0 }
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(24.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
        shadowElevation = 2.dp,
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(13.dp),
        ) {
            SectionHeader(
                title = "Osposobljavanja",
                subtitle = "${companyFilteredRecords.size} osoba · $totalCount ukupno",
                icon = Icons.Rounded.Fingerprint,
            )

            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                TrainingMiniChip("$validTotal vrijedi", Color(0xFF059669))
                if (expiringTotal > 0) TrainingMiniChip("$expiringTotal uskoro", Color(0xFFB45309))
                if (expiredTotal > 0) TrainingMiniChip("$expiredTotal isteklo", Color(0xFFDC2626))
            }

            Box {
                OutlinedButton(
                    onClick = { companyMenuOpen = true },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 12.dp),
                ) {
                    Icon(Icons.Rounded.Business, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(8.dp))
                    Column(modifier = Modifier.weight(1f), horizontalAlignment = Alignment.Start) {
                        Text("Filter po firmi", style = MaterialTheme.typography.labelSmall)
                        Text(
                            selectedCompany.ifBlank { "Sve firme" },
                            fontWeight = FontWeight.Black,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                DropdownMenu(
                    expanded = companyMenuOpen,
                    onDismissRequest = { companyMenuOpen = false },
                ) {
                    DropdownMenuItem(
                        text = { Text("Sve firme (${records.size})") },
                        onClick = {
                            selectedCompany = ""
                            companyMenuOpen = false
                        },
                    )
                    companyOptions.forEach { company ->
                        val count = records.count { record -> trainingCompanyLabel(record).equals(company, ignoreCase = true) }
                        DropdownMenuItem(
                            text = { Text("$company ($count)", maxLines = 2, overflow = TextOverflow.Ellipsis) },
                            onClick = {
                                selectedCompany = company
                                companyMenuOpen = false
                            },
                        )
                    }
                }
            }

            if (records.isEmpty()) {
                Text(
                    "Nema osposobljavanja za prikaz.",
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                )
            } else if (companyFilteredRecords.isEmpty()) {
                Text(
                    "Nema osposobljavanja za odabranu firmu.",
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                )
            } else {
                visibleRecords.forEach { record ->
                    TrainingRecordLine(
                        record = record,
                        onOpenRecord = onOpenRecord,
                        onDownloadDocument = { document -> onDownloadDocument(record, document) },
                    )
                }
                if (companyFilteredRecords.size > visibleRecords.size) {
                    Text(
                        "Prikazano je prvih ${visibleRecords.size}. Koristi pretragu ili filter firme za sužavanje popisa.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            }
        }
    }
}

@Composable
private fun TrainingRecordLine(
    record: MobileRecord,
    onOpenRecord: (MobileRecord) -> Unit,
    onDownloadDocument: (MobileTrainingDocument) -> Unit,
) {
    val items = remember(record.meta["trainingItemsJson"]) { parseTrainingItems(record) }
    val documents = remember(record.meta["documentsJson"]) { parseTrainingDocuments(record) }
    val statusColor = trainingStatusColor(record.status)
    val companyName = trainingCompanyLabel(record)
    val oib = trainingPersonOibLabel(record)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onOpenRecord(record) },
        shape = RoundedCornerShape(18.dp),
        color = statusColor.copy(alpha = 0.07f),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                Surface(shape = CircleShape, color = statusColor.copy(alpha = 0.14f)) {
                    Icon(
                        Icons.Rounded.Fingerprint,
                        contentDescription = null,
                        modifier = Modifier
                            .size(38.dp)
                            .padding(9.dp),
                        tint = statusColor,
                    )
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(record.title.ifBlank { "Osoba" }, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                    Text(
                        listOf(
                            oib.takeIf { it.isNotBlank() }?.let { "OIB $it" }.orEmpty(),
                            companyName,
                            record.meta["jobTitle"].orEmpty().ifBlank { record.meta["workPlace"].orEmpty() },
                        ).filter { it.isNotBlank() }.joinToString(" · "),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                TrainingMiniChip(record.status.ifBlank { "Evidencija" }, statusColor)
            }

            FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                TrainingMiniChip(companyName, Color(0xFF2563EB))
                oib.takeIf { it.isNotBlank() }?.let { TrainingMiniChip("OIB $it", Color(0xFF64748B)) }
                record.meta["trainingCount"]?.takeIf { it != "0" }?.let { TrainingMiniChip("$it ospos.", Color(0xFF2563EB)) }
                record.meta["documentCount"]?.takeIf { it != "0" }?.let { TrainingMiniChip("$it dok.", Color(0xFF7C3AED)) }
                record.meta["expiredCount"]?.takeIf { it != "0" }?.let { TrainingMiniChip("$it isteklo", Color(0xFFDC2626)) }
                record.meta["expiringCount"]?.takeIf { it != "0" }?.let { TrainingMiniChip("$it uskoro", Color(0xFFB45309)) }
            }

            items.take(4).forEach { item ->
                val itemColor = trainingStatusColor(item.status)
                val document = trainingItemDocument(item)
                val hasDocument = document?.id?.isNotBlank() == true
                val periodText = trainingItemPeriodText(item)
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    color = MaterialTheme.colorScheme.surface.copy(alpha = 0.74f),
                    border = BorderStroke(1.dp, itemColor.copy(alpha = 0.12f)),
                ) {
                    Row(
                        modifier = Modifier.padding(10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(9.dp),
                    ) {
                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                            Text(item.label, fontWeight = FontWeight.SemiBold, maxLines = 2, overflow = TextOverflow.Ellipsis)
                            if (periodText.isNotBlank()) {
                                Text(
                                    periodText,
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                        IconButton(
                            onClick = { document?.let(onDownloadDocument) },
                            enabled = hasDocument,
                        ) {
                            Icon(
                                Icons.Rounded.Download,
                                contentDescription = if (hasDocument) "Preuzmi PDF" else "Nema PDF-a",
                                tint = if (hasDocument) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.28f),
                            )
                        }
                    }
                }
            }

            if (documents.isNotEmpty()) {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    documents.take(4).forEach { document ->
                        OutlinedButton(
                            onClick = { onDownloadDocument(document) },
                            enabled = document.id.isNotBlank(),
                            contentPadding = PaddingValues(horizontal = 10.dp, vertical = 6.dp),
                            shape = RoundedCornerShape(12.dp),
                        ) {
                            Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(16.dp))
                            Spacer(Modifier.width(6.dp))
                            Text(document.fileName, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        }
                    }
                }
            }
        }
    }
}

