    icon: ImageVector,
    query: String,
    onOpenRecord: (MobileRecord) -> Unit,
) {
    val filtered = remember(records, query) { records.filter { record -> record.matchesSearch(query) } }

    RecordsContent(
        title = title,
        records = filtered,
        emptyText = "Nema zapisa za prikaz.",
        icon = icon,
        onOpenRecord = onOpenRecord,
    )
