private class WorkOrderMapBridge(
    private val points: List<WorkOrderMapPoint>,
    private val onOpenWorkOrder: (WorkOrder) -> Unit,
    private val onStatusChange: (WorkOrder, String) -> Unit,
) {
    private val mainHandler = Handler(Looper.getMainLooper())

    @JavascriptInterface
    fun openWorkOrder(workOrderId: String) {
        val workOrder = points
            .firstOrNull { entry -> entry.workOrder.id == workOrderId }
            ?.workOrder
            ?: return

        mainHandler.post {
            onOpenWorkOrder(workOrder)
        }
    }

    @JavascriptInterface
    fun changeWorkOrderStatus(workOrderId: String, status: String) {
        val workOrder = points
            .firstOrNull { entry -> entry.workOrder.id == workOrderId }
            ?.workOrder
            ?: return

        mainHandler.post {
            onStatusChange(workOrder, status)
        }
    }
}

@SuppressLint("SetJavaScriptEnabled")
@Composable
private fun WorkOrderLeafletMap(
    points: List<WorkOrderMapPoint>,
    statusOptions: List<String>,
    mapHeight: Dp = 280.dp,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onStatusChange: (WorkOrder, String) -> Unit,
) {
    val html = remember(points, statusOptions) { buildWorkOrderLeafletHtml(points, statusOptions) }
    val bridge = remember(points, onOpenWorkOrder, onStatusChange) {
        WorkOrderMapBridge(points, onOpenWorkOrder, onStatusChange)
    }

    AndroidView(
        modifier = Modifier
            .fillMaxWidth()
            .height(mapHeight)
            .clip(RoundedCornerShape(bottomStart = 24.dp, bottomEnd = 24.dp)),
        factory = { context ->
            WebView(context).apply {
                webViewClient = object : WebViewClient() {
                    override fun shouldOverrideUrlLoading(view: WebView, request: WebResourceRequest): Boolean {
                        return handleWorkOrderMapUrl(request.url, points, onOpenWorkOrder, onStatusChange)
                    }
                }
                settings.javaScriptEnabled = true
                settings.domStorageEnabled = true
                settings.allowFileAccess = true
                settings.allowContentAccess = true
                settings.allowFileAccessFromFileURLs = true
                settings.allowUniversalAccessFromFileURLs = true
                addJavascriptInterface(bridge, "SafeNexus")
                setBackgroundColor(android.graphics.Color.TRANSPARENT)
            }
        },
        update = { webView ->
            webView.removeJavascriptInterface("SafeNexus")
            webView.addJavascriptInterface(bridge, "SafeNexus")
            if (webView.tag != html) {
                webView.tag = html
                webView.loadDataWithBaseURL(
                    "file:///android_asset/leaflet/",
                    html,
                    "text/html",
                    "UTF-8",
                    null,
                )
            }
        },
    )
}

private fun handleWorkOrderMapUrl(
    uri: Uri,
    points: List<WorkOrderMapPoint>,
    onOpenWorkOrder: (WorkOrder) -> Unit,
    onStatusChange: (WorkOrder, String) -> Unit,
): Boolean {
    if (uri.scheme != "safenexus") {
        return false
    }

    val workOrderId = uri.lastPathSegment.orEmpty()
    val workOrder = points
        .firstOrNull { entry -> entry.workOrder.id == workOrderId }
        ?.workOrder
        ?: return true
    when (uri.host) {
        "work-order" -> onOpenWorkOrder(workOrder)
        "work-order-status" -> uri.getQueryParameter("status")?.takeIf { it.isNotBlank() }?.let { status ->
            onStatusChange(workOrder, status)
        }
        else -> return false
    }
    return true
}

private fun buildWorkOrderLeafletHtml(points: List<WorkOrderMapPoint>, statusOptions: List<String>): String {
    val markers = JSONArray()
    points.forEach { entry ->
        val workOrder = entry.workOrder
        val style = rnStatusStyle(workOrder)
        markers.put(
            JSONObject()
                .put("id", workOrder.id)
                .put("number", workOrder.displayNumber)
                .put("company", workOrder.companyName.ifBlank { "Bez tvrtke" })
                .put("location", workOrder.locationName.ifBlank { "Bez lokacije" })
                .put("service", workOrder.displayService)
                .put("executor", workOrder.primaryExecutorLabel())
                .put("dueDate", formatDateLabel(workOrder.dueDate).ifBlank { "Rok nije upisan" })
                .put("executionDate", formatDateLabel(workOrder.executionDate).ifBlank { "Izvršenje nije upisano" })
                .put("status", workOrder.status.ifBlank { "Bez statusa" })
                .put("statusAccent", style.accent.toCssHex())
                .put("statusBackground", style.background.toCssHex())
                .put("lat", entry.point.latitude)
                .put("lng", entry.point.longitude),
        )
    }
    val statuses = JSONArray()
    statusOptions
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinct()
        .forEach { statuses.put(it) }

    return """
        <!doctype html>
        <html lang="hr">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">
          <link rel="stylesheet" href="leaflet.css">
          <link rel="stylesheet" href="MarkerCluster.css">
          <link rel="stylesheet" href="MarkerCluster.Default.css">
          <style>
            html, body, #map {
              width: 100%;
              height: 100%;
              margin: 0;
            }
            body {
              background: #eef4ff;
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            }
            #map {
              min-height: 400px;
            }
            .leaflet-container {
              background: #e6eef8;
              font: inherit;
            }
            .leaflet-popup-content-wrapper {
              border-radius: 18px;
            }
            .leaflet-popup-content {
              margin: 10px 12px;
            }
            .sn-popup {
              display: grid;
              gap: 8px;
              width: 232px;
              max-width: 232px;
              max-height: 360px;
              overflow-y: auto;
              padding-right: 2px;
              color: #111827;
            }
            .sn-popup strong {
              display: block;
              color: #0f172a;
              font-size: 16px;
              font-weight: 800;
              max-width: 100%;
              overflow: hidden;
              text-overflow: ellipsis;
              white-space: nowrap;
            }
            .sn-popup span {
              display: block;
              color: #475569;
              font-size: 13px;
              line-height: 1.35;
              max-width: 100%;
              overflow: hidden;
              text-overflow: ellipsis;
              white-space: nowrap;
            }
            .sn-meta {
              display: grid;
              gap: 3px;
              padding: 8px;
              border-radius: 12px;
              background: #f8fafc;
              border: 1px solid #e2e8f0;
            }
            .sn-meta span {
              font-size: 12px;
            }
            .sn-status {
              display: inline-flex;
              width: fit-content;
              padding: 4px 8px;
              border-radius: 999px;
              background: var(--sn-status-bg, #dbeafe);
              color: var(--sn-status-color, #1d4ed8) !important;
              font-size: 12px !important;
              font-weight: 800;
            }
            .sn-status-select {
              width: 100%;
              border: 1px solid #cbd5e1;
              border-radius: 10px;
              padding: 8px 10px;
              background: #ffffff;
              color: #0f172a;
              font-weight: 700;
              outline: none;
            }
            .sn-open {
              border: 0;
              display: inline-flex;
              align-items: center;
              justify-content: center;
              margin-top: 4px;
              width: 100%;
              padding: 8px 10px;
              border-radius: 10px;
              background: #2563eb;
              color: #ffffff !important;
              font-size: 13px;
              font-weight: 800;
              text-decoration: none;
              font-family: inherit;
            }
            .sn-pin {
              width: 28px;
              height: 28px;
              display: grid;
              place-items: center;
              background: var(--pin-bg, #dbeafe);
              border: 3px solid #ffffff;
              border-radius: 50% 50% 50% 0;
              transform: rotate(-45deg);
              box-shadow: 0 8px 18px rgba(15, 23, 42, 0.26);
            }
            .sn-pin::after {
              content: "";
              width: 10px;
              height: 10px;
              border-radius: 50%;
              background: var(--pin, #2563eb);
              transform: rotate(45deg);
            }
            .marker-cluster-small,
            .marker-cluster-medium,
            .marker-cluster-large {
              background-color: rgba(37, 99, 235, 0.22);
            }
            .marker-cluster-small div,
            .marker-cluster-medium div,
            .marker-cluster-large div {
              background-color: rgba(37, 99, 235, 0.88);
              color: #ffffff;
              font-weight: 800;
            }
          </style>
        </head>
        <body>
          <div id="map"></div>
          <script src="leaflet.js"></script>
          <script src="leaflet.markercluster.js"></script>
          <script>
            const markers = $markers;
            const statusOptions = $statuses;
            const map = L.map("map", {
              zoomControl: true,
              attributionControl: true
            });

            L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
              maxZoom: 19,
              attribution: "&copy; OpenStreetMap"
            }).addTo(map);

            const clusterLayer = L.markerClusterGroup({
              showCoverageOnHover: false,
              spiderfyOnMaxZoom: true,
              maxClusterRadius: 52
            });

            function escapeHtml(value) {
              return String(value || "").replace(/[&<>"']/g, function(char) {
                return {
                  "&": "&amp;",
                  "<": "&lt;",
                  ">": "&gt;",
                  "\"": "&quot;",
                  "'": "&#039;"
                }[char];
              });
            }

            function markerIcon(marker) {
              return L.divIcon({
                className: "sn-marker",
                html: "<div class='sn-pin' style='--pin:" + escapeHtml(marker.statusAccent) + ";--pin-bg:" + escapeHtml(marker.statusBackground) + ";'></div>",
                iconSize: [30, 30],
                iconAnchor: [15, 30],
                popupAnchor: [0, -28]
              });
            }

            function statusSelect(marker) {
              if (!statusOptions || statusOptions.length === 0) return "";
              const options = statusOptions.map(function(status) {
                const selected = status === marker.status ? " selected" : "";
                return "<option value='" + escapeHtml(status) + "'" + selected + ">" + escapeHtml(status) + "</option>";
              }).join("");
              return "<select class='sn-status-select' onchange='window.SafeNexus.changeWorkOrderStatus(" + JSON.stringify(marker.id) + ", this.value)'>" + options + "</select>";
            }

            markers.forEach(function(marker) {
              const leafletMarker = L.marker([marker.lat, marker.lng], { icon: markerIcon(marker) });
              const safeId = encodeURIComponent(marker.id);
              leafletMarker.bindPopup([
                "<div class='sn-popup'>",
                "<strong>RN " + escapeHtml(marker.number) + "</strong>",
                "<span>" + escapeHtml(marker.company) + "</span>",
                "<span class='sn-status' style='--sn-status-bg:" + escapeHtml(marker.statusBackground) + ";--sn-status-color:" + escapeHtml(marker.statusAccent) + ";'>" + escapeHtml(marker.status) + "</span>",
                "<div class='sn-meta'>",
                "<span>" + escapeHtml(marker.location) + "</span>",
                "<span>" + escapeHtml(marker.service) + "</span>",
                "<span>Izvršitelj: " + escapeHtml(marker.executor) + "</span>",
                "<span>" + escapeHtml(marker.dueDate) + " · " + escapeHtml(marker.executionDate) + "</span>",
                "</div>",
                statusSelect(marker),
                "<button class='sn-open' type='button' onclick='window.SafeNexus.openWorkOrder(" + JSON.stringify(marker.id) + "); return false;'>Otvori RN</button>",
                "</div>"
              ].join(""), {
                maxWidth: 248,
                minWidth: 232,
                autoPan: true,
                autoPanPadding: [18, 18],
                keepInView: true,
                closeOnClick: false
              });
              clusterLayer.addLayer(leafletMarker);
            });

            map.addLayer(clusterLayer);

            if (markers.length === 0) {
              document.body.innerHTML = "<div style='display:grid;place-items:center;height:100%;padding:24px;color:#475569;font-weight:800;text-align:center;'>Nema dostupnih lokacija za prikaz na karti.</div>";
            } else if (markers.length === 1) {
              map.setView([markers[0].lat, markers[0].lng], 14);
            } else {
              const bounds = L.latLngBounds(markers.map(function(marker) {
                return [marker.lat, marker.lng];
              }));
              map.fitBounds(bounds, { padding: [28, 28] });
            }

            setTimeout(function() {
              map.invalidateSize(false);
            }, 80);
          </script>
        </body>
        </html>
    """.trimIndent()
}

