        Icon(icon, contentDescription = null, modifier = Modifier.size(24.dp), tint = tint)
        Spacer(Modifier.width(10.dp))
        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(2.dp),
        ) {
            Text(
                value,
                style = MaterialTheme.typography.bodyMedium,
                color = Color(0xFF0F172A),
                fontWeight = FontWeight.SemiBold,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

@Composable
private fun WorkOrderCard(
    workOrder: WorkOrder,
    isLoading: Boolean,
    statusOptions: List<String>,
    onClick: () -> Unit,
    onStatusChange: (String) -> Unit,
    onAddDocumentation: () -> Unit,
    readOnly: Boolean = false,
) {
    val statusStyle = rnStatusStyle(workOrder)
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(18.dp),
        colors = CardDefaults.cardColors(containerColor = Color(0xFFFBFDFF)),
        elevation = CardDefaults.cardElevation(defaultElevation = 3.dp),
    ) {
        Column(
            modifier = Modifier.padding(15.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                if (readOnly) {
                    StatusChip(workOrder)
                } else {
                    RnStatusMenuChip(
                        currentStatus = workOrder.status,
                        statusOptions = statusOptions,
                        enabled = !isLoading,
                        onStatusSelected = onStatusChange,
                    )
                }
                Spacer(Modifier.width(10.dp))
                Column(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(2.dp),
                ) {
                    Text(
                        workOrder.displayNumber,
                        style = MaterialTheme.typography.titleLarge,
                        color = Color(0xFF0F172A),
                        fontWeight = FontWeight.Black,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                if (!readOnly) {
                    IconButton(
                        onClick = onAddDocumentation,
                        enabled = !isLoading,
                        modifier = Modifier.size(42.dp),
                    ) {
                        Icon(
                            Icons.Rounded.Description,
                            contentDescription = "Dodaj dokumentaciju",
                            modifier = Modifier.size(21.dp),
                            tint = if (isLoading) Color(0xFF94A3B8) else statusStyle.accent,
                        )
                    }
                }
                Text(
                    "›",
                    modifier = Modifier.padding(start = 6.dp),
                    color = Color(0xFF64748B),
                    style = MaterialTheme.typography.headlineSmall,
                    fontWeight = FontWeight.Light,
                )
            }

            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(15.dp),
                color = statusStyle.background.copy(alpha = 0.82f),
            ) {
                Row(
                    modifier = Modifier.padding(12.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(
                        Icons.Rounded.Business,
                        contentDescription = null,
                        modifier = Modifier.size(22.dp),
                        tint = statusStyle.accent,
                    )
                    Spacer(Modifier.width(10.dp))
                    Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(
                            workOrder.companyName.ifBlank { "Bez tvrtke" },
                            style = MaterialTheme.typography.bodyLarge,
                            color = Color(0xFF0F172A),
                            fontWeight = FontWeight.Black,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
            }

            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                RnInfoBlock(
                    icon = Icons.Rounded.LocationOn,
                    value = workOrder.locationName.ifBlank { "Lokacija nije upisana" },
                    tint = statusStyle.accent,
                    modifier = Modifier.fillMaxWidth(),
                )
                RnInfoBlock(
                    icon = Icons.Rounded.Person,
                    value = workOrder.primaryExecutorLabel(),
                    tint = statusStyle.accent,
                    modifier = Modifier.fillMaxWidth(),
                )
            }

            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(15.dp),
                color = Color(0xFFF8FAFC),
            ) {
                Column(
                    modifier = Modifier.padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(7.dp),
                ) {
                Text(
                    "Usluge",
                    style = MaterialTheme.typography.labelSmall,
                    color = Color(0xFF64748B),
                    fontWeight = FontWeight.Black,
                )
                val services = workOrder.serviceBulletItems()
                services.take(3).forEach { service ->
                    Row(verticalAlignment = Alignment.Top) {
                        Text("•", color = statusStyle.accent, modifier = Modifier.padding(end = 7.dp))
                        Text(
                            service,
                            style = MaterialTheme.typography.bodySmall,
                            color = Color(0xFF0F172A),
                            maxLines = 3,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                if (services.size > 3) {
                    Text(
                        "+${services.size - 3} stavke",
                        color = Color(0xFF0B63E5),
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.Black,
                    )
                }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun FieldInquiryMobileDetailScreen(
    record: MobileRecord,
    isLoading: Boolean,
    onBack: () -> Unit,
    onConvert: () -> Unit,
    onDownloadDocument: (FieldInquiryDocument) -> Unit,
) {
    BackHandler(onBack = onBack)
    val documents = remember(record.meta["documentsJson"]) { parseFieldInquiryDocuments(record) }
    val statusColor = calendarRecordColor("field_inquiry")
    val timeLabel = listOf(record.meta["timeFrom"].orEmpty(), record.meta["timeTo"].orEmpty())
        .filter { it.isNotBlank() }
        .joinToString(" - ")
    Scaffold(
        topBar = {
            TopAppBar(
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
                    }
                },
                title = {
                    Column {
                        Text("Plan terena", fontWeight = FontWeight.Bold)
                        Text(
                            fieldInquiryStatusLabel(record.status),
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.background),
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(18.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(28.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f)),
            ) {
                Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Surface(shape = RoundedCornerShape(16.dp), color = statusColor.copy(alpha = 0.14f)) {
                            Icon(
                                Icons.Rounded.EventNote,
                                contentDescription = null,
                                tint = statusColor,
                                modifier = Modifier.size(48.dp).padding(12.dp),
                            )
                        }
                        Column(modifier = Modifier.weight(1f)) {
                            Text(record.title.ifBlank { "Upit za teren" }, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Black)
                            Text(
                                listOf(
                                    formatDateLabel(record.date).ifBlank { record.date },
                                    timeLabel,
                                ).filter { it.isNotBlank() }.joinToString(" · ").ifBlank { "Bez datuma" },
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                            )
                        }
                    }
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        AssistChip(onClick = {}, label = { Text(fieldInquiryStatusLabel(record.status)) })
                        record.meta["serviceLine"].orEmpty().takeIf { it.isNotBlank() }?.let { service ->
                            AssistChip(onClick = {}, label = { Text(service, maxLines = 1, overflow = TextOverflow.Ellipsis) })
                        }
                        record.meta["assignedUserLabels"].orEmpty().takeIf { it.isNotBlank() }?.let { team ->
                            AssistChip(
                                onClick = {},
                                leadingIcon = { Icon(Icons.Rounded.Groups, contentDescription = null, modifier = Modifier.size(16.dp)) },
                                label = { Text(team, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                            )
                        }
                    }
                    Button(
                        onClick = onConvert,
                        enabled = !isLoading && record.meta["companyId"].orEmpty().isNotBlank() && record.status != "converted",
                        shape = RoundedCornerShape(18.dp),
                        modifier = Modifier.fillMaxWidth(),
                    ) {
                        Icon(Icons.Rounded.Work, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(Modifier.width(8.dp))
                        Text("Popuni RN iz plana", fontWeight = FontWeight.Black)
                    }
                }
            }

            DetailSection("Dogovor") {
                DetailRow(Icons.Rounded.Business, "Tvrtka", record.meta["companyName"].orEmpty().ifBlank { "Bez tvrtke" })
                DetailRow(Icons.Rounded.LocationOn, "Lokacija", record.meta["locationName"].orEmpty().ifBlank { "Bez lokacije" })
                record.meta["workOrderNumber"].orEmpty().takeIf { it.isNotBlank() }?.let { number ->
                    DetailRow(Icons.Rounded.Work, "Povezani RN", number)
                }
                record.meta["vehicleLabel"].orEmpty().takeIf { it.isNotBlank() }?.let { vehicle ->
                    DetailRow(Icons.Rounded.Business, "Vozilo", vehicle)
                }
            }

            val contactLines = listOf(
                record.meta["contactName"].orEmpty(),
                record.meta["contactPhone"].orEmpty(),
            ).filter { it.isNotBlank() }
            if (contactLines.isNotEmpty()) {
                DetailSection("Kontakt") {
                    DetailRow(Icons.Rounded.Person, "Kontakt", contactLines.joinToString("\n"))
                }
            }

            record.meta["note"].orEmpty().takeIf { it.isNotBlank() }?.let { note ->
                DetailSection("Opis") {
                    Text(note, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f))
                }
            }

            DetailSection("Dokumenti") {
                if (documents.isEmpty()) {
                    DetailRow(Icons.Rounded.AttachFile, "Prilozi", "Nema dodanih dokumenata.")
                } else {
                    documents.forEach { document ->
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(18.dp),
                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.44f),
                        ) {
                            Row(
                                modifier = Modifier.padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(10.dp),
                            ) {
                                Icon(
                                    if (document.fileType.contains("pdf", ignoreCase = true)) Icons.Rounded.PictureAsPdf else Icons.Rounded.InsertDriveFile,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                )
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(document.fileName, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                    Text(
                                        listOf(document.category, formatFileSizeLabel(document.fileSize)).filter { it.isNotBlank() }.joinToString(" · "),
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                    )
                                }
                                IconButton(onClick = { onDownloadDocument(document) }, enabled = !isLoading) {
                                    Icon(Icons.Rounded.Download, contentDescription = "Preuzmi dokument")
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun MobileRecordDetailScreen(
    record: MobileRecord,
    users: List<WorkOrderUserOption>,
    workOrders: List<WorkOrder>,
    currentUserLabel: String,
    isLoading: Boolean,
    onBack: () -> Unit,
    onReserveVehicle: (MobileRecord, String, String, String, String, String, String, String) -> Unit,
    onRecordVehicleUsage: (MobileRecord, String, String, String, String, String, String, String, String, String, String, String, String, String, List<String>, List<String>, String, Boolean, Boolean, Boolean, Boolean, String, List<WorkOrderUploadFile>, ByteArray?) -> Unit,
    onDownloadVehicleEvidencePdf: (MobileRecord) -> Unit,
    onDownloadOfferPdf: (MobileRecord) -> Unit,
    onDownloadDocument: (MobileRecord) -> Unit,
    onConvertFieldInquiry: (MobileRecord) -> Unit,
    onDownloadFieldInquiryDocument: (MobileRecord, FieldInquiryDocument) -> Unit,
    onDownloadTrainingDocument: (MobileRecord, MobileTrainingDocument) -> Unit,
) {
    BackHandler(onBack = onBack)
    var reservationDialogOpen by remember(record.id) { mutableStateOf(false) }
    var usageDialogMode by remember(record.id) { mutableStateOf<String?>(null) }
    val displayStatus = mobileRecordStatusLabel(record)
    if (reservationDialogOpen) {
        VehicleReservationDialog(
            vehicle = record,
            users = users,
            currentUserLabel = currentUserLabel,
            isLoading = isLoading,
            onDismiss = { reservationDialogOpen = false },
            onConfirm = { purpose, startAt, endAt, destination, reservedForUserId, reservedForLabel, note ->
                reservationDialogOpen = false
                onReserveVehicle(record, purpose, startAt, endAt, destination, reservedForUserId, reservedForLabel, note)
            },
        )
    }
    usageDialogMode?.let { mode ->
        VehicleUsageDialog(
            vehicle = record,
            mode = mode,
            workOrders = workOrders,
            users = users,
            currentUserLabel = currentUserLabel,
            isLoading = isLoading,
            onDismiss = { usageDialogMode = null },
            onConfirm = { selectedMode, tripId, actionAt, odometerKm, departureAt, returnAt, startKm, endKm, destination, reservationId, linkedWorkOrderId, linkedWorkOrderNumber, performedBy, driverUserIds, driverLabels, vehicleCondition, vehicleClean, documentsPresent, fuelOk, damageNoted, note, files, signaturePngBytes ->
                usageDialogMode = null
                onRecordVehicleUsage(
                    record,
                    selectedMode,
                    tripId,
                    actionAt,
                    odometerKm,
                    departureAt,
                    returnAt,
                    startKm,
                    endKm,
                    destination,
                    reservationId,
                    linkedWorkOrderId,
                    linkedWorkOrderNumber,
                    performedBy,
                    driverUserIds,
                    driverLabels,
                    vehicleCondition,
                    vehicleClean,
                    documentsPresent,
                    fuelOk,
                    damageNoted,
                    note,
                    files,
                    signaturePngBytes,
                )
            },
        )
    }
    if (record.kind == "field_inquiry") {
        FieldInquiryMobileDetailScreen(
            record = record,
            isLoading = isLoading,
            onBack = onBack,
            onConvert = { onConvertFieldInquiry(record) },
            onDownloadDocument = { document -> onDownloadFieldInquiryDocument(record, document) },
        )
        return
    }
    Scaffold(
        topBar = {
            TopAppBar(
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
                    }
                },
                title = {
                    Column {
                        Text(recordKindLabel(record.kind), fontWeight = FontWeight.Bold)
                        Text(
                            displayStatus.ifBlank { "Mobilni zapis" },
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.background),
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(18.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(28.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
            ) {
                Column(
                    modifier = Modifier.padding(18.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                ) {
                    Surface(shape = RoundedCornerShape(18.dp), color = MaterialTheme.colorScheme.surface.copy(alpha = 0.72f)) {
                        Icon(
                            recordIcon(record),
                            contentDescription = null,
                            modifier = Modifier
                                .size(50.dp)
                                .padding(13.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                    }
                    Text(
                        record.title.ifBlank { "Zapis" },
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.Black,
                    )
                    if (record.subtitle.isNotBlank()) {
                        Text(record.subtitle, style = MaterialTheme.typography.bodyLarge)
                    }
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        if (displayStatus.isNotBlank()) {
                            AssistChip(onClick = {}, label = { Text(displayStatus) })
                        }
                        if (record.date.isNotBlank()) {
                            AssistChip(
                                onClick = {},
                                leadingIcon = { Icon(Icons.Rounded.CalendarMonth, contentDescription = null, modifier = Modifier.size(16.dp)) },
                                label = { Text(formatDateLabel(record.date).ifBlank { record.date.take(10) }) },
                            )
                        }
                    }
                    if (record.kind == "vehicle") {
                        val canUseMyTrip = vehicleCanUseMyTrip(record, currentUserLabel)
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Button(
                                onClick = { reservationDialogOpen = true },
                                enabled = !isLoading,
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.CalendarMonth, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Rezerviraj", fontWeight = FontWeight.Black)
                            }
                            OutlinedButton(
                                onClick = { usageDialogMode = "trip" },
                                enabled = !isLoading && canUseMyTrip,
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.Work, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("My Trip", fontWeight = FontWeight.Black)
                            }
                            OutlinedButton(
                                onClick = { onDownloadVehicleEvidencePdf(record) },
                                enabled = !isLoading,
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.Description, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("PDF evidencija", fontWeight = FontWeight.Black)
                            }
                        }
                    }
                    if (record.kind == "offer") {
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            OutlinedButton(
                                onClick = { onDownloadOfferPdf(record) },
                                enabled = !isLoading,
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Preuzmi PDF", fontWeight = FontWeight.Black)
                            }
                        }
                    }
                    if (record.kind == "document") {
                        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            OutlinedButton(
                                onClick = { onDownloadDocument(record) },
                                enabled = !isLoading && mobileDocumentCanDownload(record),
                                shape = RoundedCornerShape(14.dp),
                                contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                            ) {
                                Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Preuzmi", fontWeight = FontWeight.Black)
                            }
                        }
                    }
                }
            }

            if (record.kind == "vehicle") {
                val reservations = parseVehicleReservations(record)
                val trips = parseVehicleTrips(record)
                DetailSection("Raspored vozila") {
                    if (reservations.isEmpty()) {
                        DetailRow(Icons.Rounded.CalendarMonth, "Rezervacije", "Nema aktivnih rezervacija.")
                    } else {
                        reservations.take(6).forEach { reservation ->
                            DetailRow(
                                Icons.Rounded.CalendarMonth,
                                reservation.purpose.ifBlank { "Rezervacija" },
                                listOf(
                                    "${formatDateTimeLabel(reservation.startAt)} - ${formatDateTimeLabel(reservation.endAt)}",
                                    reservation.userLabel,
                                    reservation.destination,
                                    vehicleStatusLabel(reservation.status),
                                ).filter { it.isNotBlank() }.joinToString("\n"),
                            )
                        }
                    }
                }
                DetailSection("Evidencija putovanja") {
                    if (trips.isEmpty()) {
                        DetailRow(Icons.Rounded.Description, "Putovanja", "Nema evidentiranih putovanja.")
                    } else {
                        trips.take(8).forEach { trip ->
                            DetailRow(
                                Icons.Rounded.Description,
                                trip.destination.ifBlank { "Putovanje vozila" },
                                listOf(
                                    "Polazak: ${formatVehicleTripDatePart(trip.departureAt)} ${formatVehicleTripTimePart(trip.departureAt)}".trim(),
                                    if (trip.returnAt.isNotBlank()) {
                                        "Povratak: ${formatVehicleTripDatePart(trip.returnAt)} ${formatVehicleTripTimePart(trip.returnAt)}".trim()
                                    } else {
                                        "Povratak: otvoreno"
                                    },
                                    trip.drivers.takeIf { it.isNotBlank() }?.let { "Vozači: $it" }.orEmpty(),
                                    trip.linkedWorkOrderNumber.takeIf { it.isNotBlank() }?.let { "RN: $it" }.orEmpty(),
                                    listOf(
                                        trip.startKm.takeIf { it.isNotBlank() }?.let { "Početna $it km" }.orEmpty(),
                                        trip.endKm.takeIf { it.isNotBlank() }?.let { "Krajnja $it km" }.orEmpty(),
                                    ).filter { it.isNotBlank() }.joinToString(" | "),
                                    trip.condition.takeIf { it.isNotBlank() }?.let { "Stanje: $it" }.orEmpty(),
                                    if (trip.documentCount > 0) {
                                        "Prilozi: ${trip.documentLabels.ifBlank { "${trip.documentCount} dok." }}"
                                    } else {
                                        ""
                                    },
                                ).filter { it.isNotBlank() }.joinToString("\n"),
                            )
                        }
                    }
                }
            }

            if (record.kind == "offer") {
                DetailSection("Ponuda") {
                    DetailRow(Icons.Rounded.Description, "Broj ponude", record.meta["offerNumber"].orEmpty().ifBlank { record.title })
                    DetailRow(Icons.Rounded.Business, "Tvrtka", record.meta["companyName"].orEmpty().ifBlank { "Nije upisano" })
                    DetailRow(Icons.Rounded.LocationOn, "Lokacija", record.meta["locationName"].orEmpty().ifBlank { "Sve lokacije / nije upisano" })
                    DetailRow(Icons.Rounded.ListAlt, "Vrsta ponude", record.meta["serviceLine"].orEmpty().ifBlank { "Nije upisano" })
                    DetailRow(Icons.Rounded.CalendarMonth, "Datum ponude", formatDateLabel(record.meta["offerDate"].orEmpty()).ifBlank { record.meta["offerDate"].orEmpty().ifBlank { "Nije upisano" } })
                    DetailRow(Icons.Rounded.CalendarMonth, "Vrijedi do", formatDateLabel(record.meta["validUntil"].orEmpty()).ifBlank { record.meta["validUntil"].orEmpty().ifBlank { "Nije upisano" } })
                    DetailRow(Icons.Rounded.Description, "Bez PDV-a", record.meta["amountWithoutVat"].orEmpty().ifBlank { "0,00 EUR" })
                    DetailRow(Icons.Rounded.CheckCircle, "Ukupno s PDV-om", record.meta["totalWithVat"].orEmpty().ifBlank { "0,00 EUR" })
                }
                val contactLines = listOf(
                    record.meta["contactName"].orEmpty(),
                    record.meta["contactEmail"].orEmpty(),
                    record.meta["contactPhone"].orEmpty(),
                ).filter { it.isNotBlank() }
                if (contactLines.isNotEmpty()) {
                    DetailSection("Kontakt") {
                        DetailRow(Icons.Rounded.Person, "Kontakt osoba", contactLines.joinToString("\n"))
                    }
                }
            }

            if (record.kind == "training") {
                TrainingPersonDetailSection(record)
                TrainingRecordDetailSection(
                    record = record,
                    onDownloadDocument = { document -> onDownloadTrainingDocument(record, document) },
                )
            }

            if (record.kind != "training") {
                DetailSection("Osnovno") {
                    DetailRow(recordIcon(record), "Vrsta", recordKindLabel(record.kind))
                    DetailRow(Icons.Rounded.CheckCircle, "Status", displayStatus.ifBlank { "Nije upisano" })
                    DetailRow(Icons.Rounded.CalendarMonth, "Datum", formatDateLabel(record.date).ifBlank { record.date.ifBlank { "Nije upisano" } })
                    if (record.relatedId.isNotBlank()) {
                        DetailRow(Icons.Rounded.Work, "Povezani zapis", record.relatedId)
                    }
                    if (record.coordinates.isNotBlank()) {
                        DetailRow(Icons.Rounded.Map, "Koordinate", record.coordinates)
                    }
                }

                val visibleMeta = when (record.kind) {
                    "offer" -> record.meta.filterKeys { key -> key !in offerDetailMetaKeys }
                    "vehicle" -> record.meta.filterKeys { key -> key !in vehicleDetailMetaKeys }
                    else -> record.meta
                }.filter { entry -> shouldShowMobileRecordMeta(entry.key, entry.value) }
                if (visibleMeta.isNotEmpty()) {
                    DetailSection("Podaci") {
                        visibleMeta.entries
                            .sortedBy { entry -> entry.key }
                            .forEach { entry ->
                                DetailRow(
                                    Icons.Rounded.Business,
                                    formatRecordMetaLabel(entry.key),
                                    entry.value.ifBlank { "Nije upisano" },
                                )
                            }
                    }
                }
            }
        }
    }
}

@Composable
private fun TrainingPersonDetailSection(record: MobileRecord) {
    val oib = trainingPersonOibLabel(record)
    val companyName = trainingCompanyLabel(record)
    DetailSection("Osoba") {
        DetailRow(Icons.Rounded.Person, "Ime i prezime", record.title.ifBlank { "Nije upisano" })
        DetailRow(Icons.Rounded.Business, "Tvrtka", companyName.ifBlank { "Nije upisano" })
        if (oib.isNotBlank()) {
            DetailRow(Icons.Rounded.Badge, "OIB", oib)
        }
        record.meta["locationName"].orEmpty().takeIf { it.isNotBlank() }?.let { location ->
            DetailRow(Icons.Rounded.LocationOn, "Lokacija", location)
        }
        record.meta["jobTitle"].orEmpty().takeIf { it.isNotBlank() }?.let { job ->
            DetailRow(Icons.Rounded.Work, "Radno mjesto", job)
        }
        record.meta["workPlace"].orEmpty().takeIf { it.isNotBlank() && it != record.meta["jobTitle"].orEmpty() }?.let { workplace ->
            DetailRow(Icons.Rounded.Work, "Poslovi", workplace)
        }
        record.meta["email"].orEmpty().takeIf { it.isNotBlank() }?.let { email ->
            DetailRow(Icons.Rounded.Mail, "Email", email)
        }
        record.meta["phone"].orEmpty().takeIf { it.isNotBlank() }?.let { phone ->
            DetailRow(Icons.Rounded.Call, "Telefon", phone)
        }
    }
}

@Composable
private fun TrainingRecordDetailSection(
    record: MobileRecord,
    onDownloadDocument: (MobileTrainingDocument) -> Unit,
) {
    val items = remember(record.meta["trainingItemsJson"]) { parseTrainingItems(record) }
    val documents = remember(record.meta["documentsJson"]) { parseTrainingDocuments(record) }

    DetailSection("Osposobljavanja") {
        if (items.isEmpty()) {
            DetailRow(Icons.Rounded.Fingerprint, "Stavke", "Nema upisanih osposobljavanja.")
        } else {
            items.forEach { item ->
                val accent = trainingStatusColor(item.status)
                val document = trainingItemDocument(item)
                val hasDocument = document?.id?.isNotBlank() == true
                val periodText = trainingItemPeriodText(item)
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = accent.copy(alpha = 0.07f),
                    border = BorderStroke(1.dp, accent.copy(alpha = 0.14f)),
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        Column(
                            modifier = Modifier.weight(1f),
                            verticalArrangement = Arrangement.spacedBy(4.dp),
                        ) {
                            Text(
                                item.label,
                                fontWeight = FontWeight.Black,
                                maxLines = 2,
                                overflow = TextOverflow.Ellipsis,
                            )
                            if (periodText.isNotBlank()) {
                                Text(
                                    periodText,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                                    style = MaterialTheme.typography.bodySmall,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            }
                        }
                        IconButton(
                            onClick = { document?.let(onDownloadDocument) },
                            enabled = hasDocument,
                        ) {
                            Icon(
                                Icons.Rounded.Download,
                                contentDescription = if (hasDocument) "Preuzmi PDF" else "Nema PDF-a",
                                tint = if (hasDocument) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.28f),
                            )
                        }
                    }
                }
            }
        }
    }

    if (documents.isNotEmpty()) {
        DetailSection("Dokumenti") {
            documents.forEach { document ->
                OutlinedButton(
                    onClick = { onDownloadDocument(document) },
                    enabled = document.id.isNotBlank(),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(14.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 10.dp),
                ) {
                    Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(8.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(document.fileName, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text(
                            listOf(document.category, document.createdAt.takeIf { it.isNotBlank() }?.let { createdAt -> formatDateLabel(createdAt).ifBlank { createdAt } }.orEmpty())
                                .filter { it.isNotBlank() }
                                .joinToString(" · ")
                                .ifBlank { "Dokument osposobljavanja" },
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun VehicleReservationDialog(
    vehicle: MobileRecord,
    users: List<WorkOrderUserOption>,
    currentUserLabel: String,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onConfirm: (String, String, String, String, String, String, String) -> Unit,
) {
    val today = remember { LocalDate.now().toString() }
    val initialStartTime = remember(vehicle.id) { defaultReservationStartTime() }
    val initialEnd = remember(vehicle.id, today, initialStartTime) { addReservationMinutes(today, initialStartTime, 60) }
    var startDate by remember(vehicle.id) { mutableStateOf(today) }
    var startTime by remember(vehicle.id) { mutableStateOf(initialStartTime) }
    var endDate by remember(vehicle.id) { mutableStateOf(initialEnd.first) }
    var endTime by remember(vehicle.id) { mutableStateOf(initialEnd.second) }
    var purpose by remember(vehicle.id) { mutableStateOf("Službeni put") }
    var destination by remember(vehicle.id) { mutableStateOf("") }
    val userOptions = remember(users) {
        listOf("" to "Ručno upisano") + users.map { user ->
            user.id to user.label.ifBlank { user.fullName.ifBlank { user.email } }
        }
    }
    var reservedForUserId by remember(vehicle.id, currentUserLabel, users) {
        mutableStateOf(
            users.firstOrNull { user ->
                listOf(user.label, user.fullName, user.email).any { it.equals(currentUserLabel, ignoreCase = true) }
            }?.id.orEmpty(),
        )
    }
    var reservedForLabel by remember(vehicle.id, currentUserLabel) { mutableStateOf(currentUserLabel) }
    var note by remember(vehicle.id) { mutableStateOf("") }
    val reservationRangeValid = remember(startDate, startTime, endDate, endTime) {
        isReservationRangeValid(startDate, startTime, endDate, endTime)
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        modifier = Modifier.fillMaxWidth(0.96f),
        properties = DialogProperties(usePlatformDefaultWidth = false),
        title = {
            Column {
                Text("Rezervacija vozila", fontWeight = FontWeight.Black)
                Text(
                    vehicle.title,
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 620.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Text("Termin rezervacije", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    WorkOrderDatePickerField(
                        label = "Početak",
                        value = startDate,
                        onChange = { startDate = it },
                        enabled = !isLoading,
                        modifier = Modifier.weight(1.28f),
                    )
                    WorkOrderSelectField(
                        label = "Vrijeme",
                        value = startTime,
                        valueLabel = startTime,
                        options = reservationTimeOptions,
                        enabled = !isLoading,
                        onSelect = { nextTime -> startTime = nextTime },
                        modifier = Modifier.weight(0.88f),
                    )
                }
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    WorkOrderDatePickerField(
                        label = "Kraj",
                        value = endDate,
                        onChange = { endDate = it },
                        enabled = !isLoading,
                        modifier = Modifier.weight(1.28f),
                    )
                    WorkOrderSelectField(
                        label = "Vrijeme",
                        value = endTime,
                        valueLabel = endTime,
                        options = reservationTimeOptions,
                        enabled = !isLoading,
                        onSelect = { nextTime -> endTime = nextTime },
                        modifier = Modifier.weight(0.88f),
                    )
                }
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    listOf("1 h" to 60L, "2 h" to 120L, "4 h" to 240L).forEach { (label, minutes) ->
                        FilterChip(
                            selected = false,
                            enabled = !isLoading,
                            onClick = {
                                val next = addReservationMinutes(startDate, startTime, minutes)
                                endDate = next.first
                                endTime = next.second
                            },
                            label = { Text(label, fontWeight = FontWeight.Bold) },
                        )
                    }
                    FilterChip(
                        selected = false,
                        enabled = !isLoading,
                        onClick = {
                            startTime = "08:00"
                            endDate = startDate
                            endTime = "17:00"
                        },
                        label = { Text("Radni dan", fontWeight = FontWeight.Bold) },
                    )
                    AssistChip(
                        onClick = {},
                        enabled = false,
                        label = { Text("Korak 15 min") },
                    )
                }
                AnimatedVisibility(!reservationRangeValid) {
                    Text(
                        "Kraj rezervacije mora biti nakon početka.",
                        color = MaterialTheme.colorScheme.error,
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.Bold,
                    )
                }
                WorkOrderTextField("Svrha rezervacije", purpose, { purpose = it }, !isLoading)
                WorkOrderTextField("Odredište", destination, { destination = it }, !isLoading)
                WorkOrderSelectField(
                    label = "Korisnik vozila",
                    value = reservedForUserId,
                    valueLabel = userOptions.firstOrNull { it.first == reservedForUserId }?.second ?: "Ručno upisano",
                    options = userOptions,
                    enabled = !isLoading && users.isNotEmpty(),
                    onSelect = { next ->
                        reservedForUserId = next
                        if (next.isNotBlank()) {
                            reservedForLabel = userOptions.firstOrNull { it.first == next }?.second.orEmpty()
                        }
                    },
                )
                WorkOrderTextField("Ime korisnika vozila", reservedForLabel, { reservedForLabel = it }, !isLoading)
                WorkOrderTextField("Napomena", note, { note = it }, !isLoading)
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    onConfirm(
                        purpose.trim(),
                        formatReservationDateTime(startDate, startTime),
                        formatReservationDateTime(endDate, endTime),
                        destination.trim(),
                        reservedForUserId.trim(),
                        reservedForLabel.trim(),
                        note.trim(),
                    )
                },
                enabled = !isLoading && purpose.isNotBlank() && startDate.isNotBlank() && endDate.isNotBlank() && reservationRangeValid,
                shape = RoundedCornerShape(16.dp),
            ) {
                Text("Spremi rezervaciju", fontWeight = FontWeight.Black)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss, enabled = !isLoading) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun VehicleUsageDialog(
    vehicle: MobileRecord,
    mode: String,
    workOrders: List<WorkOrder>,
    users: List<WorkOrderUserOption>,
    currentUserLabel: String,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onConfirm: (String, String, String, String, String, String, String, String, String, String, String, String, String, List<String>, List<String>, String, Boolean, Boolean, Boolean, Boolean, String, List<WorkOrderUploadFile>, ByteArray?) -> Unit,
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var uploadError by remember(vehicle.id, mode) { mutableStateOf("") }
    val returnFiles = remember(vehicle.id, mode) { mutableStateListOf<WorkOrderUploadFile>() }
    var signatureStrokes by remember(vehicle.id, mode) { mutableStateOf<List<List<Offset>>>(emptyList()) }
    var activeSignatureStroke by remember(vehicle.id, mode) { mutableStateOf<List<Offset>>(emptyList()) }
    var signaturePadSize by remember(vehicle.id, mode) { mutableStateOf(androidx.compose.ui.geometry.Size.Zero) }
    val returnDocumentLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        scope.launch {
            runCatching {
                buildVehicleUsageAttachmentUploadFiles(context, uris, returnFiles.size)
            }.onSuccess { uploads ->
                returnFiles.addAll(uploads)
                uploadError = ""
            }.onFailure { error ->
                uploadError = error.message ?: "Ne mogu dodati dokumente povrata."
            }
        }
    }
    val returnPhotoLauncher = rememberLauncherForActivityResult(ActivityResultContracts.GetMultipleContents()) { uris ->
        if (uris.isEmpty()) return@rememberLauncherForActivityResult
        scope.launch {
            runCatching {
                buildVehicleUsageAttachmentUploadFiles(context, uris, returnFiles.size)
            }.onSuccess { uploads ->
                returnFiles.addAll(uploads)
                uploadError = ""
            }.onFailure { error ->
                uploadError = error.message ?: "Ne mogu dodati fotografije povrata."
            }
        }
    }
    var pendingReturnCameraUri by remember(vehicle.id, mode) { mutableStateOf<Uri?>(null) }
    val returnCameraLauncher = rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()) { success ->
        val uri = pendingReturnCameraUri
        pendingReturnCameraUri = null
        if (!success || uri == null) return@rememberLauncherForActivityResult
        scope.launch {
            runCatching {
                buildVehicleUsageAttachmentUploadFiles(context, listOf(uri), returnFiles.size)
            }.onSuccess { uploads ->
                returnFiles.addAll(uploads)
                uploadError = ""
            }.onFailure { error ->
                uploadError = error.message ?: "Ne mogu dodati fotografiju povrata."
            }
        }
    }
    val returnScannerLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartIntentSenderForResult()) { result ->
        if (result.resultCode != Activity.RESULT_OK) return@rememberLauncherForActivityResult
        val scanResult = GmsDocumentScanningResult.fromActivityResultIntent(result.data)
        val pdfUri = scanResult?.pdf?.uri ?: run {
            uploadError = "Sken nije vratio PDF dokument."
            return@rememberLauncherForActivityResult
        }
        scope.launch {
            runCatching {
                buildVehicleUsageAttachmentUploadFiles(context, listOf(pdfUri), returnFiles.size)
            }.onSuccess { uploads ->
                returnFiles.addAll(uploads)
                uploadError = ""
            }.onFailure { error ->
                uploadError = error.message ?: "Ne mogu dodati sken povrata."
            }
        }
    }
    val startReturnScan: () -> Unit = {
        val activity = context.findFragmentActivity()
        if (activity == null) {
            uploadError = "Skeniranje dokumenta nije dostupno u ovom prikazu."
        } else {
            val options = GmsDocumentScannerOptions.Builder()
                .setGalleryImportAllowed(true)
                .setPageLimit(30)
                .setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_PDF)
                .setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL)
                .build()
            GmsDocumentScanning.getClient(options)
                .getStartScanIntent(activity)
                .addOnSuccessListener { intentSender ->
                    returnScannerLauncher.launch(IntentSenderRequest.Builder(intentSender).build())
                }
                .addOnFailureListener { error ->
                    uploadError = error.message ?: "Ne mogu pokrenuti skeniranje dokumenta."
                }
        }
    }
    val reservations = remember(vehicle.meta["reservationsJson"], mode) { parseVehicleReservations(vehicle) }
    val trips = remember(vehicle.meta["activityItemsJson"], mode) { parseVehicleTrips(vehicle) }
    val userOptions = remember(users) {
        users
            .filter { user -> user.id.isNotBlank() && vehicleUserOptionLabel(user).isNotBlank() }
            .distinctBy { user -> user.id }
    }
    val userOptionIds = remember(userOptions) {
        userOptions.map { it.id }.filter(String::isNotBlank).toSet()
    }
    val currentUserOption = remember(userOptions, currentUserLabel) {
        vehicleCurrentUserOption(userOptions, currentUserLabel)
    }
    val currentUserId = currentUserOption?.id.orEmpty()
    val openTrip = remember(trips, currentUserLabel, currentUserId) {
        trips.firstOrNull { trip ->
            vehicleTripIsOpen(trip) && vehicleTripBelongsToCurrentUser(trip, currentUserLabel, currentUserId)
        } ?: trips.firstOrNull { trip ->
            vehicleTripIsOpen(trip)
        }
    }
    val hasBlockingOpenTrip = openTrip != null && !vehicleTripBelongsToCurrentUser(openTrip, currentUserLabel, currentUserId)
    val eligibleReservations = remember(reservations, currentUserLabel, currentUserId) {
        reservations.filter { reservation ->
            vehicleReservationBelongsToCurrentUser(reservation, currentUserLabel, currentUserId) &&
                vehicleReservationAllowsMyTripNow(reservation)
        }
    }
    val defaultReservation = remember(reservations, eligibleReservations, openTrip?.reservationId, vehicle.meta["nextReservationId"]) {
        val openReservation = openTrip?.reservationId
            ?.takeIf(String::isNotBlank)
            ?.let { openReservationId -> reservations.firstOrNull { it.id == openReservationId } }
        openReservation
            ?: eligibleReservations.firstOrNull { it.status.equals("checked_out", ignoreCase = true) }
            ?: eligibleReservations.firstOrNull { it.id == vehicle.meta["nextReservationId"] }
            ?: eligibleReservations.firstOrNull()
    }
    val destinationSuggestions = remember(vehicle.id, mode, trips, reservations, defaultReservation?.destination, openTrip?.destination) {
        val primaryDestinations = listOf(openTrip?.destination.orEmpty(), defaultReservation?.destination.orEmpty())
        (
            primaryDestinations +
                reservations.map { it.destination } +
                trips.map { it.destination }
            )
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .take(5)
    }
    fun dateInputValue(value: String, fallback: String = ""): String {
        val parsed = parseVehicleDateTime(value)
        if (parsed != null) return parsed.toLocalDate().toString()
        return value.take(10).ifBlank { fallback }
    }
    fun timeInputValue(value: String, fallback: String = ""): String {
        val parsed = parseVehicleDateTime(value)
        if (parsed != null) return parsed.toLocalTime().format(DateTimeFormatter.ofPattern("HH:mm"))
        return value.substringAfter('T', "").take(5).ifBlank { fallback }
    }
    val nowVehicleUsageAt = remember(vehicle.id, mode, openTrip?.id) { LocalDateTime.now().toString() }
    val initialDepartureAt = openTrip?.departureAt.orEmpty()
    val initialReturnAt = openTrip?.returnAt.orEmpty().ifBlank { if (openTrip != null) nowVehicleUsageAt else "" }
    var departureDate by remember(vehicle.id, openTrip?.id) { mutableStateOf(dateInputValue(initialDepartureAt, LocalDate.now().toString())) }
    var departureTime by remember(vehicle.id, openTrip?.id) { mutableStateOf(timeInputValue(initialDepartureAt, defaultVehicleUsageTime())) }
    var returnDate by remember(vehicle.id, openTrip?.id) { mutableStateOf(dateInputValue(initialReturnAt)) }
    var returnTime by remember(vehicle.id, openTrip?.id) { mutableStateOf(timeInputValue(initialReturnAt)) }
    var startKm by remember(vehicle.id, openTrip?.id) { mutableStateOf(openTrip?.startKm.orEmpty().ifBlank { vehicle.meta["odometerKm"].orEmpty() }) }
    var endKm by remember(vehicle.id, openTrip?.id) { mutableStateOf(openTrip?.endKm.orEmpty()) }
    var destination by remember(vehicle.id, mode, defaultReservation?.destination, openTrip?.destination) {
        val initialDestination = openTrip?.destination.orEmpty().ifBlank { defaultReservation?.destination.orEmpty() }
        mutableStateOf(initialDestination)
    }
    var reservationId by remember(vehicle.id, openTrip?.reservationId, defaultReservation?.id) {
        mutableStateOf(openTrip?.reservationId.orEmpty().ifBlank { defaultReservation?.id.orEmpty() })
    }
    var linkedWorkOrderId by remember(vehicle.id, mode, openTrip?.linkedWorkOrderId) {
        mutableStateOf(openTrip?.linkedWorkOrderId.orEmpty())
    }
    val selectedReservation = remember(reservations, reservationId, defaultReservation?.id) {
        reservations.firstOrNull { it.id == reservationId } ?: defaultReservation
    }
    val reservationInWindow = selectedReservation?.let { vehicleReservationAllowsMyTripNow(it) } == true
    val initialDriverIds = remember(vehicle.id, openTrip?.id, defaultReservation?.id, currentUserId, userOptionIds) {
        val seedIds = openTrip?.driverUserIds.orEmpty() + defaultReservation?.userIds.orEmpty() + listOf(currentUserId)
        seedIds
            .map { it.trim() }
            .filter { it.isNotBlank() && it in userOptionIds }
            .distinct()
    }
    var selectedDriverIds by remember(vehicle.id, mode, openTrip?.id, defaultReservation?.id, currentUserId, userOptionIds) {
        mutableStateOf(initialDriverIds)
    }
    LaunchedEffect(reservationId, selectedReservation?.id, openTrip?.id, userOptionIds) {
        if (openTrip == null) {
            val reservationUserIds = selectedReservation?.userIds.orEmpty()
                .map { it.trim() }
                .filter { it.isNotBlank() && it in userOptionIds }
                .distinct()
            if (reservationUserIds.isNotEmpty()) {
                selectedDriverIds = reservationUserIds
            }
        }
    }
    var manualPerformedBy by remember(vehicle.id, mode, currentUserLabel, defaultReservation?.userLabel, openTrip?.drivers) {
        mutableStateOf(defaultReservation?.userLabel.orEmpty().ifBlank { openTrip?.drivers.orEmpty().ifBlank { currentUserLabel } })
    }
    val selectedDriverLabels = remember(userOptions, selectedDriverIds) {
        vehicleUserLabelsForIds(userOptions, selectedDriverIds)
    }
    val fallbackDriverLabels = remember(currentUserLabel, defaultReservation?.userLabel, openTrip?.drivers) {
        listOf(openTrip?.drivers.orEmpty(), defaultReservation?.userLabel.orEmpty(), currentUserLabel)
            .flatMap { value -> value.split(",") }
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
    }
    val finalDriverLabels = if (userOptions.isNotEmpty()) {
        selectedDriverLabels.ifEmpty { fallbackDriverLabels }
    } else {
        listOf(manualPerformedBy.trim()).filter(String::isNotBlank).ifEmpty { fallbackDriverLabels }
    }
    val performedBy = finalDriverLabels.joinToString(", ")
    var vehicleCondition by remember(vehicle.id, openTrip?.id) { mutableStateOf(openTrip?.condition.orEmpty().ifBlank { "Uredno" }) }
    var vehicleClean by remember(vehicle.id, mode) { mutableStateOf(true) }
    var documentsPresent by remember(vehicle.id, mode) { mutableStateOf(true) }
    var fuelOk by remember(vehicle.id, mode) { mutableStateOf(true) }
    var damageNoted by remember(vehicle.id, mode) { mutableStateOf(false) }
    var note by remember(vehicle.id, mode) { mutableStateOf("") }
    val title = "My Trip"
    val reservationOptions = remember(eligibleReservations, defaultReservation?.id) {
        val options = if (defaultReservation != null && eligibleReservations.none { it.id == defaultReservation.id }) {
            listOf(defaultReservation) + eligibleReservations
        } else {
            eligibleReservations
        }
        options.distinctBy { it.id }.map { reservation ->
            reservation.id to listOf(
                reservation.purpose.ifBlank { "Rezervacija" },
                formatDateTimeLabel(reservation.startAt),
                reservation.userLabel,
            ).filter { it.isNotBlank() }.joinToString(" - ")
        }
    }
    fun parseUsageLocalDate(value: String): LocalDate? =
        runCatching { LocalDate.parse(value.take(10)) }.getOrNull()

    val workOrderOptions = remember(
        workOrders,
        openTrip?.linkedWorkOrderId,
        openTrip?.linkedWorkOrderNumber,
        departureDate,
        returnDate,
        selectedReservation?.endAt,
        finalDriverLabels,
    ) {
        val rangeStart = parseUsageLocalDate(departureDate)
        val rangeEnd = parseUsageLocalDate(returnDate)
            ?: selectedReservation?.endAt?.let { parseVehicleDateTime(it)?.toLocalDate() }
            ?: rangeStart
        val driverFilters = finalDriverLabels
            .map { it.trim() }
            .filter(String::isNotBlank)
            .distinctBy { it.lowercase(Locale.getDefault()) }
        val baseOptions = workOrders
            .filter { workOrder ->
                val executionDate = workOrder.parsedExecutionDate
                val dateMatches = if (rangeStart != null && rangeEnd != null) {
                    executionDate != null && !executionDate.isBefore(rangeStart) && !executionDate.isAfter(rangeEnd)
                } else {
                    true
                }
                val executorMatches = driverFilters.isEmpty() || workOrder.executors.any { executor ->
                    driverFilters.any { driver -> vehiclePersonMatchesCurrentUser(executor, driver) }
                }
                dateMatches && executorMatches
            }
            .sortedWith(
                compareByDescending<WorkOrder> { workOrder -> workOrder.parsedExecutionDate == rangeStart }
                    .thenByDescending { workOrder ->
                        driverFilters.isNotEmpty() && workOrder.executors.any { executor ->
                            driverFilters.any { driver -> vehiclePersonMatchesCurrentUser(executor, driver) }
                        }
                    }
                    .thenBy { workOrder -> workOrder.displayNumber },
            )
            .take(250)
            .map { workOrder ->
                workOrder.id to listOf(
                    workOrder.displayNumber,
                    workOrder.companyName,
                    workOrder.locationName,
                ).filter { it.isNotBlank() }.joinToString(" - ")
            }
        val existingLinked = openTrip?.linkedWorkOrderId.orEmpty()
        val existingLabel = openTrip?.linkedWorkOrderNumber.orEmpty()
        val merged = if (existingLinked.isNotBlank() && baseOptions.none { it.first == existingLinked }) {
            listOf(existingLinked to existingLabel.ifBlank { "Povezani RN" }) + baseOptions
        } else {
            baseOptions
        }
        listOf("" to "Bez povezanog RN-a") + merged
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        modifier = Modifier.fillMaxWidth(0.96f),
        properties = DialogProperties(usePlatformDefaultWidth = false),
        title = {
            Column {
                Text(title, fontWeight = FontWeight.Black)
                Text(
                    vehicle.title,
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 620.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Text("My Trip podaci", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                if (hasBlockingOpenTrip) {
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                        color = Color(0xFFFFEDD5),
                    ) {
                        Text(
                            "Vozilo ima otvoren put kod drugog korisnika. Novi My Trip nije moguć dok se taj put ne zatvori.",
                            modifier = Modifier.padding(12.dp),
                            style = MaterialTheme.typography.bodyMedium,
                            color = Color(0xFF9A3412),
                            fontWeight = FontWeight.SemiBold,
                        )
                    }
                } else if (defaultReservation == null) {
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                        color = Color(0xFFFFF7ED),
                    ) {
                        Text(
                            "My Trip je dostupan samo za tvoju rezervaciju vozila, od sat vremena prije početka do sat vremena nakon završetka.",
                            modifier = Modifier.padding(12.dp),
                            style = MaterialTheme.typography.bodyMedium,
                            color = Color(0xFF9A3412),
                            fontWeight = FontWeight.SemiBold,
                        )
                    }
                } else if (!reservationInWindow) {
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                        color = Color(0xFFFFF7ED),
                    ) {
                        Text(
                            "Rezervacija nije u dozvoljenom My Trip prozoru. Možeš raditi sat vremena prije i sat vremena nakon termina.",
                            modifier = Modifier.padding(12.dp),
                            style = MaterialTheme.typography.bodyMedium,
                            color = Color(0xFF9A3412),
                            fontWeight = FontWeight.SemiBold,
                        )
                    }
                }
                if (reservationOptions.isNotEmpty()) {
                    WorkOrderSelectField(
                        label = "Rezervacija",
                        value = reservationId,
                        valueLabel = reservationOptions.firstOrNull { it.first == reservationId }?.second
                            ?: defaultReservation?.purpose.orEmpty().ifBlank { "Odaberi rezervaciju" },
                        options = reservationOptions,
                        enabled = !isLoading && openTrip == null,
                        onSelect = { reservationId = it },
                    )
                }
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    WorkOrderDatePickerField(
                        label = "Datum polaska",
                        value = departureDate,
                        onChange = { departureDate = it },
                        enabled = !isLoading,
                        modifier = Modifier.weight(1.28f),
                    )
                    WorkOrderSelectField(
                        label = "Vrijeme polaska",
                        value = departureTime,
                        valueLabel = departureTime.ifBlank { "Odaberi" },
                        options = reservationTimeOptions,
                        enabled = !isLoading,
                        onSelect = { nextTime -> departureTime = nextTime },
                        modifier = Modifier.weight(0.88f),
                    )
                }
                OutlinedTextField(
                    value = startKm,
                    onValueChange = { startKm = it.filter(Char::isDigit).take(8) },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Početna KM") },
                    singleLine = true,
                    enabled = !isLoading,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    shape = RoundedCornerShape(16.dp),
                )
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    WorkOrderDatePickerField(
                        label = "Datum dolaska",
                        value = returnDate,
                        onChange = { returnDate = it },
                        enabled = !isLoading,
                        modifier = Modifier.weight(1.28f),
                    )
                    WorkOrderSelectField(
                        label = "Vrijeme dolaska",
                        value = returnTime,
                        valueLabel = returnTime.ifBlank { "Otvoreno" },
                        options = listOf("" to "Otvoreno") + reservationTimeOptions,
                        enabled = !isLoading,
                        onSelect = { nextTime -> returnTime = nextTime },
                        modifier = Modifier.weight(0.88f),
                    )
                }
                OutlinedTextField(
                    value = endKm,
                    onValueChange = { endKm = it.filter(Char::isDigit).take(8) },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Krajnja KM") },
                    singleLine = true,
                    enabled = !isLoading,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    shape = RoundedCornerShape(16.dp),
                )
                WorkOrderTextField("Lokacija gdje se ide", destination, { destination = it }, !isLoading)
                if (destinationSuggestions.isNotEmpty()) {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        destinationSuggestions.forEach { suggestion ->
                            FilterChip(
                                selected = destination.equals(suggestion, ignoreCase = true),
                                enabled = !isLoading,
                                onClick = { destination = suggestion },
                                label = { Text(suggestion, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                            )
                        }
                    }
                }
                WorkOrderSelectField(
                    label = "Povezani RN",
                    value = linkedWorkOrderId,
                    valueLabel = workOrderOptions.firstOrNull { it.first == linkedWorkOrderId }?.second
                        ?: openTrip?.linkedWorkOrderNumber.orEmpty().ifBlank { "Bez povezanog RN-a" },
                    options = workOrderOptions,
                    enabled = !isLoading,
                    onSelect = { linkedWorkOrderId = it },
                )
                if (userOptions.isNotEmpty()) {
                    VehicleUsageUserPicker(
                        users = userOptions,
                        selectedUserIds = selectedDriverIds,
                        enabled = !isLoading,
                        onChange = { selectedDriverIds = it },
                    )
                } else {
                    WorkOrderTextField("Korisnik vozila", manualPerformedBy, { manualPerformedBy = it }, !isLoading)
                }
                WorkOrderTextField(
                    "Stanje vozila / napomena",
                    vehicleCondition,
                    { vehicleCondition = it },
                    !isLoading,
                )
                Text("Kontrola vozila", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                VehicleChecklistRow("Vozilo čisto", vehicleClean, !isLoading) { vehicleClean = it }
                VehicleChecklistRow("Dokumenti u vozilu", documentsPresent, !isLoading) { documentsPresent = it }
                VehicleChecklistRow("Gorivo / baterija uredno", fuelOk, !isLoading) { fuelOk = it }
                VehicleChecklistRow("Oštećenje evidentirano", damageNoted, !isLoading) { damageNoted = it }
                WorkOrderTextField("Napomena", note, { note = it }, !isLoading)
                Text("Dokumenti i potpis", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        OutlinedButton(
                            onClick = startReturnScan,
                            enabled = !isLoading,
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.CameraAlt, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("Sken")
                        }
                        OutlinedButton(
                            onClick = {
                                val outputUri = createWorkOrderCameraCaptureUri(context.applicationContext)
                                if (outputUri == null) {
                                    uploadError = "Ne mogu pripremiti fotografiju za spremanje."
                                } else {
                                    pendingReturnCameraUri = outputUri
                                    returnCameraLauncher.launch(outputUri)
                                }
                            },
                            enabled = !isLoading,
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.Image, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("Kamera")
                        }
                        OutlinedButton(
                            onClick = { returnDocumentLauncher.launch(arrayOf("application/pdf")) },
                            enabled = !isLoading,
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.PictureAsPdf, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("PDF")
                        }
                        OutlinedButton(
                            onClick = { returnPhotoLauncher.launch("image/*") },
                            enabled = !isLoading,
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.AttachFile, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("Slike")
                        }
                        OutlinedButton(
                            onClick = { returnDocumentLauncher.launch(workOrderDocumentAllowedMimeTypes) },
                            enabled = !isLoading,
                            shape = RoundedCornerShape(14.dp),
                        ) {
                            Icon(Icons.Rounded.Folder, contentDescription = null, modifier = Modifier.size(18.dp))
                            Spacer(Modifier.width(6.dp))
                            Text("Datoteka")
                        }
                    }
                    if (uploadError.isNotBlank()) {
                        Text(uploadError, color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall)
                    }
                    if (returnFiles.isNotEmpty()) {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            returnFiles.forEachIndexed { index, upload ->
                                Surface(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(14.dp),
                                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.55f),
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                                    ) {
                                        Icon(
                                            if (upload.fileType.startsWith("image/", ignoreCase = true)) Icons.Rounded.Image else Icons.Rounded.InsertDriveFile,
                                            contentDescription = null,
                                            tint = MaterialTheme.colorScheme.primary,
                                        )
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text(upload.fileName, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                            Text(formatFileSizeLabel(upload.fileSize), style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f))
                                        }
                                        IconButton(onClick = { returnFiles.removeAt(index) }, enabled = !isLoading) {
                                            Icon(Icons.Rounded.Delete, contentDescription = "Makni dokument")
                                        }
                                    }
                                }
                            }
                        }
                    }

                    Text("Potpis korisnika vozila", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(18.dp),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.28f)),
                        color = MaterialTheme.colorScheme.surface,
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Canvas(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(150.dp)
                                    .clip(RoundedCornerShape(14.dp))
                                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.28f))
                                    .onSizeChanged { signaturePadSize = androidx.compose.ui.geometry.Size(it.width.toFloat(), it.height.toFloat()) }
                                    .pointerInput(isLoading) {
                                        if (!isLoading) {
                                            detectDragGestures(
                                                onDragStart = { offset -> activeSignatureStroke = listOf(offset) },
                                                onDrag = { change, _ ->
                                                    activeSignatureStroke = activeSignatureStroke + change.position
                                                    change.consume()
                                                },
                                                onDragEnd = {
                                                    if (activeSignatureStroke.isNotEmpty()) {
                                                        signatureStrokes = signatureStrokes + listOf(activeSignatureStroke)
                                                    }
                                                    activeSignatureStroke = emptyList()
                                                },
                                                onDragCancel = { activeSignatureStroke = emptyList() },
                                            )
                                        }
                                    },
                            ) {
                                val allStrokes = signatureStrokes + listOf(activeSignatureStroke).filter { it.isNotEmpty() }
                                allStrokes.forEach { strokePoints ->
                                    if (strokePoints.size == 1) {
                                        drawCircle(Color(0xFF111827), radius = 3f, center = strokePoints.first())
                                    } else if (strokePoints.size > 1) {
                                        val path = Path().apply {
                                            moveTo(strokePoints.first().x, strokePoints.first().y)
                                            strokePoints.drop(1).forEach { point -> lineTo(point.x, point.y) }
                                        }
                                        drawPath(path, Color(0xFF111827), style = Stroke(width = 4f))
                                    }
                                }
                            }
                            Row(horizontalArrangement = Arrangement.End, modifier = Modifier.fillMaxWidth()) {
                                TextButton(
                                    onClick = {
                                        signatureStrokes = emptyList()
                                        activeSignatureStroke = emptyList()
                                    },
                                    enabled = !isLoading && (signatureStrokes.isNotEmpty() || activeSignatureStroke.isNotEmpty()),
                                ) {
                                    Text("Očisti")
                                }
                            }
                        }
                    }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val finalDestination = destination.trim().ifBlank {
                        openTrip?.destination.orEmpty().ifBlank { defaultReservation?.destination.orEmpty() }
                    }
                    val finalReservationId = reservationId.trim().ifBlank {
                        openTrip?.reservationId.orEmpty().ifBlank { defaultReservation?.id.orEmpty() }
                    }
                    val finalLinkedWorkOrderId = linkedWorkOrderId.trim().ifBlank {
                        openTrip?.linkedWorkOrderId.orEmpty()
                    }
                    val linkedWorkOrderNumber = workOrders.firstOrNull { it.id == finalLinkedWorkOrderId }?.displayNumber
                        ?: openTrip?.linkedWorkOrderNumber.orEmpty()
                    val finalDepartureAt = formatReservationDateTime(departureDate, departureTime)
                    val finalReturnAt = if (returnDate.isNotBlank() && returnTime.isNotBlank()) {
                        formatReservationDateTime(returnDate, returnTime)
                    } else {
                        ""
                    }
                    val finalStartKm = startKm.trim()
                    val finalEndKm = endKm.trim()
                    val finalOdometerKm = finalEndKm.ifBlank { finalStartKm }
                    val signatureBytes = if (signatureStrokes.isNotEmpty()) {
                        renderSignaturePng(
                            signatureStrokes,
                            signaturePadSize.width.toInt().coerceAtLeast(480),
                            signaturePadSize.height.toInt().coerceAtLeast(220),
                        )
                    } else {
                        null
                    }
                    onConfirm(
                        "trip",
                        openTrip?.id.orEmpty(),
                        finalReturnAt.ifBlank { finalDepartureAt },
                        finalOdometerKm,
                        finalDepartureAt,
                        finalReturnAt,
                        finalStartKm,
                        finalEndKm,
                        finalDestination,
                        finalReservationId,
                        finalLinkedWorkOrderId,
                        linkedWorkOrderNumber.trim(),
                        performedBy.trim(),
                        selectedDriverIds,
                        finalDriverLabels,
                        vehicleCondition.trim(),
                        vehicleClean,
                        documentsPresent,
                        fuelOk,
                        damageNoted,
                        note.trim(),
                        returnFiles.toList(),
                        signatureBytes,
                    )
                },
                enabled = !isLoading &&
                    !hasBlockingOpenTrip &&
                    defaultReservation != null &&
                    reservationInWindow &&
                    reservationId.isNotBlank() &&
                    finalDriverLabels.isNotEmpty() &&
                    startKm.isNotBlank() &&
                    destination.isNotBlank() &&
                    (
                        (returnDate.isBlank() && returnTime.isBlank() && endKm.isBlank()) ||
                            (returnDate.isNotBlank() && returnTime.isNotBlank() && endKm.isNotBlank())
                        ),
                shape = RoundedCornerShape(16.dp),
            ) {
                Text("Spremi My Trip", fontWeight = FontWeight.Black)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss, enabled = !isLoading) {
                Text("Odustani")
            }
        },
    )
}

@Composable
private fun VehicleUsageUserPicker(
    users: List<WorkOrderUserOption>,
    selectedUserIds: List<String>,
    enabled: Boolean,
    onChange: (List<String>) -> Unit,
) {
    var query by remember(users) { mutableStateOf("") }
    val normalizedQuery = query.normalizedPickerText()
    val selectedLabels = remember(users, selectedUserIds) {
        vehicleUserLabelsForIds(users, selectedUserIds)
    }
    val visibleOptions = remember(users, selectedUserIds, normalizedQuery) {
        users
            .filter { user ->
                val label = vehicleUserOptionLabel(user)
                val searchText = listOf(label, user.fullName, user.email).joinToString(" ").normalizedPickerText()
                normalizedQuery.isBlank() || searchText.contains(normalizedQuery)
            }
            .sortedWith(
                compareByDescending<WorkOrderUserOption> { it.id in selectedUserIds }
                    .thenBy { vehicleUserOptionLabel(it).lowercase(Locale.getDefault()) },
            )
            .take(36)
            .map { user -> user.id to vehicleUserOptionLabel(user) }
    }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.24f)),
        color = MaterialTheme.colorScheme.surface,
    ) {
        Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Text("Korisnici vozila", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
            if (selectedLabels.isEmpty()) {
                Text(
                    "Odaberi barem jednog korisnika vozila.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            } else {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    selectedUserIds.forEach { userId ->
                        val label = users.firstOrNull { it.id == userId }?.let(::vehicleUserOptionLabel).orEmpty()
                        if (label.isNotBlank()) {
                            FilterChip(
                                selected = true,
                                enabled = enabled,
                                onClick = { onChange(selectedUserIds.filterNot { it == userId }) },
                                label = { Text(label, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                            )
                        }
                    }
                }
            }
            OutlinedTextField(
                value = query,
                onValueChange = { query = it },
                modifier = Modifier.fillMaxWidth(),
                label = { Text("Traži korisnika") },
                singleLine = true,
                enabled = enabled,
                shape = RoundedCornerShape(16.dp),
            )
            WorkOrderMultiSelectChips(
                options = visibleOptions,
                selected = selectedUserIds,
                enabled = enabled,
                emptyText = "Nema korisnika za odabir.",
                onToggle = { value -> onChange(selectedUserIds.toggleValue(value)) },
            )
        }
    }
}

@Composable
private fun VehicleChecklistRow(
    label: String,
    checked: Boolean,
    enabled: Boolean,
    onChange: (Boolean) -> Unit,
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(enabled = enabled) { onChange(!checked) },
        shape = RoundedCornerShape(14.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.45f),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Checkbox(checked = checked, onCheckedChange = onChange, enabled = enabled)
            Spacer(Modifier.width(8.dp))
            Text(label, fontWeight = FontWeight.SemiBold)
        }
    }
}

@OptIn(ExperimentalFoundationApi::class, ExperimentalMaterial3Api::class)
@Composable
private fun WorkOrderDetailScreen(
    workOrder: WorkOrder,
    services: List<WorkOrderServiceOption>,
    users: List<WorkOrderUserOption>,
    currentUser: SafeNexusUser?,
    priorityOptions: List<OptionItem>,
    tagSuggestions: List<String>,
    isLoading: Boolean,
    error: String,
    notice: String,
    documents: List<WorkOrderDocument>,
    documentsLoading: Boolean,
    statusOptions: List<String>,
    readOnly: Boolean = false,
    onBack: () -> Unit,
    onNumberChange: (WorkOrder, String) -> Unit,
    onStatusChange: (WorkOrder, String) -> Unit,
    onMetaChange: (WorkOrder, String, List<String>) -> Unit,
    onDatesChange: (WorkOrder, String?, String?) -> Unit,
    onExecutorsChange: (WorkOrder, List<String>) -> Unit,
    onWatchersChange: (WorkOrder, List<String>) -> Unit,
    onManageServices: (WorkOrder) -> Unit,
    onGenerateDocumentation: (WorkOrder) -> Unit,
    onAddDocumentation: (WorkOrder) -> Unit,
    onDownloadPdf: (WorkOrder) -> Unit,
    onSignWorkOrder: (WorkOrder) -> Unit,
    onOpenDocument: (WorkOrderDocument) -> Unit,
    onDownloadDocument: (WorkOrderDocument) -> Unit,
    onDeleteDocument: (WorkOrderDocument) -> Unit,
    onRefreshDocuments: () -> Unit,
) {
    BackHandler(onBack = onBack)
    val context = LocalContext.current
    val executorOptions = remember(users, workOrder.executors) {
        (
            users.map { user -> user.label.ifBlank { user.fullName.ifBlank { user.email } } } +
                workOrder.executors
            )
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .map { it to it }
    }
    val currentWatcherUser = remember(users, currentUser?.displayName, currentUser?.email) {
        val currentEmail = currentUser?.email.orEmpty().trim()
        val currentLabel = currentUser?.displayName.orEmpty().trim()
        users.firstOrNull { user ->
            currentEmail.isNotBlank() && user.email.equals(currentEmail, ignoreCase = true)
        } ?: users.firstOrNull { user ->
            currentLabel.isNotBlank() &&
                listOf(user.label, user.fullName, user.email)
                    .any { value -> value.equals(currentLabel, ignoreCase = true) }
        }
    }
    val currentWatcherId = currentWatcherUser?.id.orEmpty()
    val currentUserIsWatcher = currentWatcherId.isNotBlank() &&
        workOrder.watcherIds.any { watcherId -> watcherId.equals(currentWatcherId, ignoreCase = true) }
    val statusStyle = rnStatusStyle(workOrder)
    val heroLocation = remember(workOrder.locationName, workOrder.objectName) {
        listOf(
            workOrder.locationName.ifBlank { "Lokacija nije upisana" },
            workOrder.objectName.takeIf { it.isNotBlank() }?.let { "Objekt: $it" },
        )
            .filterNotNull()
            .filter { it.isNotBlank() }
            .joinToString(" · ")
    }
    val hasContactData = workOrder.contactName.isNotBlank() ||
        workOrder.contactPhone.isNotBlank() ||
        workOrder.contactEmail.isNotBlank() ||
        workOrder.coordinates.isNotBlank()
    val hasLocationDetails = workOrder.region.isNotBlank() ||
        workOrder.coordinates.isNotBlank() ||
        hasContactData
    var showLocationDetails by remember(workOrder.id) { mutableStateOf(false) }
    var showExecutorsEditor by remember(workOrder.id) { mutableStateOf(false) }
    var showMetaEditor by remember(workOrder.id) { mutableStateOf(false) }
    var showNumberMenu by remember(workOrder.id) { mutableStateOf(false) }
    var showNumberEditor by remember(workOrder.id) { mutableStateOf(false) }
    var numberDraft by remember(workOrder.id, workOrder.number) { mutableStateOf(workOrder.number) }
    if (showNumberEditor && !readOnly) {
        AlertDialog(
            onDismissRequest = { showNumberEditor = false },
            title = {
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    Text("Broj radnog naloga", fontWeight = FontWeight.Black)
                    Text(
                        workOrder.companyName.ifBlank { "Radni nalog" },
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            },
            text = {
                OutlinedTextField(
                    value = numberDraft,
                    onValueChange = { numberDraft = it },
                    modifier = Modifier.fillMaxWidth(),
                    enabled = !isLoading,
                    singleLine = true,
                    label = { Text("Novi broj RN-a") },
                    placeholder = { Text("npr. 26-664") },
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                    shape = RoundedCornerShape(16.dp),
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val normalized = numberDraft.trim()
                        if (normalized.isNotBlank()) {
                            onNumberChange(workOrder, normalized)
                            showNumberEditor = false
                        }
                    },
                    enabled = !isLoading && numberDraft.trim().isNotBlank(),
                    shape = RoundedCornerShape(14.dp),
                ) {
                    Text("Spremi", fontWeight = FontWeight.Black)
                }
            },
            dismissButton = {
                TextButton(onClick = { showNumberEditor = false }, enabled = !isLoading) {
                    Text("Odustani", fontWeight = FontWeight.Bold)
                }
            },
        )
    }
    if (showMetaEditor && !readOnly) {
        AlertDialog(
            onDismissRequest = { showMetaEditor = false },
            title = {
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    Text("Prioritet i tagovi", fontWeight = FontWeight.Black)
                    Text(
                        workOrder.displayNumber,
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            },
            text = {
                WorkOrderMetaEditor(
                    workOrder = workOrder,
                    priorityOptions = priorityOptions,
                    tagSuggestions = tagSuggestions,
                    enabled = !isLoading,
                    onSave = { priority, tags ->
                        onMetaChange(workOrder, priority, tags)
                        showMetaEditor = false
                    },
                )
            },
            confirmButton = {},
            dismissButton = {
                TextButton(onClick = { showMetaEditor = false }) {
                    Text("Zatvori", fontWeight = FontWeight.Bold)
                }
            },
        )
    }
    if (showExecutorsEditor && !readOnly) {
        AlertDialog(
            onDismissRequest = { showExecutorsEditor = false },
            title = {
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    Text("Izvršitelji RN-a", fontWeight = FontWeight.Black)
                    Text(
                        workOrder.displayNumber,
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            },
            text = {
                DocumentationExecutorsEditor(
                    executorOptions = executorOptions,
                    selectedExecutors = workOrder.executors,
                    enabled = !isLoading,
                    onChange = { next -> onExecutorsChange(workOrder, next) },
                )
            },
            confirmButton = {
                TextButton(onClick = { showExecutorsEditor = false }) {
                    Text("Zatvori", fontWeight = FontWeight.Bold)
                }
            },
        )
    }
    Scaffold(
        topBar = {
            TopAppBar(
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.Rounded.ArrowBack, contentDescription = "Natrag")
                    }
                },
                title = {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Box(modifier = Modifier.weight(1f)) {
                                Text(
                                    workOrder.displayNumber,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(10.dp))
                                        .combinedClickable(
                                            enabled = !readOnly,
                                            onClick = {},
                                            onLongClick = { showNumberMenu = true },
                                        )
                                        .padding(horizontal = 2.dp, vertical = 1.dp),
                                    fontWeight = FontWeight.Bold,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                DropdownMenu(
                                    expanded = showNumberMenu,
                                    onDismissRequest = { showNumberMenu = false },
                                ) {
                                    DropdownMenuItem(
                                        text = { Text("Promijeni broj RN-a") },
                                        leadingIcon = {
                                            Icon(Icons.Rounded.Edit, contentDescription = null)
                                        },
                                        onClick = {
                                            numberDraft = workOrder.number
                                            showNumberMenu = false
                                            showNumberEditor = true
                                        },
                                        enabled = !readOnly && !isLoading,
                                    )
                                }
                            }
                            WorkOrderHeaderMeta(
                                workOrder = workOrder,
                                enabled = !readOnly,
                                onClick = { showMetaEditor = true },
                            )
                        }
                        Text(
                            workOrder.status,
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.background),
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        Column(
            modifier = Modifier
                .padding(padding)
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(18.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp),
        ) {
            Card(
                shape = RoundedCornerShape(28.dp),
                colors = CardDefaults.cardColors(containerColor = statusStyle.background),
                border = BorderStroke(1.dp, statusStyle.accent.copy(alpha = 0.22f)),
            ) {
                Column(modifier = Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    StatusChip(workOrder)
                    Text(
                        workOrder.companyName.ifBlank { "Bez tvrtke" },
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.Black,
                    )
                    Surface(
                        modifier = Modifier
                            .clip(RoundedCornerShape(16.dp))
                            .clickable(enabled = hasLocationDetails) {
                                showLocationDetails = !showLocationDetails
                            },
                        shape = RoundedCornerShape(16.dp),
                        color = Color.White.copy(alpha = 0.48f),
                        border = BorderStroke(1.dp, statusStyle.accent.copy(alpha = 0.12f)),
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 12.dp, vertical = 10.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Icon(
                                Icons.Rounded.LocationOn,
                                contentDescription = null,
                                tint = statusStyle.accent,
                                modifier = Modifier.size(18.dp),
                            )
                            Spacer(Modifier.width(8.dp))
                            Text(
                                heroLocation,
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
                                maxLines = 2,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.weight(1f),
                            )
                            if (hasLocationDetails) {
                                Spacer(Modifier.width(8.dp))
                                Icon(
                                    Icons.Rounded.Info,
                                    contentDescription = "Detalji lokacije",
                                    tint = statusStyle.accent,
                                    modifier = Modifier.size(17.dp),
                                )
                            }
                        }
                    }
                    AnimatedVisibility(showLocationDetails && hasLocationDetails) {
                        Surface(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(18.dp),
                            color = Color.White.copy(alpha = 0.64f),
                            border = BorderStroke(1.dp, statusStyle.accent.copy(alpha = 0.14f)),
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp),
                            ) {
                                Text("Detalji lokacije", fontWeight = FontWeight.Black, color = statusStyle.accent)
                                if (workOrder.region.isNotBlank()) {
                                    CompactInfoLine(Icons.Rounded.Map, "Regija", workOrder.region)
                                }
                                if (workOrder.coordinates.isNotBlank()) {
                                    CompactInfoLine(Icons.Rounded.LocationOn, "Koordinate", workOrder.coordinates)
                                }
                                if (workOrder.contactName.isNotBlank()) {
                                    CompactInfoLine(Icons.Rounded.Person, "Kontakt", workOrder.contactName)
                                }
                                if (workOrder.contactPhone.isNotBlank()) {
                                    CompactInfoLine(
                                        Icons.Rounded.Call,
                                        "Telefon",
                                        workOrder.contactPhone,
                                        onClick = { openDialer(context, workOrder.contactPhone) },
                                    )
                                }
                                if (workOrder.contactEmail.isNotBlank()) {
                                    CompactInfoLine(
                                        Icons.Rounded.Mail,
                                        "Email",
                                        workOrder.contactEmail,
                                        onClick = { openEmailClient(context, workOrder.contactEmail) },
                                    )
                                }
                            }
                        }
                    }
                    if (!readOnly) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.End,
                        ) {
                            AssistChip(
                                onClick = {
                                    if (currentWatcherId.isBlank()) return@AssistChip
                                    val nextWatcherIds = if (currentUserIsWatcher) {
                                        workOrder.watcherIds.filterNot { watcherId ->
                                            watcherId.equals(currentWatcherId, ignoreCase = true)
                                        }
                                    } else {
                                        (workOrder.watcherIds + currentWatcherId).distinct()
                                    }
                                    onWatchersChange(workOrder, nextWatcherIds)
                                },
                                enabled = !isLoading && currentWatcherId.isNotBlank(),
                                leadingIcon = {
                                    Icon(Icons.Rounded.Visibility, contentDescription = null, modifier = Modifier.size(16.dp))
                                },
                                label = {
                                    Text(
                                        when {
                                            currentWatcherId.isBlank() -> "Nema profila"
                                            currentUserIsWatcher -> "Pratiš RN"
                                            else -> "Dodaj mene"
                                        },
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                },
                            )
                        }
                    }
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        if (readOnly) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                WorkOrderHeroActionTile(
                                    label = "Dokumenti",
                                    icon = Icons.Rounded.Folder,
                                    onClick = onRefreshDocuments,
                                    enabled = !isLoading && !documentsLoading,
                                    modifier = Modifier.weight(1f),
                                )
                                WorkOrderHeroActionTile(
                                    label = "PDF RN",
                                    icon = Icons.Rounded.PictureAsPdf,
                                    onClick = { onDownloadPdf(workOrder) },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                            }
                        } else {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                WorkOrderStatusMenu(
                                    currentStatus = workOrder.status,
                                    statusOptions = statusOptions,
                                    enabled = !isLoading,
                                    onStatusSelected = { status -> onStatusChange(workOrder, status) },
                                    modifier = Modifier.weight(1f),
                                )
                                WorkOrderHeroActionTile(
                                    label = "Usluge",
                                    icon = Icons.Rounded.ListAlt,
                                    onClick = { onManageServices(workOrder) },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                                WorkOrderHeroActionTile(
                                    label = "Izvršitelji",
                                    icon = Icons.Rounded.Person,
                                    onClick = { showExecutorsEditor = true },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                            }
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                WorkOrderHeroActionTile(
                                    label = "Izradi dokumentaciju",
                                    icon = Icons.Rounded.Description,
                                    onClick = { onGenerateDocumentation(workOrder) },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                                WorkOrderHeroActionTile(
                                    label = "Dokumentacija",
                                    icon = Icons.Rounded.Description,
                                    onClick = { onAddDocumentation(workOrder) },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                                WorkOrderHeroActionTile(
                                    label = "PDF RN",
                                    icon = Icons.Rounded.PictureAsPdf,
                                    onClick = { onDownloadPdf(workOrder) },
                                    enabled = !isLoading,
                                    modifier = Modifier.weight(1f),
                                )
                            }
                            Button(
                                onClick = { onSignWorkOrder(workOrder) },
                                enabled = !isLoading,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(14.dp),
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = statusStyle.accent,
                                    contentColor = Color.White,
                                ),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 9.dp),
                            ) {
                                Icon(Icons.Rounded.Fingerprint, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(Modifier.width(6.dp))
                                Text("Potpiši RN")
                            }
                        }
                    }
                }
            }

            DetailSection("Osnovno") {
                DetailRow(Icons.Rounded.CalendarMonth, "Otvoren", formatDateLabel(workOrder.openedDate).ifBlank { "Nije upisano" })
                DetailDatePickerRow(
                    icon = Icons.Rounded.CalendarMonth,
                    label = "Rok",
                    value = workOrder.dueDate,
                    enabled = !isLoading && !readOnly,
                    onChange = { date -> onDatesChange(workOrder, date, null) },
                )
                DetailDatePickerRow(
                    icon = Icons.Rounded.CalendarMonth,
                    label = "Izvršenje",
                    value = workOrder.executionDate,
                    enabled = !isLoading && !readOnly,
                    onChange = { date -> onDatesChange(workOrder, null, date) },
                )
            }

            AnimatedVisibility(isLoading) {
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
            }
            AnimatedVisibility(error.isNotBlank()) {
                MessageCard(text = error, isError = true)
            }
            AnimatedVisibility(notice.isNotBlank()) {
                MessageCard(text = notice, isError = false)
            }

            WorkOrderDocumentationSection(
                documents = documents,
                loading = documentsLoading,
                isBusy = isLoading,
                onGenerateDocumentation = { onGenerateDocumentation(workOrder) },
                onAddDocumentation = { onAddDocumentation(workOrder) },
                onOpenDocument = onOpenDocument,
                onDownloadDocument = onDownloadDocument,
                onDeleteDocument = onDeleteDocument,
                onRefreshDocuments = onRefreshDocuments,
                readOnly = readOnly,
            )

        }
    }
}

@Composable
private fun WorkOrderHeaderMeta(
    workOrder: WorkOrder,
    enabled: Boolean = true,
    onClick: () -> Unit,
) {
    val tags = workOrder.tags
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(999.dp))
            .clickable(enabled = enabled, onClick = onClick)
            .padding(start = 2.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        WorkOrderHeaderMetaChip(
            label = workOrder.priority.ifBlank { "Normal" },
            style = workOrderPriorityStyle(workOrder.priority),
        )
        tags.take(2).forEach { tag ->
            WorkOrderHeaderMetaChip(
                label = tag,
                style = workOrderTagStyle(tag),
            )
        }
        if (tags.size > 2) {
            WorkOrderHeaderMetaChip(
                label = "+${tags.size - 2}",
                style = WorkOrderMetaChipStyle(
                    background = Color(0xFFF8FAFC),
                    border = Color(0xFFCBD5E1),
                    content = Color(0xFF475569),
                ),
            )
        }
    }
}

@Composable
private fun WorkOrderMetaEditor(
    workOrder: WorkOrder,
    priorityOptions: List<OptionItem>,
    tagSuggestions: List<String>,
    enabled: Boolean,
    onSave: (String, List<String>) -> Unit,
) {
    val options = remember(priorityOptions, workOrder.priority) {
        (
            priorityOptions.map { option -> option.value to option.label.ifBlank { option.value } } +
                listOf(
                    "Normal" to "Normal",
                    "Hitno" to "Hitno",
                    "Visok" to "Visok",
                    "Nizak" to "Nizak",
                    workOrder.priority to workOrder.priority,
                )
            )
            .map { (value, label) -> value.trim() to label.trim().ifBlank { value.trim() } }
            .filter { (value, _) -> value.isNotBlank() }
            .distinctBy { (value, _) -> value.lowercase(Locale.getDefault()) }
    }
    var priority by remember(workOrder.id, workOrder.priority) { mutableStateOf(workOrder.priority.ifBlank { "Normal" }) }
    var tagText by remember(workOrder.id, workOrder.tags) { mutableStateOf(workOrder.tags.joinToString(", ")) }
    val selectedTags = remember(tagText) { normalizeWorkOrderTagText(tagText) }
    val visibleSuggestions = remember(tagSuggestions, selectedTags) {
        tagSuggestions
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .filterNot { suggestion -> selectedTags.any { it.equals(suggestion, ignoreCase = true) } }
            .take(12)
    }

    fun setTags(tags: List<String>) {
        tagText = tags
            .map { it.trim().trim('#') }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .joinToString(", ")
    }

    Column(
        modifier = Modifier.verticalScroll(rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(14.dp),
    ) {
        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Prioritet", fontWeight = FontWeight.Black)
            FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                options.forEach { (value, label) ->
                    FilterChip(
                        selected = priority.equals(value, ignoreCase = true),
                        enabled = enabled,
                        onClick = { priority = value },
                        label = { Text(label, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                    )
                }
            }
        }
        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Tagovi", fontWeight = FontWeight.Black)
            OutlinedTextField(
                value = tagText,
                onValueChange = { tagText = it },
                modifier = Modifier.fillMaxWidth(),
                enabled = enabled,
                label = { Text("Npr. teren, hitno, papir") },
                supportingText = { Text("Odvoji tagove zarezom ili novim redom.") },
                minLines = 2,
                maxLines = 4,
                shape = RoundedCornerShape(16.dp),
            )
            AnimatedVisibility(selectedTags.isNotEmpty()) {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    selectedTags.forEach { tag ->
                        WorkOrderEditableTagChip(
                            tag = tag,
                            icon = Icons.Rounded.Close,
                            enabled = enabled,
                            onClick = { setTags(selectedTags.filterNot { it.equals(tag, ignoreCase = true) }) },
                        )
                    }
                }
            }
            AnimatedVisibility(visibleSuggestions.isNotEmpty()) {
                Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    Text(
                        "Brzi odabir",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        visibleSuggestions.forEach { suggestion ->
                            WorkOrderEditableTagChip(
                                tag = suggestion,
                                icon = Icons.Rounded.Add,
                                enabled = enabled,
                                onClick = { setTags(selectedTags + suggestion) },
                            )
                        }
                    }
                }
            }
        }
        Button(
            onClick = { onSave(priority, normalizeWorkOrderTagText(tagText)) },
            enabled = enabled,
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
        ) {
            Text("Spremi prioritet i tagove", fontWeight = FontWeight.Black)
        }
    }
}

