private fun normalizeServiceMatch(value: String): String =
    value.trim()
        .lowercase(Locale.getDefault())
        .replace(Regex("\\s+"), " ")

private data class WorkOrderServiceFilterTab(
    val key: String,
    val label: String,
    val icon: ImageVector,
)

private fun normalizeServiceFilterText(value: String): String =
    normalizeServiceMatch(value)
        .replace("š", "s")
        .replace("ž", "z")
        .replace("č", "c")
        .replace("ć", "c")
        .replace("đ", "d")

private fun WorkOrderServiceOption.workOrderServiceFilterKey(): String {
    val text = normalizeServiceFilterText(listOf(name, serviceCode, type, note).joinToString(" "))
    val code = normalizeServiceFilterText(serviceCode)
    return when {
        code in setOf("spr", "tzin", "rog", "ro", "fc", "kc") ||
            text.contains("inspection") ||
            text.contains("ispitiv") ||
            text.contains("pregled") ||
            text.contains("mjeren") ||
            text.contains("radna oprema") ||
            text.contains("radni okolis") -> "ispitivanja"
        text.contains("osposob") ||
            text.contains("znr") ||
            text.contains("zastita") ||
            text.contains("pozar") ||
            text.contains("adr") ||
            text.contains("procjena rizika") ||
            code in setOf("zos", "pgp", "spztp", "adr", "znr", "pr") ||
            text.contains("pravilnik") -> "znr"
        else -> "ostalo"
    }
}

private fun resolveWorkOrderSelectedServiceIds(
    workOrder: WorkOrder,
    services: List<WorkOrderServiceOption>,
): List<String> {
    val ids = workOrder.serviceDetails.map { it.serviceId }.filter { it.isNotBlank() }
    if (ids.isNotEmpty()) return ids.distinct()

    val serviceLookup = services.flatMap { service ->
        listOf(service.id, service.name, service.serviceCode)
            .map { normalizeServiceMatch(it) }
            .filter { it.isNotBlank() }
            .map { key -> key to service.id }
    }.toMap()

    return workOrder.serviceItems
        .mapNotNull { label -> serviceLookup[normalizeServiceMatch(label)] }
        .distinct()
}

private data class WorkOrderDocumentGroupUi(
    val key: String,
    val title: String,
    val subtitle: String,
    val icon: ImageVector,
    val accent: Color,
)

private fun normalizeWorkOrderDocumentText(value: String): String =
    value.trim()
        .lowercase(Locale.getDefault())
        .replace("š", "s")
        .replace("ž", "z")
        .replace("č", "c")
        .replace("ć", "c")
        .replace("đ", "d")

private fun workOrderDocumentGroupKey(document: WorkOrderDocument): String {
    val category = normalizeWorkOrderDocumentText(document.documentCategory)
    val name = normalizeWorkOrderDocumentText(document.fileName)
    val text = "$category $name ${normalizeWorkOrderDocumentText(document.fileType)}"

    return when {
        category.contains("radni nalog") ||
        category.contains("ovjereni radni nalog") ||
            name.matches(Regex(".*\\b\\d{2}-\\d+\\.pdf$")) ||
            name.contains("radni nalog") -> "work-order"
        category.contains("radni list") -> "worksheets"
        category.contains("projekt") ||
            category.contains("shema") ||
            category.contains("elaborat") -> "projects"
        document.isImage || category.contains("fotograf") || text.contains("slik") -> "photos"
        category.contains("zapisnik") ||
            category.contains("zapisnici") ||
            category.contains("primopredaj") ||
            category.contains("uvjeren") ||
            category.contains("pdf") ||
            document.isPdf -> "reports"
        else -> "other"
    }
}

private fun workOrderDocumentGroupMeta(key: String): WorkOrderDocumentGroupUi = when (key) {
    "work-order" -> WorkOrderDocumentGroupUi(
        key = key,
        title = "Radni nalozi",
        subtitle = "Skenirani, potpisani i automatski RN PDF",
        icon = Icons.Rounded.Badge,
        accent = Color(0xFF2563EB),
    )
    "worksheets" -> WorkOrderDocumentGroupUi(
        key = key,
        title = "Radni listovi",
        subtitle = "Terenski zapisnici, radni listovi i pripreme",
        icon = Icons.Rounded.EventNote,
        accent = Color(0xFFA16207),
    )
    "photos" -> WorkOrderDocumentGroupUi(
        key = key,
        title = "Fotografije",
        subtitle = "Slike s terena i prilozi uz zapisnik",
        icon = Icons.Rounded.Image,
        accent = Color(0xFF0F766E),
    )
    "projects" -> WorkOrderDocumentGroupUi(
        key = key,
        title = "Projektna dokumentacija",
        subtitle = "Dokumenti lokacije: projekti, sheme i elaborati",
        icon = Icons.Rounded.Folder,
        accent = Color(0xFF7C3AED),
    )
    "reports" -> WorkOrderDocumentGroupUi(
        key = key,
        title = "Zapisnici",
        subtitle = "PDF, Word i primopredajni zapisnici",
        icon = Icons.Rounded.PictureAsPdf,
        accent = Color(0xFFDC2626),
    )
    else -> WorkOrderDocumentGroupUi(
        key = "other",
        title = "Ostalo",
        subtitle = "Mailovi, Word, Excel i drugi prilozi",
        icon = Icons.Rounded.InsertDriveFile,
        accent = Color(0xFF475569),
    )
}

private fun groupWorkOrderDocuments(documents: List<WorkOrderDocument>): List<Pair<WorkOrderDocumentGroupUi, List<WorkOrderDocument>>> {
    val order = listOf("work-order", "worksheets", "projects", "photos", "reports", "other")
    val grouped = documents.groupBy { workOrderDocumentGroupKey(it) }
    return order.mapNotNull { key ->
        val items = grouped[key].orEmpty()
        if (items.isEmpty()) null else workOrderDocumentGroupMeta(key) to items
    }
}

@Composable
private fun WorkOrderServiceManagementDialog(
    workOrder: WorkOrder,
    services: List<WorkOrderServiceOption>,
    isLoading: Boolean,
    onDismiss: () -> Unit,
    onSelectionChange: (List<String>) -> Unit,
) {
    var query by remember(workOrder.id) { mutableStateOf("") }
    var selectedIds by remember(workOrder.id, workOrder.serviceDetails, services) {
        mutableStateOf(resolveWorkOrderSelectedServiceIds(workOrder, services).toSet())
    }
    val filterTabs = remember {
        listOf(
            WorkOrderServiceFilterTab("ispitivanja", "Ispitivanja", Icons.Rounded.Tune),
            WorkOrderServiceFilterTab("znr", "ZNR", Icons.Rounded.Work),
            WorkOrderServiceFilterTab("ostalo", "Ostalo", Icons.Rounded.FilterList),
        )
    }
    val serviceFilterById = remember(services) {
        services.associate { service -> service.id to service.workOrderServiceFilterKey() }
    }
    fun initialServiceFilterKey(selected: Set<String>): String {
        val selectedCategory = selected.asSequence()
            .mapNotNull { serviceFilterById[it] }
            .firstOrNull()
        if (selectedCategory != null) return selectedCategory
        return filterTabs.firstOrNull { tab -> services.any { it.workOrderServiceFilterKey() == tab.key } }?.key
            ?: "ispitivanja"
    }
    var selectedFilter by remember(workOrder.id, services) { mutableStateOf(initialServiceFilterKey(selectedIds)) }
    var didInitializeAutoSave by remember(workOrder.id) { mutableStateOf(false) }
    var lastAutoSavedIds by remember(workOrder.id) { mutableStateOf(selectedIds) }
    var saveStatus by remember(workOrder.id) { mutableStateOf("Spremljeno") }
    val serviceSearchIndex = remember(services) {
        services.associate { service ->
            service.id to normalizeServiceMatch(
                listOf(service.name, service.serviceCode, service.type, service.note)
                    .joinToString(" "),
            )
        }
    }
    val filterCounts = remember(services, selectedIds) {
        filterTabs.associate { tab ->
            tab.key to services.count { it.workOrderServiceFilterKey() == tab.key }
        }
    }
    val filteredServices = remember(services, serviceSearchIndex, query, selectedFilter, selectedIds) {
        val normalizedQuery = normalizeServiceMatch(query)
        services.filter { service ->
            val matchesFilter = service.workOrderServiceFilterKey() == selectedFilter
            matchesFilter && (normalizedQuery.isBlank() || serviceSearchIndex[service.id]?.contains(normalizedQuery) == true)
        }.sortedWith(
            compareByDescending<WorkOrderServiceOption> { service -> service.id in selectedIds }
                .thenBy { service -> service.name.lowercase(Locale.getDefault()) },
        )
    }
    fun setServiceChecked(service: WorkOrderServiceOption, checked: Boolean) {
        val category = serviceFilterById[service.id] ?: service.workOrderServiceFilterKey()
        selectedFilter = category
        selectedIds = if (checked) {
            selectedIds.filter { serviceFilterById[it] == category }.toSet() + service.id
        } else {
            selectedIds - service.id
        }
    }
    LaunchedEffect(selectedIds) {
        if (!didInitializeAutoSave) {
            didInitializeAutoSave = true
            lastAutoSavedIds = selectedIds
            return@LaunchedEffect
        }
        if (selectedIds == lastAutoSavedIds) {
            saveStatus = "Spremljeno"
            return@LaunchedEffect
        }
        saveStatus = "Sprema se..."
        delay(320)
        onSelectionChange(selectedIds.toList())
        lastAutoSavedIds = selectedIds
        saveStatus = "Spremljeno"
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        modifier = Modifier.fillMaxWidth(0.96f),
        properties = DialogProperties(usePlatformDefaultWidth = false),
        title = {
            Column {
                Text("Usluge radnog naloga", fontWeight = FontWeight.Black)
                Text(
                    "${workOrder.displayNumber} · ${filterTabs.firstOrNull { it.key == selectedFilter }?.label ?: "Usluge"} · ${selectedIds.size} odabrano",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
                Text(
                    saveStatus,
                    style = MaterialTheme.typography.labelSmall,
                    color = if (saveStatus.startsWith("Sprema")) {
                        MaterialTheme.colorScheme.primary
                    } else {
                        MaterialTheme.colorScheme.onSurface.copy(alpha = 0.54f)
                    },
                    fontWeight = FontWeight.Bold,
                )
            }
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                AnimatedVisibility(saveStatus.startsWith("Sprema")) {
                    LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                }
                OutlinedTextField(
                    value = query,
                    onValueChange = { query = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Pretraži usluge") },
                    leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
                    singleLine = true,
                    enabled = !isLoading,
                    shape = RoundedCornerShape(16.dp),
                )
                FlowRow(
                    horizontalArrangement = Arrangement.spacedBy(7.dp),
                    verticalArrangement = Arrangement.spacedBy(7.dp),
                ) {
                    filterTabs.forEach { tab ->
                        val count = filterCounts[tab.key] ?: 0
                        FilterChip(
                            selected = selectedFilter == tab.key,
                            onClick = { selectedFilter = tab.key },
                            enabled = !isLoading && (tab.key == "all" || count > 0),
                            leadingIcon = {
                                Icon(tab.icon, contentDescription = null, modifier = Modifier.size(16.dp))
                            },
                            label = {
                                Text(
                                    "${tab.label} $count",
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            },
                        )
                    }
                }
                Text(
                    "Odabir je ograničen na jednu skupinu usluga.",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                )
                Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 390.dp),
                    shape = RoundedCornerShape(18.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.42f),
                ) {
                    LazyColumn(
                        modifier = Modifier.padding(7.dp),
                        verticalArrangement = Arrangement.spacedBy(6.dp),
                    ) {
                        if (filteredServices.isEmpty()) {
                            item {
                                Text(
                                    "Nema usluga za ovaj filter.",
                                    modifier = Modifier.padding(12.dp),
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                                )
                            }
                        }
                        items(filteredServices, key = { it.id }) { service ->
                            val selected = service.id in selectedIds
                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable(enabled = !isLoading) {
                                        setServiceChecked(service, !selected)
                                    },
                                shape = RoundedCornerShape(14.dp),
                                color = if (selected) {
                                    MaterialTheme.colorScheme.primaryContainer
                                } else {
                                    MaterialTheme.colorScheme.surface
                                },
                                tonalElevation = if (selected) 2.dp else 0.dp,
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                ) {
                                    Checkbox(
                                        checked = selected,
                                        onCheckedChange = { checked ->
                                            setServiceChecked(service, checked)
                                        },
                                        enabled = !isLoading,
                                        modifier = Modifier.size(30.dp),
                                    )
                                    Spacer(Modifier.width(9.dp))
                                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                                        Text(
                                            service.name.ifBlank { service.serviceCode.ifBlank { "Usluga" } },
                                            style = MaterialTheme.typography.bodyMedium,
                                            fontWeight = FontWeight.Black,
                                            maxLines = 2,
                                            overflow = TextOverflow.Ellipsis,
                                        )
                                        Text(
                                            listOf(service.serviceCode, service.validityMonths.takeIf { it.isNotBlank() }?.let { "$it mj." })
                                                .filterNotNull()
                                                .filter { it.isNotBlank() }
                                                .joinToString(" · "),
                                            style = MaterialTheme.typography.labelMedium,
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = onDismiss,
                enabled = !isLoading,
                shape = RoundedCornerShape(16.dp),
            ) {
                Text("Zatvori", fontWeight = FontWeight.Black)
            }
        },
    )
}

@Composable
private fun WorkOrderDocumentationSection(
    documents: List<WorkOrderDocument>,
    loading: Boolean,
    isBusy: Boolean,
    onGenerateDocumentation: () -> Unit,
    onAddDocumentation: () -> Unit,
    onOpenDocument: (WorkOrderDocument) -> Unit,
    onDownloadDocument: (WorkOrderDocument) -> Unit,
    onDeleteDocument: (WorkOrderDocument) -> Unit,
    onRefreshDocuments: () -> Unit,
    readOnly: Boolean = false,
) {
    DetailSection("Dokumentacija") {
        val groupedDocuments = remember(documents) { groupWorkOrderDocuments(documents) }
        var collapsedGroups by remember { mutableStateOf<Set<String>>(emptySet()) }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .horizontalScroll(rememberScrollState()),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            if (!readOnly) {
                Button(
                    onClick = onGenerateDocumentation,
                    enabled = !isBusy,
                    shape = RoundedCornerShape(16.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                ) {
                    Icon(Icons.Rounded.Description, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Izradi", fontWeight = FontWeight.Black)
                }
                Button(
                    onClick = onAddDocumentation,
                    enabled = !isBusy,
                    shape = RoundedCornerShape(16.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 10.dp),
                ) {
                    Icon(Icons.Rounded.Add, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Dodaj", fontWeight = FontWeight.Black)
                }
            }
            IconButton(onClick = onRefreshDocuments, enabled = !loading && !isBusy) {
                Icon(Icons.Rounded.Refresh, contentDescription = "Osvježi dokumentaciju")
            }
        }

        AnimatedVisibility(loading) {
            LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
        }

        if (!loading && documents.isEmpty()) {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.62f),
            ) {
                Row(
                    modifier = Modifier.padding(14.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(Icons.Rounded.InsertDriveFile, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                    Spacer(Modifier.width(12.dp))
                    Column {
                        Text("Još nema dokumentacije", fontWeight = FontWeight.Bold)
                        Text(
                            if (readOnly) "Nema dokumenata za prikaz." else "Dodaj sken, PDF, fotografije ili drugu datoteku.",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                }
            }
        }

        groupedDocuments.forEach { (group, groupDocuments) ->
            val expanded = group.key !in collapsedGroups
            WorkOrderDocumentGroupCard(
                group = group,
                documents = groupDocuments,
                expanded = expanded,
                enabled = !isBusy,
                onToggleExpanded = {
                    collapsedGroups = if (expanded) {
                        collapsedGroups + group.key
                    } else {
                        collapsedGroups - group.key
                    }
                },
                onOpenDocument = onOpenDocument,
                onDownloadDocument = onDownloadDocument,
                onDeleteDocument = onDeleteDocument,
                canDelete = !readOnly,
            )
        }
    }
}

