private const val DOCUMENTATION_BASICS_FLOW_KEY = "__basics__"
private const val DOCUMENTATION_WORK_EQUIPMENT_FLOW_KEY = "__work_equipment__"
private const val DOCUMENTATION_EQUIPMENT_INSPECTION_FLOW_KEY = "__equipment_inspection__"
private const val DOCUMENTATION_PHYSICAL_FACTORS_FLOW_KEY = "__physical_factors__"
private const val DOCUMENTATION_SUMMARY_FLOW_KEY = "__summary__"
private const val DOCUMENTATION_EXTRA_FLOW_PREFIX = "__extra__"

private fun DocumentationServiceFlowItem.serviceValidityKey(): String =
    listOf(serviceCode, serviceName, serviceKey)
        .firstOrNull { it.isNotBlank() }
        .orEmpty()

private fun normalizeDocumentationWorkEquipmentText(value: String): String =
    value.trim()
        .lowercase(Locale.getDefault())
        .replace("č", "c")
        .replace("ć", "c")
        .replace("ž", "z")
        .replace("š", "s")
        .replace("đ", "d")
        .replace(Regex("[^a-z0-9]+"), " ")
        .trim()

private fun normalizeDocumentationServiceCodeToken(value: String): String =
    normalizeDocumentationWorkEquipmentText(value)
        .replace(" ", "")
        .uppercase(Locale.getDefault())

private fun isDocumentationWorkEquipmentText(value: String): Boolean {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    val compact = normalized.replace(" ", "")
    if (
        normalized == "strojevi" ||
        normalized.startsWith("strojevi ") ||
        normalized == "radna oprema strojevi" ||
        normalized.contains("nadzor opreme") ||
        normalized.contains("nadzor strojeva")
    ) {
        return false
    }
    return normalized.contains("radna oprema") ||
        normalized.contains("radne opreme") ||
        normalized.contains("ispitivanje radne opreme") ||
        normalized.contains("pregled radne opreme") ||
        normalized == "ro" ||
        normalized.startsWith("ro ") ||
        compact == "ro"
}

private fun isDocumentationWorkEquipmentService(item: DocumentationServiceFlowItem): Boolean =
    isDocumentationWorkEquipmentText(item.serviceName) ||
        isDocumentationWorkEquipmentText(item.serviceCode) ||
        isDocumentationWorkEquipmentText(item.serviceKey)

private fun isDocumentationEquipmentInspectionCode(value: String): Boolean {
    val code = normalizeDocumentationServiceCodeToken(value)
    return code == "STROJEVI" || code == "NO"
}

private fun isDocumentationEquipmentInspectionText(value: String): Boolean {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    val compact = normalized.replace(" ", "")
    if (normalized.isBlank()) return false
    return normalized == "no" ||
        normalized.startsWith("no ") ||
        compact == "no" ||
        normalized == "strojevi" ||
        normalized.startsWith("strojevi ") ||
        normalized == "radnaoprema" ||
        normalized == "radna oprema strojevi" ||
        normalized.contains("nadzor opreme") ||
        normalized.contains("nadzor strojeva") ||
        normalized.contains("o nadzoru opreme")
}

private fun isDocumentationEquipmentInspectionService(item: DocumentationServiceFlowItem): Boolean {
    if (isDocumentationEquipmentInspectionCode(item.serviceCode) || isDocumentationEquipmentInspectionCode(item.serviceKey)) {
        return true
    }
    return false
}

private fun isDocumentationPhysicalFactorsText(value: String): Boolean {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    if (normalized.isBlank() || isDocumentationWorkEquipmentText(value) || isDocumentationEquipmentInspectionText(value)) return false
    return normalized == "fc" ||
        normalized.startsWith("fc ") ||
        normalized.contains("fizikalni cimbenici") ||
        normalized.contains("fizikalnih cimbenika") ||
        normalized.contains("radni okolis fizikal") ||
        normalized.contains("radnog okolisa fizikal")
}

private fun isDocumentationPhysicalFactorsService(item: DocumentationServiceFlowItem): Boolean =
    isDocumentationPhysicalFactorsText(item.serviceName) ||
        isDocumentationPhysicalFactorsText(item.serviceCode) ||
        isDocumentationPhysicalFactorsText(item.serviceKey)

private fun isDocumentationTrainingText(value: String): Boolean {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    if (normalized.isBlank() || isDocumentationWorkEquipmentText(value) || isDocumentationEquipmentInspectionText(value) || isDocumentationPhysicalFactorsText(value)) return false
    return normalized == "znr" ||
        normalized == "zos" ||
        normalized == "pgp" ||
        normalized == "szptp" ||
        normalized == "safe work" ||
        normalized == "fire initial" ||
        normalized.startsWith("znr ") ||
        normalized.startsWith("zos ") ||
        normalized.startsWith("pgp ") ||
        normalized.startsWith("szptp ") ||
        normalized.contains("osposoblj") ||
        normalized.contains("rad na siguran") ||
        normalized.contains("siguran nacin") ||
        normalized.contains("zastita na radu") ||
        normalized.contains("safe work") ||
        normalized.contains("fire initial") ||
        normalized.contains("pocetno gasenje") ||
        normalized.contains("gasenje pozara") ||
        normalized.contains("pozar") ||
        normalized.contains("zapaljivih tekucina") ||
        normalized.contains("adr")
}

private fun isDocumentationTrainingService(item: DocumentationServiceFlowItem): Boolean =
    isDocumentationTrainingText(item.serviceName) ||
        isDocumentationTrainingText(item.serviceCode) ||
        isDocumentationTrainingText(item.serviceKey)

private fun isDocumentationSprText(value: String): Boolean {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    if (normalized.isBlank()) return false
    return normalized == "spr" ||
        normalized == "tzin" ||
        normalized == "eiz" ||
        normalized == "szom" ||
        normalized == "szomv" ||
        normalized == "ves" ||
        normalized.startsWith("spr ") ||
        normalized.startsWith("tzin ") ||
        normalized.startsWith("eiz ") ||
        normalized.startsWith("szom ") ||
        normalized.startsWith("szomv ") ||
        normalized.startsWith("ves ") ||
        normalized.contains("sigurnosna panik") ||
        normalized.contains("panik rasvjet") ||
        normalized.contains("panic lighting") ||
        normalized.contains("emergency lighting") ||
        normalized.contains("tipkalo") ||
        normalized.contains("isklop elektric") ||
        normalized.contains("elektricn") ||
        normalized.contains("evakuacij") ||
        normalized.contains("zastitu od djelovanja munje")
}

private fun isDocumentationSprService(item: DocumentationServiceFlowItem): Boolean =
    isDocumentationSprText(item.serviceName) ||
        isDocumentationSprText(item.serviceCode) ||
        isDocumentationSprText(item.serviceKey)

private fun WorkOrderDocumentationTemplate.isSprDocumentationTemplate(): Boolean =
    listOf(serviceCode, serviceName, documentType, title, documentName)
        .any(::isDocumentationSprText)

private fun documentationNativeServiceCodeForText(value: String): String {
    val normalized = normalizeDocumentationWorkEquipmentText(value)
    val compact = normalized.replace(" ", "")
    if (normalized.isBlank()) return ""
    return when {
        normalized == "strojevi" ||
            normalized.startsWith("strojevi ") ||
            Regex("\\bstrojevi\\b").containsMatchIn(normalized) ||
            normalized.contains("nadzor opreme") ||
            normalized.contains("nadzor strojeva") -> "STROJEVI"
        normalized == "no" ||
            normalized.startsWith("no ") ||
            compact == "no" -> "NO"
        normalized == "radnaoprema" ||
            normalized == "radna oprema strojevi" -> "STROJEVI"
        normalized == "spr" ||
            normalized.startsWith("spr ") ||
            normalized.contains("sigurnosna panik") ||
            normalized.contains("panik rasvjet") ||
            normalized.contains("panic lighting") ||
            normalized.contains("emergency lighting") -> "SPR"
        normalized == "tzin" ||
            normalized.startsWith("tzin ") ||
            normalized.contains("tipkalo") ||
            normalized.contains("isklop elektric") -> "TZIN"
        normalized == "szomv" ||
            normalized.startsWith("szomv ") ||
            (normalized.contains("vizual") && normalized.contains("munj")) -> "SZOMV"
        normalized == "szom" ||
            normalized.startsWith("szom ") ||
            normalized.contains("zastitu od djelovanja munje") ||
            normalized.contains("zastite od djelovanja munje") -> "SZOM"
        normalized == "eiz" ||
            normalized.startsWith("eiz ") ||
            normalized.contains("elektricn") -> "EIZ"
        normalized == "ves" ||
            normalized.startsWith("ves ") ||
            normalized.contains("evakuacij") -> "VES"
        else -> ""
    }
}

private fun WorkOrderDocumentationTemplate.nativeDocumentationServiceCode(): String =
    documentationNativeServiceCodeForText(
        listOf(serviceCode, serviceName, documentType, title, documentName)
            .filter { it.isNotBlank() }
            .joinToString(" "),
    )

private fun WorkOrderDocumentationTemplate.previousDataSourceMatchesService(): Boolean {
    if (!dataSourceType.trim().equals("previous_inspection", ignoreCase = true)) return true
    val templateCode = nativeDocumentationServiceCode()
    val sourceCode = documentationNativeServiceCodeForText(dataSourceTitle)
    return templateCode.isBlank() || sourceCode.isBlank() || templateCode == sourceCode
}

private fun WorkOrderDocumentationTemplate.matchesDocumentationServiceFlowItem(item: DocumentationServiceFlowItem): Boolean {
    val templateCode = normalizeDocumentationWorkEquipmentText(serviceCode)
    val itemCode = normalizeDocumentationWorkEquipmentText(item.serviceCode)

    val templateLookup = listOf(serviceCode, serviceName, documentType, title, documentName)
        .filter { it.isNotBlank() }
        .joinToString(" ")
    val itemLookup = listOf(item.serviceCode, item.serviceName, item.serviceKey)
        .filter { it.isNotBlank() }
        .joinToString(" ")
    val templateNativeCode = documentationNativeServiceCodeForText(templateLookup)
    val itemNativeCode = documentationNativeServiceCodeForText(itemLookup)
    if (templateNativeCode.isNotBlank() && itemNativeCode.isNotBlank() && templateNativeCode != itemNativeCode) {
        return false
    }
    if (templateCode.isNotBlank() && itemCode.isNotBlank() && templateCode != itemCode && templateNativeCode.isBlank()) {
        return false
    }

    if (documentationServiceKey().equals(item.serviceKey, ignoreCase = true)) return true
    if (serviceIndex >= 0 && item.serviceIndex >= 0 && serviceIndex == item.serviceIndex) return true
    if (templateCode.isNotBlank() && itemCode.isNotBlank() && templateCode == itemCode) return true
    if (templateNativeCode.isNotBlank() && itemNativeCode.isNotBlank() && templateNativeCode == itemNativeCode) return true

    val templateName = normalizeDocumentationWorkEquipmentText(serviceName.ifBlank { documentType.ifBlank { title } })
    val itemName = normalizeDocumentationWorkEquipmentText(item.serviceName)
    return templateName.isNotBlank() &&
        itemName.isNotBlank() &&
        (templateName == itemName || templateName.contains(itemName) || itemName.contains(templateName))
}

private fun documentationAdditionalRecordFlowKey(record: DocumentationAdditionalObjectRecord, index: Int): String =
    "$DOCUMENTATION_EXTRA_FLOW_PREFIX:${record.serviceKey}:${record.objectId}:$index"

private fun buildDocumentationFlowTabs(
    flowItems: List<DocumentationServiceFlowItem>,
    additionalRecords: List<DocumentationAdditionalObjectRecord>,
    includeWorkEquipmentTab: Boolean = false,
    includeEquipmentInspectionTab: Boolean = false,
    includePhysicalFactorsTab: Boolean = false,
): List<DocumentationFlowTab> {
    val tabs = mutableListOf(
        DocumentationFlowTab(
            key = DOCUMENTATION_BASICS_FLOW_KEY,
            label = "Osnovno",
        ),
    )
    flowItems.forEachIndexed { serviceIndex, item ->
        val serviceLabel = when {
            isDocumentationEquipmentInspectionService(item) -> item.serviceCode.ifBlank { "STROJEVI" }
            isDocumentationWorkEquipmentService(item) -> "RO"
            isDocumentationPhysicalFactorsService(item) -> "FC"
            else -> item.serviceCode.ifBlank { item.serviceName.ifBlank { "Usluga" } }
        }
        val normalizedServiceLabel = serviceLabel.trim().uppercase(Locale.getDefault())
        val tabLabel = if (normalizedServiceLabel in setOf("SPR", "TZIN", "EIZ", "SZOM", "SZOMV", "VES", "RO", "NO", "STROJEVI", "FC")) {
            normalizedServiceLabel
        } else {
            "${serviceIndex + 1}. $serviceLabel"
        }
        tabs += DocumentationFlowTab(
            key = item.serviceKey,
            label = tabLabel,
            serviceItem = item,
        )
        additionalRecords.forEachIndexed { recordIndex, record ->
            if (record.serviceKey == item.serviceKey) {
                val sequence = tabs.count { tab -> tab.serviceItem?.serviceKey == item.serviceKey } + 1
                val recordLabel = record.serviceCode.ifBlank { item.serviceCode.ifBlank { "Usluga" } }.trim()
                val normalizedRecordLabel = recordLabel.uppercase(Locale.getDefault())
                val extraLabel = if (normalizedRecordLabel in setOf("SPR", "TZIN", "EIZ", "SZOM", "SZOMV", "VES", "RO", "NO", "STROJEVI", "FC")) {
                    "$normalizedRecordLabel $sequence"
                } else {
                    "$sequence. $recordLabel"
                }
                tabs += DocumentationFlowTab(
                    key = documentationAdditionalRecordFlowKey(record, recordIndex),
                    label = extraLabel,
                    serviceItem = item,
                    additionalRecordIndex = recordIndex,
                )
            }
        }
    }
    if (includeWorkEquipmentTab && flowItems.none { isDocumentationWorkEquipmentService(it) }) {
        tabs += DocumentationFlowTab(
            key = DOCUMENTATION_WORK_EQUIPMENT_FLOW_KEY,
            label = "RO",
        )
    }
    if (includeEquipmentInspectionTab && flowItems.none { isDocumentationEquipmentInspectionService(it) }) {
        tabs += DocumentationFlowTab(
            key = DOCUMENTATION_EQUIPMENT_INSPECTION_FLOW_KEY,
            label = "STROJEVI",
        )
    }
    if (includePhysicalFactorsTab && flowItems.none { isDocumentationPhysicalFactorsService(it) }) {
        tabs += DocumentationFlowTab(
            key = DOCUMENTATION_PHYSICAL_FACTORS_FLOW_KEY,
            label = "FC",
        )
    }
    tabs += DocumentationFlowTab(
        key = DOCUMENTATION_SUMMARY_FLOW_KEY,
        label = "Sažetak",
    )
    return tabs
}

private fun normalizeDocumentationSignatureAreaKey(value: String): String =
    value.trim()
        .lowercase(Locale.getDefault())
        .replace(Regex("[^a-z0-9_-]+"), "_")
        .trim('_')
        .ifBlank { "elektro" }

private fun inferDocumentationSignatureAreas(
    templates: List<WorkOrderDocumentationTemplate>,
    flowItem: DocumentationServiceFlowItem?,
): List<String> {
    val explicitAreas = templates
        .flatMap { template -> template.signatureAreas }
        .map(::normalizeDocumentationSignatureAreaKey)
        .filter { it.isNotBlank() }
        .distinct()
    if (explicitAreas.isNotEmpty()) {
        return explicitAreas
    }

    val text = listOf(flowItem?.serviceCode, flowItem?.serviceName)
        .filterNotNull()
        .joinToString(" ")
        .lowercase(Locale.getDefault())
    return when {
        Regex("\\b(tzin|tipkalo)\\b").containsMatchIn(text) || text.contains("isklop napona") -> listOf("tipkalo")
        Regex("\\b(spr|panik)\\b").containsMatchIn(text) || text.contains("panik rasvjet") -> listOf("elektro")
        Regex("\\b(no|strojevi)\\b").containsMatchIn(text) || text.contains("nadzor opreme") || text.contains("nadzor strojeva") -> listOf("strojevi", "radna_oprema")
        Regex("\\bro\\b").containsMatchIn(text) || text.contains("radna oprema") || text.contains("radne opreme") -> listOf("radna_oprema")
        Regex("\\bfc\\b").containsMatchIn(text) || text.contains("radni okoli") || text.contains("fizikalni") -> listOf("radni_okolis")
        else -> listOf("elektro")
    }
}

private fun List<WorkOrderDocumentationSignatureAreaOptions>.areaOptions(key: String): WorkOrderDocumentationSignatureAreaOptions {
    val normalizedKey = normalizeDocumentationSignatureAreaKey(key)
    return firstOrNull { normalizeDocumentationSignatureAreaKey(it.key) == normalizedKey }
        ?: WorkOrderDocumentationSignatureAreaOptions(
            key = normalizedKey,
            label = when (normalizedKey) {
                "tipkalo", "tzin" -> "Tipkalo za isklop napona"
                "elektro" -> "Elektro usluga"
                "radna_oprema", "ro" -> "Radna oprema"
                "strojevi", "no" -> "Nadzor opreme"
                "radni_okolis", "fc" -> "Radni okoliš"
                else -> normalizedKey.replace('_', ' ').replaceFirstChar { it.titlecase(Locale.getDefault()) }
            },
        )
}

private fun WorkOrderDocumentationOption.matchesExecutorLabel(executors: List<String>): Boolean {
    val normalizedExecutors = executors
        .map { normalizeServiceMatch(it) }
        .filter { it.isNotBlank() }
        .toSet()
    if (normalizedExecutors.isEmpty()) return false
    val candidates = listOf(id, label, subtitle, status)
        .map { normalizeServiceMatch(it) }
        .filter { it.isNotBlank() }
    return candidates.any { candidate ->
        normalizedExecutors.any { executor ->
            candidate == executor ||
                (executor.length >= 4 && candidate.contains(executor)) ||
                (candidate.length >= 4 && executor.contains(candidate))
        }
    }
}

private fun WorkOrderDocumentationSignatureAreaOptions.defaultInspectorIdsForExecutors(executors: List<String>): Set<String> {
    if (executors.isEmpty()) return emptySet()
    val defaultMatches = defaultInspectorIds
        .map { it.trim() }
        .filter { id -> inspectorOptions.firstOrNull { it.id == id }?.matchesExecutorLabel(executors) == true }
        .toSet()
    if (defaultMatches.isNotEmpty()) return defaultMatches
    return inspectorOptions
        .filter { option -> option.matchesExecutorLabel(executors) }
        .map { it.id.trim() }
        .filter { it.isNotBlank() }
        .toSet()
}

private fun WorkOrderDocumentationSignatureAreaOptions.defaultAuthorizationIdForExecutors(executors: List<String>): String {
    if (executors.isEmpty()) return ""
    val defaultId = defaultAuthorizationHolderId.trim()
    val defaultMatch = defaultId.takeIf { id -> authorizationOptions.firstOrNull { it.id == id }?.matchesExecutorLabel(executors) == true }.orEmpty()
    if (defaultMatch.isNotBlank()) return defaultMatch
    return authorizationOptions.firstOrNull { option -> option.matchesExecutorLabel(executors) }?.id.orEmpty().trim()
}

private val documentationSignatureFieldTypes = setOf(
    "qualified_inspectors",
    "inspector_signature",
    "authorization_holder_signature",
    "digital_signature",
)

private data class DocumentationPersonFieldRule(
    val id: String,
    val label: String,
    val signatureArea: String,
    val role: String,
    val multiple: Boolean,
    val required: Boolean,
    val helpText: String,
    val priority: Int,
)

private fun normalizeDocumentationSignatureRole(value: String, type: String = ""): String {
    val normalized = value.trim()
        .lowercase(Locale.getDefault())
        .replace("_", " ")
        .replace("-", " ")
    return when {
        normalized.contains("company") || normalized.contains("klijent") || normalized.contains("narucitelj") -> "company_responsible"
        normalized.contains("authorize") || normalized.contains("ovlast") || normalized.contains("nositelj") || normalized.contains("odgovorn") -> "authorize"
        type.equals("authorization_holder_signature", ignoreCase = true) -> "authorize"
        else -> "inspect"
    }
}

private fun isDocumentationSignatureFieldType(type: String): Boolean =
    documentationSignatureFieldTypes.contains(type.lowercase(Locale.getDefault()))

private fun WorkOrderDocumentationField.toPersonFieldRule(template: WorkOrderDocumentationTemplate): DocumentationPersonFieldRule? {
    if (!isDocumentationSignatureFieldType(type)) return null
    val role = normalizeDocumentationSignatureRole(signatureRole, type)
    return DocumentationPersonFieldRule(
        id = "${template.id}::${id.ifBlank { key.ifBlank { tokenKey } }}",
        label = label.ifBlank { if (role == "authorize") "Odgovorna osoba" else "Ispitivanje obavili" },
        signatureArea = normalizeDocumentationSignatureAreaKey(signatureArea),
        role = role,
        multiple = role == "inspect" && signatureMultiple,
        required = required,
        helpText = helpText,
        priority = if (type.equals("qualified_inspectors", ignoreCase = true)) 0 else 1,
    )
}

private fun WorkOrderDocumentationTemplateBlock.toPersonFieldRule(template: WorkOrderDocumentationTemplate): DocumentationPersonFieldRule? {
    if (!isDocumentationSignatureFieldType(type)) return null
    val role = normalizeDocumentationSignatureRole(signatureRole, type)
    return DocumentationPersonFieldRule(
        id = "${template.id}::${id.ifBlank { key.ifBlank { tokenKey } }}",
        label = label.ifBlank { if (role == "authorize") "Odgovorna osoba" else "Ispitivanje obavili" },
        signatureArea = normalizeDocumentationSignatureAreaKey(signatureArea),
        role = role,
        multiple = role == "inspect" && signatureMultiple,
        required = required,
        helpText = helpText,
        priority = if (type.equals("qualified_inspectors", ignoreCase = true)) 0 else 1,
    )
}

private fun buildDocumentationPersonFieldRules(templates: List<WorkOrderDocumentationTemplate>): List<DocumentationPersonFieldRule> {
    val rules = templates.flatMap { template ->
        template.fieldBlocks.mapNotNull { block -> block.toPersonFieldRule(template) } +
            template.fields.mapNotNull { field -> field.toPersonFieldRule(template) }
    }
    return rules
        .sortedWith(compareBy<DocumentationPersonFieldRule> { it.priority }.thenBy { it.label.lowercase(Locale.getDefault()) })
        .groupBy { "${it.signatureArea}::${it.role}" }
        .map { (_, areaRules) ->
            areaRules.reduce { current, next ->
                current.copy(
                    required = current.required || next.required,
                    helpText = listOf(current.helpText, next.helpText)
                        .map { it.trim() }
                        .filter { it.isNotBlank() }
                        .distinct()
                        .joinToString(" "),
                    multiple = current.multiple || next.multiple,
                )
            }
        }
}

private fun ensureDocumentationPersonFieldRulesForFlows(
    baseRules: List<DocumentationPersonFieldRule>,
    flowItems: List<DocumentationServiceFlowItem>,
    includeWorkEquipment: Boolean,
    includePhysicalFactors: Boolean,
): List<DocumentationPersonFieldRule> {
    val rules = baseRules.toMutableList()
    fun ensureRule(
        signatureArea: String,
        role: String,
        label: String,
        multiple: Boolean,
        priority: Int,
    ) {
        val normalizedArea = normalizeDocumentationSignatureAreaKey(signatureArea)
        val existingIndex = rules.indexOfFirst { normalizeDocumentationSignatureAreaKey(it.signatureArea) == normalizedArea && it.role == role }
        if (existingIndex >= 0) {
            rules[existingIndex] = rules[existingIndex].copy(
                label = label,
                multiple = rules[existingIndex].multiple || multiple,
                required = rules[existingIndex].required || true,
            )
            return
        }
        rules += DocumentationPersonFieldRule(
            id = "flow::$normalizedArea::$role",
            label = label,
            signatureArea = normalizedArea,
            role = role,
            multiple = multiple,
            required = true,
            helpText = "",
            priority = priority,
        )
    }

    if (includeWorkEquipment) {
        ensureRule("radna_oprema", "inspect", "Ispitivač radne opreme", true, -20)
        ensureRule("radna_oprema", "authorize", "Odgovorna osoba radne opreme", false, -19)
    }
    if (includePhysicalFactors) {
        ensureRule("radni_okolis", "inspect", "Ispitivač radnog okoliša", true, -18)
        ensureRule("radni_okolis", "authorize", "Odgovorna osoba radnog okoliša", false, -17)
    }
    flowItems.filter(::isDocumentationSprService).forEach { item ->
        inferDocumentationSignatureAreas(emptyList(), item).forEach { area ->
            val normalizedArea = normalizeDocumentationSignatureAreaKey(area)
            ensureRule(normalizedArea, "inspect", "Ispitivači", true, -16)
            ensureRule(normalizedArea, "authorize", "Odgovorna osoba", false, -15)
        }
    }

    return rules.sortedWith(compareBy<DocumentationPersonFieldRule> { it.priority }.thenBy { it.label.lowercase(Locale.getDefault()) })
}

private data class DocumentationEnvironmentVisibility(
    val outsideTemperature: Boolean = false,
    val relativeHumidity: Boolean = false,
    val airflowSpeed: Boolean = false,
    val weather: Boolean = false,
    val groundCondition: Boolean = false,
    val groundResistance: Boolean = false,
) {
    val any: Boolean
        get() = outsideTemperature || relativeHumidity || airflowSpeed || weather || groundCondition || groundResistance
}

private fun documentationEnvironmentVisibilityAll(): DocumentationEnvironmentVisibility =
    DocumentationEnvironmentVisibility(
        outsideTemperature = true,
        relativeHumidity = true,
        airflowSpeed = true,
        weather = true,
        groundCondition = true,
        groundResistance = true,
    )

private fun buildDocumentationEnvironmentVisibility(templates: List<WorkOrderDocumentationTemplate>): DocumentationEnvironmentVisibility {
    val lookup = normalizeTemplateFieldLookup(
        templates.joinToString(" ") { template ->
            listOf(
                template.title,
                template.documentType,
                template.fields.joinToString(" ") { field ->
                    listOf(field.id, field.key, field.tokenKey, field.label, field.helpText).joinToString(" ")
                },
                template.fieldBlocks.joinToString(" ") { block ->
                    listOf(block.id, block.key, block.tokenKey, block.label, block.typeLabel, block.group, block.helpText, block.summary).joinToString(" ")
                },
            ).joinToString(" ")
        },
    )
    fun hasAny(vararg aliases: String): Boolean =
        aliases.any { alias -> lookup.contains(normalizeTemplateFieldLookup(alias)) }
    return DocumentationEnvironmentVisibility(
        outsideTemperature = hasAny("vanjska temperatura", "outside temperature"),
        relativeHumidity = hasAny("relativna vlaga", "relative humidity", "humidity"),
        airflowSpeed = hasAny("strujanje zraka", "brzina zraka", "airflow", "air flow"),
        weather = hasAny("vremenski uvjeti", "weather"),
        groundCondition = hasAny("stanje tla", "ground condition"),
        groundResistance = hasAny("otpor tla", "ground resistance"),
    )
}

private fun WorkOrderDocumentationTemplate.documentationServiceKey(): String {
    val indexKey = serviceIndex.takeIf { it >= 0 }?.let { "service-$it" }.orEmpty()
    val fallback = listOf(serviceCode, serviceName, documentType, title)
        .firstOrNull { it.isNotBlank() }
        .orEmpty()
        .lowercase(Locale.getDefault())
    return indexKey.ifBlank { fallback.ifBlank { id } }
}

private fun documentationServiceShortCode(
    serviceCode: String,
    serviceName: String,
    serviceIndex: Int,
): String {
    val explicitCode = serviceCode.trim()
    if (explicitCode.isNotBlank() && explicitCode.length <= 18) return explicitCode.uppercase(Locale.getDefault())
    val source = explicitCode.ifBlank { serviceName }
    val acronym = source
        .split(Regex("[^\\p{L}\\p{N}]+"))
        .mapNotNull { part -> part.firstOrNull()?.uppercaseChar()?.toString() }
        .joinToString("")
        .take(8)
    return acronym.ifBlank { "USL-${serviceIndex + 1}" }
}

private fun WorkOrderServiceItem.catalogMatch(services: List<WorkOrderServiceOption>): WorkOrderServiceOption? {
    val sourceId = serviceId.trim()
    val sourceCode = normalizeDocumentationWorkEquipmentText(serviceCode)
    val sourceName = normalizeDocumentationWorkEquipmentText(name)
    return services.firstOrNull { service ->
        val catalogId = service.id.trim()
        val catalogCode = normalizeDocumentationWorkEquipmentText(service.serviceCode)
        val catalogName = normalizeDocumentationWorkEquipmentText(service.name)
        (sourceId.isNotBlank() && sourceId == catalogId) ||
            (sourceCode.isNotBlank() && sourceCode == catalogCode) ||
            (sourceName.isNotBlank() && sourceName == catalogName)
    }
}

private fun WorkOrderServiceItem.toDocumentationServiceFlowItem(
    serviceIndex: Int,
    services: List<WorkOrderServiceOption>,
): DocumentationServiceFlowItem {
    val catalogMatch = catalogMatch(services)
    val serviceName = catalogMatch?.name
        ?.ifBlank { name }
        ?.ifBlank { serviceCode.ifBlank { serviceId.ifBlank { "Usluga" } } }
        ?: name.ifBlank { serviceCode.ifBlank { serviceId.ifBlank { "Usluga" } } }
    val canonicalServiceCode = catalogMatch?.serviceCode?.ifBlank { serviceCode } ?: serviceCode
    val shortCode = documentationServiceShortCode(canonicalServiceCode, serviceName, serviceIndex)
    val serviceKey = serviceId
        .ifBlank { canonicalServiceCode }
        .ifBlank { serviceName }
        .let { source -> "work-order-service-$serviceIndex-${normalizeDocumentationWorkEquipmentText(source).ifBlank { "service" }}" }
    return DocumentationServiceFlowItem(
        serviceKey = serviceKey,
        serviceName = serviceName,
        serviceCode = shortCode,
        serviceIndex = serviceIndex,
        validityMonths = catalogMatch?.validityMonths.orEmpty(),
        documentNumbers = emptyList(),
        documentNames = emptyList(),
        templateCount = 0,
    )
}

private fun DocumentationServiceFlowItem.matchesDocumentationServiceFlowCandidate(candidate: DocumentationServiceFlowItem): Boolean {
    val itemLookup = listOf(serviceCode, serviceName, serviceKey)
        .filter { it.isNotBlank() }
        .joinToString(" ")
    val candidateLookup = listOf(candidate.serviceCode, candidate.serviceName, candidate.serviceKey)
        .filter { it.isNotBlank() }
        .joinToString(" ")
    val itemNativeCode = documentationNativeServiceCodeForText(itemLookup)
    val candidateNativeCode = documentationNativeServiceCodeForText(candidateLookup)
    if (itemNativeCode.isNotBlank() && candidateNativeCode.isNotBlank()) {
        return itemNativeCode == candidateNativeCode
    }

    val itemCode = normalizeDocumentationWorkEquipmentText(serviceCode)
    val candidateCode = normalizeDocumentationWorkEquipmentText(candidate.serviceCode)
    if (itemCode.isNotBlank() && candidateCode.isNotBlank() && itemCode == candidateCode) return true

    val itemName = normalizeDocumentationWorkEquipmentText(serviceName)
    val candidateName = normalizeDocumentationWorkEquipmentText(candidate.serviceName)
    return itemName.isNotBlank() &&
        candidateName.isNotBlank() &&
        (itemName == candidateName || itemName.contains(candidateName) || candidateName.contains(itemName))
}

private fun DocumentationServiceFlowItem.matchesWorkOrderService(service: WorkOrderServiceItem): Boolean {
    val itemCode = normalizeDocumentationWorkEquipmentText(serviceCode)
    val serviceCode = normalizeDocumentationWorkEquipmentText(service.serviceCode)
    if (itemCode.isNotBlank() && serviceCode.isNotBlank() && itemCode == serviceCode) return true

    val itemName = normalizeDocumentationWorkEquipmentText(serviceName)
    val serviceName = normalizeDocumentationWorkEquipmentText(service.name)
    return itemName.isNotBlank() && serviceName.isNotBlank() && itemName == serviceName
}

private fun buildDocumentationServiceFlowItems(
    templates: List<WorkOrderDocumentationTemplate>,
    workOrder: WorkOrder,
    services: List<WorkOrderServiceOption>,
): List<DocumentationServiceFlowItem> {
    val explicitServiceDetails = workOrder.serviceDetails
        .filter { service -> service.name.isNotBlank() || service.serviceCode.isNotBlank() || service.serviceId.isNotBlank() }
    val fallbackServiceDetails = if (explicitServiceDetails.isEmpty()) {
        val fallbackService = workOrder.displayService.takeIf { it != "Bez upisane usluge" }.orEmpty()
        if (fallbackService.isBlank()) {
            emptyList()
        } else {
            listOf(
                WorkOrderServiceItem(
                    serviceId = "",
                    name = fallbackService,
                    serviceCode = "",
                    serviceStatus = "",
                    quantity = "1",
                ),
            )
        }
    } else {
        emptyList()
    }
    val workOrderSourceServices = explicitServiceDetails.ifEmpty { fallbackServiceDetails }
    val workOrderServiceItems = workOrderSourceServices
        .mapIndexed { index, service -> service.toDocumentationServiceFlowItem(index, services) }

    if (templates.isEmpty()) {
        if (workOrderServiceItems.isNotEmpty()) {
            return workOrderServiceItems
        }
        val fallbackService = workOrder.displayService.takeIf { it != "Bez upisane usluge" }.orEmpty()
        return listOf(
            DocumentationServiceFlowItem(
                serviceKey = "fallback",
                serviceName = fallbackService.ifBlank { "Usluga" },
                serviceCode = "USL-1",
                serviceIndex = 0,
                validityMonths = "",
                documentNumbers = listOf(workOrder.displayNumber).filter { it.isNotBlank() },
                documentNames = emptyList(),
                templateCount = 0,
            ),
        )
    }
    val templateItems = templates
        .groupBy { template -> template.documentationServiceKey() }
        .map { (serviceKey, serviceTemplates) ->
            val firstTemplate = serviceTemplates.minWithOrNull(
                compareBy<WorkOrderDocumentationTemplate> { it.serviceIndex.takeIf { index -> index >= 0 } ?: Int.MAX_VALUE }
                    .thenBy { it.serviceName.lowercase(Locale.getDefault()) }
            )
            val serviceName = firstTemplate?.serviceName
                ?.ifBlank { firstTemplate.documentType.ifBlank { firstTemplate.title } }
                ?.ifBlank { "Usluga" }
                ?: "Usluga"
            val serviceIndex = firstTemplate?.serviceIndex ?: Int.MAX_VALUE
            val serviceCode = documentationServiceShortCode(firstTemplate?.serviceCode.orEmpty(), serviceName, serviceIndex.takeIf { it != Int.MAX_VALUE } ?: 0)
            DocumentationServiceFlowItem(
                serviceKey = serviceKey,
                serviceName = serviceName,
                serviceCode = serviceCode,
                serviceIndex = serviceIndex,
                validityMonths = "",
                documentNumbers = serviceTemplates.mapNotNull { template -> template.documentNumber.ifBlank { null } }.distinct(),
                documentNames = serviceTemplates.mapNotNull { template -> template.documentName.ifBlank { null } }.distinct(),
                templateCount = serviceTemplates.size,
            )
        }
        .map { item ->
            val matchedValidity = workOrderSourceServices.firstNotNullOfOrNull { service ->
                if (item.matchesWorkOrderService(service)) service.catalogMatch(services)?.validityMonths?.takeIf { it.isNotBlank() } else null
            }.orEmpty()
            if (item.validityMonths.isBlank() && matchedValidity.isNotBlank()) {
                item.copy(validityMonths = matchedValidity)
            } else {
                item
            }
        }
    val relevantTemplateItems = if (workOrderServiceItems.isNotEmpty()) {
        templateItems.filter { templateItem ->
            workOrderServiceItems.any { serviceItem -> templateItem.matchesDocumentationServiceFlowCandidate(serviceItem) }
        }
    } else {
        templateItems
    }
    val missingWorkOrderServices = workOrderServiceItems
        .filter { service -> relevantTemplateItems.none { item -> item.matchesDocumentationServiceFlowCandidate(service) } }
    return (relevantTemplateItems + missingWorkOrderServices)
        .ifEmpty { workOrderServiceItems.ifEmpty { templateItems } }
        .distinctBy { item ->
            listOf(item.serviceCode, item.serviceName, item.serviceKey)
                .firstOrNull { it.isNotBlank() }
                ?.let(::normalizeDocumentationWorkEquipmentText)
                .orEmpty()
        }
        .sortedWith(compareBy<DocumentationServiceFlowItem> { it.serviceIndex }.thenBy { it.serviceName.lowercase(Locale.getDefault()) })
}

private fun inspectionTypeMatchesOptions(value: String, options: List<Pair<String, String>>): Boolean {
    val trimmed = value.trim()
    if (trimmed.isBlank()) return false
    return options.any { option ->
        option.first.equals(trimmed, ignoreCase = true) || option.second.equals(trimmed, ignoreCase = true)
    }
}

private fun chooseInspectionTypeValue(
    savedValue: String,
    options: List<Pair<String, String>>,
    fallbackValue: String,
): String {
    val saved = savedValue.trim()
    if (saved.isNotBlank() && (options.isEmpty() || inspectionTypeMatchesOptions(saved, options))) {
        return saved
    }
    val fallback = fallbackValue.trim()
    if (fallback.isNotBlank() && (options.isEmpty() || inspectionTypeMatchesOptions(fallback, options))) {
        return fallback
    }
    return options.firstOrNull()?.first.orEmpty()
}

private data class DocumentationStandardValues(
    val inspectionDate: String,
    val issuedDate: String,
    val inspectionType: String,
    val testingLocation: String,
    val outsideTemperature: String,
    val relativeHumidity: String,
    val airflowSpeed: String,
    val weather: String,
    val groundCondition: String,
    val groundResistance: String,
    val measurementEquipmentGroup: String,
    val inspectorUserId: String,
    val inspectorLabel: String,
    val authorizationHolderUserId: String,
    val authorizationHolderLabel: String,
    val electricalInspectorUserId: String,
    val electricalInspectorLabel: String,
    val electricalAuthorizationHolderUserId: String,
    val electricalAuthorizationHolderLabel: String,
    val tipkaloInspectorUserId: String,
    val tipkaloInspectorLabel: String,
    val tipkaloAuthorizationHolderUserId: String,
    val tipkaloAuthorizationHolderLabel: String,
    val workEquipmentInspectorUserId: String,
    val workEquipmentInspectorLabel: String,
    val workEquipmentAuthorizationHolderUserId: String,
    val workEquipmentAuthorizationHolderLabel: String,
    val workEnvironmentInspectorUserId: String,
    val workEnvironmentInspectorLabel: String,
    val workEnvironmentAuthorizationHolderUserId: String,
    val workEnvironmentAuthorizationHolderLabel: String,
    val selectedEquipmentCount: Int,
    val selectedLegalCount: Int,
)

private fun WorkOrderDocumentationField.lookupText(): String =
    normalizeTemplateFieldLookup(listOf(id, key, tokenKey, label, type, signatureArea, signatureRole).joinToString(" "))

private fun WorkOrderDocumentationTemplateBlock.lookupText(): String =
    normalizeTemplateFieldLookup(listOf(id, key, tokenKey, label, type, typeLabel, group, signatureArea, signatureRole).joinToString(" "))

private fun standardDocumentationSignatureValue(
    signatureArea: String,
    role: String,
    type: String = "",
    standard: DocumentationStandardValues,
): String {
    val area = normalizeDocumentationSignatureAreaKey(signatureArea)
    val normalizedRole = normalizeDocumentationSignatureRole(role, type)
    fun authorizationValue(): String =
        when (area) {
            "tipkalo", "tzin" -> standard.tipkaloAuthorizationHolderLabel.ifBlank { standard.tipkaloAuthorizationHolderUserId }
            "elektro" -> standard.electricalAuthorizationHolderLabel.ifBlank { standard.electricalAuthorizationHolderUserId }
            "radna_oprema", "ro", "strojevi", "no" -> standard.workEquipmentAuthorizationHolderLabel.ifBlank { standard.workEquipmentAuthorizationHolderUserId }
            "radni_okolis", "fc" -> standard.workEnvironmentAuthorizationHolderLabel.ifBlank { standard.workEnvironmentAuthorizationHolderUserId }
            else -> standard.authorizationHolderLabel.ifBlank { standard.authorizationHolderUserId }
        }

    fun inspectorValue(): String =
        when (area) {
            "tipkalo", "tzin" -> standard.tipkaloInspectorLabel.ifBlank { standard.tipkaloInspectorUserId }
            "elektro" -> standard.electricalInspectorLabel.ifBlank { standard.electricalInspectorUserId }
            "radna_oprema", "ro", "strojevi", "no" -> standard.workEquipmentInspectorLabel.ifBlank { standard.workEquipmentInspectorUserId }
            "radni_okolis", "fc" -> standard.workEnvironmentInspectorLabel.ifBlank { standard.workEnvironmentInspectorUserId }
            else -> standard.inspectorLabel.ifBlank { standard.inspectorUserId }
        }

    return when (normalizedRole) {
        "authorize" -> authorizationValue()
        "all" -> listOf(inspectorValue(), authorizationValue())
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .joinToString(", ")
        else -> inspectorValue()
    }
}

private fun standardDocumentationValueForLookup(lookup: String, standard: DocumentationStandardValues): String? =
    when {
        lookup.contains("datum ispitivanja") || lookup.contains("inspection date") || lookup.contains("date of inspection") ->
            standard.inspectionDate
        lookup.contains("datum izdavanja") || lookup.contains("issued date") || lookup.contains("date issued") ->
            standard.issuedDate
        lookup.contains("vrsta ispitivanja") || lookup.contains("inspection type") ->
            standard.inspectionType
        lookup.contains("mjesto ispitivanja") ||
            lookup.contains("lokacija ispitivanja") ||
            lookup.contains("testing location") ||
            lookup.contains("inspection location") ->
            standard.testingLocation
        lookup.contains("temperatura") || lookup.contains("outside temperature") || lookup.contains("vanjska temperatura") ->
            standard.outsideTemperature
        lookup.contains("relativna vlaga") || lookup.contains("vlaga") || lookup.contains("humidity") ->
            standard.relativeHumidity
        lookup.contains("strujanje zraka") || lookup.contains("brzina zraka") || lookup.contains("airflow") || lookup.contains("air flow") ->
            standard.airflowSpeed
        lookup.contains("vrijeme") || lookup.contains("weather") ->
            standard.weather
        lookup.contains("stanje tla") || lookup.contains("ground condition") ->
            standard.groundCondition
        lookup.contains("otpor tla") || lookup.contains("ground resistance") ->
            standard.groundResistance
        lookup.contains("grupa mjerne") || lookup.contains("measurement equipment group") || lookup.contains("mjerna oprema grupa") ->
            standard.measurementEquipmentGroup
        lookup.contains("elektro") && (lookup.contains("nositelj") || lookup.contains("holder") || lookup.contains("ovlast")) ->
            standard.electricalAuthorizationHolderLabel
        lookup.contains("tipkalo") && (lookup.contains("nositelj") || lookup.contains("holder") || lookup.contains("ovlast")) ->
            standard.tipkaloAuthorizationHolderLabel
        lookup.contains("elektro") && (lookup.contains("ispitivac") || lookup.contains("ispitivao") || lookup.contains("inspector")) ->
            standard.electricalInspectorLabel
        lookup.contains("tipkalo") && (lookup.contains("ispitivac") || lookup.contains("ispitivao") || lookup.contains("inspector")) ->
            standard.tipkaloInspectorLabel
        (lookup.contains("radna oprema") || lookup.contains("radne opreme") || lookup.contains(" ro ")) &&
            (lookup.contains("nositelj") || lookup.contains("holder") || lookup.contains("ovlast") || lookup.contains("odgovorna")) ->
            standard.workEquipmentAuthorizationHolderLabel
        (lookup.contains("radni okolis") || lookup.contains("radnog okolisa") || lookup.contains(" fc ") || lookup.contains("fizikalni")) &&
            (lookup.contains("nositelj") || lookup.contains("holder") || lookup.contains("ovlast") || lookup.contains("odgovorna")) ->
            standard.workEnvironmentAuthorizationHolderLabel
        (lookup.contains("radna oprema") || lookup.contains("radne opreme") || lookup.contains(" ro ")) &&
            (lookup.contains("ispitivac") || lookup.contains("ispitivao") || lookup.contains("inspector")) ->
            standard.workEquipmentInspectorLabel
        (lookup.contains("radni okolis") || lookup.contains("radnog okolisa") || lookup.contains(" fc ") || lookup.contains("fizikalni")) &&
            (lookup.contains("ispitivac") || lookup.contains("ispitivao") || lookup.contains("inspector")) ->
            standard.workEnvironmentInspectorLabel
        lookup.contains("nositelj") || lookup.contains("authorization holder") || lookup.contains("holder") ->
            standard.authorizationHolderLabel
        lookup.contains("ispitivac") || lookup.contains("ispitivao") || lookup.contains("inspector") ->
            standard.inspectorLabel
        else -> null
    }?.trim()

private fun standardDocumentationValueForField(
    field: WorkOrderDocumentationField,
    standard: DocumentationStandardValues,
): String? {
    if (field.type.equals("qualified_inspectors", ignoreCase = true)) {
        return standardDocumentationSignatureValue(field.signatureArea, field.signatureRole, field.type, standard)
    }
    if (field.type.equals("inspector_signature", ignoreCase = true)) {
        return standardDocumentationSignatureValue(field.signatureArea, field.signatureRole, field.type, standard)
    }
    if (field.type.equals("authorization_holder_signature", ignoreCase = true) ||
        field.type.equals("digital_signature", ignoreCase = true)
    ) {
        return standardDocumentationSignatureValue(field.signatureArea, field.signatureRole, field.type, standard)
    }
    return standardDocumentationValueForLookup(field.lookupText(), standard)
}

private fun buildStandardTemplateFieldValues(
    templates: List<WorkOrderDocumentationTemplate>,
    standard: DocumentationStandardValues,
): Map<String, String> =
    buildMap {
        templates.forEach { template ->
            template.fields.forEach { field ->
                val value = standardDocumentationValueForField(field, standard).orEmpty()
                if (value.isNotBlank()) {
                    put(templateFieldStateKey(template, field), value)
                }
            }
        }
    }

private fun isDocumentationRequiredValueFilled(field: WorkOrderDocumentationField, value: String): Boolean {
    val normalized = value.trim()
    return when (field.type.lowercase(Locale.getDefault())) {
        "checkbox", "toggle" -> normalized.equals("true", ignoreCase = true) ||
            normalized == "1" ||
            normalized.equals("da", ignoreCase = true)
        else -> normalized.isNotBlank()
    }
}

private fun findMissingRequiredDocumentationFields(
    templates: List<WorkOrderDocumentationTemplate>,
    values: Map<String, String>,
    standard: DocumentationStandardValues,
): List<String> {
    val missing = mutableListOf<String>()
    val seen = mutableSetOf<String>()

    templates.forEach { template ->
        template.fields.filter { it.required }.forEach { field ->
            val value = values[templateFieldStateKey(template, field)]
                ?: standardDocumentationValueForField(field, standard)
                ?: ""
            if (!isDocumentationRequiredValueFilled(field, value)) {
                val label = listOf(template.serviceCode, field.label)
                    .filter { it.isNotBlank() }
                    .joinToString(" - ")
                    .ifBlank { field.label.ifBlank { "Obavezno polje" } }
                if (seen.add(label)) missing.add(label)
            }
        }
        template.fieldBlocks.filter { it.required }.forEach { block ->
            val lookup = block.lookupText()
            val standardValue = standardDocumentationValueForLookup(lookup, standard).orEmpty()
            val matchingField = findTemplateFieldForBlock(template, block)
            val matchingValue = matchingField?.let { field ->
                values[templateFieldStateKey(template, field)]
                    ?: standardDocumentationValueForField(field, standard)
                    ?: ""
            }.orEmpty()
            val matchingAiField = template.aiFields.firstOrNull { aiField ->
                val blockKeys = listOf(block.id, block.key, block.tokenKey, block.label)
                    .map { it.trim() }
                    .filter { it.isNotBlank() }
                    .map { normalizeTemplateFieldLookup(it) }
                    .toSet()
                templateAiFieldCandidateKeys(aiField)
                    .map(::normalizeTemplateFieldLookup)
                    .any { it.isNotBlank() && blockKeys.contains(it) }
            }
            val matchingAiValue = matchingAiField?.let { field -> values[templateAiFieldStateKey(template, field)].orEmpty() }.orEmpty()
            val complete = when (block.type.lowercase(Locale.getDefault())) {
                "equipment_list" -> standard.selectedEquipmentCount > 0
                "legal_list" -> standard.selectedLegalCount > 0
                "measurement_table" -> true
                "chapter" -> true
                "qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature" ->
                    standardDocumentationSignatureValue(block.signatureArea, block.signatureRole, block.type, standard).isNotBlank()
                else -> matchingValue.isNotBlank() || matchingAiValue.isNotBlank() || standardValue.isNotBlank()
            }
            if (!complete) {
                val label = listOf(template.serviceCode, block.label)
                    .filter { it.isNotBlank() }
                    .joinToString(" - ")
                    .ifBlank { block.label.ifBlank { "Obavezni blok" } }
                if (seen.add(label)) missing.add(label)
            }
        }
    }

    return missing
}

private fun WorkOrderDocumentationDefaults.hasReusableDocumentationDefaults(): Boolean =
    fieldValues.isNotEmpty() ||
        fieldSheets.isNotEmpty() ||
        templateFieldValues.values.any { it.isNotEmpty() } ||
        templateFieldSheets.values.any { it.isNotEmpty() } ||
        attachments.isNotEmpty() ||
        selectedEquipmentIds.isNotEmpty() ||
        selectedLegalFrameworkIds.isNotEmpty() ||
        listOf(
            inspectionDate,
            issuedDate,
            inspectionType,
            outsideTemperature,
            relativeHumidity,
            airflowSpeed,
            weather,
            groundCondition,
            groundResistance,
            measurementEquipmentGroup,
        ).any { it.isNotBlank() }

@Composable
private fun WorkOrderDocumentationWizardDialog(
    workOrder: WorkOrder,
    users: List<WorkOrderUserOption>,
    currentUser: SafeNexusUser?,
    services: List<WorkOrderServiceOption>,
    locationObjects: List<WorkOrderLocationObjectOption>,
    selectedObjectId: String,
    context: WorkOrderDocumentationContext,
    contextLoading: Boolean,
    isLoading: Boolean,
    workEquipmentSubmitResult: IsznrWorkEquipmentSubmitResult = IsznrWorkEquipmentSubmitResult(),
    physicalFactorsSubmitResult: IsznrWorkEquipmentSubmitResult = IsznrWorkEquipmentSubmitResult(),
    onDismiss: () -> Unit,
    onObjectSelectionChange: (String) -> Unit,
    onCreateObject: (String) -> Unit,
    onExecutorsChange: (List<String>) -> Unit,
    onRunAi: (
        WorkOrderDocumentationTemplate,
        List<WorkOrderDocumentationAiFile>,
        String,
        (WorkOrderDocumentationAiResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onRunSprVoiceAi: (
        WorkOrderDocumentationTemplate,
        String,
        (SprVoiceAiResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onRecognizeWorkEquipmentImages: (
        IsznrManualWorkEquipment,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onRecognizeWorkEquipmentBatchImages: (
        List<IsznrManualWorkEquipment>,
        List<IsznrRoAttachmentFile>,
        (WorkEquipmentImageRecognitionResult) -> Unit,
        (String) -> Unit,
    ) -> Unit,
    onSubmitIsznrWorkEquipment: (List<String>, List<IsznrManualWorkEquipment>) -> Unit,
    onSubmitIsznrPhysicalFactors: (List<String>, IsznrManualPhysicalFactors) -> Unit,
    onConfirmTraining: (String, List<String>, List<String>, Boolean, Boolean) -> Unit,
    onGenerateTrainingRecord: () -> Unit,
    onDownloadTrainingImportTemplate: () -> Unit,
    onUploadTrainingImport: () -> Unit,
    onAddTrainingPerson: (WorkOrderTrainingManualPersonDraft) -> Unit,
    onConfirm: (WorkOrderDocumentationDraft) -> Unit,
) {
    val androidContext = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val today = remember { LocalDate.now().toString() }
    val userOptions = remember(users) {
        listOf("" to "Nije odabrano") + users.map { user ->
            user.id to user.label.ifBlank { user.fullName.ifBlank { user.email } }
        }
    }
    val userLabelById = remember(userOptions) { userOptions.toMap() }
    val executorOptions = remember(users, workOrder.executors) {
        (
            users.map { user -> user.label.ifBlank { user.fullName.ifBlank { user.email } } } +
                workOrder.executors
            )
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .map { it to it }
    }
    var editableExecutors by remember(workOrder.id, workOrder.executors) {
        mutableStateOf(workOrder.executors.map { it.trim() }.filter { it.isNotBlank() }.distinct())
    }
    var completedBy by remember(workOrder.id, workOrder.completedBy, workOrder.executors) {
        mutableStateOf(workOrder.completedBy.ifBlank { workOrder.executors.firstOrNull().orEmpty() })
    }
    val defaultHandoverVerifierUserId = remember(users, currentUser?.displayName, currentUser?.email) {
        val currentEmail = currentUser?.email.orEmpty()
        val currentLabel = currentUser?.displayName.orEmpty()
        users.firstOrNull { user ->
            user.email.equals(currentEmail, ignoreCase = true) ||
                listOf(user.label, user.fullName, user.email)
                    .any { value -> value.equals(currentLabel, ignoreCase = true) }
        }?.id.orEmpty()
    }
    var handoverVerifierUserId by remember(workOrder.id, defaultHandoverVerifierUserId) {
        mutableStateOf(defaultHandoverVerifierUserId)
    }
    LaunchedEffect(defaultHandoverVerifierUserId) {
        if (handoverVerifierUserId.isBlank() && defaultHandoverVerifierUserId.isNotBlank()) {
            handoverVerifierUserId = defaultHandoverVerifierUserId
        }
    }
    val completedByOptions = remember(editableExecutors, completedBy) {
        (listOf("") + editableExecutors + listOf(completedBy))
            .map { it.trim() }
            .distinctBy { it.lowercase(Locale.getDefault()) }
            .map { it to it.ifBlank { "Nije odabrano" } }
    }
    val serviceFlowItems = remember(context.templates, workOrder.displayNumber, workOrder.displayService, workOrder.serviceDetails, services) {
        buildDocumentationServiceFlowItems(context.templates, workOrder, services)
    }
    val isWorkEquipmentFlow = remember(serviceFlowItems, workOrder.displayService) {
        serviceFlowItems.any { isDocumentationWorkEquipmentService(it) } ||
            isDocumentationWorkEquipmentText(workOrder.displayService)
    }
    val isEquipmentInspectionFlow = remember(serviceFlowItems, workOrder.displayService) {
        serviceFlowItems.any { isDocumentationEquipmentInspectionService(it) } ||
            isDocumentationEquipmentInspectionText(workOrder.displayService)
    }
    val isPhysicalFactorsFlow = remember(serviceFlowItems, workOrder.displayService) {
        serviceFlowItems.any { isDocumentationPhysicalFactorsService(it) } ||
            isDocumentationPhysicalFactorsText(workOrder.displayService)
    }
    val workEquipmentStatusMessage = context.workEquipmentStatus["message"].orEmpty()
    val showWorkEquipmentFromIsznr = isWorkEquipmentFlow
    val showEquipmentInspectionLocal = isEquipmentInspectionFlow
    val showPhysicalFactorsFromIsznr = isPhysicalFactorsFlow
    var selectedWorkEquipmentItemIds by remember(workOrder.id, context.workEquipmentOptions) {
        mutableStateOf(emptySet<String>())
    }
    var selectedPhysicalFactorsItemIds by remember(workOrder.id, context.workEnvironmentOptions) {
        mutableStateOf(emptySet<String>())
    }
    var manualWorkEquipments by remember(workOrder.id, context.workEquipmentOptions) {
        mutableStateOf(emptyList<IsznrManualWorkEquipment>())
    }
    var manualEquipmentInspectionEquipments by remember(workOrder.id) {
        mutableStateOf(emptyList<IsznrManualWorkEquipment>())
    }
    val selectedWorkEquipmentRecords = remember(context.workEquipmentOptions, selectedWorkEquipmentItemIds) {
        val selectedIds = selectedWorkEquipmentItemIds.map { it.trim() }.filter { it.isNotBlank() }.toSet()
        context.workEquipmentOptions.filter { option -> selectedIds.contains(option.id.trim()) }
    }
    val selectedPhysicalFactorsRecords = remember(context.workEnvironmentOptions, selectedPhysicalFactorsItemIds) {
        val selectedIds = selectedPhysicalFactorsItemIds.map { it.trim() }.filter { it.isNotBlank() }.toSet()
        context.workEnvironmentOptions.filter { option -> selectedIds.contains(option.id.trim()) }
    }
    val lastWorkEquipmentSubmitResult = workEquipmentSubmitResult
    val trainingContext = context.trainingContext
    val hasTrainingDocumentationIntent = remember(serviceFlowItems, workOrder.displayService) {
        serviceFlowItems.any { isDocumentationTrainingService(it) } ||
            isDocumentationTrainingText(workOrder.displayService)
    }
    val isTrainingDocumentationFlow = trainingContext.enabled || (contextLoading && hasTrainingDocumentationIntent)
    var additionalRecords by remember(workOrder.id, serviceFlowItems) {
        mutableStateOf(emptyList<DocumentationAdditionalObjectRecord>())
    }
    val flowTabs = remember(serviceFlowItems, additionalRecords, showWorkEquipmentFromIsznr, showEquipmentInspectionLocal, showPhysicalFactorsFromIsznr, isTrainingDocumentationFlow) {
        if (isTrainingDocumentationFlow) {
            listOf(
                DocumentationFlowTab(
                    key = DOCUMENTATION_BASICS_FLOW_KEY,
                    label = "Osposobljavanje",
                ),
            )
        } else {
            buildDocumentationFlowTabs(
                flowItems = serviceFlowItems,
                additionalRecords = additionalRecords,
                includeWorkEquipmentTab = showWorkEquipmentFromIsznr,
                includeEquipmentInspectionTab = showEquipmentInspectionLocal,
                includePhysicalFactorsTab = showPhysicalFactorsFromIsznr,
            )
        }
    }
    var selectedFlowService by rememberSaveable(workOrder.id) {
        mutableStateOf(DOCUMENTATION_BASICS_FLOW_KEY)
    }
    LaunchedEffect(flowTabs, selectedFlowService) {
        if (flowTabs.none { it.key == selectedFlowService }) {
            selectedFlowService = DOCUMENTATION_BASICS_FLOW_KEY
        }
    }
    val basicsFlowSelected = selectedFlowService == DOCUMENTATION_BASICS_FLOW_KEY
    val summaryFlowSelected = selectedFlowService == DOCUMENTATION_SUMMARY_FLOW_KEY
    val selectedFlowTab = remember(flowTabs, selectedFlowService) {
        flowTabs.firstOrNull { it.key == selectedFlowService } ?: flowTabs.firstOrNull()
    }
    val workEquipmentFlowSelected = selectedFlowService == DOCUMENTATION_WORK_EQUIPMENT_FLOW_KEY ||
        selectedFlowTab?.serviceItem?.let { isDocumentationWorkEquipmentService(it) } == true
    val equipmentInspectionFlowSelected = selectedFlowService == DOCUMENTATION_EQUIPMENT_INSPECTION_FLOW_KEY ||
        selectedFlowTab?.serviceItem?.let { isDocumentationEquipmentInspectionService(it) } == true
    val physicalFactorsFlowSelected = selectedFlowService == DOCUMENTATION_PHYSICAL_FACTORS_FLOW_KEY ||
        selectedFlowTab?.serviceItem?.let { isDocumentationPhysicalFactorsService(it) } == true
    val selectedAdditionalRecord = selectedFlowTab?.additionalRecordIndex?.let { index -> additionalRecords.getOrNull(index) }
    val selectedFlowItem = remember(serviceFlowItems, selectedFlowTab, selectedAdditionalRecord, workEquipmentFlowSelected, equipmentInspectionFlowSelected, physicalFactorsFlowSelected) {
        selectedFlowTab?.serviceItem ?: when {
            workEquipmentFlowSelected -> null
            equipmentInspectionFlowSelected -> null
            physicalFactorsFlowSelected -> null
            summaryFlowSelected -> null
            basicsFlowSelected -> serviceFlowItems.firstOrNull()
            else -> serviceFlowItems.firstOrNull()
        }
    }
    val activeTemplates = remember(
        context.templates,
        selectedFlowItem?.serviceKey,
        selectedFlowItem?.serviceCode,
        selectedFlowItem?.serviceName,
        selectedFlowItem?.serviceIndex,
        summaryFlowSelected,
        workEquipmentFlowSelected,
        equipmentInspectionFlowSelected,
        physicalFactorsFlowSelected,
    ) {
        if (summaryFlowSelected || workEquipmentFlowSelected || equipmentInspectionFlowSelected || physicalFactorsFlowSelected) {
            return@remember emptyList()
        }
        val flowItem = selectedFlowItem
        if (flowItem == null || flowItem.serviceKey.isBlank() || flowItem.serviceKey == "fallback") {
            context.templates
        } else {
            fun usableTemplates(templates: List<WorkOrderDocumentationTemplate>): List<WorkOrderDocumentationTemplate> =
                templates
                    .filter { template ->
                        template.fieldBlocks.isNotEmpty() ||
                            template.measurementTables.isNotEmpty() ||
                            template.fields.isNotEmpty()
                    }
                    .ifEmpty { templates }

            val matchedTemplates = context.templates.filter { template ->
                template.matchesDocumentationServiceFlowItem(flowItem)
            }
            val directMatches = usableTemplates(matchedTemplates)
            if (directMatches.isNotEmpty()) {
                return@remember directMatches
            }

            val flowNativeCode = documentationNativeServiceCodeForText(
                listOf(flowItem.serviceCode, flowItem.serviceName, flowItem.serviceKey)
                    .filter { it.isNotBlank() }
                    .joinToString(" "),
            )
            val nativeMatches = if (flowNativeCode.isNotBlank()) {
                context.templates.filter { template ->
                    val templateNativeCode = documentationNativeServiceCodeForText(
                        listOf(template.serviceCode, template.serviceName, template.documentType, template.title, template.documentName)
                            .filter { it.isNotBlank() }
                            .joinToString(" "),
                    )
                    templateNativeCode == flowNativeCode
                }
            } else {
                emptyList()
            }
            usableTemplates(nativeMatches).ifEmpty {
                if (context.templates.size == 1) context.templates else emptyList()
            }
        }
    }
    val activeTemplatesHaveGridline = remember(activeTemplates) {
        activeTemplates.any { template ->
            template.measurementTables.any { table -> table.sheet.columns.isNotEmpty() }
        }
    }
    val sprBrowserFlowSelected = remember(
        activeTemplates,
        activeTemplatesHaveGridline,
        selectedFlowItem,
        workOrder.displayService,
        basicsFlowSelected,
        summaryFlowSelected,
        workEquipmentFlowSelected,
        equipmentInspectionFlowSelected,
        physicalFactorsFlowSelected,
    ) {
        !basicsFlowSelected &&
            !summaryFlowSelected &&
            !workEquipmentFlowSelected &&
            !equipmentInspectionFlowSelected &&
            !physicalFactorsFlowSelected &&
            !activeTemplatesHaveGridline &&
            (
                selectedFlowItem?.let { isDocumentationSprService(it) } == true ||
                    activeTemplates.any { it.isSprDocumentationTemplate() } ||
                    isDocumentationSprText(workOrder.displayService)
                )
    }
    val templateInspectionOptions = remember(activeTemplates) {
        buildTemplateInspectionTypeOptions(activeTemplates)
    }
    val templateInspectionDefault = remember(activeTemplates) {
        getTemplateInspectionTypeDefault(activeTemplates)
    }
    val inspectionOptions = templateInspectionOptions
    val defaultInspectionType = remember(templateInspectionDefault, inspectionOptions) {
        chooseInspectionTypeValue(templateInspectionDefault, inspectionOptions, "")
    }
    val defaults = context.defaults
    val reusedDocumentationDefaultsLoaded = remember(defaults) { defaults.hasReusableDocumentationDefaults() }
    var inspectionDate by remember(workOrder.id, selectedObjectId, defaults.inspectionDate) { mutableStateOf(defaults.inspectionDate.ifBlank { today }) }
    var issuedDate by remember(workOrder.id, selectedObjectId, defaults.issuedDate) { mutableStateOf(defaults.issuedDate.ifBlank { inspectionDate.ifBlank { today } }) }
