private const val SPR_VOICE_REPLACE_COMMAND_PREFIX = "__SAFE_NEXUS_SPR_REPLACE__\n"
private const val SPR_VOICE_APPEND_COMMAND_PREFIX = "__SAFE_NEXUS_SPR_APPEND__\n"

private data class SprVoiceAction(
    val transcript: String,
    val replaceExisting: Boolean,
)

private fun encodeSprVoiceAction(transcript: String, replaceExisting: Boolean): String =
    (if (replaceExisting) SPR_VOICE_REPLACE_COMMAND_PREFIX else SPR_VOICE_APPEND_COMMAND_PREFIX) + transcript.trim()

private fun decodeSprVoiceAction(value: String, fallbackReplaceExisting: Boolean = false): SprVoiceAction {
    val trimmed = value.trim()
    return when {
        trimmed.startsWith(SPR_VOICE_REPLACE_COMMAND_PREFIX) -> SprVoiceAction(
            transcript = trimmed.removePrefix(SPR_VOICE_REPLACE_COMMAND_PREFIX).trim(),
            replaceExisting = true,
        )
        trimmed.startsWith(SPR_VOICE_APPEND_COMMAND_PREFIX) -> SprVoiceAction(
            transcript = trimmed.removePrefix(SPR_VOICE_APPEND_COMMAND_PREFIX).trim(),
            replaceExisting = false,
        )
        else -> SprVoiceAction(
            transcript = trimmed,
            replaceExisting = fallbackReplaceExisting,
        )
    }
}

private data class EditableSprMeasurementRow(
    val id: String,
    val cells: MutableMap<String, String>,
    val formats: MutableMap<String, JSONObject>,
)

private val sprVoiceNumberWords = mapOf(
    "jedan" to 1,
    "jedna" to 1,
    "jedno" to 1,
    "dva" to 2,
    "dvije" to 2,
    "tri" to 3,
    "cetiri" to 4,
    "četiri" to 4,
    "pet" to 5,
    "sest" to 6,
    "šest" to 6,
    "sedam" to 7,
    "osam" to 8,
    "devet" to 9,
    "deset" to 10,
    "jedanaest" to 11,
    "dvanaest" to 12,
    "trinaest" to 13,
    "cetrnaest" to 14,
    "četrnaest" to 14,
    "petnaest" to 15,
    "sesnaest" to 16,
    "šesnaest" to 16,
    "sedamnaest" to 17,
    "osamnaest" to 18,
    "devetnaest" to 19,
    "dvadeset" to 20,
    "trideset" to 30,
    "cetrdeset" to 40,
    "četrdeset" to 40,
    "pedeset" to 50,
)

private fun normalizeSprVoiceLookup(value: String): String =
    Normalizer.normalize(value.trim().lowercase(Locale.getDefault()), Normalizer.Form.NFD)
        .replace(Regex("\\p{Mn}+"), "")
        .replace(Regex("[^a-z0-9]+"), " ")
        .replace(Regex("\\s+"), " ")
        .trim()

private fun parseSprVoiceCount(value: String): String {
    val raw = value.trim()
    if (raw.matches(Regex("\\d{1,4}"))) return raw
    return sprVoiceNumberWords[normalizeSprVoiceLookup(raw)]?.toString().orEmpty()
}

private fun capitalizeSprVoiceFirstLetter(value: String): String {
    val trimmed = value.trim()
    val firstLetterIndex = trimmed.indexOfFirst { it.isLetter() }
    if (firstLetterIndex < 0) return trimmed
    return buildString {
        append(trimmed.substring(0, firstLetterIndex))
        append(trimmed[firstLetterIndex].uppercaseChar())
        append(trimmed.substring(firstLetterIndex + 1))
    }
}

private fun cleanSprVoicePlace(value: String): String =
    value.trim()
        .replace(Regex("^(?:i|pa|te|onda|zatim)\\s+", RegexOption.IGNORE_CASE), "")
        .replace(Regex("\\b(?:dodaj|unesi|upisi|stavi)\\b", RegexOption.IGNORE_CASE), "")
        .replace(Regex("^(?:mjesto|lokacija)\\s+", RegexOption.IGNORE_CASE), "")
        .replace(Regex("\\b(?:mjesto|lokacija)\\s*[:\\-]\\s*", RegexOption.IGNORE_CASE), "")
        .replace(Regex("\\s+"), " ")
        .trim(' ', ',', '.', ';', ':', '-')
        .let(::capitalizeSprVoiceFirstLetter)

private fun cleanSprVoiceFloor(value: String): String =
    value.trim()
        .replace(Regex("\\s+"), " ")
        .trim(' ', ',', '.', ';', ':', '-')
        .let { floor -> if (floor.startsWith("eta", ignoreCase = true)) floor else "Etaža $floor" }

private fun isSprVoiceUnitToken(value: String): Boolean =
    normalizeSprVoiceLookup(value).let { lookup ->
        lookup.startsWith("panik") ||
            lookup.startsWith("lamp") ||
            lookup.startsWith("svjetilj") ||
            lookup.startsWith("kom")
    }

private fun parseSprVoiceLooseMeasurementRows(transcript: String): List<SprVoiceMeasurementRow> {
    val tokens = transcript
        .replace(Regex("\\b(?:i onda|pa onda|zatim|onda)\\b", RegexOption.IGNORE_CASE), " ")
        .replace(Regex("[,;:]+"), " ")
        .split(Regex("\\s+"))
        .map { it.trim(' ', ',', '.', ';', ':', '-') }
        .filter { it.isNotBlank() }
    if (tokens.isEmpty()) return emptyList()
    val rows = mutableListOf<SprVoiceMeasurementRow>()
    val seen = mutableSetOf<String>()
    val placeTokens = mutableListOf<String>()
    var lastWasCount = false
    tokens.forEach { token ->
        if (lastWasCount && isSprVoiceUnitToken(token)) {
            return@forEach
        }
        val count = parseSprVoiceCount(token)
        if (count.isNotBlank()) {
            val place = cleanSprVoicePlace(placeTokens.joinToString(" "))
            val key = normalizeSprVoiceLookup(place)
            if (place.isNotBlank() && key.isNotBlank()) {
                if (key in seen) {
                    rows.indexOfFirst { it.key == key }
                        .takeIf { it >= 0 }
                        ?.let { index -> rows[index] = rows[index].copy(lampCount = count) }
                } else {
                    seen += key
                    rows += SprVoiceMeasurementRow(key = key, place = place, lampCount = count)
                }
            }
            placeTokens.clear()
            lastWasCount = true
        } else {
            if (!isSprVoiceUnitToken(token)) {
                placeTokens += token
                lastWasCount = false
            }
        }
    }
    return rows
}

private fun parseSprVoiceMeasurementRows(transcript: String): List<SprVoiceMeasurementRow> {
    val source = transcript.trim()
    if (source.isBlank()) return emptyList()
    val numberPattern = "(?:\\d{1,4}|${sprVoiceNumberWords.keys.sortedByDescending { it.length }.joinToString("|") { Regex.escape(it) }})"
    val unitPattern = "(?:panik\\w*|lamp\\w*|svjetilj\\w*|kom\\w*)"
    val itemPattern = Regex("(.+?)\\s+($numberPattern)(?:\\s*$unitPattern)?(?=\\s+\\S|$)", setOf(RegexOption.IGNORE_CASE))
    val floorPattern = Regex(
        "\\beta[zž][aeu]?\\s+((?:-?\\d+\\.?\\s*)?(?:kat|katu)|prizemlje|podrum|suteren|galerija|(?:prvi|drugi|tre[cć]i|[cč]etvrti|peti|[sš]esti|sedmi|osmi|deveti|deseti)\\s+kat)",
        RegexOption.IGNORE_CASE,
    )
    val normalizedSource = source
        .replace(floorPattern) { match -> "\n§FLOOR§${cleanSprVoiceFloor(match.groupValues[1])}\n" }
        .replace(Regex("\\b(?:i onda|pa onda|zatim|onda)\\b", RegexOption.IGNORE_CASE), "\n")
        .replace(";", "\n")
        .replace(",", "\n")
    val rows = mutableListOf<SprVoiceMeasurementRow>()
    val seen = mutableSetOf<String>()
    normalizedSource
        .split(Regex("\\r?\\n"))
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .forEach { segment ->
            if (segment.startsWith("§FLOOR§")) {
                val floor = segment.removePrefix("§FLOOR§").trim()
                val key = normalizeSprVoiceLookup(floor)
                if (floor.isNotBlank() && key.isNotBlank() && key !in seen) {
                    seen += key
                    rows += SprVoiceMeasurementRow(key = key, place = floor, lampCount = "", kind = "section")
                }
                return@forEach
            }
            itemPattern.findAll(segment).forEach matchLoop@{ match ->
                val place = cleanSprVoicePlace(match.groupValues[1])
                val count = parseSprVoiceCount(match.groupValues[2])
                val key = normalizeSprVoiceLookup(place)
                if (place.isBlank() || count.isBlank() || key.isBlank()) return@matchLoop
                if (key in seen) {
                    rows.indexOfFirst { it.key == key }
                        .takeIf { it >= 0 }
                        ?.let { index -> rows[index] = rows[index].copy(lampCount = count) }
                } else {
                    seen += key
                    rows += SprVoiceMeasurementRow(key = key, place = place, lampCount = count)
                }
            }
        }
    return rows.ifEmpty { parseSprVoiceLooseMeasurementRows(source) }
}

private fun parseSprVoiceTranscriptToAiRows(transcript: String): List<SprVoiceAiRow> =
    parseSprVoiceMeasurementRows(transcript).map { row ->
        SprVoiceAiRow(place = row.place, lampCount = row.lampCount, kind = row.kind)
    }

private fun findSprMeasurementColumn(
    sheet: WorkOrderMeasurementSheet,
    candidates: List<String>,
    fallbackIndex: Int,
): WorkOrderMeasurementColumn? {
    val normalizedCandidates = candidates.map(::normalizeSprVoiceLookup).filter { it.isNotBlank() }
    return sheet.columns.firstOrNull { column ->
        val lookup = normalizeSprVoiceLookup(listOf(column.id, column.label, column.placeholder).joinToString(" "))
        normalizedCandidates.any { lookup == it || lookup.contains(it) }
    } ?: sheet.columns.getOrNull(fallbackIndex)
}

private fun applySprVoiceRowsToSheet(
    sheet: WorkOrderMeasurementSheet,
    voiceRows: List<SprVoiceMeasurementRow>,
    replaceExisting: Boolean = false,
): WorkOrderMeasurementSheet {
    if (voiceRows.isEmpty() || sheet.columns.isEmpty()) return sheet
    val numberColumn = findSprMeasurementColumn(sheet, listOf("r br", "redni broj", "broj", "rb"), 0)
    val placeColumn = findSprMeasurementColumn(sheet, listOf("mjesto ispitivanja", "prostorija", "prostor", "lokacija", "opis"), 1)
    val lampColumn = findSprMeasurementColumn(sheet, listOf("broj lampi", "lampi", "svjetiljki", "broj svjetiljki"), 2)
    val eiColumn = findSprMeasurementColumn(sheet, listOf("ei", "izmjereno", "izmjerena vrijednost"), 3)
    val eiminColumn = findSprMeasurementColumn(sheet, listOf("eimin", "emin", "minimalno", "zahtijevano"), 4)
    val passColumn = findSprMeasurementColumn(sheet, listOf("zadovoljava", "ocjena", "ispravno", "pass"), 5)
    if (placeColumn == null || lampColumn == null) return sheet
    val rows = sheet.rows.mapIndexed { index, row ->
        EditableSprMeasurementRow(
            id = row.id.ifBlank { "measurement-row-${index + 1}" },
            cells = row.cells.toMutableMap(),
            formats = row.formats.toMutableMap(),
        )
    }.toMutableList()
    fun createRow(): EditableSprMeasurementRow =
        EditableSprMeasurementRow(
            id = "measurement-row-${rows.size + 1}",
            cells = sheet.columns.associate { it.id to "" }.toMutableMap(),
            formats = mutableMapOf(),
        ).also { row ->
            rows += row
            eiColumn?.id?.takeIf { it.isNotBlank() }?.let { row.cells[it] = ">2" }
            eiminColumn?.id?.takeIf { it.isNotBlank() }?.let { row.cells[it] = "1" }
            passColumn?.id?.takeIf { it.isNotBlank() }?.let { row.cells[it] = "DA" }
        }
    fun ensureNumber(row: EditableSprMeasurementRow, index: Int) {
        val id = numberColumn?.id.orEmpty()
        if (id.isNotBlank() && row.cells[id].orEmpty().isBlank()) {
            row.cells[id] = (index + 1).toString()
        }
    }
    rows.forEachIndexed { index, row -> ensureNumber(row, index) }
    val sectionAnchorColumn = sheet.columns.firstOrNull()
    val previousSectionRowIds = if (replaceExisting) {
        val sectionColumnIds = listOfNotNull(sectionAnchorColumn?.id, placeColumn.id)
            .filter { it.isNotBlank() }
            .toSet()
        sheet.merges
            .filter { merge ->
                merge.rowSpan == 1 &&
                    merge.colSpan > 1 &&
                    merge.columnId in sectionColumnIds
            }
            .map { it.rowId }
            .toSet()
    } else {
        emptySet()
    }
    if (replaceExisting) {
        val clearColumnIds = listOfNotNull(
            sheet.columns.firstOrNull()?.id,
            numberColumn?.id,
            placeColumn.id,
            lampColumn.id,
        )
            .filter { it.isNotBlank() }
            .distinct()
        rows.forEach { row ->
            if (row.id in previousSectionRowIds) {
                sheet.columns.forEach { column ->
                    row.cells[column.id] = ""
                    row.formats.remove(column.id)
                }
            } else {
                clearColumnIds.forEach { columnId -> row.cells[columnId] = "" }
            }
        }
    }
    val sectionMerges = mutableListOf<WorkOrderMeasurementMerge>()
    fun rowHasDictatedValues(row: EditableSprMeasurementRow): Boolean =
        row.id in sheet.headerRows ||
            sheet.isMergedMeasurementSectionRow(row.id) ||
            row.cells[placeColumn.id].orEmpty().isNotBlank() ||
            row.cells[lampColumn.id].orEmpty().isNotBlank() ||
            sectionAnchorColumn?.id?.let { row.cells[it].orEmpty().isNotBlank() } == true
    fun applyEntryToRow(targetRow: EditableSprMeasurementRow, entry: SprVoiceMeasurementRow) {
        if (entry.kind.equals("section", ignoreCase = true)) {
            val anchorColumn = sectionAnchorColumn ?: return
            sheet.columns.forEach { column -> targetRow.cells[column.id] = "" }
            targetRow.cells[anchorColumn.id] = entry.place
            targetRow.formats[anchorColumn.id] = JSONObject()
                .put("bold", true)
                .put("fillColor", "#eef7ff")
                .put("align", "left")
                .put("verticalAlign", "middle")
            sectionMerges += WorkOrderMeasurementMerge(
                rowId = targetRow.id,
                columnId = anchorColumn.id,
                rowSpan = 1,
                colSpan = sheet.columns.size.coerceAtLeast(1),
            )
            return
        }
        ensureNumber(targetRow, rows.indexOf(targetRow))
        if (targetRow.cells[placeColumn.id].orEmpty().isBlank()) {
            targetRow.cells[placeColumn.id] = entry.place
        }
        targetRow.cells[lampColumn.id] = entry.lampCount
    }
    fun finalizedSheet(): WorkOrderMeasurementSheet {
        val sectionRowIds = sectionMerges.map { it.rowId }.toSet()
        return sheet.copy(
            rows = rows.map { row ->
                WorkOrderMeasurementRow(
                    id = row.id,
                    cells = row.cells.toMap(),
                    formats = row.formats.toMap(),
                )
            },
            merges = sheet.merges
                .filterNot { merge ->
                    merge.rowId in sectionRowIds ||
                        (replaceExisting && merge.rowId in previousSectionRowIds)
                } + sectionMerges,
            headerRows = sheet.headerRows.filterNot { it in previousSectionRowIds },
        )
    }
    if (replaceExisting) {
        voiceRows.forEachIndexed { index, entry ->
            val targetRow = rows.getOrNull(index) ?: createRow()
            applyEntryToRow(targetRow, entry)
        }
        return finalizedSheet()
    }
    var appendIndex = rows.indexOfLast(::rowHasDictatedValues) + 1
    voiceRows.forEach { entry ->
        val targetRow = rows.getOrNull(appendIndex) ?: createRow()
        appendIndex += 1
        applyEntryToRow(targetRow, entry)
    }
    return finalizedSheet()
}

private fun applySprVoiceTranscriptToMeasurementSheets(
    template: WorkOrderDocumentationTemplate,
    sheets: Map<String, WorkOrderMeasurementSheet>,
    transcript: String,
    replaceExisting: Boolean = false,
): Map<String, WorkOrderMeasurementSheet> {
    if (!template.serviceCode.equals("SPR", ignoreCase = true)) return sheets
    val action = decodeSprVoiceAction(transcript, replaceExisting)
    val voiceRows = parseSprVoiceMeasurementRows(action.transcript)
    if (voiceRows.isEmpty()) return sheets
    val table = template.measurementTables.firstOrNull() ?: return sheets
    val key = measurementSheetStateKey(template, table)
    val sheet = sheets[key] ?: table.sheet
    return sheets + (key to applySprVoiceRowsToSheet(sheet, voiceRows, action.replaceExisting))
}

private fun applySprVoiceAiRowsToMeasurementSheets(
    template: WorkOrderDocumentationTemplate,
    sheets: Map<String, WorkOrderMeasurementSheet>,
    rows: List<SprVoiceAiRow>,
    replaceExisting: Boolean = false,
): Map<String, WorkOrderMeasurementSheet> {
    if (!template.serviceCode.equals("SPR", ignoreCase = true)) return sheets
    val voiceRows = rows
        .mapNotNull { row ->
            val place = capitalizeSprVoiceFirstLetter(row.place)
            val isSection = row.kind.equals("section", ignoreCase = true) || row.kind.equals("floor", ignoreCase = true)
            val lampCount = if (isSection) "" else parseSprVoiceCount(row.lampCount).ifBlank { row.lampCount.trim() }
            val key = normalizeSprVoiceLookup(place)
            if (place.isBlank() || (!isSection && lampCount.isBlank()) || key.isBlank()) null else {
                SprVoiceMeasurementRow(key = key, place = place, lampCount = lampCount, kind = if (isSection) "section" else row.kind)
            }
        }
    if (voiceRows.isEmpty()) return sheets
    val table = template.measurementTables.firstOrNull() ?: return sheets
    val key = measurementSheetStateKey(template, table)
    val sheet = sheets[key] ?: table.sheet
    return sheets + (key to applySprVoiceRowsToSheet(sheet, voiceRows, replaceExisting))
}

private fun measurementTablePrimaryUsageKey(
    template: WorkOrderDocumentationTemplate,
    table: WorkOrderMeasurementTable,
): String = "${template.id}::${table.key.ifBlank { table.id.ifBlank { table.tokenKey.ifBlank { table.label } } }}"

private fun measurementTableUsagePayloadKeys(
    template: WorkOrderDocumentationTemplate,
    table: WorkOrderMeasurementTable,
): List<String> {
    val baseKeys = listOf(table.key, table.id, table.tokenKey, table.label)
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }
    val templateKeys = listOf(template.id, template.serviceCode, template.documentType, template.title)
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }
    return buildList {
        add(measurementTablePrimaryUsageKey(template, table))
        templateKeys.forEach { templateKey ->
            baseKeys.forEach { baseKey -> add("$templateKey::$baseKey") }
        }
        baseKeys.forEach { baseKey ->
            add(baseKey)
            add("use-$baseKey")
        }
    }.distinctBy { it.lowercase(Locale.getDefault()) }
}

private fun defaultIncludedMeasurementTableKeys(templates: List<WorkOrderDocumentationTemplate>): Set<String> =
    templates
        .flatMap { template -> template.measurementTables.map { table -> measurementTablePrimaryUsageKey(template, table) } }
        .filter { it.isNotBlank() }
        .toSet()

private fun buildIncludedMeasurementTablePayloadKeys(
    templates: List<WorkOrderDocumentationTemplate>,
    includedPrimaryKeys: Set<String>,
): List<String> =
    templates
        .flatMap { template ->
            template.measurementTables.flatMap { table ->
                if (measurementTablePrimaryUsageKey(template, table) in includedPrimaryKeys) {
                    measurementTableUsagePayloadKeys(template, table)
                } else {
                    emptyList()
                }
            }
        }
        .distinctBy { it.lowercase(Locale.getDefault()) }

private fun measurementTableCandidateKeys(table: WorkOrderMeasurementTable): List<String> =
    listOf(table.key, table.id, table.tokenKey, table.label)
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .distinctBy { it.lowercase(Locale.getDefault()) }

private fun resolveSavedMeasurementSheet(
    defaults: WorkOrderDocumentationDefaults,
    template: WorkOrderDocumentationTemplate,
    table: WorkOrderMeasurementTable,
): WorkOrderMeasurementSheet? {
    val candidates = measurementTableCandidateKeys(table)
    val templateSheets = defaults.templateFieldSheets[template.id].orEmpty()
    for (key in candidates) {
        templateSheets[key]?.takeIf { it.columns.isNotEmpty() }?.let { return it }
    }
    val normalizedTemplateSheets = normalizedMeasurementSheetMap(templateSheets)
    for (key in candidates) {
        normalizedTemplateSheets[normalizeTemplateFieldLookup(key)]?.takeIf { it.columns.isNotEmpty() }?.let { return it }
    }
    for (key in candidates) {
        defaults.fieldSheets[key]?.takeIf { it.columns.isNotEmpty() }?.let { return it }
    }
    val normalizedFieldSheets = normalizedMeasurementSheetMap(defaults.fieldSheets)
    for (key in candidates) {
        normalizedFieldSheets[normalizeTemplateFieldLookup(key)]?.takeIf { it.columns.isNotEmpty() }?.let { return it }
    }
    return null
}

private fun defaultMeasurementSheetValues(
    templates: List<WorkOrderDocumentationTemplate>,
    defaults: WorkOrderDocumentationDefaults = WorkOrderDocumentationDefaults(),
): Map<String, WorkOrderMeasurementSheet> =
    buildMap {
        templates.forEach { template ->
            template.measurementTables.forEach { table ->
                put(measurementSheetStateKey(template, table), resolveSavedMeasurementSheet(defaults, template, table) ?: table.sheet)
            }
        }
    }

private const val PHYSICAL_FACTORS_BUILT_IN_TEMPLATE_ID = "mobile-ro-f"
private const val PHYSICAL_FACTORS_BUILT_IN_TABLE_ID = "mobile-ro-f-3"
private const val PHYSICAL_FACTORS_BUILT_IN_TABLE_KEY = "RO-F.3"
private const val PHYSICAL_FACTORS_DEFAULT_MEASUREMENT_ROWS = 80
private const val PHYSICAL_FACTORS_MIN_ROWS_PER_SPACE = 3

private fun physicalFactorsMeasurementFormat(
    fillColor: String = "",
    bold: Boolean = false,
    align: String = "",
    type: String = "",
    decimals: Int? = null,
): JSONObject =
    JSONObject().apply {
        if (fillColor.isNotBlank()) put("fillColor", fillColor)
        if (bold) put("bold", true)
        if (align.isNotBlank()) put("align", align)
        if (type.isNotBlank()) put("type", type)
        decimals?.let { put("decimals", it) }
    }

private fun physicalFactorsMeasurementColumn(
    id: String,
