        physicalFactorsMeasurementColumn("measuring_place", "Mjerno mjesto*", 118),
        physicalFactorsMeasurementColumn("illumination_measured", "Izmjereno opće osvjetljenje [lx]*", 174),
        physicalFactorsMeasurementColumn("illumination_allowed", "Propisano osvjetljenje [lx]*", 164),
        physicalFactorsMeasurementColumn("noise_measured", "Ekvivalentna razina buke [dB]*", 172),
        physicalFactorsMeasurementColumn("noise_allowed", "Dopuštena razina buke [dB]*", 164),
        physicalFactorsMeasurementColumn("temperature_measured", "Izmjerena temperatura zraka [°C]*", 184),
        physicalFactorsMeasurementColumn("temperature_allowed", "Dopuštena temperatura zraka [°C]*", 180),
        physicalFactorsMeasurementColumn("airflow_measured", "Izmjerena brzina strujanja zraka [m/s]*", 204),
        physicalFactorsMeasurementColumn("airflow_allowed", "Dopuštena brzina strujanja zraka [m/s]*", 204),
        physicalFactorsMeasurementColumn("humidity_measured", "Izmjerena relativna vlažnost zraka [%]*", 210),
        physicalFactorsMeasurementColumn("humidity_allowed", "Preporučena relativna vlažnost zraka [%]*", 220),
        physicalFactorsMeasurementColumn("final_grade", "DA/NE", 92),
    )

private fun physicalFactorsIfSpace(rowNumber: Int, expression: String): String =
    "=IF(A$rowNumber=\"\",\"\",$expression)"

private fun physicalFactorsTextIfSpace(rowNumber: Int, text: String): String =
    "=IF(A$rowNumber=\"\",\"\",\"$text\")"

private val physicalFactorsNumberRegex = Regex("-?\\d+(?:[,.]\\d+)?")

private fun physicalFactorsNumberOrBlank(value: String): Double? =
    physicalFactorsNumberRegex
        .find(value.trim())
        ?.value
        ?.replace(",", ".")
        ?.toDoubleOrNull()

private fun physicalFactorsDecimalPlaces(value: String): Int {
    val normalized = physicalFactorsNumberRegex.find(value.trim())?.value?.replace(",", ".").orEmpty()
    val decimals = normalized.substringAfter('.', "")
        .takeWhile { it.isDigit() }
        .trimEnd('0')
        .length
    return decimals.coerceIn(0, 3)
}

private fun physicalFactorsNumberText(value: Double): String {
    val integer = value.toLong()
    return if (value == integer.toDouble()) integer.toString() else value.toString()
}

private fun physicalFactorsInputNumberText(value: Double): String {
    val text = String.format(Locale.US, "%.3f", value)
        .trimEnd('0')
        .trimEnd('.')
    return text.replace(".", ",")
}

private fun physicalFactorsAllowedAirflowForTemperature(temperature: String): String {
    val airTemperature = physicalFactorsNumberOrBlank(temperature) ?: return "0,6"
    return when {
        airTemperature < 10.0 -> "0,5"
        airTemperature > 27.0 -> "0,8"
        else -> "0,6"
    }
}

private fun IsznrFcSpaceDraft.withPhysicalFactorsCommonConditions(
    airTemperature: String = "",
    relativeHumidity: String = "",
    airFlowSpeed: String = "",
): IsznrFcSpaceDraft {
    val parsedTemperature = physicalFactorsNumberOrBlank(airTemperature)
    val parsedHumidity = physicalFactorsNumberOrBlank(relativeHumidity)
    val parsedAirFlow = physicalFactorsNumberOrBlank(airFlowSpeed)
    val nextTemperature = parsedTemperature?.let(::physicalFactorsInputNumberText)
    val nextHumidity = parsedHumidity?.let(::physicalFactorsInputNumberText)
    val nextAirFlow = parsedAirFlow?.let(::physicalFactorsInputNumberText)
    return copy(
        temperatureMin = nextTemperature ?: temperatureMin,
        temperatureMax = nextTemperature ?: temperatureMax,
        humidityMin = nextHumidity ?: humidityMin,
        humidityMax = nextHumidity ?: humidityMax,
        airflowAllowed = if (parsedTemperature != null) physicalFactorsAllowedAirflowForTemperature(airTemperature) else airflowAllowed.ifBlank { "0,6" },
        airflowMin = nextAirFlow ?: airflowMin,
        airflowMax = nextAirFlow ?: airflowMax,
    )
}

private fun IsznrManualPhysicalFactors.withPhysicalFactorsCommonConditions(
    airTemperature: String = this.airTemperature,
    relativeHumidity: String = this.relativeAirHumidity,
    airFlowSpeed: String = this.airFlowSpeed,
): IsznrManualPhysicalFactors =
    copy(
        airTemperature = airTemperature,
        relativeAirHumidity = relativeHumidity,
        airFlowSpeed = airFlowSpeed,
        spaces = spaces.map { space ->
            space.withPhysicalFactorsCommonConditions(
                airTemperature = airTemperature,
                relativeHumidity = relativeHumidity,
                airFlowSpeed = airFlowSpeed,
            )
        },
    )

private fun physicalFactorsRandomBetweenFormula(
    rowNumber: Int,
    minValue: String,
    maxValue: String,
    fallback: String,
): String {
    val minNumber = physicalFactorsNumberOrBlank(minValue)
    val maxNumber = physicalFactorsNumberOrBlank(maxValue)
    if (minNumber == null || maxNumber == null) return fallback
    val decimals = maxOf(physicalFactorsDecimalPlaces(minValue), physicalFactorsDecimalPlaces(maxValue))
    val scale = when (decimals) {
        0 -> 1
        1 -> 10
        2 -> 100
        else -> 1000
    }
    val first = Math.round(minOf(minNumber, maxNumber) * scale).toInt()
    val last = Math.round(maxOf(minNumber, maxNumber) * scale).toInt()
    val expression = if (scale == 1) {
        "RANDBETWEEN($first,$last)"
    } else {
        "RANDBETWEEN($first,$last)/$scale"
    }
    return physicalFactorsIfSpace(rowNumber, expression)
}

private fun physicalFactorsAllowedFormula(rowNumber: Int, value: String, fallback: String): String {
    val allowed = value.trim().ifBlank { fallback }
    val number = physicalFactorsNumberOrBlank(allowed)
    return if (number != null) {
        physicalFactorsIfSpace(rowNumber, physicalFactorsNumberText(number))
    } else {
        physicalFactorsTextIfSpace(rowNumber, allowed)
    }
}

private fun physicalFactorsMeasurementCells(
    rowNumber: Int,
    space: IsznrFcSpaceDraft,
): Map<String, String> =
    mapOf(
        "space" to space.name,
        "measuring_place" to physicalFactorsIfSpace(rowNumber, "ROW()-1"),
        "illumination_measured" to physicalFactorsRandomBetweenFormula(rowNumber, space.illuminationMin, space.illuminationMax, physicalFactorsIfSpace(rowNumber, "RANDBETWEEN(650,880)")),
        "illumination_allowed" to physicalFactorsAllowedFormula(rowNumber, space.illuminationAllowed, "500"),
        "noise_measured" to physicalFactorsRandomBetweenFormula(rowNumber, space.noiseMin, space.noiseMax, "=IFERROR(IF(A$rowNumber=\"\",\"\",RANDBETWEEN(520,530))/10,\"\")"),
        "noise_allowed" to physicalFactorsAllowedFormula(rowNumber, space.noiseAllowed, "65"),
        "temperature_measured" to physicalFactorsRandomBetweenFormula(rowNumber, space.temperatureMin, space.temperatureMax, "=IFERROR(IF(A$rowNumber=\"\",\"\",RANDBETWEEN(220,224))/10,\"\")"),
        "temperature_allowed" to physicalFactorsAllowedFormula(rowNumber, space.temperatureAllowed, "20-25"),
        "airflow_measured" to physicalFactorsRandomBetweenFormula(rowNumber, space.airflowMin, space.airflowMax, "=IFERROR(IF(A$rowNumber=\"\",\"\",RANDBETWEEN(12,33))/100,\"\")"),
        "airflow_allowed" to physicalFactorsAllowedFormula(rowNumber, space.airflowAllowed, "0.6"),
        "humidity_measured" to physicalFactorsRandomBetweenFormula(rowNumber, space.humidityMin, space.humidityMax, "=IFERROR(IF(A$rowNumber=\"\",\"\",RANDBETWEEN(520,530))/10,\"\")"),
        "humidity_allowed" to physicalFactorsAllowedFormula(rowNumber, space.humidityAllowed, "40-60"),
        "final_grade" to physicalFactorsTextIfSpace(rowNumber, "Da"),
    )

private fun WorkOrderMeasurementSheet.physicalFactorsSpaceRowIndexes(
    space: IsznrFcSpaceDraft,
    originalName: String = "",
): List<Int> {
    val spaceColumn = physicalFactorsColumnById("space") ?: return emptyList()
    val candidates = listOf(space.name, originalName)
        .map(::normalizePhysicalFactorsSheetLookup)
        .filter { it.isNotBlank() }
        .toSet()
    if (candidates.isEmpty()) return emptyList()
    return rows.mapIndexedNotNull { index, row ->
        val currentSpace = normalizePhysicalFactorsSheetLookup(row.cells[spaceColumn.id].orEmpty())
        index.takeIf { row.id !in headerRows && currentSpace in candidates }
    }
}

private fun WorkOrderMeasurementSheet.withPhysicalFactorsSpaceDraftRows(
    space: IsznrFcSpaceDraft,
    originalName: String = "",
    rowCount: Int = PHYSICAL_FACTORS_MIN_ROWS_PER_SPACE,
): WorkOrderMeasurementSheet {
    if (!isBuiltInPhysicalFactorsSheet() || space.name.isBlank()) return this
    val spaceColumn = physicalFactorsColumnById("space") ?: return this
    val existingIndexes = physicalFactorsSpaceRowIndexes(space, originalName)
    val neededRows = maxOf(rowCount, existingIndexes.size)
    val blankIndexes = rows.mapIndexedNotNull { index, row ->
        index.takeIf {
            row.id !in headerRows &&
                row.cells[spaceColumn.id].orEmpty().trim().isBlank() &&
                index !in existingIndexes
        }
    }
    val updateIndexes = (existingIndexes + blankIndexes.take((neededRows - existingIndexes.size).coerceAtLeast(0)))
        .distinct()
    val nextRows = rows.toMutableList()
    updateIndexes.forEach { rowIndex ->
        val rowNumber = rowIndex + 1
        nextRows[rowIndex] = physicalFactorsMeasurementRow(
            id = rows[rowIndex].id,
            columns = columns,
            cells = physicalFactorsMeasurementCells(rowNumber = rowNumber, space = space),
        )
    }
    var appendedCount = updateIndexes.size
    while (appendedCount < neededRows) {
        val rowNumber = nextRows.size + 1
        nextRows += physicalFactorsMeasurementRow(
            id = "fc-space-${space.id.ifBlank { rowNumber.toString() }}-${appendedCount + 1}",
            columns = columns,
            cells = physicalFactorsMeasurementCells(rowNumber = rowNumber, space = space),
        )
        appendedCount += 1
    }
    return copy(rows = nextRows)
}

private fun WorkOrderMeasurementSheet.withPhysicalFactorsSyncedSpaces(
    spaces: List<IsznrFcSpaceDraft>,
): WorkOrderMeasurementSheet {
    if (!isBuiltInPhysicalFactorsSheet()) return this
    val spaceColumn = physicalFactorsColumnById("space") ?: return this
    val validSpaceNames = spaces
        .map { it.name }
        .map(::normalizePhysicalFactorsSheetLookup)
        .filter { it.isNotBlank() }
        .toSet()
    val rowsWithoutRemovedSpaces = rows.filter { row ->
        if (row.id in headerRows) {
            true
        } else {
            val currentSpace = normalizePhysicalFactorsSheetLookup(row.cells[spaceColumn.id].orEmpty())
            currentSpace.isBlank() || currentSpace in validSpaceNames
        }
    }
    val compacted = if (rowsWithoutRemovedSpaces.size == rows.size) this else copy(rows = rowsWithoutRemovedSpaces)
    return spaces
        .filter { it.name.trim().isNotBlank() }
        .fold(compacted) { sheet, space -> sheet.withPhysicalFactorsSpaceDraftRows(space) }
}

private fun physicalFactorsMeasurementRow(
    id: String,
    columns: List<WorkOrderMeasurementColumn>,
    cells: Map<String, String>,
    header: Boolean = false,
): WorkOrderMeasurementRow =
    WorkOrderMeasurementRow(
        id = id,
        cells = columns.associate { column -> column.id to cells[column.id].orEmpty() },
        formats = columns.associate { column ->
            column.id to if (header) {
                physicalFactorsMeasurementFormat(fillColor = "#e5e7eb", bold = true, align = "center")
            } else if (column.id == "final_grade") {
                physicalFactorsMeasurementFormat(fillColor = "#d9ead3", bold = true, align = "center")
            } else if (column.id.contains("allowed")) {
                physicalFactorsMeasurementFormat(fillColor = "#f8fafc", align = "center")
            } else {
                physicalFactorsMeasurementFormat()
            }
        }.filterValues { it.isMeasurementFormatCustomizedMobile() },
    )

private fun defaultPhysicalFactorsMeasurementSheet(): WorkOrderMeasurementSheet {
    val columns = physicalFactorsColumns()
    val headerRow = physicalFactorsMeasurementRow(
        id = "fc-header",
        columns = columns,
        cells = columns.associate { it.id to it.label },
        header = true,
    )
    val measurementRows = (0 until PHYSICAL_FACTORS_DEFAULT_MEASUREMENT_ROWS).map { index ->
        val rowNumber = index + 2
        physicalFactorsMeasurementRow(
            id = "fc-row-${index + 1}",
            columns = columns,
            cells = physicalFactorsMeasurementCells(rowNumber = rowNumber, space = IsznrFcSpaceDraft()),
        )
    }
    return WorkOrderMeasurementSheet(
        columns = columns,
        rows = listOf(headerRow) + measurementRows,
        headerRows = listOf(headerRow.id),
    )
}

