        serviceCode = "FC",
        dataSourceType = "mobile_builtin_excel",
        dataSourceTitle = "Predlošci prostora i RO-F.3 mjerenja",
        fields = emptyList(),
        measurementTables = listOf(
            WorkOrderMeasurementTable(
