                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

@Composable
private fun DocumentationSummarySection(
    workOrder: WorkOrder,
    flowItems: List<DocumentationServiceFlowItem>,
    additionalRecords: List<DocumentationAdditionalObjectRecord>,
    selectedService: String,
    documentNumber: String,
    objectName: String,
    inspectionDate: String,
    issuedDate: String,
    testingLocation: String,
    selectedEquipmentCount: Int,
    selectedLegalCount: Int,
    showWorkEquipmentIsznr: Boolean,
    selectedWorkEquipmentCount: Int,
    workEquipmentMissingLabels: List<String>,
    canSubmitWorkEquipmentToIsznr: Boolean,
    isSubmittingWorkEquipmentToIsznr: Boolean,
    showPhysicalFactorsIsznr: Boolean,
    selectedPhysicalFactorsCount: Int,
    physicalFactorsMissingLabels: List<String>,
    canSubmitPhysicalFactorsToIsznr: Boolean,
    isSubmittingPhysicalFactorsToIsznr: Boolean,
    signatureMode: String,
    completedBy: String,
    completedByOptions: List<Pair<String, String>>,
    handoverVerifierUserId: String,
    handoverVerifierOptions: List<Pair<String, String>>,
    handoverVerifierLabelById: Map<String, String>,
    includeHandoverProtocol: Boolean,
    enabled: Boolean,
    onSignatureMode: (String) -> Unit,
    onCompletedByChange: (String) -> Unit,
    onHandoverVerifierChange: (String) -> Unit,
    onIncludeHandoverProtocol: (Boolean) -> Unit,
    onSubmitWorkEquipmentToIsznr: () -> Unit,
    onSubmitPhysicalFactorsToIsznr: () -> Unit,
) {
    WizardSection(title = "Sažetak", icon = Icons.Rounded.CheckCircle) {
        DocumentationSummaryRow("RN", workOrder.displayNumber)
        DocumentationSummaryRow("Broj zapisnika", documentNumber.ifBlank { "Automatski kod izrade" })
        DocumentationSummaryRow("Usluga", selectedService.ifBlank { "Nije odabrano" })
        if (additionalRecords.isNotEmpty()) {
            DocumentationSummaryRow(
                "Dodatni zapisnici",
                additionalRecords.joinToString(", ") { record ->
                    "${record.serviceCode.ifBlank { record.serviceName }} - ${record.objectName.ifBlank { "drugi objekt" }}"
                },
            )
        }
        DocumentationSummaryRow("Objekt", objectName.ifBlank { "Samo lokacija" })
        DocumentationSummaryRow("Datum ispitivanja", formatDatePickerLabel(inspectionDate))
        DocumentationSummaryRow("Datum izdavanja", formatDatePickerLabel(issuedDate))
        DocumentationSummaryRow("Mjesto ispitivanja", testingLocation.ifBlank { "Nije upisano" })
        WorkOrderSelectField(
            label = "Tko je završio radni nalog",
            value = completedBy,
            valueLabel = completedBy.ifBlank { "Odaberi izvršitelja" },
            options = completedByOptions,
            enabled = enabled && completedByOptions.size > 1,
            onSelect = onCompletedByChange,
        )
        WorkOrderSelectField(
            label = "Ovjerio izvršitelj",
            value = handoverVerifierUserId,
            valueLabel = handoverVerifierLabelById[handoverVerifierUserId].orEmpty().ifBlank { "Odaberi osobu" },
            options = handoverVerifierOptions,
            enabled = enabled && handoverVerifierOptions.size > 1,
            onSelect = onHandoverVerifierChange,
        )
        DocumentationSummaryRow(
            "Izvori",
            listOf(
                "$selectedEquipmentCount oprema",
                "$selectedLegalCount propisi",
            ).joinToString(" · "),
        )
        if (showWorkEquipmentIsznr) {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                color = if (canSubmitWorkEquipmentToIsznr) {
                    Color(0xFFECFDF5)
                } else {
                    Color(0xFFFFF7ED)
                },
                tonalElevation = 0.dp,
            ) {
                Column(
                    modifier = Modifier.padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            if (canSubmitWorkEquipmentToIsznr) Icons.Rounded.CheckCircle else Icons.Rounded.Info,
                            contentDescription = null,
                            tint = if (canSubmitWorkEquipmentToIsznr) Color(0xFF059669) else Color(0xFFB45309),
                        )
                        Column(modifier = Modifier.weight(1f)) {
                            Text("IS ZNR radna oprema", fontWeight = FontWeight.Black)
                            Text(
                                if (selectedWorkEquipmentCount > 0) {
                                    "$selectedWorkEquipmentCount odabrano za zapisnik."
                                } else {
                                    "Odaberi opremu u RO tabu prije slanja."
                                },
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                            )
                        }
                    }
                    val visibleMissing = workEquipmentMissingLabels
                        .filterNot { it.equals("Odabrana radna oprema", ignoreCase = true) }
                    if (selectedWorkEquipmentCount == 0 || visibleMissing.isNotEmpty()) {
                        Text(
                            when {
                                selectedWorkEquipmentCount == 0 && visibleMissing.isNotEmpty() ->
                                    "Fali: odabrana radna oprema, ${visibleMissing.joinToString(", ")}"
                                selectedWorkEquipmentCount == 0 ->
                                    "Fali: odabrana radna oprema"
                                else -> "Fali: ${visibleMissing.joinToString(", ")}"
                            },
                            style = MaterialTheme.typography.labelSmall,
                            color = Color(0xFFB45309),
                        )
                    }
                    Button(
                        onClick = onSubmitWorkEquipmentToIsznr,
                        enabled = canSubmitWorkEquipmentToIsznr && enabled,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                    ) {
                        if (isSubmittingWorkEquipmentToIsznr) {
                            CircularProgressIndicator(
                                modifier = Modifier.size(18.dp),
                                strokeWidth = 2.dp,
                                color = MaterialTheme.colorScheme.onPrimary,
                            )
                        } else {
                            Icon(Icons.Rounded.CheckCircle, contentDescription = null, modifier = Modifier.size(18.dp))
                        }
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            if (isSubmittingWorkEquipmentToIsznr) "Šaljem u IS ZNR..." else "Pošalji RO u IS ZNR",
                            fontWeight = FontWeight.Black,
                        )
                    }
                }
            }
        }
        if (showPhysicalFactorsIsznr) {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                color = if (canSubmitPhysicalFactorsToIsznr) {
                    Color(0xFFECFDF5)
                } else {
                    Color(0xFFFFF7ED)
                },
                tonalElevation = 0.dp,
            ) {
                Column(
                    modifier = Modifier.padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(
                            if (canSubmitPhysicalFactorsToIsznr) Icons.Rounded.CheckCircle else Icons.Rounded.Info,
                            contentDescription = null,
                            tint = if (canSubmitPhysicalFactorsToIsznr) Color(0xFF059669) else Color(0xFFB45309),
                        )
                        Column(modifier = Modifier.weight(1f)) {
                            Text("IS ZNR FC", fontWeight = FontWeight.Black)
                            Text(
                                if (selectedPhysicalFactorsCount > 0) {
                                    "$selectedPhysicalFactorsCount FC unos spreman za slanje."
                                } else {
                                    "Unesi FC blokove ili odaberi prethodni FC zapisnik."
                                },
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                            )
                        }
                    }
                    val visibleMissing = physicalFactorsMissingLabels
                        .filterNot { it.equals("Prethodni FC zapisnik", ignoreCase = true) }
                        .filterNot { it.equals("Prethodni FC zapisnik ili novi unos", ignoreCase = true) }
                    if (selectedPhysicalFactorsCount == 0 || visibleMissing.isNotEmpty()) {
                        Text(
                            when {
                                selectedPhysicalFactorsCount == 0 && visibleMissing.isNotEmpty() ->
                                    "Fali: FC unos, ${visibleMissing.joinToString(", ")}"
                                selectedPhysicalFactorsCount == 0 ->
                                    "Fali: FC unos"
                                else -> "Fali: ${visibleMissing.joinToString(", ")}"
                            },
                            style = MaterialTheme.typography.labelSmall,
                            color = Color(0xFFB45309),
                        )
                    }
                    Button(
                        onClick = onSubmitPhysicalFactorsToIsznr,
                        enabled = canSubmitPhysicalFactorsToIsznr && enabled,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                    ) {
                        if (isSubmittingPhysicalFactorsToIsznr) {
                            CircularProgressIndicator(
                                modifier = Modifier.size(18.dp),
                                strokeWidth = 2.dp,
                                color = MaterialTheme.colorScheme.onPrimary,
                            )
                        } else {
                            Icon(Icons.Rounded.CheckCircle, contentDescription = null, modifier = Modifier.size(18.dp))
                        }
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            if (isSubmittingPhysicalFactorsToIsznr) "Šaljem u IS ZNR..." else "Pošalji FC u IS ZNR",
                            fontWeight = FontWeight.Black,
                        )
                    }
                }
            }
        }
        DocumentationSummaryRow(
            "Potpis",
            when (signatureMode) {
                "digital" -> "Digitalni"
                "scan" -> "Sken"
                "manual" -> "Ručni"
                else -> signatureMode.ifBlank { "Digitalni" }
            },
        )
        Text("Način potpisa", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            SignatureModeChip("digital", "Digitalni", signatureMode, enabled, onSignatureMode)
            SignatureModeChip("scan", "Sken", signatureMode, enabled, onSignatureMode)
            SignatureModeChip("manual", "Ručni", signatureMode, enabled, onSignatureMode)
        }
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(16.dp),
            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.78f),
        ) {
            Row(
                modifier = Modifier.padding(12.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(Icons.Rounded.CheckCircle, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                Spacer(Modifier.width(8.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text("Primopredajni zapisnik", fontWeight = FontWeight.Black)
                    Text(
                        "Primopredaja se uvijek generira i sprema u dokumentaciju RN-a.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                    )
                }
            }
        }
        if (flowItems.size > 1) {
            Text(
                "Izradit će se zapisnici za ${flowItems.size} usluge.",
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.Bold,
            )
        }
    }
}

