@Composable
private fun DocumentationMeasurementFullscreenDialog(
    workOrder: WorkOrder,
    selectedLabel: String,
    measurementTemplates: List<WorkOrderDocumentationTemplate>,
    measurementSheets: Map<String, WorkOrderMeasurementSheet>,
    includedMeasurementTableKeys: Set<String>,
    enabled: Boolean,
    onSheetChange: (String, WorkOrderMeasurementSheet) -> Unit,
    onTableIncludedChange: (String, Boolean) -> Unit,
    onDismiss: () -> Unit,
    onDone: () -> Unit,
) {
    val context = LocalContext.current
    DisposableEffect(Unit) {
        val activity = context.findFragmentActivity()
        activity?.requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE
        onDispose {
            activity?.requestedOrientation = ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED
        }
    }

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = false,
        ),
    ) {
        Surface(
            modifier = Modifier
                .fillMaxSize()
                .imePadding(),
            shape = RoundedCornerShape(0.dp),
            color = MaterialTheme.colorScheme.surface,
        ) {
            Row(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(WindowInsets.safeDrawing.asPaddingValues())
                    .padding(start = 10.dp, top = 8.dp, end = 8.dp, bottom = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Column(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight(),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 4.dp),
                        verticalArrangement = Arrangement.spacedBy(1.dp),
                    ) {
                        Text(
                            "Mjerenja",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Black,
                            maxLines = 1,
                        )
                        Text(
                            listOf("RN ${workOrder.displayNumber}", selectedLabel, workOrder.companyName)
                                .filter { it.isNotBlank() }
                                .joinToString(" · "),
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                    DocumentationMeasurementPreviewContent(
                        measurementTemplates = measurementTemplates,
                        measurementSheets = measurementSheets,
                        includedMeasurementTableKeys = includedMeasurementTableKeys,
                        enabled = enabled,
                        fullscreen = true,
                        onSheetChange = onSheetChange,
                        onTableIncludedChange = onTableIncludedChange,
                    )
                }
                Column(
                    modifier = Modifier
                        .width(56.dp)
                        .fillMaxHeight()
                        .padding(vertical = 6.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Top,
                ) {
                    FloatingActionButton(
                        onClick = onDone,
                        modifier = Modifier.size(48.dp),
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor = MaterialTheme.colorScheme.onPrimary,
                    ) {
                        Icon(Icons.Rounded.CheckCircle, contentDescription = "Gotovo")
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentationMeasurementLaunchCard(
    measurementTemplates: List<WorkOrderDocumentationTemplate>,
    measurementSheets: Map<String, WorkOrderMeasurementSheet>,
    enabled: Boolean,
    onOpen: () -> Unit,
) {
    val tables = remember(measurementTemplates) {
        measurementTemplates.flatMap { template ->
            template.measurementTables.map { table -> template to table }
        }
    }
    val rowCount = remember(measurementTemplates, measurementSheets) {
        tables.sumOf { (template, table) ->
            (measurementSheets[measurementSheetStateKey(template, table)] ?: table.sheet).rows.size
        }
    }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.26f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.18f)),
    ) {
        Row(
            modifier = Modifier.padding(14.dp),
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Surface(shape = CircleShape, color = MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)) {
                Icon(
                    Icons.Rounded.Description,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier
                        .size(38.dp)
                        .padding(9.dp),
                )
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text("Rezultati ispitivanja", fontWeight = FontWeight.Black)
                Text(
                    "${tables.size} tablica · $rowCount redova · otvara se u većem prikazu",
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            }
            Button(onClick = onOpen, enabled = enabled, shape = RoundedCornerShape(14.dp)) {
                Text("Prikaži mjerenja", fontWeight = FontWeight.Black)
            }
        }
    }
}

@Composable
private fun DocumentationMeasurementPreviewContent(
    measurementTemplates: List<WorkOrderDocumentationTemplate>,
    measurementSheets: Map<String, WorkOrderMeasurementSheet>,
    includedMeasurementTableKeys: Set<String>,
    enabled: Boolean,
    fullscreen: Boolean = false,
    onSheetChange: (String, WorkOrderMeasurementSheet) -> Unit,
    onTableIncludedChange: (String, Boolean) -> Unit,
) {
    val tables = remember(measurementTemplates) {
        measurementTemplates.flatMap { template ->
            template.measurementTables.map { table -> template to table }
        }
    }
    LazyColumn(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight(if (fullscreen) 1f else 0.82f),
        verticalArrangement = Arrangement.spacedBy(10.dp),
        contentPadding = PaddingValues(bottom = 8.dp),
    ) {
        items(
            items = tables,
            key = { (template, table) -> "${template.id}:${table.key}:${table.id}" },
        ) { (template, table) ->
            val stateKey = measurementSheetStateKey(template, table)
            val usageKey = measurementTablePrimaryUsageKey(template, table)
            MeasurementTableEditor(
                template = template,
                table = table,
                sheet = measurementSheets[stateKey] ?: table.sheet,
                tableIncluded = usageKey in includedMeasurementTableKeys,
                enabled = enabled,
                expanded = true,
                tableOnly = true,
                onSheetChange = { nextSheet -> onSheetChange(stateKey, nextSheet) },
                onTableIncludedChange = { included -> onTableIncludedChange(usageKey, included) },
            )
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun DocumentationProcessToolbar(
    flowTabs: List<DocumentationFlowTab>,
    selectedService: String,
    enabled: Boolean,
    compact: Boolean = false,
    modifier: Modifier = Modifier,
    onSelectService: (String) -> Unit,
    onLongPressService: (DocumentationServiceFlowItem) -> Unit,
) {
    Surface(
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(if (compact) 14.dp else 18.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.48f),
    ) {
        if (compact) {
            Row(
                modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(Icons.Rounded.Work, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                Text("Proces", fontWeight = FontWeight.Black, maxLines = 1)
                Row(
                    modifier = Modifier
                        .weight(1f)
                        .horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    flowTabs.forEach { tab ->
                        DocumentationProcessChip(
                            label = tab.label,
                            selected = tab.key.equals(selectedService, ignoreCase = true),
                            compact = true,
                            onClick = { onSelectService(tab.key) },
                            onLongClick = tab.serviceItem?.let { item -> { onLongPressService(item) } },
                            enabled = enabled,
                        )
                    }
                }
            }
        } else {
            Column(
                modifier = Modifier.padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    Icon(Icons.Rounded.Work, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                    Text("Proces izrade", fontWeight = FontWeight.Black)
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    flowTabs.forEach { tab ->
                        DocumentationProcessChip(
                            label = tab.label,
                            selected = tab.key.equals(selectedService, ignoreCase = true),
                            onClick = { onSelectService(tab.key) },
                            onLongClick = tab.serviceItem?.let { item -> { onLongPressService(item) } },
                            enabled = enabled,
                        )
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun DocumentationProcessChip(
    label: String,
    selected: Boolean,
    enabled: Boolean,
    compact: Boolean = false,
    onClick: () -> Unit,
    onLongClick: (() -> Unit)? = null,
) {
    val shape = RoundedCornerShape(12.dp)
    Surface(
        modifier = Modifier.combinedClickable(
            enabled = enabled,
            onClick = onClick,
            onLongClick = onLongClick,
        ),
        shape = shape,
        color = if (selected) {
            MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.92f)
        } else {
            MaterialTheme.colorScheme.surface.copy(alpha = 0.82f)
        },
        tonalElevation = if (selected) 2.dp else 0.dp,
    ) {
        Text(
            label,
            modifier = Modifier
                .border(
                    width = 1.dp,
                    color = if (selected) {
                        MaterialTheme.colorScheme.primary.copy(alpha = 0.22f)
                    } else {
                        MaterialTheme.colorScheme.outline.copy(alpha = 0.28f)
                    },
                    shape = shape,
                )
                .padding(horizontal = if (compact) 14.dp else 18.dp, vertical = if (compact) 8.dp else 10.dp),
            color = if (selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface,
            fontWeight = if (selected) FontWeight.Black else FontWeight.SemiBold,
            style = if (compact) MaterialTheme.typography.labelLarge else MaterialTheme.typography.bodyMedium,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
    }
}

