                        Text("RN ${workOrder.displayNumber}", fontWeight = FontWeight.Black)
                        Text(
                            listOf(workOrder.companyName, workOrder.locationName).filter { it.isNotBlank() }.joinToString(" - ")
                                .ifBlank { "Bez tvrtke / lokacije" },
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                        )
                    }
                }
                if (flowItems.isNotEmpty()) {
                    Text("Usluge i zapisnici", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        flowItems.forEachIndexed { index, item ->
                            val selected = item.serviceName.equals(selectedService, ignoreCase = true)
                            FilterChip(
                                selected = selected,
                                onClick = { onSelectService(item.serviceName) },
                                enabled = enabled,
                                label = {
                                    Text(
                                        "${index + 1}. ${item.serviceName}",
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                },
                            )
                        }
                        AssistChip(onClick = {}, label = { Text("Sažetak") })
                    }
                }
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    AssistChip(onClick = {}, label = { Text("${templateCount.coerceAtLeast(0)} predložak") })
                    AssistChip(onClick = {}, label = { Text("${measurementCount.coerceAtLeast(0)} Excel") })
                    AssistChip(onClick = {}, label = { Text("${equipmentCount.coerceAtLeast(0)} oprema") })
                    AssistChip(onClick = {}, label = { Text("${legalFrameworkCount.coerceAtLeast(0)} propisi") })
                    AssistChip(onClick = {}, label = { Text("${rulebookCount.coerceAtLeast(0)} pravilnici") })
                    AssistChip(onClick = {}, label = { Text(workOrder.status.ifBlank { "Bez statusa" }) })
                }
                FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    FilterChip(
                        selected = signatureMode == "scan",
                        onClick = { onSignatureMode("scan") },
                        enabled = enabled,
                        label = { Text("Potpis") },
                    )
                    FilterChip(
                        selected = signatureMode == "digital",
                        onClick = { onSignatureMode("digital") },
                        enabled = enabled,
                        label = { Text("Digitalni") },
                    )
                    FilterChip(
                        selected = signatureMode == "manual",
                        onClick = { onSignatureMode("manual") },
                        enabled = enabled,
                        label = { Text("Ručni") },
                    )
                    AssistChip(onClick = {}, label = { Text("PDF nakon spremanja") })
                }
            }
        }
    }
}

@Composable
private fun MeasurementTableEditor(
    template: WorkOrderDocumentationTemplate,
    table: WorkOrderMeasurementTable,
    sheet: WorkOrderMeasurementSheet,
    tableIncluded: Boolean = true,
    enabled: Boolean,
    spaceOptions: List<Pair<String, String>> = emptyList(),
    requireSpaceSelection: Boolean = false,
    expanded: Boolean = false,
    tableOnly: Boolean = false,
    onSheetChange: (WorkOrderMeasurementSheet) -> Unit,
    onTableIncludedChange: (Boolean) -> Unit = {},
) {
    val historyLimit = 24
    val columnWindowSize = if (tableOnly || expanded) sheet.columns.size.coerceAtLeast(1) else 10
    var columnWindowStart by remember(table.key, table.id) { mutableStateOf(0) }
    var undoStack by remember(table.key, table.id) { mutableStateOf(emptyList<WorkOrderMeasurementSheet>()) }
    var redoStack by remember(table.key, table.id) { mutableStateOf(emptyList<WorkOrderMeasurementSheet>()) }
    fun commitSheetChange(nextSheet: WorkOrderMeasurementSheet) {
        if (nextSheet == sheet) return
        undoStack = (undoStack + sheet).takeLast(historyLimit)
        redoStack = emptyList()
        onSheetChange(nextSheet)
    }
    fun undoSheetChange() {
        val previous = undoStack.lastOrNull() ?: return
        undoStack = undoStack.dropLast(1)
        redoStack = (redoStack + sheet).takeLast(historyLimit)
        onSheetChange(previous)
    }
    fun redoSheetChange() {
        val next = redoStack.lastOrNull() ?: return
        redoStack = redoStack.dropLast(1)
        undoStack = (undoStack + sheet).takeLast(historyLimit)
        onSheetChange(next)
    }
    LaunchedEffect(sheet.columns.size, columnWindowSize) {
        val maxStart = (sheet.columns.size - columnWindowSize).coerceAtLeast(0)
        if (columnWindowStart > maxStart) {
            columnWindowStart = maxStart
        }
    }
    val visibleColumns = remember(sheet.columns, columnWindowStart, columnWindowSize) {
        sheet.columns.drop(columnWindowStart).take(columnWindowSize)
    }
    val lastMeaningfulRowIndex = remember(sheet.rows, sheet.columns, sheet.headerRows) {
        sheet.lastMeaningfulMeasurementRowIndex()
    }
    var extraRowWindow by remember(table.key, table.id) { mutableStateOf(0) }
    var quickFillOpen by remember(table.key, table.id) { mutableStateOf(false) }
    var lastQuickFillDraft by remember(table.key, table.id) { mutableStateOf<MeasurementQuickFillDraft?>(null) }
    val rowLoadPageSize = if (tableOnly) 24 else 20
    val baseVisibleRowCount = remember(sheet.rows.size, lastMeaningfulRowIndex, tableOnly) {
        if (sheet.rows.isEmpty()) {
            0
        } else if (tableOnly) {
            sheet.rows.size
        } else if (lastMeaningfulRowIndex >= 0) {
            val initialRows = if (tableOnly) 24 else 12
            val maxRows = if (tableOnly) 24 else 32
            maxOf(initialRows, minOf(lastMeaningfulRowIndex + 6, maxRows)).coerceAtMost(sheet.rows.size)
        } else {
            minOf(if (tableOnly) 24 else 12, sheet.rows.size)
        }
    }
    val visibleRowCount = (baseVisibleRowCount + extraRowWindow).coerceAtMost(sheet.rows.size)
    val visibleRows = remember(sheet.rows, visibleRowCount) { sheet.rows.take(visibleRowCount) }
    val gridScrollState = rememberScrollState()
    LaunchedEffect(tableOnly, gridScrollState.value, gridScrollState.maxValue, visibleRowCount, sheet.rows.size) {
        if (
            tableOnly &&
            visibleRowCount < sheet.rows.size &&
            gridScrollState.maxValue > 0 &&
            gridScrollState.value >= gridScrollState.maxValue - 180
        ) {
            extraRowWindow = (extraRowWindow + rowLoadPageSize).coerceAtMost((sheet.rows.size - baseVisibleRowCount).coerceAtLeast(0))
        }
    }
    val initialSelection = remember(table.key, table.id, sheet.columns.size) {
        val columnIndex = sheet.columns.indexOfFirst { it.isEditableMeasurementColumn() }.takeIf { it >= 0 } ?: 0
        MeasurementCellSelection(0, columnIndex)
    }
    var selectedCell by remember(table.key, table.id) { mutableStateOf(initialSelection) }
    var editingRowId by remember(table.key, table.id) { mutableStateOf("") }
    var editingColumnId by remember(table.key, table.id) { mutableStateOf("") }
    var editingValue by remember(table.key, table.id) { mutableStateOf("") }
    fun sheetWithPendingCellValue(baseSheet: WorkOrderMeasurementSheet = sheet): WorkOrderMeasurementSheet {
        if (editingRowId.isBlank() || editingColumnId.isBlank()) return baseSheet
        val column = baseSheet.columns.firstOrNull { it.id == editingColumnId } ?: return baseSheet
        if (!column.isEditableMeasurementColumn()) return baseSheet
        val row = baseSheet.rows.firstOrNull { it.id == editingRowId } ?: return baseSheet
        if (row.cells[editingColumnId].orEmpty() == editingValue) return baseSheet
        return updateMeasurementSheetCell(baseSheet, editingRowId, editingColumnId, editingValue)
    }
    fun flushPendingCellValue(): WorkOrderMeasurementSheet {
        val nextSheet = sheetWithPendingCellValue(sheet)
        if (nextSheet != sheet) {
            commitSheetChange(nextSheet)
        }
        return nextSheet
    }
    fun selectMeasurementCell(rowIndex: Int, columnIndex: Int) {
        flushPendingCellValue()
        selectedCell = MeasurementCellSelection(rowIndex, columnIndex)
    }
    LaunchedEffect(sheet.rows.size, sheet.columns.size) {
        val safeRow = selectedCell.rowIndex.coerceIn(0, (sheet.rows.size - 1).coerceAtLeast(0))
        val safeColumn = selectedCell.columnIndex.coerceIn(0, (sheet.columns.size - 1).coerceAtLeast(0))
        if (safeRow != selectedCell.rowIndex || safeColumn != selectedCell.columnIndex) {
            selectedCell = MeasurementCellSelection(safeRow, safeColumn)
        }
    }
    LaunchedEffect(columnWindowStart, visibleColumns.size) {
        val visibleRange = columnWindowStart until (columnWindowStart + visibleColumns.size)
        if (visibleColumns.isNotEmpty() && selectedCell.columnIndex !in visibleRange) {
            selectedCell = selectedCell.copy(columnIndex = columnWindowStart)
        }
    }
    val selectedRow = sheet.rows.getOrNull(selectedCell.rowIndex)
    val selectedColumn = sheet.columns.getOrNull(selectedCell.columnIndex)
    val selectedRaw = selectedRow?.cells?.get(selectedColumn?.id.orEmpty()).orEmpty()
    val selectedEditable = selectedColumn?.isEditableMeasurementColumn() == true
    val selectedRequiresSpaceSelection = requireSpaceSelection && selectedColumn?.isPhysicalFactorsSpaceSelectorColumn() == true
    val selectedDisplay = sheet.measurementCellDisplay(selectedCell.rowIndex, selectedCell.columnIndex)
    val selectedFormat = selectedRow?.formats?.get(selectedColumn?.id.orEmpty())
    val selectedFormatType = selectedFormat.measurementFormatString("type").ifBlank { "general" }
    val selectedFormatDecimals = selectedFormat.measurementFormatInt("decimals", 2).coerceIn(0, 6)
    val measurementDataTypeOptions = remember {
        listOf(
            "general" to "Auto",
            "text" to "Tekst",
            "number" to "Broj",
            "integer" to "Cijeli broj",
            "percent" to "Postotak",
        )
    }
    val measurementDecimalsOptions = remember {
        (0..6).map { it.toString() to "$it dec." }
    }
    fun commitSelectedCellFormat(patch: Map<String, Any?>) {
        val row = selectedRow ?: return
        val column = selectedColumn ?: return
        if (!selectedEditable) return
        commitSheetChange(updateMeasurementCellFormat(sheetWithPendingCellValue(sheet), row.id, column.id, patch))
    }
    val gridLine = MaterialTheme.colorScheme.outline.copy(alpha = 0.34f)
    val rowHeaderWidth = if (tableOnly) 46.dp else if (expanded) 54.dp else 46.dp
    val rowHeight = if (tableOnly) 42.dp else if (expanded) 52.dp else 44.dp
    val columnHeaderHeight = if (tableOnly) 34.dp else if (expanded) 40.dp else 34.dp
    val showColumnLabelRow = remember(sheet.columns) { sheet.hasMeaningfulMeasurementColumnLabels() }
    LaunchedEffect(selectedRow?.id.orEmpty(), selectedColumn?.id.orEmpty()) {
        val nextSheet = sheetWithPendingCellValue(sheet)
        if (nextSheet != sheet) {
            commitSheetChange(nextSheet)
        }
        editingRowId = selectedRow?.id.orEmpty()
        editingColumnId = selectedColumn?.id.orEmpty()
        editingValue = selectedRaw
    }
    LaunchedEffect(editingRowId, editingColumnId, editingValue) {
        if (editingRowId.isBlank() || editingColumnId.isBlank()) return@LaunchedEffect
        delay(420)
        flushPendingCellValue()
    }
    if (quickFillOpen) {
        MeasurementQuickFillDialog(
            columns = if (requireSpaceSelection) {
                visibleColumns.filterNot { it.isPhysicalFactorsSpaceSelectorColumn() }
            } else {
                visibleColumns
            },
            enabled = enabled,
            initialDraft = lastQuickFillDraft,
            onDismiss = { quickFillOpen = false },
            onApply = { draft ->
                lastQuickFillDraft = draft
                commitSheetChange(applyMeasurementQuickFill(sheetWithPendingCellValue(sheet), draft))
                extraRowWindow = extraRowWindow.coerceAtLeast(rowLoadPageSize)
                quickFillOpen = false
            },
        )
    }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(10.dp),
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 1.dp,
    ) {
        Column(
            modifier = Modifier.padding(10.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            if (!tableOnly) {
                Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(table.label, fontWeight = FontWeight.Black)
                    Text(
                        listOf(template.title, table.summary).filter { it.isNotBlank() }.joinToString(" - "),
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    )
                    if (table.helpText.isNotBlank()) {
                        Text(
                            table.helpText,
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.54f),
                        )
                    }
                }
            }
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(12.dp))
                    .clickable(enabled = enabled) { onTableIncludedChange(!tableIncluded) },
                shape = RoundedCornerShape(12.dp),
                color = if (tableIncluded) {
                    MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.32f)
                } else {
                    MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.32f)
                },
                border = BorderStroke(
                    1.dp,
                    if (tableIncluded) {
                        MaterialTheme.colorScheme.primary.copy(alpha = 0.24f)
                    } else {
                        MaterialTheme.colorScheme.outline.copy(alpha = 0.18f)
                    },
                ),
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Checkbox(
                        checked = tableIncluded,
                        onCheckedChange = { checked -> onTableIncludedChange(checked) },
                        enabled = enabled,
                    )
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(1.dp)) {
                        Text("Koristi se u zapisniku", fontWeight = FontWeight.Black)
                        Text(
                            if (tableIncluded) "Tablica ide u PDF zapisnik." else "Tablica ostaje u predlošku, ali se ne prikazuje u PDF-u.",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                }
            }
            if (visibleColumns.isEmpty() || visibleRows.isEmpty()) {
                Text("Excel tablica nema dostupnih ćelija za unos.")
            } else {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Surface(
                        modifier = Modifier
                            .width(64.dp)
                            .height(46.dp)
                            .border(1.dp, gridLine, RoundedCornerShape(6.dp)),
                        shape = RoundedCornerShape(6.dp),
                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.48f),
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Text(
                                measurementCellReference(selectedCell.rowIndex, selectedCell.columnIndex),
                                fontWeight = FontWeight.Black,
                                color = MaterialTheme.colorScheme.primary,
                            )
                        }
                    }
                    Surface(
                        modifier = Modifier
                            .width(42.dp)
                            .height(46.dp)
                            .border(1.dp, gridLine, RoundedCornerShape(6.dp)),
                        shape = RoundedCornerShape(6.dp),
                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f),
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Text("fx", fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.primary)
                        }
                    }
                    if (selectedRequiresSpaceSelection) {
                        Box(modifier = Modifier.weight(1f)) {
                            WorkOrderSelectField(
                                label = selectedColumn?.label?.ifBlank { "Prostor" } ?: "Prostor",
                                value = selectedRaw,
                                valueLabel = selectedRaw.ifBlank {
                                    if (spaceOptions.isEmpty()) "Prvo dodaj prostor" else "Odaberi prostor"
                                },
                                options = spaceOptions,
                                enabled = enabled && selectedEditable && spaceOptions.isNotEmpty(),
                                onSelect = { value ->
                                    val row = selectedRow
                                    val column = selectedColumn
                                    if (row != null && column != null) {
                                        editingValue = value
                                        commitSheetChange(updateMeasurementSheetCell(sheet, row.id, column.id, value))
                                    }
                                },
                            )
                        }
                    } else {
                        OutlinedTextField(
                            value = editingValue,
                            onValueChange = { value ->
                                if (selectedEditable) {
                                    editingValue = value
                                }
                            },
                            modifier = Modifier.weight(1f),
                            placeholder = { Text(if (selectedDisplay.isNotBlank()) selectedDisplay else "Vrijednost ili formula") },
                            singleLine = true,
                            enabled = enabled && selectedEditable,
                            shape = RoundedCornerShape(6.dp),
                        )
                    }
                }
                if (selectedRow != null && selectedColumn != null && selectedEditable) {
                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(7.dp),
                        verticalArrangement = Arrangement.spacedBy(7.dp),
                    ) {
                        WorkOrderSelectField(
                            label = "Tip podatka",
                            value = selectedFormatType,
                            valueLabel = measurementDataTypeOptions.firstOrNull { it.first == selectedFormatType }?.second ?: "Auto",
                            options = measurementDataTypeOptions,
                            enabled = enabled,
                            onSelect = { value ->
                                commitSelectedCellFormat(
                                    mapOf<String, Any?>("type" to value.takeUnless { it == "general" }),
                                )
                            },
                            modifier = Modifier.width(154.dp),
                            compact = true,
                        )
                        WorkOrderSelectField(
                            label = "Decimale",
                            value = selectedFormatDecimals.toString(),
                            valueLabel = "${selectedFormatDecimals} dec.",
                            options = measurementDecimalsOptions,
                            enabled = enabled,
                            onSelect = { value ->
                                commitSelectedCellFormat(
                                    mapOf<String, Any?>("decimals" to value.toIntOrNull()?.coerceIn(0, 6)),
                                )
                            },
                            modifier = Modifier.width(132.dp),
                            compact = true,
                        )
                    }
                }
                FlowRow(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(7.dp),
                    verticalArrangement = Arrangement.spacedBy(7.dp),
                ) {
                    AssistChip(
                        onClick = { commitSheetChange(appendBlankMeasurementRows(sheetWithPendingCellValue(sheet), 1)) },
                        enabled = enabled,
                        label = { Text("+ Red") },
                    )
                    AssistChip(
                        onClick = { commitSheetChange(appendBlankMeasurementRows(sheetWithPendingCellValue(sheet), 5)) },
                        enabled = enabled,
                        label = { Text("+ 5") },
                    )
                    AssistChip(
                        onClick = {
                            flushPendingCellValue()
                            quickFillOpen = true
                        },
                        enabled = enabled && visibleColumns.any { it.isEditableMeasurementColumn() },
                        label = { Text("Brzi unos") },
                    )
                    AssistChip(
                        onClick = { commitSheetChange(duplicateLastMeasurementRow(sheetWithPendingCellValue(sheet))) },
                        enabled = enabled,
                        label = { Text("Kopiraj zadnji") },
                    )
                    AssistChip(
                        onClick = { commitSheetChange(fillMeasurementRowNumbers(sheetWithPendingCellValue(sheet))) },
                        enabled = enabled,
                        label = { Text("R.br.") },
                    )
                    AssistChip(
                        onClick = { commitSheetChange(fillMeasurementCellDown(sheetWithPendingCellValue(sheet), selectedCell)) },
                        enabled = enabled && selectedEditable && selectedRaw.isNotBlank() && selectedCell.rowIndex < sheet.rows.lastIndex,
                        label = { Text("Popuni dolje") },
                    )
                    AssistChip(
                        onClick = { commitSheetChange(appendMeasurementColumn(sheetWithPendingCellValue(sheet))) },
                        enabled = enabled,
                        label = { Text("+ Kolona") },
                    )
                    AssistChip(
                        onClick = { undoSheetChange() },
                        enabled = enabled && undoStack.isNotEmpty(),
                        label = { Text("Undo") },
                    )
                    AssistChip(
                        onClick = { redoSheetChange() },
                        enabled = enabled && redoStack.isNotEmpty(),
                        label = { Text("Redo") },
                    )
                }
                if (!tableOnly && selectedRow != null && selectedColumn != null && selectedEditable && !selectedRequiresSpaceSelection) {
                    val formulaSeeds = listOf("SUM", "AVERAGE", "IF", "IFERROR", "COUNTIF", "TEXTAFTER", "VLOOKUP", "RANDBETWEEN")
                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(7.dp),
                        verticalArrangement = Arrangement.spacedBy(7.dp),
                    ) {
                        Text(
                            "fx prijedlozi",
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                            modifier = Modifier.padding(top = 8.dp),
                        )
                        formulaSeeds.forEach { seed ->
                            AssistChip(
                                onClick = {
                                    val nextValue = if (editingValue.trim().startsWith("=")) {
                                        editingValue + seed + "("
                                    } else {
                                        "=$seed("
                                    }
                                    editingValue = nextValue
                                    commitSheetChange(updateMeasurementSheetCell(sheet, selectedRow.id, selectedColumn.id, nextValue))
                                },
                                enabled = enabled,
                                label = { Text(seed) },
                            )
                        }
                    }
                }
                if (sheet.columns.size > columnWindowSize) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            "Kolone ${measurementColumnLabel(columnWindowStart)}-${measurementColumnLabel((columnWindowStart + visibleColumns.size - 1).coerceAtLeast(columnWindowStart))} / ${sheet.columns.size}",
                            modifier = Modifier.weight(1f),
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                        )
                        OutlinedButton(
                            onClick = { columnWindowStart = (columnWindowStart - columnWindowSize).coerceAtLeast(0) },
                            enabled = enabled && columnWindowStart > 0,
                        ) {
                            Text("Preth.")
                        }
                        OutlinedButton(
                            onClick = {
                                val maxStart = (sheet.columns.size - columnWindowSize).coerceAtLeast(0)
                                columnWindowStart = (columnWindowStart + columnWindowSize).coerceAtMost(maxStart)
                            },
                            enabled = enabled && columnWindowStart + columnWindowSize < sheet.columns.size,
                        ) {
                            Text("Sljed.")
                        }
                    }
                }
                if (selectedRow != null && selectedColumn != null && selectedEditable) {
                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(7.dp),
                        verticalArrangement = Arrangement.spacedBy(7.dp),
                    ) {
                        listOf(
                            "Da" to "#d9ead3",
                            "Ne" to "#f4cccc",
                            "-" to "#eeeeee",
                        ).forEach { (value, color) ->
                            AssistChip(
                                onClick = {
                                    editingValue = value
                                    commitSheetChange(
                                        updateMeasurementCellFill(
                                            updateMeasurementSheetCell(sheet, selectedRow.id, selectedColumn.id, value),
                                            selectedRow.id,
                                            selectedColumn.id,
                                            color,
                                        ),
                                    )
                                },
                                enabled = enabled,
                                label = { Text(value) },
                            )
                        }
                        MeasurementColorChip("Zelena", "#d9ead3", enabled) {
                            commitSheetChange(updateMeasurementCellFill(sheetWithPendingCellValue(sheet), selectedRow.id, selectedColumn.id, "#d9ead3"))
                        }
                        MeasurementColorChip("Žuta", "#fff2cc", enabled) {
                            commitSheetChange(updateMeasurementCellFill(sheetWithPendingCellValue(sheet), selectedRow.id, selectedColumn.id, "#fff2cc"))
                        }
                        MeasurementColorChip("Crvena", "#f4cccc", enabled) {
                            commitSheetChange(updateMeasurementCellFill(sheetWithPendingCellValue(sheet), selectedRow.id, selectedColumn.id, "#f4cccc"))
                        }
                        MeasurementColorChip("Siva", "#eeeeee", enabled) {
                            commitSheetChange(updateMeasurementCellFill(sheetWithPendingCellValue(sheet), selectedRow.id, selectedColumn.id, "#eeeeee"))
                        }
                        MeasurementColorChip("Bez", null, enabled) {
                            commitSheetChange(updateMeasurementCellFill(sheetWithPendingCellValue(sheet), selectedRow.id, selectedColumn.id, null))
                        }
                    }
                }
                val gridModifier = Modifier
                    .fillMaxWidth()
                    .border(1.dp, gridLine, RoundedCornerShape(6.dp))
                    .clip(RoundedCornerShape(6.dp))
                    .let { baseModifier ->
                        if (tableOnly) {
                            baseModifier
                                .heightIn(max = if (expanded) 440.dp else 360.dp)
                                .verticalScroll(gridScrollState)
                        } else {
                            baseModifier
                        }
                    }
                Row(
                    modifier = gridModifier,
                ) {
                    Column {
                        MeasurementHeaderCell("", rowHeaderWidth.value.toInt(), height = columnHeaderHeight, subtle = true)
                        if (showColumnLabelRow) {
                            Surface(
                                modifier = Modifier
                                    .width(rowHeaderWidth)
                                    .height(rowHeight)
                                    .border(0.6.dp, gridLine),
                                color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.34f),
                            ) {
                                Box(contentAlignment = Alignment.Center) {
                                    Text("", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Black)
                                }
                            }
                        }
                        visibleRows.forEachIndexed { rowIndex, row ->
                            Surface(
                                modifier = Modifier
                                    .width(rowHeaderWidth)
                                    .height(rowHeight)
                                    .border(0.6.dp, gridLine),
                                color = if (selectedCell.rowIndex == rowIndex) {
                                    MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f)
                                } else {
                                    MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.72f)
                                },
                            ) {
                                Box(contentAlignment = Alignment.Center) {
                                    Text("${rowIndex + 1}", style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .horizontalScroll(rememberScrollState()),
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            visibleColumns.forEachIndexed { columnIndex, column ->
                                val absoluteColumnIndex = sheet.columns.indexOfFirst { it.id == column.id }.takeIf { it >= 0 }
                                    ?: (columnWindowStart + columnIndex)
                                MeasurementHeaderCell(measurementColumnLabel(absoluteColumnIndex), column.width, height = columnHeaderHeight)
                            }
                        }
                        if (showColumnLabelRow) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                visibleColumns.forEach { column ->
                                    MeasurementColumnLabelCell(column = column, rowHeight = rowHeight)
                                }
                            }
                        }
                        visibleRows.forEachIndexed { rowIndex, row ->
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                visibleColumns.forEachIndexed { columnIndex, column ->
                                    val absoluteColumnIndex = sheet.columns.indexOfFirst { it.id == column.id }.takeIf { it >= 0 }
                                        ?: (columnWindowStart + columnIndex)
                                    MeasurementGridCell(
                                        column = column,
                                        displayValue = sheet.measurementCellDisplay(rowIndex, absoluteColumnIndex),
                                        rawValue = if (selectedCell.rowIndex == rowIndex && selectedCell.columnIndex == absoluteColumnIndex) {
                                            editingValue
                                        } else {
                                            row.cells[column.id].orEmpty()
                                        },
                                        cellFormat = row.formats[column.id],
                                        headerRow = sheet.headerRows.contains(row.id),
                                        selected = selectedCell.rowIndex == rowIndex && selectedCell.columnIndex == absoluteColumnIndex,
                                        enabled = enabled,
                                        onClick = {
                                            selectMeasurementCell(rowIndex, absoluteColumnIndex)
                                        },
                                        onChange = { value ->
                                            if (!(requireSpaceSelection && column.isPhysicalFactorsSpaceSelectorColumn())) {
                                                editingValue = value
                                            }
                                        },
                                        rowHeight = rowHeight,
                                        expanded = expanded,
                                        directEditable = !(requireSpaceSelection && column.isPhysicalFactorsSpaceSelectorColumn()),
                                    )
                                }
                            }
                        }
                    }
                }
                if (visibleRowCount < sheet.rows.size) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            "Prikazano $visibleRowCount/${sheet.rows.size} redova",
                            modifier = Modifier.weight(1f),
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                        )
                        OutlinedButton(onClick = { extraRowWindow += rowLoadPageSize }, enabled = enabled) {
                            Text("Još $rowLoadPageSize")
                        }
                        TextButton(onClick = { extraRowWindow = sheet.rows.size }, enabled = enabled) {
                            Text("Sve")
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun MeasurementQuickFillDialog(
    columns: List<WorkOrderMeasurementColumn>,
    enabled: Boolean,
    initialDraft: MeasurementQuickFillDraft? = null,
    onDismiss: () -> Unit,
    onApply: (MeasurementQuickFillDraft) -> Unit,
) {
    val editableColumns = remember(columns) { columns.filter { it.isEditableMeasurementColumn() } }
    val columnSignature = remember(editableColumns) { editableColumns.joinToString("|") { "${it.id}:${it.label}" } }
    val editableColumnIds = remember(columnSignature) { editableColumns.map { it.id }.toSet() }
    var floor by remember(initialDraft) { mutableStateOf(initialDraft?.floor.orEmpty()) }
    var room by remember(initialDraft) { mutableStateOf(initialDraft?.room.orEmpty()) }
    var itemsText by remember(initialDraft) { mutableStateOf(initialDraft?.itemsText.orEmpty()) }
    var defaultCount by remember(initialDraft) { mutableStateOf((initialDraft?.defaultCount ?: 1).coerceIn(1, 500).toString()) }
    var columnModes by remember(columnSignature) {
        mutableStateOf(
            editableColumns.associate { it.id to defaultMeasurementQuickFillColumnModeMobile(it) } +
                initialDraft?.columnModes.orEmpty().filterKeys { it in editableColumnIds },
        )
    }
    var customValues by remember(columnSignature) {
        mutableStateOf(initialDraft?.customValues.orEmpty().filterKeys { it in editableColumnIds })
    }
    val visibleEditableColumns = remember(columnSignature) { editableColumns.take(10) }
    val modeOptions = listOf(
        "itemIndex" to "Redni broj",
        "floor" to "Etaža",
        "room" to "Prostorija",
        "item" to "Stavka / naziv",
        "quantity" to "Količina",
        "formula" to "Formula",
        "custom" to "Vrijednost",
        "empty" to "Prazno",
    )
    AlertDialog(
        onDismissRequest = onDismiss,
        modifier = Modifier.fillMaxWidth(0.98f),
        confirmButton = {
            Button(
                onClick = {
                    onApply(
                        MeasurementQuickFillDraft(
                            floor = floor,
                            room = room,
                            itemsText = itemsText,
                            defaultCount = defaultCount.toIntOrNull()?.coerceIn(1, 500) ?: 1,
                            columnModes = columnModes,
                            customValues = customValues,
                        ),
                    )
                },
                enabled = enabled,
            ) {
                Text("Dodaj")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Odustani")
            }
        },
        title = { Text("Brzi unos stavki") },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 560.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "Jedan red je jedna stavka. Količina može ići kao: Izlaz;3.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    OutlinedTextField(
                        value = floor,
                        onValueChange = { floor = it },
                        modifier = Modifier.weight(1f),
                        label = { Text("Etaža") },
                        singleLine = true,
                        enabled = enabled,
                        shape = RoundedCornerShape(12.dp),
                    )
                    OutlinedTextField(
                        value = room,
                        onValueChange = { room = it },
                        modifier = Modifier.weight(1f),
                        label = { Text("Prostorija") },
                        singleLine = true,
                        enabled = enabled,
                        shape = RoundedCornerShape(12.dp),
                    )
                }
                OutlinedTextField(
                    value = itemsText,
                    onValueChange = { itemsText = it },
                    modifier = Modifier.fillMaxWidth(),
                    label = { Text("Redovi za unos") },
                    minLines = 3,
                    maxLines = 4,
                    enabled = enabled,
                    shape = RoundedCornerShape(12.dp),
                )
                OutlinedTextField(
                    value = defaultCount,
                    onValueChange = { value -> defaultCount = value.filter { it.isDigit() }.take(3) },
                    modifier = Modifier.widthIn(min = 120.dp, max = 160.dp),
                    label = { Text("Količina po stavci") },
                    singleLine = true,
                    enabled = enabled,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    shape = RoundedCornerShape(12.dp),
                )
                Text("Vrijednosti po kolonama", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.34f),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.22f)),
                ) {
                    Row(
                        modifier = Modifier
                            .horizontalScroll(rememberScrollState())
                            .padding(10.dp),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                    ) {
                        visibleEditableColumns.forEach { column ->
                            val mode = columnModes[column.id] ?: defaultMeasurementQuickFillColumnModeMobile(column)
                            Column(
                                modifier = Modifier.width(184.dp),
                                verticalArrangement = Arrangement.spacedBy(7.dp),
                            ) {
                                Text(
                                    column.label.ifBlank { column.id },
                                    style = MaterialTheme.typography.labelMedium,
                                    fontWeight = FontWeight.Black,
                                    maxLines = 2,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                WorkOrderSelectField(
                                    label = "Izvor",
                                    value = mode,
                                    valueLabel = modeOptions.firstOrNull { it.first == mode }?.second ?: mode,
                                    options = modeOptions,
                                    enabled = enabled,
                                    onSelect = { value -> columnModes = columnModes + (column.id to value) },
                                    compact = true,
                                )
                                if (mode == "custom" || mode == "formula") {
                                    OutlinedTextField(
                                        value = customValues[column.id].orEmpty(),
                                        onValueChange = { value -> customValues = customValues + (column.id to value) },
                                        modifier = Modifier.fillMaxWidth(),
                                        label = { Text(if (mode == "formula") "Formula" else "Vrijednost") },
                                        singleLine = true,
                                        enabled = enabled,
                                        shape = RoundedCornerShape(12.dp),
                                    )
                                } else {
                                    Text(
                                        modeOptions.firstOrNull { it.first == mode }?.second ?: mode,
                                        style = MaterialTheme.typography.labelSmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                }
                            }
                        }
                    }
                }
                if (editableColumns.size > 10) {
                    Text(
                        "Prikazano je prvih 10 kolona za brzi unos. Ostale možeš urediti direktno u tablici.",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    )
                }
            }
        },
        properties = DialogProperties(usePlatformDefaultWidth = false),
    )
}

@Composable
private fun MeasurementColorChip(
    label: String,
    colorHex: String?,
    enabled: Boolean,
    onClick: () -> Unit,
) {
    val chipColor = colorHex?.let(::parseMeasurementColorMobile)
    val shape = RoundedCornerShape(999.dp)
    Surface(
        modifier = Modifier
            .clip(shape)
            .clickable(enabled = enabled) { onClick() },
        shape = shape,
        color = MaterialTheme.colorScheme.surface,
        tonalElevation = 0.dp,
    ) {
        Row(
            modifier = Modifier
                .border(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.35f), shape)
                .padding(horizontal = 9.dp, vertical = 6.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Surface(
                modifier = Modifier.size(13.dp),
                shape = CircleShape,
                color = chipColor ?: Color.Transparent,
                border = if (chipColor == null) {
                    androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.55f))
                } else {
                    null
                },
            ) {}
            Text(label, style = MaterialTheme.typography.labelMedium, fontWeight = FontWeight.SemiBold)
        }
    }
}

private fun WorkOrderMeasurementSheet.hasMeaningfulMeasurementColumnLabels(): Boolean =
    columns.withIndex().any { (index, column) ->
        val label = column.label.trim()
        label.isNotBlank() &&
            !label.equals(column.id, ignoreCase = true) &&
            !label.equals("Kolona ${index + 1}", ignoreCase = true)
    }

