@Composable
private fun MeasurementGridCell(
    column: WorkOrderMeasurementColumn,
    displayValue: String,
    rawValue: String,
    cellFormat: JSONObject?,
    headerRow: Boolean,
    selected: Boolean,
    enabled: Boolean,
    onClick: () -> Unit,
    onChange: (String) -> Unit,
    rowHeight: Dp = 44.dp,
    expanded: Boolean = false,
    directEditable: Boolean = true,
) {
    val editable = column.isEditableMeasurementColumn()
    val isFormula = rawValue.trim().startsWith("=")
    val value = formatMeasurementCellDisplayMobile(
        displayValue = if (isFormula) displayValue else displayValue.ifBlank { rawValue },
        rawValue = rawValue,
        format = cellFormat,
    )
    val hasError = value == "#ERROR"
    val gridLine = MaterialTheme.colorScheme.outline.copy(alpha = 0.34f)
    val cellWidth = column.width.coerceIn(46, 260).dp
    val fillColor = measurementFormatFillColor(cellFormat, value)
    val textColor = measurementFormatTextColor(cellFormat)
    val textAlign = measurementFormatTextAlign(cellFormat)
    val contentAlignment = measurementFormatContentAlignment(cellFormat)
    val fontSize = measurementFormatFontSizeSp(cellFormat, expanded)
    val fontFamily = measurementFormatFontFamily(cellFormat)
    val bold = headerRow || measurementFormatBold(cellFormat, value)
    val italic = measurementFormatItalic(cellFormat)
    val underline = measurementFormatUnderline(cellFormat)
    val hasCustomBorder = cellFormat.measurementBorderCustomized()
    val borderWidth = when {
        selected -> 2.dp
        hasCustomBorder -> 1.4.dp
        else -> 0.6.dp
    }
    val borderColor = when {
        selected -> MaterialTheme.colorScheme.primary
        hasCustomBorder -> MaterialTheme.colorScheme.onSurface.copy(alpha = 0.82f)
        else -> gridLine
    }
    val textModifier = when (contentAlignment) {
        Alignment.CenterEnd, Alignment.TopEnd, Alignment.BottomEnd -> Modifier
            .fillMaxWidth()
            .padding(horizontal = 8.dp)
        Alignment.Center, Alignment.TopCenter, Alignment.BottomCenter -> Modifier
            .fillMaxWidth()
            .padding(horizontal = 8.dp)
        else -> Modifier.padding(horizontal = 8.dp)
    }
    if (selected && editable && directEditable) {
        OutlinedTextField(
            value = rawValue,
            onValueChange = onChange,
            modifier = Modifier
                .width(cellWidth)
                .height(rowHeight),
            singleLine = true,
            enabled = enabled,
            textStyle = (if (expanded) MaterialTheme.typography.bodyMedium else MaterialTheme.typography.bodySmall).copy(
                color = textColor ?: MaterialTheme.colorScheme.onSurface,
                fontFamily = fontFamily,
                fontSize = fontSize,
                fontWeight = if (bold) FontWeight.Bold else FontWeight.Normal,
                fontStyle = if (italic) FontStyle.Italic else FontStyle.Normal,
                textDecoration = if (underline) TextDecoration.Underline else TextDecoration.None,
                textAlign = textAlign,
            ),
            keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
            shape = RoundedCornerShape(2.dp),
        )
        return
    }
    Box(
        modifier = Modifier
            .width(cellWidth)
            .height(rowHeight)
            .border(borderWidth, borderColor)
            .background(
                when {
                    hasError -> MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.58f)
                    selected -> MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.52f)
                    fillColor != null -> fillColor
                    headerRow -> MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.28f)
                    !editable -> MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.46f)
                    else -> MaterialTheme.colorScheme.surface
                },
            )
            .clickable(enabled = enabled) { onClick() },
        contentAlignment = contentAlignment,
    ) {
        Text(
            value.ifBlank { if (isFormula) "" else column.placeholder },
            modifier = textModifier,
            style = (if (expanded) MaterialTheme.typography.bodyMedium else MaterialTheme.typography.bodySmall).copy(
                fontFamily = fontFamily,
                fontSize = fontSize,
                fontStyle = if (italic) FontStyle.Italic else FontStyle.Normal,
                textDecoration = if (underline) TextDecoration.Underline else TextDecoration.None,
            ),
            fontWeight = if (selected || bold) FontWeight.Bold else FontWeight.Normal,
            textAlign = textAlign,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            color = when {
                hasError -> MaterialTheme.colorScheme.onErrorContainer
                value.isBlank() -> MaterialTheme.colorScheme.onSurface.copy(alpha = 0.42f)
                textColor != null -> textColor
                else -> MaterialTheme.colorScheme.onSurface
            },
        )
    }
}

@Composable
private fun TemplateBlockOverview(
    template: WorkOrderDocumentationTemplate,
    values: Map<String, String>,
    standardControls: DocumentationTemplateStandardControls,
    onChange: (WorkOrderDocumentationField, String) -> Unit,
) {
    val sections = remember(template.fieldBlocks) {
        buildTemplateBlockSections(template.fieldBlocks)
    }
    val sourceTitle = documentationTemplateDataSourceTitle(template)
    val sourceDetails = documentationTemplateDataSourceDetails(template)
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.88f),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(11.dp),
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                Text(sourceTitle, fontWeight = FontWeight.Black)
                Text(
                    listOf(
                        sourceDetails,
                        "${template.fieldBlocks.size} blokova",
                        "${template.measurementTables.size} Excel",
                    ).filter { it.isNotBlank() }.joinToString(" - "),
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                )
            }
            sections.forEach { section ->
                TemplateBlockSectionCard(
                    template = template,
                    section = section,
                    values = values,
                    standardControls = standardControls,
                    onChange = onChange,
                )
            }
        }
    }
}

@Composable
private fun DocumentationSprMobileWorkspace(
    workOrder: WorkOrder,
    templates: List<WorkOrderDocumentationTemplate>,
    measurementTemplates: List<WorkOrderDocumentationTemplate>,
    measurementSheets: Map<String, WorkOrderMeasurementSheet>,
    documentNumber: String,
    objectName: String,
    inspectionDate: String,
    inspectionType: String,
    testingLocation: String,
    selectedEquipmentCount: Int,
    selectedLegalCount: Int,
    selectedPeopleCount: Int,
    values: Map<String, String>,
    standardControls: DocumentationTemplateStandardControls,
    attachmentFiles: List<WorkOrderDocumentationAiFile>,
    attachmentLoading: Boolean,
    attachmentMessage: String,
    sprVoiceAiLoading: Boolean,
    sprVoiceAiMessage: String,
    sprVoicePreviewRows: List<SprVoiceAiRow>,
    enabled: Boolean,
    onOpenMeasurements: () -> Unit,
    onPickAttachments: () -> Unit,
    onOpenAttachment: (WorkOrderDocumentationAiFile) -> Unit,
    onRemoveAttachment: (String) -> Unit,
    onFieldChange: (WorkOrderDocumentationTemplate, WorkOrderDocumentationField, String, Boolean) -> Unit,
    onSprVoicePreview: (WorkOrderDocumentationTemplate, WorkOrderDocumentationField, String) -> Unit,
) {
    val sourceLabel = remember(templates) { documentationSprMobileSourceLabel(templates) }
    val menuEntries = remember(templates) {
        templates.flatMap { template ->
            buildTemplateBlockSections(template.fieldBlocks)
                .filter { section ->
                    (isBasicTemplateSection(section) || !isSharedDocumentationTemplateSection(section)) &&
                        !isDocumentationSignatureTemplateSection(section) &&
                        !isDocumentationAttachmentTemplateSection(section)
                }
                .map { section -> template to section }
        }.mapIndexed { index, (template, section) ->
            DocumentationSprMenuEntry(
                key = "${template.id}:${section.id}",
                template = template,
                section = section,
                index = index,
            )
        }
    }
    val fallbackFieldTemplates = remember(templates) {
        templates.filter { template -> template.fields.isNotEmpty() && template.fieldBlocks.isEmpty() }
    }
    val tableCount = remember(measurementTemplates) {
        measurementTemplates.sumOf { template -> template.measurementTables.size }
    }
    val rowCount = remember(measurementTemplates, measurementSheets) {
        measurementTemplates.sumOf { template ->
            template.measurementTables.sumOf { table ->
                val sheet = measurementSheets[measurementSheetStateKey(template, table)] ?: table.sheet
                sheet.rows.size
            }
        }
    }

    val templateLabel = remember(templates) { documentationSprTemplateLabel(templates) }
    val workspaceTitle = remember(templateLabel) {
        if (templateLabel.equals("Zapisnik", ignoreCase = true) || templateLabel.endsWith("zapisnik", ignoreCase = true)) {
            templateLabel
        } else {
            "$templateLabel zapisnik"
        }
    }

    WizardSection(title = workspaceTitle, icon = Icons.Rounded.PictureAsPdf) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(20.dp),
            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.52f),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)),
        ) {
            Row(
                modifier = Modifier.padding(14.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Surface(shape = RoundedCornerShape(16.dp), color = MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)) {
                    Icon(
                        Icons.Rounded.Description,
                        contentDescription = null,
                        modifier = Modifier
                            .size(44.dp)
                            .padding(10.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    Text(
                        documentNumber.ifBlank { workOrder.displayNumber.ifBlank { documentationSprTemplateLabel(templates) } },
                        style = MaterialTheme.typography.titleMedium,
                        fontWeight = FontWeight.Black,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        listOf(
                            workOrder.companyName,
                            objectName.ifBlank { testingLocation },
                        ).filter { it.isNotBlank() }.joinToString(" - "),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                    Text(
                        listOf(
                            formatDatePickerLabel(inspectionDate),
                            inspectionType,
                            sourceLabel,
                        ).filter { it.isNotBlank() }.distinct().joinToString(" · "),
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.primary,
                        fontWeight = FontWeight.Bold,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
        }

        FlowRow(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            DocumentationSprStatusChip(Icons.Rounded.Work, "Oprema", selectedEquipmentCount.toString())
            DocumentationSprStatusChip(Icons.Rounded.Lock, "Propisi", selectedLegalCount.toString())
            DocumentationSprStatusChip(Icons.Rounded.Groups, "Osobe", selectedPeopleCount.toString())
            if (attachmentFiles.isNotEmpty()) {
                DocumentationSprStatusChip(Icons.Rounded.AttachFile, "Prilozi", attachmentFiles.size.toString())
            }
            DocumentationSprStatusChip(Icons.Rounded.ListAlt, "Gridline", "$tableCount / $rowCount")
        }

        AnimatedVisibility(visible = sprVoiceAiLoading || sprVoiceAiMessage.isNotBlank()) {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.5f),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.14f)),
            ) {
                Row(
                    modifier = Modifier.padding(11.dp),
                    horizontalArrangement = Arrangement.spacedBy(9.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    if (sprVoiceAiLoading) {
                        CircularProgressIndicator(modifier = Modifier.size(17.dp), strokeWidth = 2.dp)
                    } else {
                        Icon(Icons.Rounded.Fingerprint, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                    }
                    Text(
                        if (sprVoiceAiLoading) "NexAI strukturira diktat u retke..." else sprVoiceAiMessage,
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.78f),
                    )
                }
            }
        }

        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(18.dp),
            color = MaterialTheme.colorScheme.surface.copy(alpha = 0.78f),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.12f)),
        ) {
            Column(
                modifier = Modifier.padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    Icon(Icons.Rounded.ListAlt, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(19.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text("Poglavlja zapisnika", fontWeight = FontWeight.Black)
                        Text(
                            if (menuEntries.isEmpty()) "Ručna polja" else "${menuEntries.size} poglavlja",
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                }
                if (menuEntries.isNotEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        menuEntries.forEach { entry ->
                            DocumentationSprTemplateSectionPanel(
                                entry = entry,
                                values = values,
                                standardControls = standardControls,
                                tableCount = tableCount,
                                rowCount = rowCount,
                                attachmentFiles = attachmentFiles,
                                attachmentLoading = attachmentLoading,
                                attachmentMessage = attachmentMessage,
                                sprVoicePreviewRows = sprVoicePreviewRows,
                                sprVoicePreviewLoading = sprVoiceAiLoading,
                                sprVoicePreviewMessage = sprVoiceAiMessage,
                                enabled = enabled,
                                onOpenMeasurements = onOpenMeasurements,
                                onPickAttachments = onPickAttachments,
                                onOpenAttachment = onOpenAttachment,
                                onRemoveAttachment = onRemoveAttachment,
                                onFieldChange = onFieldChange,
                                onSprVoicePreview = onSprVoicePreview,
                            )
                        }
                    }
                } else if (fallbackFieldTemplates.isNotEmpty()) {
                    fallbackFieldTemplates.forEach { template ->
                        TemplateFieldGroup(
                            template = template,
                            values = values,
                            enabled = enabled,
                            onChange = { field, value -> onFieldChange(template, field, value, false) },
                        )
                    }
                } else {
                    Text(
                        "Nema polja za mobilni unos u ovom predlošku.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.64f),
                    )
                }
            }
        }
    }
}

