@Composable
private fun DocumentationSprTemplateSectionPanel(
    entry: DocumentationSprMenuEntry,
    values: Map<String, String>,
    standardControls: DocumentationTemplateStandardControls,
    tableCount: Int,
    rowCount: Int,
    attachmentFiles: List<WorkOrderDocumentationAiFile>,
    attachmentLoading: Boolean,
    attachmentMessage: String,
    sprVoicePreviewRows: List<SprVoiceAiRow>,
    sprVoicePreviewLoading: Boolean,
    sprVoicePreviewMessage: String,
    enabled: Boolean,
    onOpenMeasurements: () -> Unit,
    onPickAttachments: () -> Unit,
    onOpenAttachment: (WorkOrderDocumentationAiFile) -> Unit,
    onRemoveAttachment: (String) -> Unit,
    onFieldChange: (WorkOrderDocumentationTemplate, WorkOrderDocumentationField, String, Boolean) -> Unit,
    onSprVoicePreview: (WorkOrderDocumentationTemplate, WorkOrderDocumentationField, String) -> Unit,
) {
    var expanded by rememberSaveable(entry.key) { mutableStateOf(false) }
    val isBasicSection = remember(entry.section) { isBasicTemplateSection(entry.section) }
    val isAttachmentSection = remember(entry.section) { isDocumentationAttachmentTemplateSection(entry.section) }
    val isResultsTextSection = remember(entry.section) { isDocumentationResultsTextSection(entry.section) }
    val isAssessmentSection = remember(entry.section) { isDocumentationAssessmentSection(entry.section) }
    val hideDefects = remember(entry.template, entry.section.blocks, values) {
        shouldHideDocumentationDefects(entry.template, entry.section.blocks, values)
    }
    val visibleBlocks = remember(entry.section, isResultsTextSection, isAssessmentSection) {
        entry.section.blocks.filterNot { block ->
            isDocumentationAttachmentUploadBlock(block) ||
                block.type.equals("equipment_list", ignoreCase = true) ||
                (block.type.equals("measurement_table", ignoreCase = true) && (isResultsTextSection || isAssessmentSection))
        }
    }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.38f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.1f)),
    ) {
        Column(
            modifier = Modifier.padding(11.dp),
            verticalArrangement = Arrangement.spacedBy(9.dp),
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(14.dp))
                    .clickable(enabled = enabled) {
                        expanded = !expanded
                    },
                horizontalArrangement = Arrangement.spacedBy(9.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(shape = RoundedCornerShape(13.dp), color = MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)) {
                    Icon(
                        templateBlockIcon(entry.section.header?.type ?: entry.section.blocks.firstOrNull()?.type.orEmpty()),
                        contentDescription = null,
                        modifier = Modifier
                            .size(34.dp)
                            .padding(8.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text("${entry.index + 1}. ${entry.section.title}", fontWeight = FontWeight.Black, maxLines = 2, overflow = TextOverflow.Ellipsis)
                    Text(
                        listOf(
                            if (isAttachmentSection) {
                                "${attachmentFiles.size} prilog(a)"
                            } else if (isResultsTextSection) {
                                "Tekstualni opis"
                            } else if (isAssessmentSection) {
                                "Popis ocjena"
                            } else if (isBasicSection) {
                                "Osnovni podaci"
                            } else if (visibleBlocks.isNotEmpty()) {
                                "${visibleBlocks.size} polja"
                            } else {
                                "Nema polja"
                            },
                        ).filter { it.isNotBlank() }.joinToString(" · "),
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Icon(
                    if (expanded) Icons.Rounded.ExpandLess else Icons.Rounded.ExpandMore,
                    contentDescription = if (expanded) "Sakrij poglavlje" else "Prikaži poglavlje",
                    tint = MaterialTheme.colorScheme.primary,
                )
            }
            AnimatedVisibility(visible = expanded) {
                Column(verticalArrangement = Arrangement.spacedBy(9.dp)) {
                    entry.section.header?.summary?.takeIf { it.isNotBlank() }?.let { summary ->
                        Text(
                            summary,
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                        )
                    }
                    if (entry.section.blocks.isEmpty()) {
                        Text(
                            "Nema dodatnih polja u ovom poglavlju.",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        )
                    }
                    if (isAttachmentSection) {
                        DocumentationSprAttachmentsCard(
                            files = attachmentFiles,
                            loading = attachmentLoading,
                            message = attachmentMessage,
                            enabled = enabled,
                            onPickFiles = onPickAttachments,
                            onOpen = onOpenAttachment,
                            onRemove = onRemoveAttachment,
                        )
                    }
                    if ((isResultsTextSection || isAssessmentSection) && visibleBlocks.isEmpty()) {
                        Text(
                            if (isResultsTextSection) {
                                "Ovdje ide tekstualni opis rezultata. Gridline tablice su odvojene u svojim ispitnim listovima."
                            } else {
                                "Ovdje ide popis ocjena ispitnih listova. Gridline tablice se uređuju u odvojenim ispitnim listovima."
                            },
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                        )
                    }
                    if (isBasicSection) {
                        TemplateBasicControls(standardControls)
                    }
                    visibleBlocks.forEach { block ->
                        if (isAttachmentSection || (isBasicSection && isBasicStandardTemplateBlock(block))) {
                            return@forEach
                        }
                        val editableField = findTemplateFieldForBlock(entry.template, block)
                        if (editableField != null && hideDefects && isDocumentationDefectsTemplateField(editableField, block)) {
                            return@forEach
                        }
                        when (block.type.lowercase(Locale.getDefault())) {
                            "equipment_list" -> Unit
                            "legal_list" -> TemplateLegalControls(standardControls)
                            "measurement_table" -> {
                                val blockTables = getMeasurementTablesForBlock(entry.template, block)
                                val blockRowCount = blockTables.sumOf { table ->
                                    val sheet = standardControls.measurementSheets[measurementSheetStateKey(entry.template, table)] ?: table.sheet
                                    sheet.rows.size
                                }
                                DocumentationSprGridlineInlineCard(
                                    title = blockTables.firstOrNull()?.label ?: block.label,
                                    summary = blockTables.firstOrNull()?.summary ?: block.summary,
                                    tableCount = blockTables.size,
                                    rowCount = blockRowCount,
                                    enabled = enabled,
                                    onOpenMeasurements = onOpenMeasurements,
                                )
                            }
                            else -> {
                                TemplateBlockDetailRow(
                                    template = entry.template,
                                    block = block,
                                    editableField = editableField,
                                    value = editableField?.let { field -> values[templateFieldStateKey(entry.template, field)] }.orEmpty(),
                                    standardValues = standardControls.standardValues,
                                    standardControls = standardControls,
                                    enabled = enabled,
                                    onPickAttachments = onPickAttachments,
                                    onChange = { field, value -> onFieldChange(entry.template, field, value, false) },
                                    onSprVoiceApply = { field, value, replaceExisting ->
                                        onFieldChange(entry.template, field, value, replaceExisting)
                                    },
                                    onSprVoicePreview = { field, transcript ->
                                        onSprVoicePreview(entry.template, field, transcript)
                                    },
                                    sprVoicePreviewRows = sprVoicePreviewRows,
                                    sprVoicePreviewLoading = sprVoicePreviewLoading,
                                    sprVoicePreviewMessage = sprVoicePreviewMessage,
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentationSprGridlineInlineCard(
    title: String = "Gridline tablica",
    summary: String = "",
    tableCount: Int,
    rowCount: Int,
    enabled: Boolean,
    onOpenMeasurements: () -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.9f),
    ) {
        Row(
            modifier = Modifier.padding(10.dp),
            horizontalArrangement = Arrangement.spacedBy(9.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(Icons.Rounded.ListAlt, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
            Column(modifier = Modifier.weight(1f)) {
                Text(title.ifBlank { "Gridline tablica" }, fontWeight = FontWeight.Black, maxLines = 2, overflow = TextOverflow.Ellipsis)
                Text(
                    when {
                        tableCount == 0 -> "Nema povezane tablice."
                        summary.isNotBlank() -> "$summary · $rowCount redaka"
                        else -> "$tableCount tablica · $rowCount redaka"
                    },
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            OutlinedButton(
                onClick = onOpenMeasurements,
                enabled = enabled && tableCount > 0,
                shape = RoundedCornerShape(13.dp),
            ) {
                Text("Otvori", fontWeight = FontWeight.Bold)
            }
        }
    }
}

