@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun DocumentationSprAttachmentsCard(
    files: List<WorkOrderDocumentationAiFile>,
    loading: Boolean,
    message: String,
    enabled: Boolean,
    onPickFiles: () -> Unit,
    onOpen: (WorkOrderDocumentationAiFile) -> Unit,
    onRemove: (String) -> Unit,
) {
    val canAdd = enabled && !loading && files.size < WORK_ORDER_DOCUMENTATION_ATTACHMENT_MAX_INLINE_FILES
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.94f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Box(
                modifier = Modifier.fillMaxWidth(),
                contentAlignment = Alignment.Center,
            ) {
                DocumentationSprAttachmentPlusButton(
                    enabled = canAdd,
                    compact = false,
                    onPickFiles = onPickFiles,
                )
                if (loading) {
                    CircularProgressIndicator(
                        modifier = Modifier
                            .align(Alignment.CenterEnd)
                            .size(18.dp),
                        strokeWidth = 2.dp,
                    )
                }
            }
            if (loading) {
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
            }
            if (files.isNotEmpty()) {
                Column(verticalArrangement = Arrangement.spacedBy(7.dp)) {
                    files.forEach { file ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(14.dp))
                                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.38f))
                                .padding(horizontal = 10.dp, vertical = 8.dp),
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Icon(
                                when {
                                    file.type.equals("application/pdf", ignoreCase = true) -> Icons.Rounded.PictureAsPdf
                                    file.type.startsWith("image/", ignoreCase = true) -> Icons.Rounded.Image
                                    else -> Icons.Rounded.InsertDriveFile
                                },
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(18.dp),
                            )
                            Column(modifier = Modifier.weight(1f)) {
                                Text(file.name, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                Text(
                                    listOf(file.type, formatFileSizeLabel(file.size)).filter { it.isNotBlank() }.joinToString(" · "),
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                                )
                            }
                            IconButton(onClick = { onOpen(file) }, enabled = enabled && !loading) {
                                Icon(Icons.Rounded.Visibility, contentDescription = "Otvori prilog", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                            }
                            IconButton(onClick = { onRemove(file.id) }, enabled = enabled && !loading) {
                                Icon(Icons.Rounded.Delete, contentDescription = "Ukloni prilog", tint = Color(0xFFDC2626), modifier = Modifier.size(18.dp))
                            }
                        }
                    }
                }
            }
            if (message.isNotBlank()) {
                Text(
                    message,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.SemiBold,
                )
            }
        }
    }
}

