private fun documentationSprMobileSourceLabel(templates: List<WorkOrderDocumentationTemplate>): String {
    val previous = templates.firstOrNull { template ->
        template.dataSourceType.trim().equals("previous_inspection", ignoreCase = true) &&
            template.previousDataSourceMatchesService()
    }
    if (previous != null) {
        return listOf("Prethodni zapisnik", formatDatePickerLabel(previous.dataSourceDate))
            .filter { it.isNotBlank() }
            .joinToString(" - ")
    }
    return "Template"
}

private fun documentationSprTemplateLabel(templates: List<WorkOrderDocumentationTemplate>): String =
    templates.firstOrNull { it.serviceCode.isNotBlank() }?.serviceCode
        ?: templates.firstOrNull { it.serviceName.isNotBlank() }?.serviceName
        ?: templates.firstOrNull { it.documentType.isNotBlank() }?.documentType
        ?: templates.firstOrNull { it.documentName.isNotBlank() }?.documentName
        ?: templates.firstOrNull()?.title
        ?: "Zapisnik"

private fun documentationTemplateDataSourceTitle(template: WorkOrderDocumentationTemplate): String {
    val type = template.dataSourceType.trim().lowercase(Locale.getDefault())
    return if (type == "previous_inspection" && template.previousDataSourceMatchesService()) {
        val dateLabel = formatDatePickerLabel(template.dataSourceDate)
        listOf("Vrijednosti iz prethodnog zapisnika", dateLabel).filter { it.isNotBlank() }.joinToString(" - ")
    } else if (type == "previous_inspection" || type == "template" || type.isBlank()) {
        "Vrijednosti iz templatea"
    } else {
        "Vrijednosti iz ${type.replace('_', ' ')}"
    }
}

private fun documentationTemplateDataSourceDetails(template: WorkOrderDocumentationTemplate): String {
    val type = template.dataSourceType.trim().lowercase(Locale.getDefault())
    if (type != "previous_inspection" || !template.previousDataSourceMatchesService()) {
        return ""
    }
    return listOf(
        template.dataSourceWorkOrderNumber.takeIf { it.isNotBlank() }?.let { "RN $it" },
    ).filterNotNull().joinToString(" - ")
}

private data class DocumentationTemplateStandardControls(
    val documentNumber: String,
    val serviceName: String,
    val companyName: String,
    val companyHeadquarters: String,
    val companyOib: String,
    val objectName: String,
    val validUntil: String,
    val inspectionDate: String,
    val onInspectionDateChange: (String) -> Unit,
    val issuedDate: String,
    val onIssuedDateChange: (String) -> Unit,
    val inspectionType: String,
    val inspectionOptions: List<Pair<String, String>>,
    val onInspectionTypeChange: (String) -> Unit,
    val testingLocation: String,
    val onTestingLocationChange: (String) -> Unit,
    val measurementEquipmentGroup: String,
