            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                Text("Osnovno", fontWeight = FontWeight.Black)
                Text(
                    listOf(
                        formatDatePickerLabel(inspectionDate),
                        inspectionType,
                        testingLocation,
                    ).filter { it.isNotBlank() }.joinToString(" · ").ifBlank { "Datumi, ispitivači, oprema i uvjeti" },
                    style = MaterialTheme.typography.labelMedium,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    listOf(
                        "Broj: ${documentNumber.ifBlank { "auto" }}",
                        formatDatePickerLabel(issuedDate).takeIf { it.isNotBlank() }?.let { "Izdano $it" },
                        serviceName.takeIf { it.isNotBlank() },
                        measurementEquipmentGroup.takeIf { it.isNotBlank() }?.let { "Oprema $it" },
                        listOf(outsideTemperature, relativeHumidity).filter { it.isNotBlank() }.joinToString(" / ").takeIf { it.isNotBlank() },
                    ).filterNotNull().joinToString(" · "),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            TextButton(onClick = onOpen) {
                Text("Uredi", fontWeight = FontWeight.Bold)
            }
        }
    }
}

@Composable
private fun DocumentationExecutorsEditor(
    executorOptions: List<Pair<String, String>>,
    selectedExecutors: List<String>,
    enabled: Boolean,
    onChange: (List<String>) -> Unit,
) {
    var query by remember { mutableStateOf("") }
    val selectedEntries = remember(executorOptions, selectedExecutors) {
        val labelByValue = executorOptions.associate { it.first to it.second }
        selectedExecutors
            .map { value -> value.trim() to (labelByValue[value] ?: value).trim() }
            .filter { it.first.isNotBlank() && it.second.isNotBlank() }
            .distinctBy { it.first.lowercase(Locale.getDefault()) }
    }
    val filteredOptions = remember(executorOptions, query) {
        val normalizedQuery = query.trim().lowercase(Locale.getDefault())
        executorOptions
            .filter { option ->
                normalizedQuery.isBlank() ||
                    option.second.lowercase(Locale.getDefault()).contains(normalizedQuery)
            }
            .take(42)
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(20.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.36f),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.12f)),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Icon(Icons.Rounded.Person, contentDescription = null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text("Izvršitelji RN-a", fontWeight = FontWeight.Black)
                    Text(
                        if (selectedEntries.isEmpty()) "Nije dodijeljeno" else "${selectedEntries.size} odabrano",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
                if (selectedEntries.isNotEmpty()) {
                    TextButton(onClick = { onChange(emptyList()) }, enabled = enabled) {
                        Text("Očisti", fontWeight = FontWeight.Bold)
                    }
                }
            }

            if (selectedEntries.isEmpty()) {
                Surface(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surface.copy(alpha = 0.72f),
                ) {
                    Text(
                        "Nema odabranih izvršitelja.",
                        modifier = Modifier.padding(12.dp),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                }
            } else {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    selectedEntries.forEach { (value, label) ->
                        Surface(
                            modifier = Modifier
                                .widthIn(max = 280.dp)
                                .clickable(enabled = enabled) {
                                    onChange(selectedExecutors.filterNot { it.trim() == value })
                                },
                            shape = RoundedCornerShape(999.dp),
                            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)),
                        ) {
                            Row(
                                modifier = Modifier.padding(start = 10.dp, end = 8.dp, top = 7.dp, bottom = 7.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                            ) {
                                Text(
                                    label,
                                    style = MaterialTheme.typography.labelMedium,
                                    fontWeight = FontWeight.Bold,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                                Icon(
                                    Icons.Rounded.Close,
                                    contentDescription = "Makni izvršitelja",
                                    modifier = Modifier.size(15.dp),
                                    tint = MaterialTheme.colorScheme.primary,
                                )
                            }
                        }
                    }
                }
            }

            OutlinedTextField(
                value = query,
                onValueChange = { query = it },
                enabled = enabled,
                singleLine = true,
                label = { Text("Dodaj ili traži izvršitelja") },
                leadingIcon = { Icon(Icons.Rounded.Search, contentDescription = null) },
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
            )

            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 190.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                WorkOrderMultiSelectChips(
                    options = filteredOptions,
                    selected = selectedExecutors,
                    enabled = enabled,
                    emptyText = "Nema dostupnih korisnika za odabir izvršitelja.",
                    onToggle = { value -> onChange(selectedExecutors.toggleValue(value)) },
                )
                if (executorOptions.size > filteredOptions.size) {
                    Text(
                        "Prikazano ${filteredOptions.size} od ${executorOptions.size}.",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    )
                }
            }

            Text(
                "Sprema se odmah nakon promjene.",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.Bold,
            )
        }
    }
}

private data class DocumentationTrainingModeOption(
    val value: String,
    val label: String,
    val helper: String,
    val actionLabel: String,
    val icon: ImageVector,
    val sendEmails: Boolean,
)

private val documentationTrainingModeOptions = listOf(
    DocumentationTrainingModeOption(
        value = "online_teams",
        label = "Online - Teams",
        helper = "Remote classroom session. No automatic test link is sent.",
        actionLabel = "Prepare Online - Teams",
        icon = Icons.Rounded.Groups,
        sendEmails = false,
    ),
    DocumentationTrainingModeOption(
        value = "online_test",
        label = "Online - Test",
        helper = "Sends test links by email and tracks remote completion.",
        actionLabel = "Send Online - Test",
        icon = Icons.Rounded.Mail,
        sendEmails = true,
    ),
    DocumentationTrainingModeOption(
        value = "live_paper",
        label = "Live - Paper",
        helper = "In-person training with paper exam evidence.",
        actionLabel = "Prepare Live - Paper",
        icon = Icons.Rounded.Description,
        sendEmails = false,
    ),
    DocumentationTrainingModeOption(
        value = "live_application",
        label = "Live - Application",
        helper = "In-person training with the test completed in the app or by link.",
        actionLabel = "Prepare Live - Application",
        icon = Icons.Rounded.Fingerprint,
        sendEmails = true,
    ),
)

private fun normalizeDocumentationTrainingMode(value: String): String {
    val normalized = value.trim().lowercase(Locale.getDefault())
        .replace("-", "_")
        .replace(Regex("\\s+"), "_")
    val canonical = when (normalized) {
        "online", "online_test", "onlinetest", "test" -> "online_test"
        "online_teams", "onlineteams", "teams" -> "online_teams"
        "live", "live_paper", "livepaper", "paper" -> "live_paper"
        "live_app", "live_application", "liveapp", "liveapplication", "application" -> "live_application"
        else -> normalized
    }
    return documentationTrainingModeOptions.firstOrNull { it.value == canonical }?.value ?: "online_test"
}

private fun WorkOrderTrainingService.trainingSelectionKey(): String =
    serviceKey.ifBlank { serviceId.ifBlank { id.ifBlank { serviceCode } } }.trim()

private fun WorkOrderTrainingService.trainingShortLabel(): String =
    serviceCode.ifBlank { shortLabel.ifBlank { label.ifBlank { serviceName }.take(4).uppercase(Locale.getDefault()) } }

private fun WorkOrderTrainingService.trainingTitle(): String =
    label.ifBlank { serviceName.ifBlank { serviceCode.ifBlank { "Osposobljavanje" } } }

private fun WorkOrderTrainingAssignment.trainingStatusKey(): String =
    when (passed) {
        true -> "passed"
        false -> "failed"
        null -> status.trim().lowercase(Locale.getDefault()).ifBlank {
            learningStatus.trim().lowercase(Locale.getDefault()).ifBlank {
                when {
                    existingValidUntil.isNotBlank() || existingPassedOn.isNotBlank() -> "valid"
                    linkedLearningTestIds.isNotEmpty() -> "pending"
                    else -> "missing"
                }
            }
        }
    }

private fun trainingAssignmentNeedsAction(assignment: WorkOrderTrainingAssignment?): Boolean {
    if (assignment?.passed == false) return true
    val status = assignment?.trainingStatusKey().orEmpty()
    return status !in setOf("valid", "done", "completed", "passed", "not_required")
}

private fun WorkOrderTrainingPerson.assignmentFor(service: WorkOrderTrainingService): WorkOrderTrainingAssignment? {
    val serviceKey = service.trainingSelectionKey()
    val serviceId = service.serviceId.trim()
    val serviceCode = service.serviceCode.trim()
    return assignments.firstOrNull { assignment ->
        listOf(assignment.serviceKey, assignment.serviceId, assignment.serviceCode)
            .map { it.trim() }
            .any { value ->
                value.isNotBlank() && (
                    value.equals(serviceKey, ignoreCase = true) ||
                        value.equals(serviceId, ignoreCase = true) ||
                        value.equals(serviceCode, ignoreCase = true)
                    )
            }
    }
}

private fun WorkOrderTrainingPerson.needsTrainingAction(services: List<WorkOrderTrainingService>): Boolean =
    services.any { service -> trainingAssignmentNeedsAction(assignmentFor(service)) }

private enum class DocumentationTrainingPeopleFilter {
    NeedsAction,
    Pending,
    Passed,
    Selected,
    All,
}

private fun trainingAssignmentCompleted(assignment: WorkOrderTrainingAssignment?): Boolean =
    assignment != null && !trainingAssignmentNeedsAction(assignment)

private fun trainingAssignmentPending(assignment: WorkOrderTrainingAssignment?): Boolean {
    val status = assignment?.trainingStatusKey().orEmpty()
    return status in setOf("pending", "assigned", "in_progress") ||
        (
            assignment?.linkedLearningTestIds?.isNotEmpty() == true &&
                !trainingAssignmentCompleted(assignment)
            )
}

private fun WorkOrderTrainingPerson.hasPendingTraining(services: List<WorkOrderTrainingService>): Boolean =
    services.any { service -> trainingAssignmentPending(assignmentFor(service)) }

private fun WorkOrderTrainingPerson.hasPassedTraining(services: List<WorkOrderTrainingService>): Boolean =
    services.isNotEmpty() && services.all { service -> trainingAssignmentCompleted(assignmentFor(service)) }

@Composable
private fun DocumentationTrainingLaunchSection(
    context: WorkOrderTrainingContext,
    mode: String,
    selectedPersonIds: Set<String>,
    selectedServiceKeys: Set<String>,
    onlyNeedsAction: Boolean,
    enabled: Boolean,
    onModeChange: (String) -> Unit,
    onSelectedPersonIdsChange: (Set<String>) -> Unit,
    onSelectedServiceKeysChange: (Set<String>) -> Unit,
    onOnlyNeedsActionChange: (Boolean) -> Unit,
    onGenerateRecord: () -> Unit,
    onDownloadImportTemplate: () -> Unit,
    onUploadImport: () -> Unit,
    onAddManualPerson: (WorkOrderTrainingManualPersonDraft) -> Unit,
    onConfirm: () -> Unit,
) {
    if (!context.enabled) {
        return
    }
    var manualPersonDialogOpen by remember { mutableStateOf(false) }
    val normalizedMode = normalizeDocumentationTrainingMode(mode)
    val activeMode = documentationTrainingModeOptions.firstOrNull { it.value == normalizedMode }
        ?: documentationTrainingModeOptions.first()
    val selectedServices = remember(context.services, selectedServiceKeys) {
        context.services.filter { service -> selectedServiceKeys.contains(service.trainingSelectionKey()) }
            .ifEmpty { context.services }
    }
    var peopleFilter by remember(context.people, selectedServices) {
        mutableStateOf(if (onlyNeedsAction) DocumentationTrainingPeopleFilter.NeedsAction else DocumentationTrainingPeopleFilter.All)
    }
    fun updatePeopleFilter(filter: DocumentationTrainingPeopleFilter) {
        peopleFilter = filter
        onOnlyNeedsActionChange(filter == DocumentationTrainingPeopleFilter.NeedsAction)
    }
    val visiblePeople = remember(context.people, selectedServices, selectedPersonIds, peopleFilter) {
        when (peopleFilter) {
            DocumentationTrainingPeopleFilter.NeedsAction ->
                context.people.filter { person -> person.recommended || person.needsTrainingAction(selectedServices) }
            DocumentationTrainingPeopleFilter.Pending ->
                context.people.filter { person -> person.hasPendingTraining(selectedServices) }
            DocumentationTrainingPeopleFilter.Passed ->
                context.people.filter { person -> person.hasPassedTraining(selectedServices) }
            DocumentationTrainingPeopleFilter.Selected ->
                context.people.filter { person -> selectedPersonIds.contains(person.id) }
            DocumentationTrainingPeopleFilter.All -> context.people
        }
    }
    val completedCount = remember(context.people, selectedServices) {
        context.people.sumOf { person -> selectedServices.count { service -> !trainingAssignmentNeedsAction(person.assignmentFor(service)) } }
    }
    val needsActionCount = remember(context.people, selectedServices) {
        context.people.sumOf { person -> selectedServices.count { service -> trainingAssignmentNeedsAction(person.assignmentFor(service)) } }
    }
    val peopleNeedingActionCount = remember(context.people, selectedServices) {
        context.people.count { person -> person.recommended || person.needsTrainingAction(selectedServices) }
    }
    val peoplePendingCount = remember(context.people, selectedServices) {
        context.people.count { person -> person.hasPendingTraining(selectedServices) }
    }
    val peoplePassedCount = remember(context.people, selectedServices) {
        context.people.count { person -> person.hasPassedTraining(selectedServices) }
    }

    if (manualPersonDialogOpen) {
        DocumentationTrainingManualPersonDialog(
            companyName = context.companyName,
            locationName = context.locationName,
            enabled = enabled,
            onDismiss = { manualPersonDialogOpen = false },
            onConfirm = { draft ->
                manualPersonDialogOpen = false
                onAddManualPerson(draft)
            },
        )
    }

    WizardSection(title = "Osposobljavanje", icon = Icons.Rounded.Badge) {
        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(24.dp),
            color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.48f),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)),
        ) {
            Column(
                modifier = Modifier.padding(14.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Surface(shape = CircleShape, color = MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)) {
                        Icon(
                            activeMode.icon,
                            contentDescription = null,
                            modifier = Modifier.padding(10.dp).size(22.dp),
                            tint = MaterialTheme.colorScheme.primary,
                        )
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text("Pokretanje osposobljavanja", fontWeight = FontWeight.Black)
                        Text(
                            "${context.peopleCount} osoba · ${context.services.size} usluga",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                        )
                    }
                }
            }
        }

        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Način provedbe", fontWeight = FontWeight.Black)
            documentationTrainingModeOptions.forEach { option ->
                DocumentationTrainingModeCard(
                    option = option,
                    selected = option.value == normalizedMode,
                    enabled = enabled,
                    onClick = { onModeChange(option.value) },
                )
            }
        }

        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(18.dp),
            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.44f),
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.12f)),
        ) {
            Column(
                modifier = Modifier.padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text("Usluge / ispiti", fontWeight = FontWeight.Black)
                if (context.services.isEmpty()) {
                    Text(
                        "RN nema povezanu uslugu osposobljavanja.",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    )
                } else {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        context.services.forEach { service ->
                            val key = service.trainingSelectionKey()
                            FilterChip(
                                selected = selectedServiceKeys.contains(key),
                                onClick = {
                                    onSelectedServiceKeysChange(
                                        if (selectedServiceKeys.contains(key)) {
                                            selectedServiceKeys - key
                                        } else {
                                            selectedServiceKeys + key
                                        },
                                    )
                                },
                                enabled = enabled,
                                label = {
                                    Text(
                                        service.trainingTitle(),
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                },
                                leadingIcon = {
                                    Text(service.trainingShortLabel(), fontWeight = FontWeight.Black)
                                },
                            )
                        }
                    }
                }
            }
        }

        Surface(
            modifier = Modifier.fillMaxWidth(),
            shape = RoundedCornerShape(18.dp),
            color = MaterialTheme.colorScheme.surface,
            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.14f)),
        ) {
            Column(
                modifier = Modifier.padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(6.dp),
            ) {
                Row(horizontalArrangement = Arrangement.SpaceBetween, modifier = Modifier.fillMaxWidth()) {
                    Text("Masovni import ljudi", fontWeight = FontWeight.Black)
                    Icon(Icons.Rounded.InsertDriveFile, contentDescription = null, tint = MaterialTheme.colorScheme.primary)
                }
                Text(
                    if (context.importProfile.enabled) {
                        "${context.importProfile.profileName} · ${context.importProfile.sheetName} · ${context.importProfile.columnCount} polja"
                    } else {
                        "Predložak se uređuje u webu po tvrtki. Na mobitelu koristi već uvezene osobe."
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                )
                if (context.importProfile.columnsLabel.isNotBlank()) {
                    Text(
                        context.importProfile.columnsLabel,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    OutlinedButton(
                        modifier = Modifier.weight(1f),
                        onClick = onDownloadImportTemplate,
                        enabled = enabled,
                        shape = RoundedCornerShape(14.dp),
                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 10.dp),
                    ) {
                        Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(Modifier.width(4.dp))
                        Text("Predložak", maxLines = 1, overflow = TextOverflow.Ellipsis)
                    }
                    Button(
                        modifier = Modifier.weight(1f),
                        onClick = onUploadImport,
                        enabled = enabled,
                        shape = RoundedCornerShape(14.dp),
                        contentPadding = PaddingValues(horizontal = 8.dp, vertical = 10.dp),
                    ) {
                        Icon(Icons.Rounded.InsertDriveFile, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(Modifier.width(4.dp))
                        Text("Excel", maxLines = 1)
                    }
                    OutlinedButton(
                        modifier = Modifier.width(54.dp),
                        onClick = { manualPersonDialogOpen = true },
                        enabled = enabled,
                        shape = RoundedCornerShape(14.dp),
                        contentPadding = PaddingValues(horizontal = 0.dp, vertical = 10.dp),
                    ) {
                        Icon(Icons.Rounded.Add, contentDescription = "Dodaj osobu", modifier = Modifier.size(20.dp))
                    }
                }
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column {
                Text("Radnici", fontWeight = FontWeight.Black)
                Text(
                    "${visiblePeople.size} prikazano · $completedCount položeno · $needsActionCount treba",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                )
            }
            TextButton(
                onClick = { onSelectedPersonIdsChange(visiblePeople.map { it.id }.filter { it.isNotBlank() }.toSet()) },
                enabled = enabled && visiblePeople.isNotEmpty(),
            ) {
                Text("Odaberi")
            }
        }

        FlowRow(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            DocumentationTrainingPeopleFilterChip(
                label = "Treba",
                count = peopleNeedingActionCount,
                icon = Icons.Rounded.ErrorOutline,
                selected = peopleFilter == DocumentationTrainingPeopleFilter.NeedsAction,
                enabled = enabled,
                onClick = { updatePeopleFilter(DocumentationTrainingPeopleFilter.NeedsAction) },
            )
            DocumentationTrainingPeopleFilterChip(
                label = "Čeka",
                count = peoplePendingCount,
                icon = Icons.Rounded.Mail,
                selected = peopleFilter == DocumentationTrainingPeopleFilter.Pending,
                enabled = enabled,
                onClick = { updatePeopleFilter(DocumentationTrainingPeopleFilter.Pending) },
            )
            DocumentationTrainingPeopleFilterChip(
                label = "Položeno",
                count = peoplePassedCount,
                icon = Icons.Rounded.CheckCircle,
                selected = peopleFilter == DocumentationTrainingPeopleFilter.Passed,
                enabled = enabled,
                onClick = { updatePeopleFilter(DocumentationTrainingPeopleFilter.Passed) },
            )
            DocumentationTrainingPeopleFilterChip(
                label = "Odabrani",
                count = selectedPersonIds.size,
                icon = Icons.Rounded.Person,
                selected = peopleFilter == DocumentationTrainingPeopleFilter.Selected,
                enabled = enabled,
                onClick = { updatePeopleFilter(DocumentationTrainingPeopleFilter.Selected) },
            )
            DocumentationTrainingPeopleFilterChip(
                label = "Svi",
                count = context.peopleCount,
                icon = Icons.Rounded.Groups,
                selected = peopleFilter == DocumentationTrainingPeopleFilter.All,
                enabled = enabled,
                onClick = { updatePeopleFilter(DocumentationTrainingPeopleFilter.All) },
            )
        }

        if (visiblePeople.isEmpty()) {
            Text(
                if (context.people.isEmpty()) {
                    "Nema osoba za ovu tvrtku. Uvezi Excel ili dodaj osobu ručno preko plusa."
                } else {
                    "Nema osoba koje trebaju rješavati odabrane usluge. Prikaži sve za ručni odabir."
                },
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
            )
        } else {
            visiblePeople.take(80).forEach { person ->
                DocumentationTrainingPersonRow(
                    person = person,
                    services = selectedServices,
                    checked = selectedPersonIds.contains(person.id),
                    enabled = enabled,
                    onCheckedChange = { checked ->
                        onSelectedPersonIdsChange(
                            if (checked) selectedPersonIds + person.id else selectedPersonIds - person.id,
                        )
                    },
                )
            }
            if (visiblePeople.size > 80) {
                Text(
                    "Prikazano prvih 80 osoba. Za veći popis koristi web.",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.56f),
                )
            }
        }

        Button(
            modifier = Modifier.fillMaxWidth(),
            onClick = onConfirm,
            enabled = enabled && selectedPersonIds.isNotEmpty() && selectedServiceKeys.isNotEmpty(),
            shape = RoundedCornerShape(18.dp),
        ) {
            Text(activeMode.actionLabel, fontWeight = FontWeight.Black)
        }

        OutlinedButton(
            modifier = Modifier.fillMaxWidth(),
            onClick = onGenerateRecord,
            enabled = enabled && completedCount > 0,
            shape = RoundedCornerShape(18.dp),
        ) {
            Icon(Icons.Rounded.Description, contentDescription = null, modifier = Modifier.size(18.dp))
            Spacer(Modifier.width(8.dp))
            Text(
                if (completedCount > 0) "Generiraj zapisnik ($completedCount)" else "Zapisnik nakon polaganja",
                fontWeight = FontWeight.Black,
            )
        }
    }
}

@Composable
private fun DocumentationTrainingManualPersonDialog(
    companyName: String,
    locationName: String,
    enabled: Boolean,
    onDismiss: () -> Unit,
    onConfirm: (WorkOrderTrainingManualPersonDraft) -> Unit,
) {
    var fullName by remember { mutableStateOf("") }
    var oib by remember { mutableStateOf("") }
    var jobTitle by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var phone by remember { mutableStateOf("") }
    val cleanOib = oib.filter { it.isDigit() }
    val canSubmit = fullName.trim().isNotBlank() && cleanOib.length == 11

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text("Dodaj osobu", fontWeight = FontWeight.Black)
                Text(
                    listOf(companyName, locationName).filter { it.isNotBlank() }.joinToString(" · "),
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                OutlinedTextField(
                    value = fullName,
                    onValueChange = { fullName = it },
                    label = { Text("Ime i prezime *") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    enabled = enabled,
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Next),
                )
                OutlinedTextField(
                    value = oib,
                    onValueChange = { oib = it.filter { char -> char.isDigit() }.take(11) },
                    label = { Text("OIB *") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    enabled = enabled,
                    isError = oib.isNotBlank() && cleanOib.length != 11,
                    supportingText = {
                        Text(if (cleanOib.length == 11) "Provjera postojeće osobe ide po OIB-u." else "Obavezno 11 znamenki.")
                    },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number, imeAction = ImeAction.Next),
                )
                OutlinedTextField(
                    value = jobTitle,
                    onValueChange = { jobTitle = it },
                    label = { Text("Radno mjesto") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    enabled = enabled,
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Next),
                )
                OutlinedTextField(
                    value = email,
                    onValueChange = { email = it },
                    label = { Text("Email") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    enabled = enabled,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email, imeAction = ImeAction.Next),
                )
                OutlinedTextField(
                    value = phone,
                    onValueChange = { phone = it },
                    label = { Text("Telefon") },
                    modifier = Modifier.fillMaxWidth(),
                    singleLine = true,
                    enabled = enabled,
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone, imeAction = ImeAction.Done),
                )
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    onConfirm(
                        WorkOrderTrainingManualPersonDraft(
                            fullName = fullName.trim(),
                            oib = oib.trim(),
                            email = email.trim(),
                            phone = phone.trim(),
                            jobTitle = jobTitle.trim(),
                        ),
                    )
                },
                enabled = enabled && canSubmit,
                shape = RoundedCornerShape(16.dp),
            ) {
                Text("Dodaj", fontWeight = FontWeight.Black)
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss, enabled = enabled) {
                Text("Odustani")
            }
        },
    )
}

