@Composable
private fun DocumentationTrainingPersonRow(
    person: WorkOrderTrainingPerson,
    services: List<WorkOrderTrainingService>,
    checked: Boolean,
    enabled: Boolean,
    onCheckedChange: (Boolean) -> Unit,
) {
    val needsAction = person.needsTrainingAction(services)
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(enabled = enabled) { onCheckedChange(!checked) },
        shape = RoundedCornerShape(20.dp),
        color = when {
            checked -> MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.42f)
            needsAction -> Color(0xFFFFFBEB)
            else -> MaterialTheme.colorScheme.surface
        },
        border = BorderStroke(
            1.dp,
            when {
                checked -> MaterialTheme.colorScheme.primary.copy(alpha = 0.32f)
                needsAction -> Color(0xFFF59E0B).copy(alpha = 0.24f)
                else -> MaterialTheme.colorScheme.outline.copy(alpha = 0.16f)
            },
        ),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Checkbox(
                    checked = checked,
                    onCheckedChange = if (enabled) onCheckedChange else null,
                )
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                    Text(person.fullName.ifBlank { "Osoba" }, fontWeight = FontWeight.Black)
                    Text(
                        listOf(
                            person.oib.takeIf { it.isNotBlank() }?.let { "OIB $it" },
                            person.jobTitle,
                            person.locationName,
                            person.email,
                        ).filterNotNull().joinToString(" · ").ifBlank { "Bez dodatnih podataka" },
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }

            if (services.isEmpty()) {
                Text(
                    "Nema odabrane usluge.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                )
            } else {
                Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    services.forEach { service ->
                        DocumentationTrainingAssignmentRow(service, person.assignmentFor(service))
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentationTrainingAssignmentRow(
    service: WorkOrderTrainingService,
    assignment: WorkOrderTrainingAssignment?,
) {
    val status = assignment?.trainingStatusKey().orEmpty()
    val label = when {
        assignment?.passed == true -> "Položeno"
        assignment?.passed == false -> "Nije položeno"
        else -> when (status) {
            "valid", "done", "completed", "passed" -> "Položeno"
            "failed", "not_passed" -> "Nije položeno"
            "expired" -> "Isteklo"
            "expiring" -> "Istječe"
            "pending", "assigned" -> "Dodijeljeno"
            "in_progress" -> "U tijeku"
            else -> "Nedostaje"
        }
    }
    val tint = when (status) {
        "valid", "done", "completed", "passed" -> Color(0xFF047857)
        "pending", "assigned", "in_progress" -> MaterialTheme.colorScheme.primary
        "expired", "expiring" -> Color(0xFFB45309)
        "failed", "not_passed" -> Color(0xFFB91C1C)
        else -> MaterialTheme.colorScheme.error
    }
    val passPercent = assignment?.passPercent ?: service.passPercent
    val scoreText = assignment?.scorePercent
        ?.takeIf { it.isNotBlank() }
        ?.let { "Rezultat $it% / prolaz $passPercent%" }
    val testTitles = assignment?.linkedLearningTestTitles
        ?.takeIf { it.isNotEmpty() }
        ?: service.linkedLearningTestTitles
    val testsText = when {
        testTitles.isNotEmpty() -> testTitles.joinToString(", ")
        (assignment?.linkedLearningTestCount ?: 0) > 0 -> "${assignment?.linkedLearningTestCount} test"
        service.linkedLearningTestIds.isNotEmpty() -> "${service.linkedLearningTestIds.size} test"
        else -> ""
    }
    val scheduleText = when {
        (assignment?.questionLimit ?: 0) > 0 && (assignment?.timePerQuestionSeconds ?: 0) > 0 ->
            "${assignment?.questionLimit} pitanja · ${assignment?.timePerQuestionSeconds}s/pitanje"
        passPercent > 0 && service.linkedLearningTestIds.isNotEmpty() -> "Prolaz $passPercent%"
        else -> ""
    }
    val metaText = listOf(
        scoreText,
        testsText.takeIf { it.isNotBlank() },
        scheduleText.takeIf { it.isNotBlank() },
        assignment?.existingPassedOn?.takeIf { it.isNotBlank() }?.let { "Ispit $it" },
        assignment?.existingValidUntil?.takeIf { it.isNotBlank() }?.let { "Rok $it" },
    ).filterNotNull().joinToString(" · ").ifBlank { label }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        color = tint.copy(alpha = 0.08f),
        border = BorderStroke(1.dp, tint.copy(alpha = 0.16f)),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(
                if (trainingAssignmentNeedsAction(assignment)) Icons.Rounded.ErrorOutline else Icons.Rounded.CheckCircle,
                contentDescription = null,
                tint = tint,
                modifier = Modifier.size(18.dp),
            )
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    service.trainingTitle(),
                    fontWeight = FontWeight.Bold,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    metaText,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            Text(label, color = tint, fontWeight = FontWeight.Black, style = MaterialTheme.typography.labelMedium)
        }
    }
}

@Composable
private fun DocumentationServiceValiditySection(
    flowItems: List<DocumentationServiceFlowItem>,
    serviceValidityMonths: Map<String, String>,
    onServiceValidityMonthsChange: (String, String) -> Unit,
    enabled: Boolean,
) {
    WizardSection(title = "Rok važenja usluge", icon = Icons.Rounded.CalendarMonth) {
        if (flowItems.isEmpty()) {
            Text(
                "Rok važenja se uzima iz starog zapisnika ili web predloška.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
            )
        } else {
            flowItems.forEach { item ->
                val key = item.serviceValidityKey()
                NumberTextField(
                    "${item.serviceCode} - ${item.serviceName}".trim(' ', '-'),
                    serviceValidityMonths[key].orEmpty(),
                    { value -> onServiceValidityMonthsChange(key, value) },
                    enabled,
                )
            }
        }
    }
}

@Composable
private fun DocumentationServicePeopleSection(
    personRules: List<DocumentationPersonFieldRule>,
    areaOptions: List<WorkOrderDocumentationSignatureAreaOptions>,
    inspectorUserIds: Set<String>,
    onInspectorUserIdsChange: (Set<String>) -> Unit,
    authorizationHolderUserId: String,
    onAuthorizationHolderUserIdChange: (String) -> Unit,
    electricalInspectorUserIds: Set<String>,
    onElectricalInspectorUserIdsChange: (Set<String>) -> Unit,
    electricalAuthorizationHolderUserId: String,
    onElectricalAuthorizationHolderUserIdChange: (String) -> Unit,
    tipkaloInspectorUserIds: Set<String>,
    onTipkaloInspectorUserIdsChange: (Set<String>) -> Unit,
    tipkaloAuthorizationHolderUserId: String,
    onTipkaloAuthorizationHolderUserIdChange: (String) -> Unit,
    workEquipmentInspectorUserIds: Set<String>,
    onWorkEquipmentInspectorUserIdsChange: (Set<String>) -> Unit,
    workEquipmentAuthorizationHolderUserId: String,
    onWorkEquipmentAuthorizationHolderUserIdChange: (String) -> Unit,
    workEnvironmentInspectorUserIds: Set<String>,
    onWorkEnvironmentInspectorUserIdsChange: (Set<String>) -> Unit,
    workEnvironmentAuthorizationHolderUserId: String,
    onWorkEnvironmentAuthorizationHolderUserIdChange: (String) -> Unit,
    enabled: Boolean,
) {
    if (personRules.isEmpty()) {
        return
    }
    val rulesByArea = personRules.groupBy { normalizeDocumentationSignatureAreaKey(it.signatureArea) }

    WizardSection(title = "Osobe i ovlaštenja", icon = Icons.Rounded.CheckCircle) {
        rulesByArea.forEach { (area, rules) ->
            val options = areaOptions.areaOptions(area)
            val inspectorSelection = when (area) {
                "tipkalo", "tzin" -> tipkaloInspectorUserIds
                "elektro" -> electricalInspectorUserIds
                "radna_oprema", "ro", "strojevi", "no" -> workEquipmentInspectorUserIds
                "radni_okolis", "fc" -> workEnvironmentInspectorUserIds
                else -> inspectorUserIds
            }
            val authorizationSelection = when (area) {
                "tipkalo", "tzin" -> tipkaloAuthorizationHolderUserId
                "elektro" -> electricalAuthorizationHolderUserId
                "radna_oprema", "ro", "strojevi", "no" -> workEquipmentAuthorizationHolderUserId
                "radni_okolis", "fc" -> workEnvironmentAuthorizationHolderUserId
                else -> authorizationHolderUserId
            }
            val onInspectorChange: (Set<String>) -> Unit = when (area) {
                "tipkalo", "tzin" -> onTipkaloInspectorUserIdsChange
                "elektro" -> onElectricalInspectorUserIdsChange
                "radna_oprema", "ro", "strojevi", "no" -> onWorkEquipmentInspectorUserIdsChange
                "radni_okolis", "fc" -> onWorkEnvironmentInspectorUserIdsChange
                else -> onInspectorUserIdsChange
            }
            val onAuthorizationChange: (String) -> Unit = when (area) {
                "tipkalo", "tzin" -> onTipkaloAuthorizationHolderUserIdChange
                "elektro" -> onElectricalAuthorizationHolderUserIdChange
                "radna_oprema", "ro", "strojevi", "no" -> onWorkEquipmentAuthorizationHolderUserIdChange
                "radni_okolis", "fc" -> onWorkEnvironmentAuthorizationHolderUserIdChange
                else -> onAuthorizationHolderUserIdChange
            }

            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(18.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.42f),
            ) {
                Column(
                    modifier = Modifier.padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                ) {
                    Text(options.label, fontWeight = FontWeight.Black)
                    rules.forEach { rule ->
                        when (rule.role) {
                            "company_responsible" -> {
                                DocumentationPersonRoleCard(
                                    label = if (rule.required) "${rule.label} *" else rule.label,
                                    selectedSummary = "Automatski iz tvrtke/lokacije",
                                    icon = Icons.Rounded.Business,
                                ) {
                                    Text(
                                        "Osoba naručitelja popunjava se iz podataka tvrtke/lokacije.",
                                        style = MaterialTheme.typography.bodySmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                                    )
                                }
                            }
                            "authorize" -> {
                                val authorizationLabel = options.authorizationOptions.firstOrNull { it.id == authorizationSelection }?.label.orEmpty()
                                DocumentationPersonRoleCard(
                                    label = if (rule.required) "${rule.label} *" else rule.label,
                                    selectedSummary = authorizationLabel.ifBlank { "Nije odabrano" },
                                    icon = Icons.Rounded.Person,
                                ) {
                                    DocumentationMultiSelectField(
                                        label = "Odabir osoba",
                                        options = options.authorizationOptions,
                                        selectedIds = authorizationSelection.takeIf { it.isNotBlank() }?.let { setOf(it) }.orEmpty(),
                                        enabled = enabled,
                                        emptyText = "Nema aktivnih odgovornih osoba s ovlaštenjem za ovu uslugu.",
                                        singleSelection = true,
                                        maxVisibleItems = options.authorizationOptions.size,
                                        onChange = { selected -> onAuthorizationChange(selected.firstOrNull().orEmpty()) },
                                    )
                                }
                            }
                            else -> {
                                if (rule.multiple) {
                                    val selectedInspectorLabels = options.inspectorOptions
                                        .filter { it.id in inspectorSelection }
                                        .joinToString(", ") { it.label }
                                    DocumentationPersonRoleCard(
                                        label = if (rule.required) "${rule.label} *" else rule.label,
                                        selectedSummary = selectedInspectorLabels.ifBlank { "Nije odabrano" },
                                        icon = Icons.Rounded.CheckCircle,
                                    ) {
                                        DocumentationMultiSelectField(
                                            label = "Odabir osoba",
                                            options = options.inspectorOptions,
                                            selectedIds = inspectorSelection,
                                            enabled = enabled,
                                            emptyText = "Nema aktivnih ispitivača s ovlaštenjem za ovu uslugu.",
                                            maxVisibleItems = options.inspectorOptions.size,
                                            onChange = onInspectorChange,
                                        )
                                    }
                                } else {
                                    val selectedInspectorId = inspectorSelection.firstOrNull().orEmpty()
                                    val inspectorLabel = options.inspectorOptions.firstOrNull { it.id == selectedInspectorId }?.label.orEmpty()
                                    DocumentationPersonRoleCard(
                                        label = if (rule.required) "${rule.label} *" else rule.label,
                                        selectedSummary = inspectorLabel.ifBlank { "Nije odabrano" },
                                        icon = Icons.Rounded.CheckCircle,
                                    ) {
                                        DocumentationMultiSelectField(
                                            label = "Odabir osoba",
                                            options = options.inspectorOptions,
                                            selectedIds = selectedInspectorId.takeIf { it.isNotBlank() }?.let { setOf(it) }.orEmpty(),
                                            enabled = enabled,
                                            emptyText = "Nema aktivnih ispitivača s ovlaštenjem za ovu uslugu.",
                                            singleSelection = true,
                                            maxVisibleItems = options.inspectorOptions.size,
                                            onChange = onInspectorChange,
                                        )
                                    }
                                }
                            }
                        }
                        if (rule.helpText.isNotBlank()) {
                            Text(
                                rule.helpText,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.54f),
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun DocumentationPersonRoleCard(
    label: String,
    selectedSummary: String,
    icon: ImageVector,
    content: @Composable () -> Unit,
) {
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(18.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.86f),
    ) {
        Column(
            modifier = Modifier.padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Surface(
                    shape = RoundedCornerShape(14.dp),
                    color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.72f),
                ) {
                    Icon(
                        icon,
                        contentDescription = null,
                        modifier = Modifier
                            .padding(9.dp)
                            .size(18.dp),
                        tint = MaterialTheme.colorScheme.primary,
                    )
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                    Text(label, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                    Text(
                        selectedSummary,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.62f),
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
            content()
        }
    }
}

@Composable
private fun DocumentationCoreBasicsContent(
    documentNumber: String,
    serviceName: String,
    showDocumentNumber: Boolean = true,
    inspectionDate: String,
    onInspectionDateChange: (String) -> Unit,
    issuedDate: String,
    onIssuedDateChange: (String) -> Unit,
    testingLocation: String,
    onTestingLocationChange: (String) -> Unit,
    measurementEquipmentGroup: String,
    measurementEquipmentGroupOptions: List<Pair<String, String>>,
    onMeasurementEquipmentGroupChange: (String) -> Unit,
    outsideTemperature: String,
    relativeHumidity: String,
    airflowSpeed: String,
    weather: String,
    groundCondition: String,
    groundResistance: String,
    onOutsideTemperatureChange: (String) -> Unit,
    onRelativeHumidityChange: (String) -> Unit,
    onAirflowSpeedChange: (String) -> Unit,
    onWeatherChange: (String) -> Unit,
    onGroundConditionChange: (String) -> Unit,
    onGroundResistanceChange: (String) -> Unit,
    environmentVisibility: DocumentationEnvironmentVisibility,
    enabled: Boolean,
) {
    if (showDocumentNumber) {
        DocumentationNumberPreview(documentNumber = documentNumber, serviceName = serviceName)
    }
    DocumentationMobileDatePickerField("Datum ispitivanja", inspectionDate, onInspectionDateChange, enabled)
    DocumentationMobileDatePickerField("Datum izdavanja", issuedDate, onIssuedDateChange, enabled)
    DocumentationMobileTextField("Mjesto ispitivanja", testingLocation, onTestingLocationChange, enabled)

    Text("Mjerna oprema", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
    DocumentationMobileSelectField(
        label = "Grupa mjerne opreme",
        value = measurementEquipmentGroup,
        valueLabel = measurementEquipmentGroup.ifBlank { "Bez odabira" },
        options = measurementEquipmentGroupOptions,
        enabled = enabled,
        onSelect = onMeasurementEquipmentGroupChange,
    )
    if (environmentVisibility.any) {
        Text("Vanjski utjecaji", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
        if (environmentVisibility.outsideTemperature) {
            DocumentationMobileTextField("Vanjska temperatura", outsideTemperature, onOutsideTemperatureChange, enabled)
        }
        if (environmentVisibility.relativeHumidity) {
            DocumentationMobileTextField("Relativna vlaga", relativeHumidity, onRelativeHumidityChange, enabled)
        }
        if (environmentVisibility.airflowSpeed) {
            DocumentationMobileTextField("Strujanje zraka", airflowSpeed, onAirflowSpeedChange, enabled)
        }
        if (environmentVisibility.weather) {
            DocumentationMobileTextField("Vremenski uvjeti", weather, onWeatherChange, enabled)
        }
        if (environmentVisibility.groundCondition) {
            DocumentationMobileTextField("Stanje tla", groundCondition, onGroundConditionChange, enabled)
        }
        if (environmentVisibility.groundResistance) {
            DocumentationMobileTextField("Otpor tla", groundResistance, onGroundResistanceChange, enabled)
        }
    }
}

@Composable
private fun TemplateBasicControls(controls: DocumentationTemplateStandardControls) {
    DocumentationReadonlyFactGrid(
        listOf(
            "Tvrtka" to controls.companyName,
            "Sjedište" to controls.companyHeadquarters,
            "OIB" to controls.companyOib,
            "Objekt" to controls.objectName.ifBlank { "Samo lokacija" },
            "Vrijedi do" to formatDatePickerLabel(controls.validUntil).ifBlank { controls.validUntil },
        ),
    )
    DocumentationNumberPreview(
        documentNumber = controls.documentNumber,
        serviceName = controls.serviceName,
    )
    DocumentationMobileDatePickerField(
        "Datum ispitivanja",
        controls.inspectionDate,
        controls.onInspectionDateChange,
        controls.enabled,
    )
    DocumentationMobileDatePickerField(
        "Datum izdavanja",
        controls.issuedDate,
        controls.onIssuedDateChange,
        controls.enabled,
    )
    DocumentationMobileSelectField(
        label = "Vrsta ispitivanja",
        value = controls.inspectionType,
        valueLabel = controls.inspectionType.ifBlank {
            if (controls.inspectionOptions.isEmpty()) "Nema opcija u templateu" else "Odaberi vrstu ispitivanja"
        },
        options = controls.inspectionOptions,
        enabled = controls.enabled,
        onSelect = controls.onInspectionTypeChange,
    )
    DocumentationMobileTextField(
        "Mjesto ispitivanja",
        controls.testingLocation,
        controls.onTestingLocationChange,
        controls.enabled,
    )
}

