private fun normalizeTemplateSectionLookup(value: String): String =
    value.trim()
        .lowercase(Locale.getDefault())
        .replace("č", "c")
        .replace("ć", "c")
        .replace("ž", "z")
        .replace("š", "s")
        .replace("đ", "d")
        .replace(Regex("\\s+"), " ")

private fun TemplateBlockSection.lookupText(): String =
    normalizeTemplateSectionLookup(
        listOf(
            title,
            subtitle,
            header?.label.orEmpty(),
            header?.summary.orEmpty(),
            blocks.joinToString(" ") { "${it.group} ${it.label} ${it.typeLabel}" },
        ).joinToString(" "),
    )

private fun isBasicTemplateSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return lookup.contains("osnovn") || lookup.contains("opci podaci")
}

private fun isSharedDocumentationTemplateSection(section: TemplateBlockSection): Boolean {
    val sectionLookup = normalizeTemplateSectionLookup(
        listOf(section.title, section.subtitle, section.header?.label.orEmpty(), section.header?.summary.orEmpty())
            .joinToString(" "),
    )
    val blockTypes = section.blocks
        .map { it.type.trim().lowercase(Locale.getDefault()) }
        .toSet()
    val sharedBlockTypes = setOf(
        "equipment_list",
        "legal_list",
        "qualified_inspectors",
        "inspector_signature",
        "authorization_holder_signature",
        "digital_signature",
    )

    return sectionLookup.contains("osnovni podaci") ||
        sectionLookup.contains("opci podaci") ||
        sectionLookup.contains("mjerna i ispitna oprema") ||
        sectionLookup.contains("primijenjeni propisi") ||
        (sectionLookup.contains("osobe") && sectionLookup.contains("ovlast")) ||
        blockTypes.any { it in sharedBlockTypes }
}

private fun isDocumentationSignatureTemplateSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    if (lookup.contains("osobe") && lookup.contains("ovlast")) return true
    return section.blocks.isNotEmpty() &&
        section.blocks.all { block ->
            isDocumentationSignatureFieldType(block.type) ||
                block.signatureRole.trim().isNotBlank() ||
                block.signatureArea.trim().isNotBlank()
        }
}

private fun isEquipmentTemplateSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return section.blocks.any { it.type.equals("equipment_list", ignoreCase = true) } ||
        lookup.contains("mjerna") ||
        lookup.contains("ispitna oprema")
}

private fun isLegalTemplateSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return section.blocks.any { it.type.equals("legal_list", ignoreCase = true) } ||
        lookup.contains("propis") ||
        lookup.contains("pravilnik")
}

private fun isMeasurementTemplateSection(section: TemplateBlockSection): Boolean {
    return section.blocks.any { it.type.equals("measurement_table", ignoreCase = true) }
}

private fun isDocumentationResultsTextSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return lookup.contains("rezultati ispitivanja") &&
        !lookup.contains("ocjena rezultata") &&
        !lookup.contains("zakljuc")
}

private fun isDocumentationAssessmentSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return lookup.contains("ocjena rezultata") ||
        (lookup.contains("ocjena") && lookup.contains("ispitivanja"))
}

private fun isBasicStandardTemplateBlock(block: WorkOrderDocumentationTemplateBlock): Boolean {
    val lookup = normalizeTemplateSectionLookup("${block.label} ${block.key} ${block.tokenKey}")
    return lookup.contains("broj zapisnika") ||
        lookup.contains("datum ispitivanja") ||
        lookup.contains("datum izdavanja") ||
        lookup.contains("vrsta ispitivanja") ||
        lookup.contains("mjesto ispitivanja")
}

private fun measurementTableIdentity(table: WorkOrderMeasurementTable): String =
    table.key.ifBlank { table.id.ifBlank { table.tokenKey.ifBlank { table.label } } }

private fun getMeasurementTablesForBlock(
    template: WorkOrderDocumentationTemplate,
    block: WorkOrderDocumentationTemplateBlock,
): List<WorkOrderMeasurementTable> {
    if (!block.type.equals("measurement_table", ignoreCase = true)) return emptyList()
    val blockKeys = listOf(block.id, block.key, block.tokenKey, block.label)
        .map(::normalizeTemplateSectionLookup)
        .filter { it.isNotBlank() }
        .toSet()
    if (blockKeys.isEmpty()) return emptyList()
    val matched = template.measurementTables.filter { table ->
        listOf(table.id, table.key, table.tokenKey, table.label)
            .map(::normalizeTemplateSectionLookup)
            .any { it.isNotBlank() && blockKeys.contains(it) }
    }
    return matched.ifEmpty {
        if (blockKeys.contains("gridline results")) template.measurementTables else emptyList()
    }
}

private fun getMeasurementTablesForSection(
    template: WorkOrderDocumentationTemplate,
    section: TemplateBlockSection,
): List<WorkOrderMeasurementTable> {
    val measurementBlocks = section.blocks.filter { it.type.equals("measurement_table", ignoreCase = true) }
    if (measurementBlocks.isEmpty()) {
        return if (isMeasurementTemplateSection(section)) template.measurementTables else emptyList()
    }
    return measurementBlocks
        .flatMap { block -> getMeasurementTablesForBlock(template, block) }
        .distinctBy(::measurementTableIdentity)
        .ifEmpty { template.measurementTables }
}

private fun documentationSignatureBlockTypeLabel(block: WorkOrderDocumentationTemplateBlock): String {
    if (!isDocumentationSignatureFieldType(block.type)) return ""
    return when (normalizeDocumentationSignatureRole(block.signatureRole, block.type)) {
        "authorize" -> "Ovlaštena osoba"
        "company_responsible" -> "Odgovorna osoba naručitelja"
        "all" -> "Ispitivači i ovlaštena osoba"
        else -> "Ispitivači"
    }
}

private fun documentationSignatureBlockSelectionSummary(
    block: WorkOrderDocumentationTemplateBlock,
    standard: DocumentationStandardValues,
): String? {
    if (!isDocumentationSignatureFieldType(block.type)) return null
    val role = normalizeDocumentationSignatureRole(block.signatureRole, block.type)
    if (role == "company_responsible") {
        return "Automatski iz podataka tvrtke/lokacije."
    }
    return standardDocumentationSignatureValue(block.signatureArea, block.signatureRole, block.type, standard)
        .ifBlank { "Odaberi osobu u bloku Osobe i ovlaštenja." }
}

private fun isDocumentationAttachmentTemplateSection(section: TemplateBlockSection): Boolean {
    val lookup = section.lookupText()
    return section.blocks.any(::isDocumentationAttachmentUploadBlock) ||
        lookup.contains("dodaj dokument") ||
        lookup.contains("dokumenti") ||
        lookup.contains("prilog") ||
        lookup.contains("privit") ||
        lookup.contains("skic")
}

private fun isDocumentationAttachmentUploadBlock(block: WorkOrderDocumentationTemplateBlock): Boolean =
    block.type.equals("sketch_upload", ignoreCase = true) ||
        block.type.equals("image_upload", ignoreCase = true) ||
        block.type.equals("attachment_upload", ignoreCase = true) ||
        normalizeTemplateSectionLookup(
            listOf(
                block.id,
                block.key,
                block.tokenKey,
                block.label,
                block.type,
                block.typeLabel,
                block.group,
                block.helpText,
                block.summary,
            ).joinToString(" "),
        ).let { lookup ->
            val hasAttachmentIntent = lookup.contains("dodaj dokument") ||
                lookup.contains("dodaj prilog") ||
                lookup.contains("attachment") ||
                lookup.contains("prilog") ||
                lookup.contains("privit")
            val hasUploadMedia = lookup.contains("pdf") ||
                lookup.contains("sken") ||
                lookup.contains("kamer") ||
                lookup.contains("slik") ||
                lookup.contains("datotek") ||
                lookup.contains("dokument")
            hasAttachmentIntent && hasUploadMedia
        }

private fun documentationFieldLookup(
    field: WorkOrderDocumentationField?,
    block: WorkOrderDocumentationTemplateBlock,
): String =
    normalizeTemplateSectionLookup(
        listOf(
            field?.id.orEmpty(),
            field?.key.orEmpty(),
            field?.tokenKey.orEmpty(),
            field?.label.orEmpty(),
            field?.helpText.orEmpty(),
            field?.defaultValue.orEmpty(),
            block.id,
            block.key,
            block.tokenKey,
            block.label,
            block.typeLabel,
            block.helpText,
        ).joinToString(" "),
    )

private fun isDocumentationSatisfactoryTemplateField(
    field: WorkOrderDocumentationField,
    block: WorkOrderDocumentationTemplateBlock,
): Boolean {
    val lookup = documentationFieldLookup(field, block)
    if (lookup.contains("nedostat") ||
        lookup.contains("nepravilnost") ||
        lookup.contains("defect") ||
        lookup.contains("deficien") ||
        lookup.contains("omission")
    ) {
        return false
    }
    return lookup.contains("zadovoljava") ||
        (lookup.contains("zakljuc") && lookup.contains("ocjen")) ||
        lookup.contains("ocjena rezultata") ||
        lookup.contains("ocjena ispitivanja")
}

private fun isDocumentationDefectsTemplateField(
    field: WorkOrderDocumentationField,
    block: WorkOrderDocumentationTemplateBlock,
): Boolean =
    documentationFieldLookup(field, block).let { lookup ->
        lookup.contains("nedostat") ||
            lookup.contains("nepravilnost") ||
            lookup.contains("defect") ||
            lookup.contains("deficien") ||
            lookup.contains("omission")
    }

private fun isDocumentationRecommendationsTemplateField(
    field: WorkOrderDocumentationField,
    block: WorkOrderDocumentationTemplateBlock,
): Boolean =
    documentationFieldLookup(field, block).let { lookup ->
        lookup.contains("preporuk") || lookup.contains("napomen")
    }

private fun documentationSatisfactoryValueIsPositive(value: String): Boolean {
    val lookup = normalizeTemplateSectionLookup(value)
    if (lookup.isBlank()) return true
    return !(lookup == "false" ||
        lookup == "0" ||
        lookup == "ne" ||
        lookup.contains("ne zadovoljava") ||
        lookup.contains("nezadovoljava") ||
        lookup.contains("negativ"))
}

private fun shouldHideDocumentationDefects(
    template: WorkOrderDocumentationTemplate,
    blocks: List<WorkOrderDocumentationTemplateBlock>,
    values: Map<String, String>,
): Boolean {
    blocks.forEach { block ->
        val field = findTemplateFieldForBlock(template, block) ?: return@forEach
        if (isDocumentationSatisfactoryTemplateField(field, block)) {
            val value = values[templateFieldStateKey(template, field)].orEmpty()
            return documentationSatisfactoryValueIsPositive(value)
        }
    }
    return false
}

private fun DocumentationTemplateStandardControls.selectedInspectorsForArea(area: String): Set<String> {
    val normalizedArea = normalizeDocumentationSignatureAreaKey(area)
    return selectedInspectorIdsByArea[normalizedArea].orEmpty()
        .ifEmpty { selectedInspectorIdsByArea["default"].orEmpty() }
}

private fun DocumentationTemplateStandardControls.selectedAuthorizationForArea(area: String): String {
    val normalizedArea = normalizeDocumentationSignatureAreaKey(area)
    return selectedAuthorizationIdByArea[normalizedArea].orEmpty()
        .ifBlank { selectedAuthorizationIdByArea["default"].orEmpty() }
}

@Composable
private fun DocumentationSignatureBlockSelector(
    block: WorkOrderDocumentationTemplateBlock,
    standardControls: DocumentationTemplateStandardControls,
    enabled: Boolean,
) {
    val area = normalizeDocumentationSignatureAreaKey(block.signatureArea)
    val role = normalizeDocumentationSignatureRole(block.signatureRole, block.type)
    val options = standardControls.signatureAreaOptions.areaOptions(area)
    when (role) {
        "company_responsible" -> {
            Text(
                "Odgovorna osoba naručitelja popunjava se iz podataka tvrtke/lokacije.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
            )
        }
        "authorize" -> {
            val selectedId = standardControls.selectedAuthorizationForArea(area)
            val selectedLabel = options.authorizationOptions.firstOrNull { it.id == selectedId }?.label.orEmpty()
            Text(
                selectedLabel.ifBlank { "Odaberi odgovornu osobu za ${options.label}." },
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                fontWeight = FontWeight.SemiBold,
            )
            DocumentationMultiSelectField(
                label = "Odgovorna osoba",
                options = options.authorizationOptions,
                selectedIds = selectedId.takeIf { it.isNotBlank() }?.let { setOf(it) }.orEmpty(),
                enabled = enabled,
                emptyText = "Nema aktivnih odgovornih osoba s ovlaštenjem za ovu uslugu.",
                singleSelection = true,
                maxVisibleItems = options.authorizationOptions.size,
                onChange = { selected -> standardControls.onAuthorizationIdChangeForArea(area, selected.firstOrNull().orEmpty()) },
            )
        }
        else -> {
            val selectedIds = standardControls.selectedInspectorsForArea(area)
            val selectedLabel = options.inspectorOptions
                .filter { it.id in selectedIds }
                .joinToString(", ") { it.label }
            Text(
                selectedLabel.ifBlank { "Odaberi ispitivače za ${options.label}." },
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.68f),
                fontWeight = FontWeight.SemiBold,
            )
            DocumentationMultiSelectField(
                label = "Ispitivači",
                options = options.inspectorOptions,
                selectedIds = selectedIds,
                enabled = enabled,
                emptyText = "Nema aktivnih ispitivača s ovlaštenjem za ovu uslugu.",
                maxVisibleItems = options.inspectorOptions.size,
                onChange = { selected -> standardControls.onInspectorIdsChangeForArea(area, selected) },
            )
        }
    }
}

@Composable
private fun DocumentationSatisfactoryTemplateInput(
    field: WorkOrderDocumentationField,
    value: String,
    enabled: Boolean,
    onChange: (String) -> Unit,
) {
    val positive = documentationSatisfactoryValueIsPositive(value)
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Text(if (field.required) "${field.label} *" else field.label, style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Black)
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
            DocumentationSatisfactoryChoice(
                modifier = Modifier.weight(1f),
                selected = positive,
                label = "Zadovoljava",
                icon = Icons.Rounded.CheckCircle,
                accent = Color(0xFF059669),
                enabled = enabled,
                onClick = { onChange("true") },
            )
            DocumentationSatisfactoryChoice(
                modifier = Modifier.weight(1f),
                selected = !positive,
                label = "Ne zadovoljava",
                icon = Icons.Rounded.ErrorOutline,
                accent = Color(0xFFDC2626),
                enabled = enabled,
                onClick = { onChange("false") },
            )
        }
        Text(
            if (positive) "Nedostaci se ne prikazuju za pozitivnu ocjenu." else "Nedostaci su obavezni za negativnu ocjenu.",
            style = MaterialTheme.typography.labelSmall,
            color = if (positive) Color(0xFF047857) else Color(0xFFB91C1C),
            fontWeight = FontWeight.SemiBold,
        )
    }
}

@Composable
private fun DocumentationSatisfactoryChoice(
    modifier: Modifier,
    selected: Boolean,
    label: String,
    icon: ImageVector,
    accent: Color,
    enabled: Boolean,
    onClick: () -> Unit,
) {
    Surface(
        modifier = modifier
            .clip(RoundedCornerShape(16.dp))
            .clickable(enabled = enabled, onClick = onClick),
        shape = RoundedCornerShape(16.dp),
        color = if (selected) accent.copy(alpha = 0.14f) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.36f),
        border = BorderStroke(1.dp, if (selected) accent.copy(alpha = 0.82f) else MaterialTheme.colorScheme.outline.copy(alpha = 0.14f)),
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 8.dp, vertical = 11.dp),
            horizontalArrangement = Arrangement.spacedBy(5.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(icon, contentDescription = null, modifier = Modifier.size(16.dp), tint = if (selected) accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.46f))
            Text(
                label,
                style = MaterialTheme.typography.labelSmall,
                fontWeight = FontWeight.Black,
                color = if (selected) accent else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.66f),
                maxLines = 1,
                softWrap = false,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
}

@Composable
private fun DocumentationPremiumLongTextInput(
    field: WorkOrderDocumentationField,
    value: String,
    enabled: Boolean,
    onChange: (String) -> Unit,
    icon: ImageVector,
    accent: Color,
) {
    Column(verticalArrangement = Arrangement.spacedBy(7.dp)) {
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
            Icon(icon, contentDescription = null, tint = accent, modifier = Modifier.size(18.dp))
            Text(if (field.required) "${field.label} *" else field.label, fontWeight = FontWeight.Black)
        }
        OutlinedTextField(
            value = value,
            onValueChange = onChange,
            modifier = Modifier.fillMaxWidth(),
            minLines = 3,
            maxLines = 6,
            enabled = enabled,
            placeholder = { Text(field.defaultValue.ifBlank { field.label }) },
            shape = RoundedCornerShape(16.dp),
        )
    }
}

@Composable
private fun TemplateBlockDetailRow(
    template: WorkOrderDocumentationTemplate,
    block: WorkOrderDocumentationTemplateBlock,
    editableField: WorkOrderDocumentationField?,
    value: String,
    standardValues: DocumentationStandardValues,
    standardControls: DocumentationTemplateStandardControls? = null,
    enabled: Boolean,
    onPickAttachments: (() -> Unit)? = null,
    onChange: (WorkOrderDocumentationField, String) -> Unit,
    onSprVoiceApply: ((WorkOrderDocumentationField, String, Boolean) -> Unit)? = null,
    onSprVoicePreview: ((WorkOrderDocumentationField, String) -> Unit)? = null,
    sprVoicePreviewRows: List<SprVoiceAiRow> = emptyList(),
    sprVoicePreviewLoading: Boolean = false,
    sprVoicePreviewMessage: String = "",
) {
    if (isDocumentationAttachmentUploadBlock(block) && onPickAttachments != null) {
        DocumentationSprInlineAttachmentUploadBlock(
            block = block,
            enabled = enabled,
            onPickFiles = onPickAttachments,
        )
        return
    }
    val signatureSummary = remember(block, standardValues) {
        documentationSignatureBlockSelectionSummary(block, standardValues)
    }
    val shouldFlattenEditableField = editableField != null &&
        signatureSummary == null &&
        !isDocumentationDefectsTemplateField(editableField, block) &&
        !isDocumentationSatisfactoryTemplateField(editableField, block) &&
        !isDocumentationRecommendationsTemplateField(editableField, block)
    if (shouldFlattenEditableField && editableField != null) {
        TemplateFieldInput(
            field = editableField,
            value = value,
            enabled = enabled,
            onChange = { onChange(editableField, it) },
            onSprVoiceApply = onSprVoiceApply?.let { handler ->
                { nextValue, replaceExisting -> handler(editableField, nextValue, replaceExisting) }
            },
            onSprVoicePreview = onSprVoicePreview?.let { handler ->
                { transcript -> handler(editableField, transcript) }
            },
            sprVoicePreviewRows = sprVoicePreviewRows,
            sprVoicePreviewLoading = sprVoicePreviewLoading,
            sprVoicePreviewMessage = sprVoicePreviewMessage,
            showHelpText = false,
        )
        return
    }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.9f),
    ) {
        Column(
            modifier = Modifier.padding(10.dp),
            verticalArrangement = Arrangement.spacedBy(7.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.Top,
            ) {
                Icon(
                    templateBlockIcon(block.type),
                    contentDescription = null,
                    modifier = Modifier.size(18.dp),
                    tint = MaterialTheme.colorScheme.primary,
                )
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        if (block.required) "${block.label} *" else block.label,
                        fontWeight = FontWeight.Black,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
            }
            if (standardControls != null && signatureSummary != null && isDocumentationSignatureFieldType(block.type)) {
                DocumentationSignatureBlockSelector(
                    block = block,
                    standardControls = standardControls,
                    enabled = enabled,
                )
            } else if (editableField != null) {
                when {
                    isDocumentationDefectsTemplateField(editableField, block) -> DocumentationPremiumLongTextInput(
                        field = editableField,
                        value = value,
                        enabled = enabled,
                        onChange = { onChange(editableField, it) },
                        icon = Icons.Rounded.ErrorOutline,
                        accent = Color(0xFFDC2626),
                    )
                    isDocumentationSatisfactoryTemplateField(editableField, block) -> DocumentationSatisfactoryTemplateInput(
                        field = editableField,
                        value = value,
                        enabled = enabled,
                        onChange = { onChange(editableField, it) },
                    )
                    isDocumentationRecommendationsTemplateField(editableField, block) -> DocumentationPremiumLongTextInput(
                        field = editableField,
                        value = value,
                        enabled = enabled,
                        onChange = { onChange(editableField, it) },
                        icon = Icons.Rounded.CheckCircle,
                        accent = Color(0xFF2563EB),
                    )
                    else -> TemplateFieldInput(
                        field = editableField,
                        value = value,
                        enabled = enabled,
                        onChange = { onChange(editableField, it) },
                        onSprVoiceApply = onSprVoiceApply?.let { handler ->
                            { nextValue, replaceExisting -> handler(editableField, nextValue, replaceExisting) }
                        },
                        onSprVoicePreview = onSprVoicePreview?.let { handler ->
                            { transcript -> handler(editableField, transcript) }
                        },
                        sprVoicePreviewRows = sprVoicePreviewRows,
                        sprVoicePreviewLoading = sprVoicePreviewLoading,
                        sprVoicePreviewMessage = sprVoicePreviewMessage,
                        showHelpText = false,
                    )
                }
            } else {
                Text(
                    signatureSummary ?: block.summary.ifBlank {
                        when (block.type.lowercase(Locale.getDefault())) {
                            "measurement_table" -> "Excel tablica se uređuje u bloku Excel / mjerenja."
                            "equipment_list" -> "Oprema se bira u bloku Mjerna i ispitna oprema."
                            "legal_list" -> "Propisi se biraju u bloku Propisi."
                            "qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature" ->
                                "Osobe i potpis se popunjavaju u bloku Osobe i potpis."
                            "sketch_upload", "image_upload" -> "Prilozi se dodaju kroz dokumentaciju radnog naloga."
                            else -> block.typeLabel
                        }
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                )
            }
            if (block.options.isNotEmpty() && editableField == null) {
                FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                    block.options.take(6).forEach { option ->
                        AssistChip(
                            onClick = {},
                            label = {
                                Text(
                                    option.label.ifBlank { option.value },
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                )
                            },
                        )
                    }
                    if (block.options.size > 6) {
                        AssistChip(onClick = {}, label = { Text("+${block.options.size - 6}") })
                    }
                }
            }
        }
    }
}

@Composable
private fun TemplateBlockRow(
    template: WorkOrderDocumentationTemplate,
    block: WorkOrderDocumentationTemplateBlock,
    editableField: WorkOrderDocumentationField?,
    value: String,
    enabled: Boolean,
    onChange: (WorkOrderDocumentationField, String) -> Unit,
) {
    var expanded by remember(template.id, block.id, block.key, block.tokenKey) { mutableStateOf(false) }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(14.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.48f),
    ) {
        Row(
            modifier = Modifier.padding(10.dp),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            verticalAlignment = Alignment.Top,
        ) {
            Surface(shape = RoundedCornerShape(12.dp), color = MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)) {
                Icon(
                    templateBlockIcon(block.type),
                    contentDescription = null,
                    modifier = Modifier
                        .size(34.dp)
                        .padding(8.dp),
                    tint = MaterialTheme.colorScheme.primary,
                )
            }
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(5.dp),
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.Top,
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            if (block.required) "${block.label} *" else block.label,
                            fontWeight = FontWeight.Black,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                        )
                        Text(
                            block.typeLabel,
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                        )
                    }
                }
                if (block.summary.isNotBlank() && !expanded) {
                    Text(
                        block.summary,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
                        maxLines = 3,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                if (expanded) {
                    if (editableField != null) {
                        TemplateFieldInput(
                            field = editableField,
                            value = value,
                            enabled = enabled,
                            onChange = { onChange(editableField, it) },
                        )
                    } else {
                        Text(
                            block.summary.ifBlank {
                                when (block.type.lowercase(Locale.getDefault())) {
                                    "measurement_table" -> "Excel tablica se uređuje u bloku Excel / mjerenja."
                                    "equipment_list" -> "Oprema se bira u bloku Mjerna i ispitna oprema."
                                    "legal_list" -> "Propisi se biraju u bloku Propisi."
                                    "qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature" ->
                                        "Osobe i potpis se popunjavaju u bloku Osobe i potpis."
                                    "sketch_upload", "image_upload" -> "Prilozi se dodaju kroz dokumentaciju radnog naloga."
                                    else -> block.typeLabel
                                }
                            },
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.72f),
                        )
                    }
                }
                if (block.helpText.isNotBlank() && expanded) {
                    Text(
                        block.helpText,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.54f),
                        maxLines = 3,
                        overflow = TextOverflow.Ellipsis,
                    )
                }
                if (block.options.isNotEmpty() && expanded && editableField == null) {
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                        block.options.take(5).forEach { option ->
                            AssistChip(
                                onClick = {},
                                label = {
                                    Text(
                                        option.label.ifBlank { option.value },
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                    )
                                },
                            )
                        }
                        if (block.options.size > 5) {
                            AssistChip(onClick = {}, label = { Text("+${block.options.size - 5}") })
                        }
                    }
                }
            }
        }
    }
}

private fun findTemplateFieldForBlock(
    template: WorkOrderDocumentationTemplate,
    block: WorkOrderDocumentationTemplateBlock,
): WorkOrderDocumentationField? {
    if (!block.editable) return null
    val blockKeys = listOf(block.id, block.key, block.tokenKey, block.label)
        .map { it.trim() }
        .filter { it.isNotBlank() }
        .map { it.lowercase(Locale.getDefault()) }
        .toSet()
    return template.fields.firstOrNull { field ->
        listOf(field.id, field.key, field.tokenKey, field.label)
            .map { it.trim().lowercase(Locale.getDefault()) }
            .any { it.isNotBlank() && blockKeys.contains(it) }
    }
}

private fun templateBlockIcon(type: String): ImageVector =
    when (type.lowercase(Locale.getDefault())) {
        "measurement_table" -> Icons.Rounded.Description
        "equipment_list" -> Icons.Rounded.Work
        "legal_list" -> Icons.Rounded.Lock
        "qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature" -> Icons.Rounded.Fingerprint
        "sketch_upload" -> Icons.Rounded.PictureAsPdf
        "image_upload" -> Icons.Rounded.Image
        "system_description" -> Icons.Rounded.InsertDriveFile
        else -> Icons.Rounded.Description
    }

