@Composable
private fun TemplateFieldInput(
    field: WorkOrderDocumentationField,
    value: String,
    enabled: Boolean,
    onChange: (String) -> Unit,
    onSprVoiceApply: ((String, Boolean) -> Unit)? = null,
    onSprVoicePreview: ((String) -> Unit)? = null,
    sprVoicePreviewRows: List<SprVoiceAiRow> = emptyList(),
    sprVoicePreviewLoading: Boolean = false,
    sprVoicePreviewMessage: String = "",
    showHelpText: Boolean = true,
) {
    val label = if (field.required) "${field.label} *" else field.label
    Column(verticalArrangement = Arrangement.spacedBy(5.dp)) {
        when (field.type.lowercase(Locale.getDefault())) {
            "dropdown", "select" -> DocumentationMobileSelectField(
                label = label,
                value = value,
                valueLabel = field.options.firstOrNull { it.value == value }?.label ?: value.ifBlank { "Odaberi" },
                options = listOf("" to "Nije odabrano") + field.options.map { it.value to it.label },
                enabled = enabled,
                onSelect = onChange,
            )
            "checkbox", "toggle" -> {
                val checked = value.equals("true", ignoreCase = true) || value == "1" || value.equals("da", ignoreCase = true)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(14.dp))
                        .clickable(enabled = enabled) { onChange((!checked).toString()) }
                        .padding(vertical = 4.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Checkbox(
                        checked = checked,
                        onCheckedChange = { onChange(it.toString()) },
                        enabled = enabled,
                    )
                    Column {
                        Text(label, fontWeight = FontWeight.SemiBold)
                        Text(
                            if (checked) "Da" else "Ne",
                            style = MaterialTheme.typography.labelMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.58f),
                        )
                    }
                }
            }
            "longtext", "textarea", "richtext" -> DocumentationMobileTextField(
                label = label,
                value = value,
                onChange = onChange,
                enabled = enabled,
                singleLine = false,
                minLines = 3,
                maxLines = 7,
            )
            "spr_voice" -> DocumentationSprVoiceField(
                label = label,
                value = value,
                onChange = onChange,
                onVoiceApply = onSprVoiceApply ?: { nextValue, _ -> onChange(nextValue) },
                onVoicePreview = onSprVoicePreview ?: {},
                voicePreviewRows = sprVoicePreviewRows,
                voicePreviewLoading = sprVoicePreviewLoading,
                voicePreviewMessage = sprVoicePreviewMessage,
                enabled = enabled,
            )
            "number" -> DocumentationMobileTextField(
                label = label,
                value = value,
                onChange = onChange,
                enabled = enabled,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            )
            "date" -> DocumentationMobileDatePickerField(label, value, onChange, enabled)
            else -> DocumentationMobileTextField(label, value, onChange, enabled)
        }
        if (showHelpText && field.helpText.isNotBlank()) {
            Text(
                field.helpText,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.55f),
            )
        }
    }
}

