private suspend fun buildIsznrRoAttachmentFiles(
    context: Context,
    uris: List<Uri>,
    existingCount: Int,
    maxFiles: Int = ISZNR_RO_ATTACHMENT_MAX_INLINE_FILES,
    mode: WorkOrderDocumentInputMode = WorkOrderDocumentInputMode.Photos,
    role: String = "image",
    allowPdf: Boolean = false,
): List<IsznrRoAttachmentFile> = withContext(Dispatchers.IO) {
    val availableSlots = (maxFiles - existingCount).coerceAtLeast(0)
    if (availableSlots <= 0) {
        error("Možeš dodati najviše $maxFiles privitaka za RO zapisnik.")
    }
    uris.take(availableSlots).mapIndexed { index, uri ->
        val rawBytes = readUriBytes(context, uri)
        val name = resolveUriDisplayName(context, uri, existingCount + index, mode)
        val mimeType = resolveUriMimeType(context, uri, name).ifBlank {
            if (mode == WorkOrderDocumentInputMode.Pdf) "application/pdf" else "image/jpeg"
        }
        val isImage = mimeType.startsWith("image/", ignoreCase = true)
        val isPdf = mimeType.equals("application/pdf", ignoreCase = true)
        if (!isImage && !(allowPdf && isPdf)) {
            error(if (allowPdf) "Možeš dodati samo slike ili PDF za RO privitke." else "Možeš dodati samo slike za RO privitke.")
        }
        val attachmentBytes = if (isImage) normalizeRoImageAttachmentBytes(rawBytes) else rawBytes
        if (attachmentBytes.size.toLong() > ISZNR_RO_ATTACHMENT_MAX_INLINE_FILE_BYTES) {
            error("Privitak $name mora biti manji od 8 MB.")
        }
        val attachmentMimeType = if (isImage) "image/jpeg" else mimeType
        val resolvedRole = role.ifBlank { if (isPdf) "document" else "image" }
        IsznrRoAttachmentFile(
            id = "${System.currentTimeMillis()}-${existingCount + index}-${name.hashCode()}",
            fileName = name.withFallbackExtension(attachmentMimeType),
            fileType = attachmentMimeType,
            fileSize = attachmentBytes.size.toLong(),
            contentDataUrl = "data:$attachmentMimeType;base64,${Base64.getEncoder().encodeToString(attachmentBytes)}",
            role = resolvedRole,
            includeInReport = true,
        )
    }
}

private fun normalizeRoImageAttachmentBytes(bytes: ByteArray): ByteArray {
    val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
    BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
    if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return bytes

    var sampleSize = 1
    val largestSide = maxOf(bounds.outWidth, bounds.outHeight)
    while ((largestSide / sampleSize) > ISZNR_RO_IMAGE_MAX_DIMENSION_PX * 2) {
        sampleSize *= 2
    }

    val decoded = BitmapFactory.decodeByteArray(
        bytes,
        0,
        bytes.size,
        BitmapFactory.Options().apply {
            inSampleSize = sampleSize
            inPreferredConfig = Bitmap.Config.RGB_565
        },
    ) ?: return bytes

    val scaled = if (maxOf(decoded.width, decoded.height) > ISZNR_RO_IMAGE_MAX_DIMENSION_PX) {
        val ratio = ISZNR_RO_IMAGE_MAX_DIMENSION_PX.toFloat() / maxOf(decoded.width, decoded.height).toFloat()
        Bitmap.createScaledBitmap(
            decoded,
            (decoded.width * ratio).toInt().coerceAtLeast(1),
            (decoded.height * ratio).toInt().coerceAtLeast(1),
            true,
        )
    } else {
        decoded
    }

    val output = ByteArrayOutputStream()
    scaled.compress(Bitmap.CompressFormat.JPEG, ISZNR_RO_IMAGE_JPEG_QUALITY, output)
    if (scaled !== decoded) scaled.recycle()
    decoded.recycle()
    val normalized = output.toByteArray()
    return if (normalized.isNotEmpty()) normalized else bytes
}

private fun readUriBytes(context: Context, uri: Uri): ByteArray =
    context.contentResolver.openInputStream(uri)?.use { input -> input.readBytes() }
        ?: error("Ne mogu učitati odabrani dokument.")

private fun resolveUriDisplayName(
    context: Context,
    uri: Uri,
    index: Int,
    mode: WorkOrderDocumentInputMode,
): String {
    val resolver = context.contentResolver
    val queried = resolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
        val nameIndex = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
        if (cursor.moveToFirst() && nameIndex >= 0) cursor.getString(nameIndex) else ""
    }.orEmpty().trim()
    if (queried.isNotBlank()) return queried

    val fallback = when (mode) {
        WorkOrderDocumentInputMode.Photos -> "fotografija-${index + 1}.jpg"
        WorkOrderDocumentInputMode.Pdf -> "dokument-${index + 1}.pdf"
        WorkOrderDocumentInputMode.Scan -> "sken-${index + 1}.pdf"
        WorkOrderDocumentInputMode.File -> "dokument-${index + 1}"
    }
    return fallback
}

private fun resolveUriMimeType(context: Context, uri: Uri, fallbackName: String): String {
    val resolverType = context.contentResolver.getType(uri).orEmpty().trim()
    if (resolverType.isNotBlank()) return resolverType

    val extension = fallbackName.substringAfterLast('.', "")
        .ifBlank { uri.toString().substringAfterLast('.', "") }
        .lowercase()
    return MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension).orEmpty()
}

private fun String.withFallbackExtension(mimeType: String): String {
    if (contains(".") || mimeType.isBlank()) return this
    val extension = MimeTypeMap.getSingleton().getExtensionFromMimeType(mimeType).orEmpty()
    return if (extension.isBlank()) this else "$this.$extension"
}

private fun buildWorkOrderDocumentFileName(
    workOrder: WorkOrder,
    category: WorkOrderDocumentCategory,
    extension: String,
): String {
    val number = workOrder.displayNumber
        .replace(Regex("[^A-Za-z0-9_-]+"), "-")
        .trim('-')
        .ifBlank { "RN" }
    val categorySlug = category.value
        .lowercase()
        .replace(Regex("[^a-z0-9]+"), "-")
        .trim('-')
        .ifBlank { "dokument" }
    val stamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss"))
    return "$categorySlug-$number-$stamp.$extension"
}

private fun buildWorkOrderDocumentDescription(
    mode: WorkOrderDocumentInputMode,
    category: WorkOrderDocumentCategory,
    projectDocumentName: String = "",
): String {
    if (category == WorkOrderDocumentCategory.ProjectDocumentation && projectDocumentName.isNotBlank()) {
        return projectDocumentName.trim()
    }
    return when (mode) {
        WorkOrderDocumentInputMode.Scan -> "Skenirani dokument iz SafeNexus Android aplikacije."
        WorkOrderDocumentInputMode.Photos -> "Fotografija dodana iz SafeNexus Android aplikacije."
        WorkOrderDocumentInputMode.Pdf -> "PDF dokument dodan iz SafeNexus Android aplikacije."
        WorkOrderDocumentInputMode.File -> "Datoteka dodana iz SafeNexus Android aplikacije."
    }
}

private fun buildProjectDocumentationDefaultName(value: String): String =
    value.substringAfterLast('/')
        .substringBeforeLast('.', missingDelimiterValue = value.substringAfterLast('/'))
        .replace(Regex("[_-]+"), " ")
        .replace(Regex("\\s+"), " ")
        .trim()

private fun cacheDownloadedDocumentFile(context: Context, document: DownloadedDocument): File {
    val directory = File(context.cacheDir, "work-order-documents").apply { mkdirs() }
    val safeName = document.fileName
        .replace(Regex("""[\\/:*?"<>|]+"""), "-")
        .trim()
        .ifBlank { "dokument" }
    val file = File(directory, safeName)
    file.writeBytes(document.bytes)
    return file
}

private fun cacheDownloadedDocument(context: Context, document: DownloadedDocument): Uri {
    val file = cacheDownloadedDocumentFile(context, document)
    return FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file)
}

private fun cacheDownloadedDocumentFileUri(context: Context, document: DownloadedDocument): Uri =
    Uri.fromFile(cacheDownloadedDocumentFile(context, document))

private fun saveDownloadedDocument(context: Context, document: DownloadedDocument): Uri {
    val safeName = document.fileName
        .replace(Regex("""[\\/:*?"<>|]+"""), "-")
        .trim()
        .ifBlank { "dokument" }

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
        val resolver = context.contentResolver
        val values = ContentValues().apply {
            put(MediaStore.Downloads.DISPLAY_NAME, safeName)
            put(MediaStore.Downloads.MIME_TYPE, document.fileType.ifBlank { "application/octet-stream" })
            put(MediaStore.Downloads.RELATIVE_PATH, "${Environment.DIRECTORY_DOWNLOADS}/SafeNexus")
            put(MediaStore.Downloads.IS_PENDING, 1)
        }
        val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)
            ?: error("Ne mogu otvoriti Android Downloads mapu.")
        resolver.openOutputStream(uri)?.use { output -> output.write(document.bytes) }
            ?: error("Ne mogu zapisati dokument.")
        values.clear()
        values.put(MediaStore.Downloads.IS_PENDING, 0)
        resolver.update(uri, values, null, null)
        return uri
    }

    return cacheDownloadedDocument(context, document)
}

private fun openExternalUrl(context: Context, url: String): Boolean {
    val trimmed = url.trim()
    if (trimmed.isBlank()) return false
    val intent = Intent(Intent.ACTION_VIEW, Uri.parse(trimmed)).apply {
        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
    }
    return try {
        context.startActivity(intent)
        true
    } catch (_: ActivityNotFoundException) {
        false
    }
}

private fun openDialer(context: Context, phone: String): Boolean {
    val normalized = phone.trim().filterNot { it.isWhitespace() }
    if (normalized.isBlank()) return false
    val intent = Intent(Intent.ACTION_DIAL, Uri.fromParts("tel", normalized, null)).apply {
        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
    }
    return try {
        context.startActivity(intent)
        true
    } catch (_: ActivityNotFoundException) {
        false
    }
}

private fun openEmailClient(context: Context, email: String): Boolean {
    val normalized = email.trim()
    if (normalized.isBlank()) return false
    val intent = Intent(Intent.ACTION_SENDTO, Uri.fromParts("mailto", normalized, null)).apply {
        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
    }
    return try {
        context.startActivity(Intent.createChooser(intent, "Pošalji email").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
        true
    } catch (_: ActivityNotFoundException) {
        false
    }
}

private fun createWorkOrderCameraCaptureUri(context: Context): Uri? =
    runCatching {
        val directory = File(context.cacheDir, "work-order-documents").apply { mkdirs() }
        val file = File(directory, "fotografija-${System.currentTimeMillis()}.jpg")
        FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file)
    }.getOrNull()

private fun openCachedDocument(context: Context, uri: Uri, mimeType: String): Boolean {
    val intent = Intent(Intent.ACTION_VIEW).apply {
        setDataAndType(uri, mimeType.ifBlank { "application/octet-stream" })
        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
    }
    return try {
        context.startActivity(Intent.createChooser(intent, "Otvori dokument").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
        true
    } catch (_: ActivityNotFoundException) {
        false
    }
}
